  name?: string;
  tagline?: string;
  size?: "sm" | "md" | "lg";
  className?: string;
}

export interface BrandMarkProps extends HTMLAttributes<HTMLSpanElement> {
  /** What sits in the square — a letter, an initial, an icon. */
  glyph?: ReactNode;
  /**
   * `"sm" | "md" | "lg"`, or an exact pixel size when a design calls for one
   * the scale does not have.
   */
  size?: "sm" | "md" | "lg" | number;
}

import { forwardRef } from "react";
import { cn } from "../../utils/cn";
import type { BrandMarkProps } from "./Brand.types";

const sizeClasses: Record<Exclude<NonNullable<BrandMarkProps["size"]>, number>, string> = {
  sm: "h-6 w-6 rounded-md text-[11px]",
  md: "h-8 w-8 rounded-lg text-sm",
  lg: "h-11 w-11 rounded-xl text-lg",
};

/**
 * The square logo tile — a glyph centred in a rounded, coloured square.
 *
 * `Brand` has always taken its mark as a caller-supplied `logo` node, which is
 * exactly why every page that wanted one rebuilt the same square: fixed size,
 * rounded, grid-centred, bold, white, and `shrink-0` so a flex row never
 * squashes it. Four surfaces carried that block inline.
 *
 * ## It ships no brand colour, deliberately
 *
 * The default is a neutral zinc tile. A component library inventing your brand
 * gradient would be wrong, and would be the first thing every consumer had to
 * override — so the FILL is `className`'s job and only the geometry lives here.
 * That is also what the duplicated code actually had in common: each copy
 * already pulled its gradient from a token class and hand-rolled the box.
 */
export const BrandMark = forwardRef<HTMLSpanElement, BrandMarkProps>(
  ({ glyph, size = "md", className, style, ...props }, ref) => {
    const numeric = typeof size === "number";

    return (
      <span
        ref={ref}
        data-react-fancy-brand-mark=""
        aria-hidden={props["aria-label"] ? undefined : true}
        className={cn(
          "grid shrink-0 place-items-center font-bold leading-none text-white select-none",
          numeric ? "rounded-lg" : sizeClasses[size],
          // Overridable default: a mark with no `className` still reads as a
          // mark rather than as an invisible box.
          "bg-zinc-900 dark:bg-zinc-100 dark:text-zinc-900",
          className,
        )}
        style={numeric ? { height: size, width: size, fontSize: Math.round(size * 0.5), ...style } : style}
        {...props}
      >
        {glyph}
      </span>
    );
  },
);

BrandMark.displayName = "BrandMark";

export { Brand } from "./Brand";
export { BrandMark } from "./BrandMark";
export type { BrandProps, BrandMarkProps } from "./Brand.types";

import { Children, Fragment, useState, type ReactElement } from "react";
import { ChevronRight } from "lucide-react";
import { cn } from "../../utils/cn";
import { BreadcrumbsItem } from "./BreadcrumbsItem";
import { BreadcrumbsDropdown } from "./BreadcrumbsDropdown";
import type { BreadcrumbsProps, BreadcrumbsItemProps } from "./Breadcrumbs.types";

function BreadcrumbsRoot({
  children,
  separator,
  shrink,
  className,
}: BreadcrumbsProps) {
  const items = Children.toArray(children);
  const [expanded, setExpanded] = useState(false);

  const sep = separator ?? (
    <ChevronRight size={12} className="text-zinc-400" />
  );

  const lastItem = items[items.length - 1];

  // Extract info from children for mobile dropdown
  const dropdownItems = items.map((child) => {
    const el = child as ReactElement<BreadcrumbsItemProps>;
    return {
      label: el.props?.children,
      href: el.props?.href,
      active: el.props?.active,
    };
  });

  const activeLabel = dropdownItems[dropdownItems.length - 1]?.label ?? "Menu";

  const showShrunk = shrink && !expanded && items.length > 1;

  return (
    <>
      {/* Desktop trail */}
      <nav
        data-react-fancy-breadcrumbs=""
        aria-label="Breadcrumb"
        className={cn("hidden items-center gap-2 md:flex", className)}
        onMouseLeave={() => shrink && setExpanded(false)}
      >
        {showShrunk ? (
          <>
            <button
              type="button"
              onClick={() => setExpanded(true)}
              onMouseEnter={() => setExpanded(true)}
              className="text-sm text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-300"
            >
              ...
            </button>
            <span aria-hidden="true">{sep}</span>
            {lastItem}
          </>
        ) : (
          items.map((child, i) => (
            <Fragment key={i}>
              {i > 0 && <span aria-hidden="true">{sep}</span>}
              {child}
            </Fragment>
          ))
        )}
      </nav>

      {/* Mobile dropdown */}
      <BreadcrumbsDropdown items={dropdownItems} activeLabel={activeLabel} />
    </>
  );
}

export const Breadcrumbs = Object.assign(BreadcrumbsRoot, {
  Item: BreadcrumbsItem,
});

import type { ReactNode } from "react";
import type { NavigableProps } from "../../utils/types";

export interface BreadcrumbsProps {
  children: ReactNode;
  separator?: ReactNode;
  shrink?: boolean;
  className?: string;
}

export interface BreadcrumbsItemProps extends NavigableProps {
  children: ReactNode;
  active?: boolean;
  /**
   * Navigate by callback instead of by URL, for a crumb with no href.
   *
   * Controlled components own their own navigation — a repository browser
   * walking directories, a wizard stepping back — and have no address to link
   * to. Renders the crumb as a `<button>`. Ignored when `active`, since the
   * current crumb is not a destination, and `href` wins if both are given.
   */
  onClick?: () => void;
  className?: string;
}

import { useState, useRef, type ReactNode } from "react";
import { ChevronDown } from "lucide-react";
import { cn } from "../../utils/cn";
import { useOutsideClick } from "../../hooks/use-outside-click";
import { useEscapeKey } from "../../hooks/use-escape-key";

interface BreadcrumbsDropdownItem {
  label: ReactNode;
  href?: string;
  active?: boolean;
}

interface BreadcrumbsDropdownProps {
  items: BreadcrumbsDropdownItem[];
  activeLabel: ReactNode;
}

export function BreadcrumbsDropdown({ items, activeLabel }: BreadcrumbsDropdownProps) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useOutsideClick(ref, () => setOpen(false), open);
  useEscapeKey(() => setOpen(false), open);

  return (
    <div ref={ref} data-react-fancy-breadcrumbs-dropdown="" className="relative flex md:hidden">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="flex items-center gap-1 rounded-lg px-2 py-1 text-sm font-medium text-zinc-900 hover:bg-zinc-100 dark:text-white dark:hover:bg-zinc-800"
      >
        {activeLabel}
        <ChevronDown size={14} className={cn("transition-transform", open && "rotate-180")} />
      </button>
      {open && (
        <div className="absolute top-full left-0 z-50 mt-1 min-w-[180px] rounded-lg border border-zinc-200 bg-white py-1 shadow-lg dark:border-zinc-700 dark:bg-zinc-900">
          {items.map((item, i) => {
            const cls = cn(
              "block w-full px-3 py-1.5 text-left text-sm",
              item.active
                ? "font-medium text-zinc-900 dark:text-white"
                : "text-zinc-500 hover:bg-zinc-50 hover:text-zinc-700 dark:text-zinc-400 dark:hover:bg-zinc-800 dark:hover:text-zinc-300",
            );

            if (item.href && !item.active) {
              return (
                <a key={i} href={item.href} className={cls} onClick={() => setOpen(false)}>
                  {item.label}
                </a>
              );
            }

            return (
              <span key={i} className={cls}>
                {item.label}
              </span>
            );
          })}
        </div>
      )}
    </div>
  );
}

BreadcrumbsDropdown.displayName = "BreadcrumbsDropdown";

import type { ElementType } from "react";
import { cn } from "../../utils/cn";
import type { BreadcrumbsItemProps } from "./Breadcrumbs.types";

export function BreadcrumbsItem({
  children,
  href,
  as: As,
  active = false,
  onClick,
  className,
  ...rest
}: BreadcrumbsItemProps) {
  const baseClass = cn(
    "text-sm",
    active
      ? "font-medium text-zinc-900 dark:text-white"
      : "text-zinc-500 hover:text-zinc-700 dark:text-zinc-400 dark:hover:text-zinc-300",
    className,
  );

  // The CURRENT crumb stays a <span> even with `as`: it is the page you are on,
  // so a link to it is a link to nowhere, and `aria-current="page"` is the point.
  if ((href || As) && !active) {
    const Link = (As ?? "a") as ElementType;

    return (
      <Link
        data-react-fancy-breadcrumbs-item=""
        {...(href ? { href } : {})}
        onClick={onClick}
        className={baseClass}
        {...rest}
      >
        {children}
      </Link>
    );
  }

  // A crumb that navigates through a callback rather than a URL. Controlled
  // components own their navigation and have no href to give — a repository
  // browser walking directories, a wizard stepping back — and until this
  // existed the only way to make such a crumb clickable was to nest a button
  // inside the span below, which is interactive content inside a non-
  // interactive element.
  if (onClick && !active) {
    return (
      <button
        type="button"
        data-react-fancy-breadcrumbs-item=""
        onClick={onClick}
        className={cn(baseClass, "cursor-pointer border-0 bg-transparent p-0")}
        {...rest}
      >
        {children}
      </button>
    );
  }

  return (
    <span data-react-fancy-breadcrumbs-item="" className={baseClass} aria-current={active ? "page" : undefined} {...rest}>
      {children}
    </span>
  );
}

BreadcrumbsItem.displayName = "BreadcrumbsItem";

import { forwardRef, type AnchorHTMLAttributes, type ElementType, type ForwardedRef, type ReactNode } from "react";
import { cn } from "../../utils/cn";
import { sanitizeHref } from "../../utils/sanitize";
import { resolve } from "../../data/emoji-utils";
import { Icon } from "../Icon/Icon";
import type { ButtonProps } from "./Button.types";
import type { ButtonColor, Size } from "../../utils/types";
import {
  buttonColorClasses as colorClasses,
  buttonGhostClasses as ghostColorClasses,
} from "./Button.colors";

const iconSizeMap: Record<Size, "xs" | "sm" | "md" | "lg" | "xl"> = {
  xs: "xs",
  sm: "xs",
  md: "sm",
  lg: "md",
  xl: "lg",
};

const alertIconSizeMap: Record<Size, "xs" | "sm" | "md" | "lg" | "xl"> = {
  xs: "xs",
  sm: "xs",
  md: "xs",
  lg: "sm",
  xl: "sm",
};

// ---------------------------------------------------------------------------
// Color classes
//
// Solid + ghost color maps live in ./Button.colors (AUTO-GENERATED, all 22
// Tailwind v4 hues as literal strings). The state-color classes below
// (default/active/checked/warn) branch on flags, not specific colors.
// ---------------------------------------------------------------------------

const defaultClasses =
  "bg-white text-zinc-700 border border-zinc-200 hover:bg-zinc-50 hover:border-zinc-300 dark:bg-zinc-800 dark:text-zinc-300 dark:border-zinc-700 dark:hover:bg-zinc-700";

const activeClasses =
  "bg-blue-500 text-white border border-blue-600 hover:bg-blue-600 dark:bg-blue-600 dark:border-blue-500 dark:hover:bg-blue-500";

const checkedClasses =
  "bg-emerald-500 text-white border border-emerald-600 hover:bg-emerald-600 dark:bg-emerald-600 dark:border-emerald-500 dark:hover:bg-emerald-500";

const warnClasses =
  "bg-amber-50 text-amber-700 border border-amber-200 hover:bg-amber-100 dark:bg-amber-900/30 dark:text-amber-300 dark:border-amber-700 dark:hover:bg-amber-900/50";

const ghostDefaultClasses =
  "bg-transparent text-zinc-700 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800";

const ghostActiveClasses =
  "bg-blue-50 text-blue-700 hover:bg-blue-100 dark:bg-blue-950/50 dark:text-blue-300 dark:hover:bg-blue-950";

const ghostCheckedClasses =
  "bg-emerald-50 text-emerald-700 hover:bg-emerald-100 dark:bg-emerald-950/50 dark:text-emerald-300 dark:hover:bg-emerald-950";

const ghostWarnClasses =
  "bg-transparent text-amber-700 hover:bg-amber-50 dark:text-amber-300 dark:hover:bg-amber-950/50";

// ---------------------------------------------------------------------------
// Size helpers
// ---------------------------------------------------------------------------

const horizontalSize: Record<Size, string> = {
  xs: "px-2 py-1 text-xs",
  sm: "px-2 py-1 text-xs",
  md: "px-3 py-1.5 text-sm",
  lg: "px-4 py-2.5 text-base",
  xl: "px-5 py-3 text-lg",
};

const circleSize: Record<Size, string> = {
  xs: "w-7 h-7 text-xs",
  sm: "w-8 h-8 text-xs",
  md: "w-10 h-10 text-sm",
  lg: "w-12 h-12 text-base",
  xl: "w-14 h-14 text-lg",
};

const iconSize: Record<Size, string> = {
  xs: "w-3 h-3",
  sm: "w-3 h-3",
  md: "w-4 h-4",
  lg: "w-5 h-5",
  xl: "w-6 h-6",
};

const avatarSize: Record<Size, string> = {
  xs: "w-4 h-4",
  sm: "w-4 h-4",
  md: "w-5 h-5",
  lg: "w-6 h-6",
  xl: "w-7 h-7",
};

const alertIconSize: Record<Size, string> = {
  xs: "w-2 h-2",
  sm: "w-2.5 h-2.5",
  md: "w-3 h-3",
  lg: "w-4 h-4",
  xl: "w-4 h-4",
};

const badgeSize: Record<Size, string> = {
  xs: "text-[10px] px-1 min-w-[14px] h-3.5",
  sm: "text-[10px] px-1.5 min-w-[16px] h-4",
  md: "text-[11px] px-1.5 min-w-[18px] h-[18px]",
  lg: "text-xs px-2 min-w-[22px] h-5",
  xl: "text-xs px-2 min-w-[24px] h-5",
};

const externalIconOffset: Record<Size, string> = {
  xs: "0.75rem",
  sm: "0.75rem",
  md: "1rem",
  lg: "1.25rem",
  xl: "1.5rem",
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function isColored(color?: ButtonColor, active?: boolean, checked?: boolean): boolean {
  return !!(color || active || checked);
}

function getColorClasses(
  color?: ButtonColor,
  active?: boolean,
  checked?: boolean,
  warn?: boolean,
  ghost?: boolean,
): string {
  if (ghost) {
    if (color) return ghostColorClasses[color];
    if (checked) return ghostCheckedClasses;
    if (active) return ghostActiveClasses;
    if (warn) return ghostWarnClasses;
    return ghostDefaultClasses;
  }
  if (color) return colorClasses[color];
  if (checked) return checkedClasses;
  if (active) return activeClasses;
  if (warn) return warnClasses;
  return defaultClasses;
}

function getIconColorClasses(
  color?: ButtonColor,
  active?: boolean,
  checked?: boolean,
  warn?: boolean,
  ghost?: boolean,
): string {
  if (ghost) {
    // Ghost variant: icon inherits currentColor from the button text
    return "text-current";
  }
  if (color || active || checked) return "text-white";
  if (warn) return "text-amber-600 dark:text-amber-400";
  return "text-zinc-500 dark:text-zinc-400";
}

function getBadgeClasses(
  color?: ButtonColor,
  active?: boolean,
  checked?: boolean,
  warn?: boolean,
  ghost?: boolean,
): string {
  if (ghost) {
    return "bg-current/10 text-current";
  }
  if (isColored(color, active, checked)) return "bg-white/20 text-white";
  if (warn) return "bg-amber-200 text-amber-800 dark:bg-amber-800 dark:text-amber-200";
  return "bg-zinc-200 text-zinc-700 dark:bg-zinc-600 dark:text-zinc-200";
}

// ---------------------------------------------------------------------------
// Placement parsing
// ---------------------------------------------------------------------------

type PlacementAxis = "left" | "right" | "top" | "bottom";

function parsePlacement(iconPlace: string): { primary: PlacementAxis; secondary?: PlacementAxis } {
  const parts = iconPlace.split(" ") as PlacementAxis[];
  return { primary: parts[0], secondary: parts[1] };
}

function isVerticalPrimary(primary: PlacementAxis): boolean {
  return primary === "top" || primary === "bottom";
}

// ---------------------------------------------------------------------------
// Sort parsing
// ---------------------------------------------------------------------------

type ElementKey = "e" | "i" | "a" | "b";
const DEFAULT_SORT = "eiab";

function parseSortOrder(sort?: string): ElementKey[] {
  const chars = (sort ?? DEFAULT_SORT).split("") as ElementKey[];
  const valid: ElementKey[] = [];
  const seen = new Set<string>();
  for (const c of chars) {
    if ("eiab".includes(c) && !seen.has(c)) {
      valid.push(c);
      seen.add(c);
    }
  }
  // Add missing keys in default order
  for (const c of DEFAULT_SORT.split("") as ElementKey[]) {
    if (!seen.has(c)) valid.push(c);
  }
  return valid;
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      children,
      className,
      variant = "default",
      color,
      size = "md",
      active,
      checked,
      warn,
      alert: alertProp,
      icon,
      iconTrailing,
      iconPlace = "left",
      alertIcon,
      alertIconTrailing,
      emoji,
      emojiTrailing,
      avatar,
      avatarTrailing,
      badge,
      badgeTrailing,
      sort,
      loading = false,
      disabled,
      href,
      as: As,
      responsive,
      labelClassName,
      ...props
    },
    ref,
  ) => {
    const isCircle = variant === "circle";
    const isGhost = variant === "ghost";
    const { primary, secondary } = parsePlacement(iconPlace);
    const isVertical = isVerticalPrimary(primary);
    const isCompound = !!secondary;
    const needsWrapper = isVertical || isCompound;
    const isReversed = iconPlace === "right";

    // -----------------------------------------------------------------------
    // Sizing — always use horizontalSize for the button itself
    // -----------------------------------------------------------------------
    const sizeClass = isCircle ? circleSize[size] : horizontalSize[size];

    // -----------------------------------------------------------------------
    // Build decorative elements
    // -----------------------------------------------------------------------
    const iconColorCls = getIconColorClasses(color, active, checked, warn, isGhost);

    const buildElement = (key: ElementKey, trailing: boolean): ReactNode => {
      switch (key) {
        case "e": {
          const slug = trailing ? emojiTrailing : emoji;
          if (!slug) return null;
          const char = resolve(slug);
          if (!char) return null;
          return (
            <span key={`emoji-${trailing ? "t" : "l"}`} data-action-emoji>
              {char}
            </span>
          );
        }
        case "i": {
          if (loading && !trailing) {
            return (
              <span
                key="spinner"
                className={cn("animate-spin border-2 border-current border-t-transparent rounded-full", iconSize[size])}
              />
            );
          }
          const iconSlug = trailing ? iconTrailing : icon;
          if (!iconSlug) return null;
          // For vertical/compound placements, icons render outside the button — not inside
          if (needsWrapper) return null;
          return (
            <span
              key={`icon-${trailing ? "t" : "l"}`}
              className={cn("inline-flex items-center flex-shrink-0", iconColorCls)}
            >
              <Icon name={iconSlug} size={iconSizeMap[size]} />
            </span>
          );
        }
        case "a": {
          if (!avatar) return null;
          const isTrailing = avatarTrailing ?? trailing;
          if (isTrailing !== trailing) return null;
          return (
            <img
              key="avatar"
              src={avatar}
              alt=""
              className={cn(avatarSize[size], "rounded-full object-cover flex-shrink-0")}
              data-action-avatar
            />
          );
        }
        case "b": {
          if (!badge) return null;
          const isTrailing = badgeTrailing ?? trailing;
          if (isTrailing !== trailing) return null;
          return (
            <span
              key="badge"
              className={cn(
                "inline-flex items-center justify-center font-medium rounded-full",
                badgeSize[size],
                getBadgeClasses(color, active, checked, warn, isGhost),
              )}
              data-action-badge
            >
              {badge}
            </span>
          );
        }
        default:
          return null;
      }
    };

    // Alert icon element
    const renderAlertIcon = (trailing: boolean): ReactNode => {
      if (!alertIcon) return null;
      const isTrailing = alertIconTrailing ?? false;
      if (isTrailing !== trailing) return null;
      const alertIconEl = <Icon name={alertIcon} size={alertIconSizeMap[size]} />;
      return (
        <span
          key="alert-icon"
          className="relative inline-flex flex-shrink-0"
          data-action-alert
        >
          <span className="text-red-500 dark:text-red-400 animate-pulse">
            {alertIconEl}
          </span>
          <span className="absolute inset-0 flex items-center justify-center text-red-400 dark:text-red-300 animate-ping opacity-75">
            {alertIconEl}
          </span>
        </span>
      );
    };

    const sortOrder = parseSortOrder(sort);

    const leadingElements: ReactNode[] = [];
    const trailingElements: ReactNode[] = [];

    for (const key of sortOrder) {
      const leading = buildElement(key, false);
      if (leading) leadingElements.push(leading);
      const trailing = buildElement(key, true);
      if (trailing) trailingElements.push(trailing);
    }

    // Insert alert icon
    const leadingAlert = renderAlertIcon(false);
    if (leadingAlert) leadingElements.push(leadingAlert);
    const trailingAlert = renderAlertIcon(true);
    if (trailingAlert) trailingElements.push(trailingAlert);

    // -----------------------------------------------------------------------
    // Classes
    // -----------------------------------------------------------------------
    const classes = cn(
      // `text-left` overrides the UA <button> center default so a wrapped,
      // width-constrained multi-word label stacks left-aligned. Overridable —
      // twMerge lets a `text-center` / `text-right` in `className` win.
      "inline-flex items-center justify-center text-left font-medium transition-all duration-200",
      "focus:outline-none focus:ring-2 focus:ring-offset-1",
      "disabled:opacity-50 disabled:cursor-not-allowed",
      isCircle ? "rounded-full" : "rounded-lg",
      sizeClass,
      getColorClasses(color, active, checked, warn, isGhost),
      !isCircle && !needsWrapper && "gap-2",
      !isCircle && needsWrapper && "gap-2",
      isReversed && !needsWrapper && "flex-row-reverse",
      alertProp && "animate-pulse",
      className,
    );

    // -----------------------------------------------------------------------
    // Content
    // -----------------------------------------------------------------------
    const content = isCircle ? (
      <>
        {loading ? (
          <span
            className={cn(
              "animate-spin border-2 border-current border-t-transparent rounded-full",
              iconSize[size],
            )}
          />
        ) : (
          icon ? <Icon name={icon} size={iconSizeMap[size]} /> : children
        )}
      </>
    ) : (
      <>
        {leadingElements}
        {children != null && (
          <span
            data-react-fancy-button-label=""
            className={cn(
              // A button label must stay on one line. When a host flex layout
              // squeezes the button, `whitespace-nowrap` keeps the label and any
              // trailing icon/arrow together instead of wrapping and stacking the
              // icon below it (the classic "send" over "→" break). `min-w-0` keeps
              // the span shrinkable so `truncate`/ellipsis still works; multi-line
              // wrapping is opt-in via `labelClassName` ("whitespace-normal") or
              // the `responsive` prop.
              "min-w-0 whitespace-nowrap",
              // `responsive` collapses to icon-only when squeezed, while keeping
              // the label readable to screen readers.
              responsive && "sr-only sm:not-sr-only",
              labelClassName,
            )}
          >
            {children}
          </span>
        )}
        {trailingElements}
      </>
    );

    // -----------------------------------------------------------------------
    // Build the button element
    // -----------------------------------------------------------------------
    const safeHref = sanitizeHref(href);
    // Anchor mode renders `as` when provided (e.g. a router's <Link> for
    // client-side navigation — Inertia, React Router, Next). Previously `as`
    // fell through ...props onto the <a> where React silently DROPS a
    // function-valued unknown attribute — so `<Button as={Link}>` looked fine
    // but did a full page load. `as` only applies in anchor mode; without an
    // href (or when disabled) the plain <button> renders as always.
    const Anchor = (As ?? "a") as ElementType;
    const buttonEl = safeHref && !disabled ? (
      // Anchor mode forwards the same rest props as the <button> branch so
      // onClick / target / rel / ref / ARIA / data-* reach the <a> (issue #7).
      <Anchor
        ref={ref as ForwardedRef<HTMLAnchorElement>}
        href={safeHref}
        className={classes}
        data-react-fancy-button=""
        data-react-fancy-action=""
        {...(props as AnchorHTMLAttributes<HTMLAnchorElement>)}
      >
        {content}
      </Anchor>
    ) : (
      <button
        ref={ref}
        className={classes}
        disabled={disabled || loading}
        data-react-fancy-button=""
        data-react-fancy-action=""
        {...props}
      >
        {content}
      </button>
    );

    // -----------------------------------------------------------------------
    // Wrap for vertical/compound icon placement
    // The icon is absolutely positioned so it never shifts the button.
    // -----------------------------------------------------------------------
    if (needsWrapper && (icon || iconTrailing)) {
      const iconSlug = icon ?? iconTrailing;
      const offset = externalIconOffset[size];

      // Determine position styles for the icon
      const posStyle: React.CSSProperties = { position: "absolute" };

      // Primary axis: which side of the button
      if (primary === "top") {
        posStyle.bottom = "100%";
        posStyle.marginBottom = "0.125rem";
      } else if (primary === "bottom") {
        posStyle.top = "100%";
        posStyle.marginTop = "0.125rem";
      } else if (primary === "left") {
        posStyle.right = "100%";
        posStyle.marginRight = "0.125rem";
      } else if (primary === "right") {
        posStyle.left = "100%";
        posStyle.marginLeft = "0.125rem";
      }

      // Secondary axis: cross-axis alignment
      if (isVerticalPrimary(primary)) {
        // Vertical primary → secondary controls horizontal position
        if (secondary === "left") {
          posStyle.left = "0";
        } else if (secondary === "right") {
          posStyle.right = "0";
        } else {
          // center (default)
          posStyle.left = "50%";
          posStyle.transform = "translateX(-50%)";
        }
      } else {
        // Horizontal primary → secondary controls vertical position
        if (secondary === "top") {
          posStyle.top = "0";
        } else if (secondary === "bottom") {
          posStyle.bottom = "0";
        } else {
          // center (default)
          posStyle.top = "50%";
          posStyle.transform = "translateY(-50%)";
        }
      }

      const externalIcon = (
        <span
          className={cn("absolute flex-shrink-0", iconColorCls)}
          style={posStyle}
        >
          <Icon name={iconSlug!} size={iconSizeMap[size]} />
        </span>
      );

      return (
        <span
          data-react-fancy-action-group=""
          className="relative inline-flex"
        >
          {buttonEl}
          {externalIcon}
        </span>
      );
    }

    return buttonEl;
  },
);

