import { ZoomIn, ZoomOut, Maximize, RotateCcw } from "lucide-react";
import { cn } from "../utils/cn";
import { useCanvas } from "./Canvas.context";
import type { CanvasControlsProps } from "./Canvas.types";

export function CanvasControls({
  className,
  showZoomIn = true,
  showZoomOut = true,
  showReset = true,
  showFitAll = true,
}: CanvasControlsProps) {
  const { setViewport, nodeRects, containerRef } = useCanvas();

  const zoomIn = () => setViewport((v) => ({ ...v, zoom: Math.min(3, v.zoom * 1.25) }));
  const zoomOut = () => setViewport((v) => ({ ...v, zoom: Math.max(0.1, v.zoom / 1.25) }));
  const reset = () => setViewport({ panX: 0, panY: 0, zoom: 1 });

  const fitAll = () => {
    const container = containerRef.current;
    if (!container || nodeRects.size === 0) return reset();

    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    nodeRects.forEach((r) => {
      minX = Math.min(minX, r.x);
      minY = Math.min(minY, r.y);
      maxX = Math.max(maxX, r.x + r.width);
      maxY = Math.max(maxY, r.y + r.height);
    });

    const padding = 40;
    const contentW = maxX - minX + padding * 2;
    const contentH = maxY - minY + padding * 2;
    const cw = container.clientWidth;
    const ch = container.clientHeight;
    const zoom = Math.min(cw / contentW, ch / contentH, 1.5);
    const panX = (cw - contentW * zoom) / 2 - minX * zoom + padding * zoom;
    const panY = (ch - contentH * zoom) / 2 - minY * zoom + padding * zoom;

    setViewport({ panX, panY, zoom });
  };

  const btnClass =
    "flex h-8 w-8 items-center justify-center rounded-md text-zinc-500 hover:bg-zinc-100 hover:text-zinc-700 dark:hover:bg-zinc-800 dark:hover:text-zinc-300 transition-colors";

  return (
    <div
      data-react-fancy-canvas-controls=""
      className={cn(
        "absolute bottom-3 left-3 flex gap-1 rounded-lg border border-zinc-200 bg-white/90 p-1 shadow-sm dark:border-zinc-700 dark:bg-zinc-900/90",
        className,
      )}
    >
      {showZoomIn && (
        <button type="button" onClick={zoomIn} className={btnClass} aria-label="Zoom in">
          <ZoomIn size={16} />
        </button>
      )}
      {showZoomOut && (
        <button type="button" onClick={zoomOut} className={btnClass} aria-label="Zoom out">
          <ZoomOut size={16} />
        </button>
      )}
      {showReset && (
        <button type="button" onClick={reset} className={btnClass} aria-label="Reset view">
          <RotateCcw size={16} />
        </button>
      )}
      {showFitAll && (
        <button type="button" onClick={fitAll} className={btnClass} aria-label="Fit all">
          <Maximize size={16} />
        </button>
      )}
    </div>
  );
}

CanvasControls.displayName = "CanvasControls";

import { useMemo } from "react";
import { cn } from "../utils/cn";
import { useCanvas } from "./Canvas.context";
import { getAnchorPoint, getEdgePath } from "./canvas.utils";
import type { CanvasEdgeProps } from "./Canvas.types";

export function CanvasEdge({
  from,
  to,
  fromAnchor = "auto",
  toAnchor = "auto",
  curve = "bezier",
  color = "currentColor",
  strokeWidth = 2,
  dashed = false,
  animated = false,
  label,
  className,
  markerStart,
  markerEnd,
}: CanvasEdgeProps) {
  const { nodeRects, registryVersion } = useCanvas();

  const path = useMemo(() => {
    const fromRect = nodeRects.get(from);
    const toRect = nodeRects.get(to);
    if (!fromRect || !toRect) return null;

    const fromPt = getAnchorPoint(fromRect, fromAnchor, toRect);
    const toPt = getAnchorPoint(toRect, toAnchor, fromRect);
    return {
      d: getEdgePath(fromPt, toPt, curve),
      midX: (fromPt.x + toPt.x) / 2,
      midY: (fromPt.y + toPt.y) / 2,
    };
  }, [from, to, fromAnchor, toAnchor, curve, nodeRects, registryVersion]);

  if (!path) return null;

  return (
    <g data-react-fancy-canvas-edge="" className={cn("text-zinc-300 dark:text-zinc-600", className)}>
      <path
        d={path.d}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeDasharray={dashed ? "6 4" : undefined}
        markerStart={markerStart ? `url(#${markerStart})` : undefined}
        markerEnd={markerEnd ? `url(#${markerEnd})` : undefined}
        className={animated ? "animate-[dash_1s_linear_infinite]" : ""}
        style={animated ? { strokeDasharray: "8 4" } : undefined}
      />
      {label && (
        <foreignObject x={path.midX - 40} y={path.midY - 12} width={80} height={24}>
          <div className="flex items-center justify-center text-xs text-zinc-500">{label}</div>
        </foreignObject>
      )}
    </g>
  );
}

CanvasEdge.displayName = "CanvasEdge";

import { useMemo } from "react";
import { cn } from "../utils/cn";
import { useCanvas } from "./Canvas.context";
import type { CanvasMinimapProps } from "./Canvas.types";

export function CanvasMinimap({ width = 150, height = 100, className }: CanvasMinimapProps) {
  const { nodeRects, registryVersion, viewport } = useCanvas();

  const bounds = useMemo(() => {
    if (nodeRects.size === 0) return { minX: 0, minY: 0, maxX: 500, maxY: 300 };
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    nodeRects.forEach((r) => {
      minX = Math.min(minX, r.x);
      minY = Math.min(minY, r.y);
      maxX = Math.max(maxX, r.x + r.width);
      maxY = Math.max(maxY, r.y + r.height);
    });
    const padding = 50;
    return { minX: minX - padding, minY: minY - padding, maxX: maxX + padding, maxY: maxY + padding };
  }, [nodeRects, registryVersion]);

  const scaleX = width / (bounds.maxX - bounds.minX || 1);
  const scaleY = height / (bounds.maxY - bounds.minY || 1);
  const scale = Math.min(scaleX, scaleY);

  return (
    <div
      data-react-fancy-canvas-minimap=""
      className={cn(
        "absolute right-3 bottom-3 overflow-hidden rounded-lg border border-zinc-200 bg-white/90 dark:border-zinc-700 dark:bg-zinc-900/90",
        className,
      )}
      style={{ width, height }}
    >
      <svg width={width} height={height}>
        {Array.from(nodeRects.entries()).map(([id, rect]) => (
          <rect
            key={id}
            x={(rect.x - bounds.minX) * scale}
            y={(rect.y - bounds.minY) * scale}
            width={Math.max(rect.width * scale, 4)}
            height={Math.max(rect.height * scale, 3)}
            rx={1}
            className="fill-blue-400/60"
          />
        ))}
        {/* Viewport indicator */}
        <rect
          x={(-viewport.panX / viewport.zoom - bounds.minX) * scale}
          y={(-viewport.panY / viewport.zoom - bounds.minY) * scale}
          width={(width / viewport.zoom / scale > 0 ? width / viewport.zoom : width) * scale / (bounds.maxX - bounds.minX || 1) * (bounds.maxX - bounds.minX)}
          height={(height / viewport.zoom / scale > 0 ? height / viewport.zoom : height) * scale / (bounds.maxY - bounds.minY || 1) * (bounds.maxY - bounds.minY)}
          fill="none"
          stroke="currentColor"
          strokeWidth={1}
          className="text-blue-500"
        />
      </svg>
    </div>
  );
}

CanvasMinimap.displayName = "CanvasMinimap";

import { useEffect, useRef, useCallback } from "react";
import { cn } from "../utils/cn";
import { useCanvas } from "./Canvas.context";
import type { CanvasNodeProps } from "./Canvas.types";

export function CanvasNode({ children, id, x, y, draggable, onPositionChange, className, style }: CanvasNodeProps) {
  const { registerNode, unregisterNode, viewport, gridSize, snapToGrid } = useCanvas();
  const nodeRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);
  const dragStart = useRef({ mouseX: 0, mouseY: 0, nodeX: 0, nodeY: 0 });

  useEffect(() => {
    const el = nodeRef.current;
    if (!el) return;

    const updateRect = () => {
      registerNode(id, { x, y, width: el.offsetWidth, height: el.offsetHeight });
    };

    updateRect();

    const observer = new ResizeObserver(updateRect);
    observer.observe(el);

    return () => {
      observer.disconnect();
      unregisterNode(id);
    };
  }, [id, x, y, registerNode, unregisterNode]);

  const handlePointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (!draggable || e.button !== 0) return;
      e.stopPropagation();
      isDragging.current = true;
      dragStart.current = { mouseX: e.clientX, mouseY: e.clientY, nodeX: x, nodeY: y };
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
    },
    [draggable, x, y],
  );

  const handlePointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!isDragging.current) return;
      const dx = (e.clientX - dragStart.current.mouseX) / viewport.zoom;
      const dy = (e.clientY - dragStart.current.mouseY) / viewport.zoom;
      let nx = dragStart.current.nodeX + dx;
      let ny = dragStart.current.nodeY + dy;
      if (snapToGrid && gridSize > 0) {
        nx = Math.round(nx / gridSize) * gridSize;
        ny = Math.round(ny / gridSize) * gridSize;
      }
      onPositionChange?.(nx, ny);
    },
    [viewport.zoom, onPositionChange, snapToGrid, gridSize],
  );

  const handlePointerUp = useCallback(() => {
    isDragging.current = false;
  }, []);

  return (
    <div
      ref={nodeRef}
      data-react-fancy-canvas-node=""
      data-node-id={id}
      className={cn("absolute", draggable && "cursor-grab active:cursor-grabbing", className)}
      style={{ left: x, top: y, ...style }}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
    >
      {children}
    </div>
  );
}

CanvasNode.displayName = "CanvasNode";

import type { NodeRect } from "../hooks/use-node-registry";
import type { EdgeAnchor } from "./Canvas.types";

export interface Point {
  x: number;
  y: number;
}

export function getAnchorPoint(rect: NodeRect, anchor: EdgeAnchor, otherRect?: NodeRect): Point {
  const cx = rect.x + rect.width / 2;
  const cy = rect.y + rect.height / 2;

  if (anchor === "auto" && otherRect) {
    const ocx = otherRect.x + otherRect.width / 2;
    const ocy = otherRect.y + otherRect.height / 2;
    const dx = ocx - cx;
    const dy = ocy - cy;

    if (Math.abs(dx) > Math.abs(dy)) {
      return dx > 0
        ? { x: rect.x + rect.width, y: cy }
        : { x: rect.x, y: cy };
    }
    return dy > 0
      ? { x: cx, y: rect.y + rect.height }
      : { x: cx, y: rect.y };
  }

  switch (anchor) {
    case "top": return { x: cx, y: rect.y };
    case "bottom": return { x: cx, y: rect.y + rect.height };
    case "left": return { x: rect.x, y: cy };
    case "right": return { x: rect.x + rect.width, y: cy };
    case "center": return { x: cx, y: cy };
    default: return { x: cx, y: cy };
  }
}

export function bezierPath(from: Point, to: Point): string {
  const dx = Math.abs(to.x - from.x);
  const dy = Math.abs(to.y - from.y);

  // Determine if the connection is more horizontal or vertical
  if (dx > dy) {
    // Horizontal: control points extend horizontally
    const offset = dx * 0.5;
    const cp1x = from.x + (to.x > from.x ? offset : -offset);
    const cp2x = to.x + (to.x > from.x ? -offset : offset);
    return `M${from.x},${from.y} C${cp1x},${from.y} ${cp2x},${to.y} ${to.x},${to.y}`;
  }
  // Vertical: control points extend vertically
  const offset = Math.max(dy * 0.5, 30);
  const cp1y = from.y + (to.y > from.y ? offset : -offset);
  const cp2y = to.y + (to.y > from.y ? -offset : offset);
  return `M${from.x},${from.y} C${from.x},${cp1y} ${to.x},${cp2y} ${to.x},${to.y}`;
}

export function stepPath(from: Point, to: Point): string {
  const midX = (from.x + to.x) / 2;
  return `M${from.x},${from.y} H${midX} V${to.y} H${to.x}`;
}

export function straightPath(from: Point, to: Point): string {
  return `M${from.x},${from.y} L${to.x},${to.y}`;
}

export function getEdgePath(
  from: Point,
  to: Point,
  curve: "bezier" | "step" | "straight" = "bezier",
): string {
  switch (curve) {
    case "bezier": return bezierPath(from, to);
    case "step": return stepPath(from, to);
    case "straight": return straightPath(from, to);
  }
}

export { Canvas } from "./Canvas";
export { useCanvas } from "./Canvas.context";
export type {
  CanvasProps,
  CanvasNodeProps,
  CanvasEdgeProps,
