    }

    // Directional variant (default)
    const prevDisabled = !loop && isFirst;
    const nextDisabled = !loop && isLast;

    return (
      <div ref={ref} data-react-fancy-carousel-controls="" className={cn("flex items-center gap-2", className)}>
        <button
          type="button"
          onClick={prev}
