import { useMemo, useRef, useState } from "react";
import { cn } from "../../utils/cn";
import { DEFAULT_COLORS, createLinearScale, linearPath, monotonePath, niceScale } from "./chart.utils";
import { ChartAxis } from "./ChartAxis";
import { ChartGrid } from "./ChartGrid";
import { ChartTooltip } from "./ChartTooltip";
import type { ChartLineProps } from "./Chart.types";

const PADDING = { top: 16, right: 16, bottom: 40, left: 48 };

export function ChartLine({
  labels,
  series,
  height = 240,
  curve = "monotone",
  showDots = true,
  fill = false,
  fillOpacity = 0.1,
  xAxis = true,
  yAxis = true,
  grid = true,
  tooltip = true,
  animate = true,
  responsive = false,
  className,
}: ChartLineProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [hoverInfo, setHoverInfo] = useState<{ x: number; y: number; labelIdx: number } | null>(null);
  const width = 500;

  const plotWidth = width - PADDING.left - PADDING.right;
  const plotHeight = height - PADDING.top - PADDING.bottom;

  const allValues = series.flatMap((s) => s.data);
  const dataMin = Math.min(0, ...allValues);
  const dataMax = Math.max(...allValues);

  const { min: yMin, max: yMax, ticks: yTicks } = useMemo(
    () => niceScale(dataMin, dataMax, 5),
    [dataMin, dataMax],
  );

  const xScale = useMemo(
    () => createLinearScale([0, labels.length - 1], [PADDING.left, PADDING.left + plotWidth]),
    [labels.length, plotWidth],
  );
  const yScale = useMemo(
    () => createLinearScale([yMin, yMax], [PADDING.top + plotHeight, PADDING.top]),
    [yMin, yMax, plotHeight],
  );

  const pathFn = curve === "monotone" ? monotonePath : linearPath;

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!tooltip || !containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const svgX = ((e.clientX - rect.left) / rect.width) * width;
    const closestIdx = Math.round(((svgX - PADDING.left) / plotWidth) * (labels.length - 1));
    const idx = Math.max(0, Math.min(labels.length - 1, closestIdx));
    setHoverInfo({
      x: ((xScale(idx) / width) * rect.width),
      y: e.clientY - rect.top,
      labelIdx: idx,
    });
  };

  const svgProps = responsive
    ? { viewBox: `0 0 ${width} ${height}`, width: "100%", preserveAspectRatio: "xMidYMid meet" as const }
    : { width, height };

  return (
    <div
      ref={containerRef}
      data-react-fancy-chart-line=""
      className={cn("relative", className)}
      onMouseMove={handleMouseMove}
      onMouseLeave={() => setHoverInfo(null)}
    >
      <svg {...svgProps} height={responsive ? undefined : height}>
        {grid && (
          <ChartGrid
            x={PADDING.left}
            y={PADDING.top}
            width={plotWidth}
            height={plotHeight}
            horizontal={{ ticks: yTicks, scale: yScale }}
          />
        )}

        {series.map((s, si) => {
          const color = s.color ?? DEFAULT_COLORS[si % DEFAULT_COLORS.length];
          const points: [number, number][] = s.data.map((v, i) => [xScale(i), yScale(v)]);
          const d = pathFn(points);

          return (
            <g key={s.label}>
              {fill && (
                <path
                  d={`${d} L${points[points.length - 1][0]},${yScale(yMin)} L${points[0][0]},${yScale(yMin)} Z`}
                  fill={color}
                  fillOpacity={fillOpacity}
                />
              )}
              <path
                d={d}
                fill="none"
                stroke={color}
                strokeWidth={2}
                className={animate ? "transition-all duration-500" : ""}
              />
              {showDots && points.map(([px, py], i) => (
                <circle
                  key={i}
                  cx={px}
                  cy={py}
                  r={3}
                  fill="white"
                  stroke={color}
                  strokeWidth={2}
                />
              ))}
            </g>
          );
        })}

        {yAxis && (
          <ChartAxis orientation="y" ticks={yTicks} scale={yScale} x={PADDING.left} y={PADDING.top} length={plotHeight} />
        )}
        {xAxis && (
          <ChartAxis
            orientation="x"
            ticks={labels.map((_, i) => i)}
            scale={xScale}
            x={PADDING.left}
            y={PADDING.top + plotHeight}
            length={plotWidth}
            formatTick={(v) => labels[Math.round(v)] ?? ""}
          />
        )}

        {/* Hover line */}
        {hoverInfo !== null && (
          <line
            x1={xScale(hoverInfo.labelIdx)}
            y1={PADDING.top}
            x2={xScale(hoverInfo.labelIdx)}
            y2={PADDING.top + plotHeight}
            stroke="currentColor"
            strokeDasharray="4 4"
            className="text-zinc-300 dark:text-zinc-600"
          />
        )}
      </svg>

      {tooltip && hoverInfo !== null && (
        <ChartTooltip
          visible
          x={hoverInfo.x}
          y={hoverInfo.y}
          content={
            <div>
              <div className="mb-1 font-medium">{labels[hoverInfo.labelIdx]}</div>
              {series.map((s, si) => (
                <div key={s.label} className="flex items-center gap-2">
                  <span
                    className="inline-block h-2 w-2 rounded-full"
                    style={{ backgroundColor: s.color ?? DEFAULT_COLORS[si % DEFAULT_COLORS.length] }}
                  />
                  <span className="text-zinc-500">{s.label}:</span>
                  <span className="font-medium">{s.data[hoverInfo.labelIdx]}</span>
                </div>
              ))}
            </div>
          }
        />
      )}

      {/* Legend */}
      {series.length > 1 && (
        <div className="mt-2 flex flex-wrap items-center justify-center gap-4">
          {series.map((s, si) => (
            <div key={s.label} className="flex items-center gap-1.5 text-xs">
              <span
                className="inline-block h-2.5 w-2.5 rounded-full"
                style={{ backgroundColor: s.color ?? DEFAULT_COLORS[si % DEFAULT_COLORS.length] }}
              />
              <span className="text-zinc-600 dark:text-zinc-400">{s.label}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

ChartLine.displayName = "ChartLine";

import { useMemo, useRef, useState } from "react";
import { cn } from "../../utils/cn";
import { DEFAULT_COLORS } from "./chart.utils";
import { ChartTooltip } from "./ChartTooltip";
import type { ChartPieProps } from "./Chart.types";

export function ChartPie({
  data,
  size = 200,
  showLabels = false,
  tooltip = true,
  className,
}: ChartPieProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [hoverIdx, setHoverIdx] = useState<number | null>(null);
  const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });

  const total = useMemo(() => data.reduce((s, d) => s + d.value, 0), [data]);
  const center = size / 2;
  const radius = size / 2 - 4;

  const slices = useMemo(() => {
    let startAngle = -Math.PI / 2;
    return data.map((item, i) => {
      const pct = total > 0 ? item.value / total : 0;
      const angle = pct * 2 * Math.PI;
      const endAngle = startAngle + angle;
      const largeArc = angle > Math.PI ? 1 : 0;

      const x1 = center + radius * Math.cos(startAngle);
      const y1 = center + radius * Math.sin(startAngle);
      const x2 = center + radius * Math.cos(endAngle);
      const y2 = center + radius * Math.sin(endAngle);

      const midAngle = startAngle + angle / 2;
      const labelX = center + (radius * 0.65) * Math.cos(midAngle);
      const labelY = center + (radius * 0.65) * Math.sin(midAngle);

      const d = pct >= 1
        ? `M${center},${center - radius} A${radius},${radius} 0 1 1 ${center},${center + radius} A${radius},${radius} 0 1 1 ${center},${center - radius}`
        : `M${center},${center} L${x1},${y1} A${radius},${radius} 0 ${largeArc} 1 ${x2},${y2} Z`;

      const color = item.color ?? DEFAULT_COLORS[i % DEFAULT_COLORS.length];
      startAngle = endAngle;

      return { ...item, d, color, labelX, labelY, pct };
    });
  }, [data, total, center, radius]);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    setTooltipPos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
  };

  return (
    <div ref={containerRef} data-react-fancy-chart-pie="" className={cn("relative inline-flex items-center gap-6", className)} onMouseMove={handleMouseMove}>
      <svg width={size} height={size}>
        {slices.map((slice, i) => (
          <g key={slice.label}>
            <path
              d={slice.d}
              fill={slice.color}
              stroke="white"
              strokeWidth={2}
              className="transition-opacity"
              opacity={hoverIdx !== null && hoverIdx !== i ? 0.5 : 1}
              onMouseEnter={() => setHoverIdx(i)}
              onMouseLeave={() => setHoverIdx(null)}
            />
            {showLabels && slice.pct > 0.05 && (
              <text
                x={slice.labelX}
                y={slice.labelY}
                textAnchor="middle"
                dominantBaseline="middle"
                className="fill-white text-[10px] font-medium"
              >
                {Math.round(slice.pct * 100)}%
              </text>
            )}
          </g>
        ))}
      </svg>

      {/* Legend */}
      <div className="flex flex-col gap-2">
        {slices.map((slice) => (
          <div key={slice.label} className="flex items-center gap-2 text-sm">
            <div className="h-3 w-3 rounded-full" style={{ backgroundColor: slice.color }} />
            <span className="text-zinc-600 dark:text-zinc-400">{slice.label}</span>
            <span className="font-medium">{slice.value}</span>
          </div>
        ))}
      </div>

      {tooltip && hoverIdx !== null && (
        <ChartTooltip
          visible
          x={tooltipPos.x}
          y={tooltipPos.y}
          content={
            <div>
              <span className="font-medium">{slices[hoverIdx].label}</span>:{" "}
              {slices[hoverIdx].value} ({Math.round(slices[hoverIdx].pct * 100)}%)
            </div>
          }
        />
      )}
    </div>
  );
}

ChartPie.displayName = "ChartPie";

import { useMemo } from "react";
import { cn } from "../../utils/cn";
import { createLinearScale, monotonePath } from "./chart.utils";
import type { ChartSparklineProps } from "./Chart.types";

export function ChartSparkline({
  data,
  width = 120,
  height = 32,
  color = "#3b82f6",
  className,
}: ChartSparklineProps) {
  const d = useMemo(() => {
    if (data.length < 2) return "";
    const min = Math.min(...data);
    const max = Math.max(...data);
    const xScale = createLinearScale([0, data.length - 1], [1, width - 1]);
    const yScale = createLinearScale([min, max], [height - 2, 2]);
    const points: [number, number][] = data.map((v, i) => [xScale(i), yScale(v)]);
    return monotonePath(points);
  }, [data, width, height]);

  return (
    <svg
      width={width}
      height={height}
      className={cn("inline-block", className)}
      data-react-fancy-chart-sparkline=""
    >
      <path d={d} fill="none" stroke={color} strokeWidth={1.5} strokeLinecap="round" />
    </svg>
  );
}

