    const [value, setValue] = useControllableState(
      controlledValue,
      defaultValue,
      onChange,
    );
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    const handleSubmit = useCallback(() => {
      if (!value.trim() || disabled) return;
      onSubmit?.(value);
      setValue("");
