import { useMemo, useState } from 'react';
import {
    Badge,
    Button,
    Callout,
    Card,
    cn,
    Heading,
    Modal,
    Progress,
    Text,
} from '@particle-academy/react-fancy';
import {
    QuestionRenderer,
    type AnswerValue,
    answerValueToPayload,
} from './QuestionRenderer';
import type { AnswerInput, Test, TestAttempt } from '../types';

export interface TestRunnerProps {
    test: Test;
    onSubmit: (answers: AnswerInput[]) => Promise<TestAttempt>;
    onFinished?: (attempt: TestAttempt) => void;
}

export function TestRunner({ test, onSubmit, onFinished }: TestRunnerProps) {
    const questions = useMemo(() => test.questions ?? [], [test.questions]);
    const [answers, setAnswers] = useState<Record<number, AnswerValue>>({});
    const [submitting, setSubmitting] = useState(false);
    const [result, setResult] = useState<TestAttempt | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [confirmOpen, setConfirmOpen] = useState(false);

    const answeredCount = Object.values(answers).filter(
        (a) => a !== null && a !== undefined,
    ).length;
    const percent = questions.length
        ? Math.round((answeredCount / questions.length) * 100)
        : 0;
    const allAnswered = answeredCount === questions.length && questions.length > 0;

    async function handleSubmit(): Promise<void> {
        setConfirmOpen(false);
        setSubmitting(true);
        setError(null);
        try {
            const payload: AnswerInput[] = questions.map(
                (q) => answerValueToPayload(q.id, answers[q.id] ?? null) as AnswerInput,
            );
            const attempt = await onSubmit(payload);
            setResult(attempt);
            onFinished?.(attempt);
        } catch (e) {
            const message = e instanceof Error ? e.message : String(e);
            setError(message);
        } finally {
            setSubmitting(false);
        }
    }

    if (result) {
        return <TestResult attempt={result} />;
    }

    return (
        <>
            <Card
                variant="outlined"
                padding="none"
                className="!rounded-xl !shadow-sm overflow-hidden"
            >
                <div className="px-6 py-5 border-b border-secondary-200">
                    <div className="flex items-start justify-between gap-4">
                        <div>
                            <Heading as="h1" size="xl" weight="bold">
                                {test.title}
                            </Heading>
                            {test.description && (
                                <Text className="!mt-1" color="muted">
                                    {test.description}
                                </Text>
                            )}
                        </div>
                        <div className="flex flex-col items-end gap-2">
                            {test.is_final && (
                                <Badge color="amber" variant="soft" size="md">
                                    Final exam
                                </Badge>
                            )}
                            <Text size="xs" color="muted">
                                Pass at {test.passing_score}%
                            </Text>
                        </div>
                    </div>

                    <div className="mt-4 grid gap-1.5">
                        <Progress
                            value={percent}
                            max={100}
                            color="red"
                            size="sm"
                        />
                        <div className="flex items-center justify-between">
                            <Text size="xs" color="muted">
                                {answeredCount} of {questions.length} answered
                            </Text>
                            <Text size="xs" weight="semibold" className="!text-brand">
                                {percent}%
                            </Text>
                        </div>
                    </div>
                </div>

                <div className="px-6 py-6 grid gap-5">
                    {questions.map((q, i) => (
                        <Card
                            key={q.id}
                            variant="outlined"
                            padding="md"
                            className="!rounded-lg"
                        >
                            <div className="flex items-center justify-between mb-3">
                                <Text size="xs" weight="semibold" className="uppercase tracking-wide" color="muted">
                                    Question {i + 1} of {questions.length}
                                </Text>
                                <Badge color="zinc" variant="soft" size="sm">
                                    {q.points} pt{q.points === 1 ? '' : 's'}
                                </Badge>
                            </div>
                            <QuestionRenderer
                                question={q}
                                value={answers[q.id] ?? null}
                                onChange={(next) =>
                                    setAnswers((prev) => ({ ...prev, [q.id]: next }))
                                }
                            />
                        </Card>
                    ))}
                </div>

                {error && (
                    <div className="px-6 pb-4">
                        <Callout color="red">{error}</Callout>
                    </div>
                )}

                <div className="px-6 py-4 border-t border-secondary-200 bg-secondary-50/50 flex items-center justify-between gap-3">
                    <Text size="sm" color="muted">
                        {allAnswered
                            ? "You've answered every question."
                            : `${questions.length - answeredCount} question${questions.length - answeredCount === 1 ? '' : 's'} remaining`}
                    </Text>
                    <Button
                        loading={submitting}
                        disabled={submitting || answeredCount === 0}
                        onClick={() => setConfirmOpen(true)}
                        className="!bg-brand hover:!bg-primary-600 disabled: !text-white !font-semibold !px-6 !py-2.5 !rounded-md !shadow-sm"
                    >
                        {submitting ? 'Submitting…' : 'Submit test'}
                    </Button>
                </div>
            </Card>

            <Modal open={confirmOpen} onClose={() => setConfirmOpen(false)} size="sm">
                <Card variant="flat" padding="lg">
                    <Heading as="h2" size="lg" weight="bold">
                        Submit your answers?
                    </Heading>
                    <Text color="muted" className="!mt-2">
                        {allAnswered
                            ? `You've answered all ${questions.length} questions. You can't change your answers after submitting.`
                            : `You have ${questions.length - answeredCount} unanswered question${questions.length - answeredCount === 1 ? '' : 's'}. Unanswered questions count as zero.`}
                    </Text>
                    <div className="mt-6 flex justify-end gap-3">
                        <Button
                            variant="ghost"
                            onClick={() => setConfirmOpen(false)}
                            className="hover:!text-brand !px-4 !py-2"
                        >
                            Keep working
                        </Button>
                        <Button
                            onClick={handleSubmit}
                            className="!bg-brand hover:!bg-primary-600 !text-white !font-semibold !px-5 !py-2 !rounded-md"
                        >
                            Submit
                        </Button>
                    </div>
                </Card>
            </Modal>
        </>
    );
}

function TestResult({ attempt }: { attempt: TestAttempt }) {
    const passed = attempt.passed === true;
    const pending = attempt.passed === null;
    const score = attempt.score !== null ? Number(attempt.score) : null;

    return (
        <Card
            variant="outlined"
            padding="none"
            className="!rounded-xl !shadow-sm overflow-hidden"
        >
            <div
                className={cn(
                    'px-6 py-5',
                    pending
                            ? 'bg-blue-50 dark:bg-blue-950/40'
                            : passed
                              ? 'bg-emerald-50 dark:bg-emerald-950/40'
                              : 'bg-red-50 dark:bg-red-950/40',
                )}
            >
                <div className="flex items-center gap-3">
                    <div
                        className={cn(
                            'flex h-12 w-12 items-center justify-center rounded-full text-xl font-bold',
                            pending
                                ? 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200'
                                : passed
                                ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-200'
                                : 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200',
                        )}
                    >
                        {pending ? '…' : passed ? '✓' : '✕'}
                    </div>
                    <div>
                        <Heading as="h2" size="xl" weight="bold">
                            {pending ? 'Awaiting grading' : passed ? 'You passed!' : 'Did not pass'}
                        </Heading>
                        <Text className="!mt-0.5" color="muted">
                            {pending
                                ? 'Some answers require manual review.'
                                : passed
                                ? 'Nice work. Your certificate is being issued.'
                                : 'Review the material and try again.'}
                        </Text>
                    </div>
                </div>
            </div>

            <div className="px-6 py-5 grid sm:grid-cols-3 gap-4">
                <Stat label="Score" value={score !== null ? `${score}%` : '—'} highlight />
                <Stat
                    label="Points awarded"
                    value={
                        attempt.points_awarded !== null && attempt.max_score !== null
                            ? `${attempt.points_awarded} / ${attempt.max_score}`
                            : '—'
                    }
                />
                <Stat label="Attempt" value={`#${attempt.attempt_number}`} />
            </div>
        </Card>
    );
}

function Stat({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
    return (
        <div className="rounded-lg border border-secondary-200 bg-secondary-50/50 px-4 py-3">
            <Text size="xs" weight="semibold" className="uppercase tracking-wide" color="muted">
                {label}
            </Text>
            <div
                className={cn(
                    'mt-1 text-2xl font-bold',
                    highlight ? 'text-brand' : 'text-secondary-900',
                )}
            >
                {value}
            </div>
        </div>
    );
}

import {
    CheckboxGroup,
    RadioGroup,
    Text,
    Textarea,
} from '@particle-academy/react-fancy';
import type { Question } from '../types';

export type AnswerValue =
    | { kind: 'option_id'; value: number }
    | { kind: 'option_ids'; value: number[] }
    | { kind: 'text'; value: string }
    | null;

export interface QuestionRendererProps {
    question: Question;
    value: AnswerValue;
    onChange: (next: AnswerValue) => void;
    disabled?: boolean;
}

export function QuestionRenderer({
    question,
    value,
    onChange,
    disabled,
}: QuestionRendererProps) {
    const options = question.options ?? [];

    if (question.type === 'multiple_choice' || question.type === 'true_false') {
        const selected =
            value?.kind === 'option_id' ? String(value.value) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <RadioGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_id', value: Number(next) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    if (question.type === 'multiple_select') {
        const selected =
            value?.kind === 'option_ids' ? value.value.map(String) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <Text size="sm" color="muted">
                    Select all that apply.
                </Text>
                <CheckboxGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_ids', value: next.map(Number) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    // short_answer
    const text = value?.kind === 'text' ? value.value : '';
    return (
        <div className="grid gap-3">
            <Text weight="semibold" className="!text-base">
                {question.prompt}
            </Text>
            <Textarea
                value={text}
                onChange={(e) =>
                    onChange({
                        kind: 'text',
                        value: (e.target as HTMLTextAreaElement).value,
                    })
                }
                disabled={disabled}
                rows={4}
                placeholder="Type your answer here…"
            />
        </div>
    );
}

export function answerValueToPayload(
    questionId: number,
    value: AnswerValue,
): { question_id: number; answer: unknown } {
    if (!value) return { question_id: questionId, answer: null };
    switch (value.kind) {
        case 'option_id':
            return { question_id: questionId, answer: { option_id: value.value } };
        case 'option_ids':
            return { question_id: questionId, answer: { option_ids: value.value } };
        case 'text':
            return { question_id: questionId, answer: { text: value.value } };
    }
}

import { Button, Checkbox, Form, Input, Select, Textarea } from "@particle-academy/react-fancy";
import type { FieldMode } from "@particle-academy/react-fancy";
import type { CreateReviewInput } from "@particle-academy/fancy-git";

export interface CreateReviewFormProps {
  value: CreateReviewInput;
  onChange: (value: CreateReviewInput) => void;
  onSubmit?: (value: CreateReviewInput) => void;
  branches: string[];
  pending?: boolean;
  /** `"view"` renders the draft as text — see {@link CommitComposer}. */
  mode?: FieldMode;
  className?: string;
}

/**
 * Source, target, title, body → the intent to open a review.
 *
 * The one validation the component makes itself: **a branch cannot be merged
 * into itself.** The provider would reject it too, but only after a round trip
 * that spends a token and a rate-limit unit, and reports it in its own wording.
 * Everything else is the host's to judge.
 */
export function CreateReviewForm({
  value,
  onChange,
  onSubmit,
  branches,
  pending,
  mode,
  className,
}: CreateReviewFormProps) {
  const sameBranch = Boolean(value.sourceBranch) && value.sourceBranch === value.targetBranch;

  return (
    <Form
      className={className}
      mode={mode}
      data-git-create-review=""
      onSubmit={(event) => {
        event.preventDefault();
        onSubmit?.(value);
      }}
    >
      <Input
        label="Title"
        required
        value={value.title}
        onValueChange={(title) => onChange({ ...value, title })}
        placeholder="Fix the merge point"
      />
      <Select
        label="Source"
        list={branches}
        value={value.sourceBranch}
        onValueChange={(sourceBranch) => onChange({ ...value, sourceBranch })}
      />
      <Select
        label="Target"
        list={branches}
        value={value.targetBranch}
        onValueChange={(targetBranch) => onChange({ ...value, targetBranch })}
        error={sameBranch ? "Pick a different branch — a branch cannot merge into itself." : undefined}
      />
      <Textarea
        label="Body"
        rows={3}
        value={value.body ?? ""}
        onValueChange={(body) => onChange({ ...value, body })}
      />
      <Checkbox
        label="Draft"
        description="Draft reviews do not notify reviewers — the right default for work in progress."
        checked={value.draft ?? false}
        onCheckedChange={(draft) => onChange({ ...value, draft })}
      />
      <Button type="submit" size="sm" disabled={pending || !value.title.trim() || sameBranch}>
        Review creation proposal
      </Button>
    </Form>
  );
}

import { Badge, Button, Card, cn, Heading, Progress, Text, type Color } from '@particle-academy/react-fancy';
import type { Course, Curriculum } from '../types';

/** Per-slot class overrides. Every slot also carries a stable `data-*` handle. */
export interface CurriculumOverviewClassNames {
    root?: string;
    hero?: string;
    heroMeta?: string;
    grid?: string;
    card?: string;
    cardIndex?: string;
    cardTitle?: string;
    cardDescription?: string;
    cardMeta?: string;
    cardProgress?: string;
    cardAction?: string;
}

export interface CurriculumOverviewProps {
    curriculum: Curriculum;
    courseProgress?: Record<number, number>;
    onEnroll?: (curriculum: Curriculum) => void;
    onOpenCourse?: (course: Course) => void;
    /** Accent for buttons, progress and highlights. Any react-fancy Color. */
    accent?: Color;
    /** Class for the root element. */
    className?: string;
    /** Class overrides per slot. */
    classNames?: CurriculumOverviewClassNames;
    /** Label for the primary action on an unstarted course. */
    startLabel?: string;
}

/**
 * A curriculum and its courses.
 *
 * **Two styling rules this component exists to demonstrate, having broken both:**
 *
 * 1. **Colour comes from react-fancy PROPS**, never class overrides. An earlier
 *    version forced `!bg-brand hover:!bg-primary-600` — custom palette tokens a
 *    consumer has to define — so on a host that had not defined them the classes
 *    resolved to nothing and every button rendered as a bare grey slab.
 * 2. **Nothing cosmetic is forced with `!`.** A host has to be able to restyle
 *    this. Radius, shadow and spacing are left to react-fancy's defaults or to
 *    the `classNames` slots; an `!important` in a library is a decision taken
 *    away from the person consuming it.
 *
 * Restyle it three ways, in increasing specificity: `accent` for the colour,
 * `classNames` for per-slot classes, or the `data-classroom-*` attributes from
 * your own stylesheet.
 */
export function CurriculumOverview({
    curriculum,
    courseProgress = {},
    onEnroll,
    onOpenCourse,
    accent = 'violet',
    className,
    classNames = {},
    startLabel = 'Start',
}: CurriculumOverviewProps) {
    const courses = curriculum.courses ?? [];
    const started = courses.filter((c) => (courseProgress[c.id] ?? 0) > 0).length;
    const totalMinutes = courses.reduce((sum, c) => sum + (c.estimated_minutes ?? 0), 0);

    return (
        <div
            className={cn('grid gap-6', className, classNames.root)}
            data-classroom-curriculum={curriculum.slug}
        >
            <Card variant="outlined" padding="lg" className={classNames.hero} data-classroom-hero="">
                <div className="grid gap-3">
                    <div className={cn('flex flex-wrap items-center gap-2', classNames.heroMeta)}>
                        <Badge color={curriculum.is_published ? 'emerald' : 'zinc'} variant="soft" size="sm">
                            {curriculum.is_published ? 'Published' : 'Draft'}
                        </Badge>
                        <Badge color="zinc" variant="soft" size="sm">
                            {courses.length} course{courses.length === 1 ? '' : 's'}
                        </Badge>
                        {totalMinutes > 0 && (
                            <Badge color="zinc" variant="soft" size="sm">
                                ~{Math.round(totalMinutes / 60)}h
                            </Badge>
                        )}
                        {started > 0 && (
                            <Badge color={accent} variant="soft" size="sm">
                                {started} in progress
                            </Badge>
                        )}
                    </div>

                    <Heading as="h1" size="2xl" weight="bold">
                        {curriculum.title}
                    </Heading>

                    {curriculum.description && (
                        <Text color="muted" className="max-w-2xl">
                            {curriculum.description}
                        </Text>
                    )}

                    {onEnroll && (
                        <div className="pt-1">
                            <Button
                                color={accent}
                                size="lg"
                                iconTrailing="arrow-right"
                                onClick={() => onEnroll(curriculum)}
                                data-classroom-enroll=""
                            >
                                Enroll in curriculum
                            </Button>
                        </div>
                    )}
                </div>
            </Card>

            <div
                className={cn('grid gap-4 sm:grid-cols-2 lg:grid-cols-3', classNames.grid)}
                data-classroom-course-grid=""
            >
                {courses.map((course, index) => {
                    const percent = courseProgress[course.id] ?? 0;
                    const complete = percent >= 100;

                    return (
                        <Card
                            key={course.id}
                            variant="outlined"
                            padding="lg"
                            className={cn('flex flex-col transition hover:-translate-y-0.5', classNames.card)}
                            data-classroom-course={course.slug}
                            data-classroom-progress={percent}
                        >
                            <div className="flex items-baseline gap-2.5">
                                <span
                                    className={cn('text-sm font-semibold tabular-nums opacity-60', classNames.cardIndex)}
                                    data-classroom-course-index=""
                                >
                                    {String(index + 1).padStart(2, '0')}
                                </span>
                                <Heading as="h3" size="md" weight="bold" className={classNames.cardTitle}>
                                    {course.title}
                                </Heading>
                            </div>

                            {course.description && (
                                <Text
                                    color="muted"
                                    size="sm"
                                    className={cn('mt-2 line-clamp-3', classNames.cardDescription)}
                                >
                                    {course.description}
                                </Text>
                            )}

                            {(course.estimated_minutes || complete) && (
                                <div className={cn('mt-3 flex flex-wrap gap-1.5', classNames.cardMeta)}>
                                    {course.estimated_minutes ? (
                                        <Badge color="zinc" variant="soft" size="sm">
                                            {course.estimated_minutes} min
                                        </Badge>
                                    ) : null}
                                    {complete && (
                                        <Badge color="emerald" variant="soft" size="sm">
                                            Complete
                                        </Badge>
                                    )}
                                </div>
                            )}

                            {/*
                             * A 0%-wide bar under every card is noise — it says
                             * nothing the "Start" button does not already say. The
                             * bar earns its place once there is progress to show.
                             */}
                            {percent > 0 && (
                                <div className={cn('mt-4', classNames.cardProgress)}>
                                    <Progress
                                        value={percent}
                                        max={100}
                                        color={complete ? 'emerald' : accent}
                                        size="sm"
                                        showValue
                                    />
                                </div>
                            )}

                            {onOpenCourse && (
                                <div className={cn('mt-auto pt-5', classNames.cardAction)}>
                                    <Button
                                        // Always the accent. A zinc ghost made
                                        // the primary action on every card read
                                        // as disabled — an unstarted course is
                                        // the one thing you most want clicked.
                                        color={accent}
                                        variant={percent > 0 ? 'default' : 'ghost'}
                                        iconTrailing="chevron-right"
                                        className="w-full justify-center"
                                        onClick={() => onOpenCourse(course)}
                                        data-classroom-open-course={course.slug}
                                    >
                                        {complete ? 'Review' : percent > 0 ? 'Continue' : startLabel}
                                    </Button>
                                </div>
                            )}
                        </Card>
                    );
                })}
            </div>
        </div>
    );
}

import { type ReactNode } from "react";
import type { Deck, DeckOp, SlideElement, Theme } from "../../types";
import { type IdStrategy } from "../../hooks/use-deck-state";
import { type ToolbarApi } from "../EditorToolbar";
import { DeckEditorProvider } from "./DeckEditorProvider";
import {
    DeckEditorCanvas,
    DeckEditorInspector,
    DeckEditorNotes,
    DeckEditorRail,
    DeckEditorStatusBar,
    DeckEditorToolbar,
} from "./slots";

export interface DeckEditorProps {
    /** Controlled deck — pair with `onChange`. */
    value: Deck;
    onChange: (next: Deck) => void;
    /** Called after every mutation with the op that produced it — feed into AgentPanel / audit log. */
    onOp?: (op: DeckOp) => void;
    /** Called when the user clicks Present. The host decides how to open the SlideViewer. */
    onPresent?: () => void;
    /** Controlled selected slide id. Uncontrolled by default. */
    selectedSlideId?: string | null;
    onSelectedSlideChange?: (id: string | null) => void;
    /**
     * Renderer for chart / code / table / embed elements (the elements this
     * package doesn't render natively). Defaults to the built-in
     * `defaultElementRegistry` so the editor is full out of the box; pass your
     * own to override (it wins entirely). The optional-peer hosts (chart/code)
     * load fancy-echarts/fancy-code via guarded dynamic imports, so the base
     * bundle never statically requires them.
     */
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /** Hide the slide rail (e.g. for embedded use). */
    hideRail?: boolean;
    /** Hide the speaker notes panel. */
    hideNotes?: boolean;
    /** Hide the toolbar. */
    hideToolbar?: boolean;
    /** Hide the inspector. */
    hideInspector?: boolean;
    /** Optional extra content on the toolbar's trailing edge. */
    toolbarExtra?: ReactNode;
    /**
     * Theme list the toolbar's picker offers. Defaults to the built-in themes;
     * pass user-authored themes (`[...builtinThemes, myTheme]`) to extend it.
     */
    themes?: Theme[];
    /** Who mints new slide/element ids. Defaults to `"client"`. See {@link IdStrategy}. */
    idStrategy?: IdStrategy;
    /**
     * Compose the toolbar yourself. Receives the toolbar action surface and
     * returns the toolbar node — typically built from `EditorToolbar` + its slot
     * components (`.Title` / `.Insert` / `.Themes` / `.Trailing`). When omitted,
     * the default toolbar is rendered.
     */
    renderToolbar?: (api: ToolbarApi) => ReactNode;
    className?: string;
}

/**
 * Full deck editor — toolbar + rail + canvas + inspector + speaker notes.
 *
 * Controlled (`value` + `onChange`). State is intentionally simple: deck
 * lives in the consumer, the editor just renders a view + dispatches ops.
 * The same `DeckOp` enum that the agent bridge speaks runs through here —
 * agents and humans drive identical mutations.
 *
 * This is the **default layout** over a shared controller. To build a bespoke
 * editor — reposition panels, drop an app panel *beside* them, restyle each —
 * compose the parts yourself: `<DeckEditor.Provider>` runs the controller, and
 * `DeckEditor.Toolbar` / `.Rail` / `.Canvas` / `.Inspector` / `.Notes` /
 * `.StatusBar` are slots that share it (selection included). `useDeckEditor()`
 * exposes the same controller to any panel of your own.
 */
export function DeckEditor({
    value,
    onChange,
    onOp,
    onPresent,
    selectedSlideId,
    onSelectedSlideChange,
    renderElement,
    hideRail = false,
    hideNotes = false,
    hideToolbar = false,
    hideInspector = false,
    toolbarExtra,
    themes,
    idStrategy = "client",
    renderToolbar,
    className,
}: DeckEditorProps) {
    return (
        <DeckEditorProvider
            value={value}
            onChange={onChange}
            onOp={onOp}
            onPresent={onPresent}
            selectedSlideId={selectedSlideId}
            onSelectedSlideChange={onSelectedSlideChange}
            renderElement={renderElement}
            themes={themes}
            idStrategy={idStrategy}
        >
            <div
                className={`fs-editor flex h-full w-full flex-col bg-zinc-100 dark:bg-zinc-950 ${className ?? ""}`}
                data-fancy-slides-editor={value.id}
            >
                {!hideToolbar && <DeckEditorToolbar renderToolbar={renderToolbar} extra={toolbarExtra} />}

                <div className="flex min-h-0 flex-1">
                    {!hideRail && <DeckEditorRail />}

                    <div className="flex min-w-0 flex-1 flex-col">
                        <DeckEditorCanvas />
                        {!hideNotes && <DeckEditorNotes />}
                    </div>

                    {!hideInspector && <DeckEditorInspector />}
                </div>
            </div>
        </DeckEditorProvider>
    );
}

// Compound slot statics — match the house style (direct assignment, like
// EditorToolbar.Title) so consumers compose `<DeckEditor.Provider>` +
// `<DeckEditor.Rail>` etc.
DeckEditor.Provider = DeckEditorProvider;
DeckEditor.Toolbar = DeckEditorToolbar;
DeckEditor.Rail = DeckEditorRail;
DeckEditor.Canvas = DeckEditorCanvas;
DeckEditor.Inspector = DeckEditorInspector;
DeckEditor.Notes = DeckEditorNotes;
DeckEditor.StatusBar = DeckEditorStatusBar;

import { useCallback, useEffect, useMemo, useState, type ReactNode } from "react";
import type {
    ChartElement,
    CodeElement,
    Deck,
    DeckOp,
    ImageElement,
    ShapeElement,
    ShapeKind,
    Slide as SlideData,
    SlideElement,
    TableElement,
    TextElement,
    Theme,
} from "../../types";
import { resolveTheme } from "../../theme/theme-utils";
import { builtinThemes } from "../../theme/default-theme";
import { elementId } from "../../utils/ids";
import { useDeckState, type IdStrategy } from "../../hooks/use-deck-state";
import { migrateDeck } from "../../utils/serialize";
import { chartStarterOption, type ChartKind } from "../../utils/chart-presets";
import { type ToolbarApi } from "../EditorToolbar";
import { defaultElementRegistry } from "../../registry";
import { DeckEditorContext, type DeckEditorContextValue } from "./context";

export interface DeckEditorProviderProps {
    /** Controlled deck — pair with `onChange`. */
    value: Deck;
    onChange: (next: Deck) => void;
    /** Called after every mutation with the op that produced it — feed into AgentPanel / audit log. */
    onOp?: (op: DeckOp) => void;
    /** Called when the user clicks Present. The host decides how to open the SlideViewer. */
    onPresent?: () => void;
    /** Controlled selected slide id. Uncontrolled by default. */
    selectedSlideId?: string | null;
    onSelectedSlideChange?: (id: string | null) => void;
    /**
     * Renderer for chart / code / table / embed elements. Defaults to the
     * built-in `defaultElementRegistry`; pass your own to override (it wins
     * entirely).
     */
    renderElement?: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /**
     * Theme list the toolbar's picker offers. Defaults to the built-in themes;
     * pass user-authored themes (`[...builtinThemes, myTheme]`) to extend it.
     */
    themes?: Theme[];
    /** Who mints new slide/element ids. Defaults to `"client"`. See {@link IdStrategy}. */
    idStrategy?: IdStrategy;
    /** The composed editor — `DeckEditor.*` slots plus any app chrome. */
    children: ReactNode;
}

/**
 * Runs the editor controller — op surface, slide + element selection, insert
 * handlers, the toolbar action surface — and provides it to every
 * `DeckEditor.*` slot via {@link useDeckEditor}. `<DeckEditor>` mounts this for
 * you with its default layout; mount it yourself to compose a bespoke editor
 * from the slot parts (and your own panels) sharing one controller.
 *
 * Controlled (`value` + `onChange`). The same `DeckOp` enum the agent bridge
 * speaks runs through here — agents and humans drive identical mutations.
 */
export function DeckEditorProvider({
    value,
    onChange,
    onOp,
    onPresent,
    selectedSlideId: controlledSlideId,
    onSelectedSlideChange,
    renderElement = defaultElementRegistry,
    themes,
    idStrategy = "client",
    children,
}: DeckEditorProviderProps) {
    const deck = value;
    const ops = useDeckState({ value: deck, onChange, onOp, idStrategy });

    // Migrate an older-schema deck forward on load and emit one normalized
    // onChange so the consumer can persist the upgraded shape. migrateDeck is
    // idempotent (returns the same ref once current), so this won't loop. Keyed
    // on deck id: a freshly-loaded deck re-runs the migration.
    useEffect(() => {
        const migrated = migrateDeck(value);
        if (migrated !== value) onChange(migrated);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [value.id]);

    // Slide selection — controlled or internal.
    const [internalSlideId, setInternalSlideId] = useState<string | null>(deck.slides[0]?.id ?? null);
    const isControlled = controlledSlideId !== undefined;
    const slideId = isControlled ? controlledSlideId! : internalSlideId;
    const setSlideId = useCallback(
        (id: string | null) => {
            if (!isControlled) setInternalSlideId(id);
            onSelectedSlideChange?.(id);
        },
        [isControlled, onSelectedSlideChange],
    );

    // If the selected slide disappears (deletion / agent ops), fall back to the first slide.
    useEffect(() => {
        if (slideId && !deck.slides.some((s) => s.id === slideId)) {
            setSlideId(deck.slides[0]?.id ?? null);
        } else if (!slideId && deck.slides.length > 0) {
            setSlideId(deck.slides[0]!.id);
        }
    }, [deck.slides, slideId, setSlideId]);

    const slide: SlideData | undefined = deck.slides.find((s) => s.id === slideId);

    // Element selection — internal, resets on slide change.
    const [elementIdSelected, setElementIdSelected] = useState<string | null>(null);
    useEffect(() => {
        setElementIdSelected(null);
    }, [slideId]);

    const selectedElement = slide && elementIdSelected ? slide.elements.find((e) => e.id === elementIdSelected) ?? null : null;

    // ─── Toolbar insert handlers ───────────────────────────────────────────
    const insertEl = useCallback(
        (element: Omit<SlideElement, "id">) => {
            if (!slide) return;
            const id = ops.addElement(slide.id, { id: elementId(), ...element });
            setElementIdSelected(id);
        },
        [slide, ops],
    );

    const insertText = useCallback(
        () =>
            insertEl({
                type: "text",
                x: 0.1,
                y: 0.4,
                w: 0.8,
                h: 0.2,
                content: "Click to edit",
                format: "plain",
                style: { fontSize: 36, weight: "semibold", align: "center" },
            } as Omit<TextElement, "id">),
        [insertEl],
    );

    const insertImage = useCallback(
        () =>
            insertEl({
                type: "image",
                x: 0.25,
                y: 0.25,
                w: 0.5,
                h: 0.5,
                src: "https://placehold.co/600x400?text=Image",
                fit: "contain",
            } as Omit<ImageElement, "id">),
        [insertEl],
    );

    const insertShape = useCallback(
        (shape: ShapeKind) =>
            insertEl({
                type: "shape",
                shape,
                x: 0.3,
                y: 0.3,
                w: 0.4,
                h: 0.4,
                fill: shape === "line" || shape === "arrow" ? "none" : "rgba(139,92,246,0.15)",
                stroke: "#8b5cf6",
                strokeWidth: 2,
            } as Omit<ShapeElement, "id">),
        [insertEl],
    );

    const insertChart = useCallback(
        (kind: ChartKind = "bar") =>
            insertEl({
                type: "chart",
                x: 0.1,
                y: 0.2,
                w: 0.8,
                h: 0.6,
                option: chartStarterOption(kind),
            } as Omit<ChartElement, "id">),
        [insertEl],
    );

    const insertCode = useCallback(
        () =>
            insertEl({
                type: "code",
                x: 0.15,
                y: 0.2,
                w: 0.7,
                h: 0.6,
                code: "function hello() {\n  return \"world\";\n}\n",
                language: "typescript",
                codeTheme: "dark",
            } as Omit<CodeElement, "id">),
        [insertEl],
    );

    const insertTable = useCallback(
        () =>
            insertEl({
                type: "table",
                x: 0.15,
                y: 0.25,
                w: 0.7,
                h: 0.5,
                columns: [
                    { key: "name", label: "Name" },
                    { key: "value", label: "Value" },
                ],
                rows: [
                    { name: "Alpha", value: 12 },
                    { name: "Beta", value: 34 },
                    { name: "Gamma", value: 56 },
                ],
            } as Omit<TableElement, "id">),
        [insertEl],
    );

    const insert = useMemo<DeckEditorContextValue["insert"]>(
        () => ({ text: insertText, image: insertImage, shape: insertShape, chart: insertChart, code: insertCode, table: insertTable }),
        [insertText, insertImage, insertShape, insertChart, insertCode, insertTable],
    );

    const themeList = themes ?? Object.values(builtinThemes);

    // The toolbar action surface — handed to a custom `renderToolbar`, and the
    // source for the default toolbar too.
    const toolbarApi: ToolbarApi = useMemo(
        () => ({
            title: { value: deck.title, onChange: (t) => ops.setTitle(t) },
            theme: { name: deck.theme.name, themes: themeList, onApply: (t) => ops.applyTheme(t) },
            insert,
            present: onPresent,
            disabled: !slide,
        }),
        [deck.title, deck.theme.name, themeList, ops, insert, onPresent, slide],
    );

    const ctx = useMemo<DeckEditorContextValue>(
        () => ({
            deck,
            theme: resolveTheme(deck.theme),
            ops,
            slideId,
            setSlideId,
            slide,
            selectedElementId: elementIdSelected,
            setSelectedElementId: setElementIdSelected,
            selectedElement,
            insert,
            toolbarApi,
            renderElement,
            themes: themeList,
            onPresent,
        }),
        [deck, ops, slideId, setSlideId, slide, elementIdSelected, selectedElement, insert, toolbarApi, renderElement, themeList, onPresent],
    );

    return <DeckEditorContext.Provider value={ctx}>{children}</DeckEditorContext.Provider>;
}

import { createContext, useContext, type ReactNode } from "react";
import type { Deck, ShapeKind, Slide as SlideData, SlideElement, Theme } from "../../types";
import type { DeckStateApi } from "../../hooks/use-deck-state";
import type { ChartKind, ToolbarApi } from "../EditorToolbar";

/**
 * The editor's insert action surface — one entry per element type the toolbar
 * can add. Each inserts a starter element on the active slide and selects it.
 */
export interface DeckEditorInsertApi {
    text(): void;
    image(): void;
    shape(kind: ShapeKind): void;
    chart(kind?: ChartKind): void;
    code(): void;
    table(): void;
}

/**
 * The shared editor controller — everything a slot part needs to render itself
 * and drive the deck. Provided by {@link DeckEditorProvider} (and therefore by
 * `<DeckEditor>` itself), read by every `DeckEditor.*` slot via
 * {@link useDeckEditor}. Selection lives here, so all slots — and any app panel
 * the host drops alongside them — share one controller rather than re-deriving
 * their own.
 */
export interface DeckEditorContextValue {
    /** The controlled deck (== the provider's `value`). */
    deck: Deck;
    /** Resolved theme (`resolveTheme(deck.theme)`) — defaults filled in. */
    theme: Theme;
    /** The op surface from `useDeckState`. */
    ops: DeckStateApi;
    /** Currently-selected slide id. */
    slideId: string | null;
    setSlideId: (id: string | null) => void;
    /** The currently-selected slide, if any. */
    slide: SlideData | undefined;
    /** Currently-selected element id (shared across slots — the crux of #11). */
    selectedElementId: string | null;
    setSelectedElementId: (id: string | null) => void;
    /** The currently-selected element, if any. */
    selectedElement: SlideElement | null;
    /** Insert handlers — add a starter element of each type to the active slide. */
    insert: DeckEditorInsertApi;
    /** The toolbar action surface (title / theme / insert / present / disabled). */
    toolbarApi: ToolbarApi;
    /** Renderer for chart / code / table / embed elements. */
    renderElement: (element: SlideElement, slideWidthPx: number) => ReactNode | undefined;
    /** The theme list the picker offers (defaults to the built-ins). */
    themes: Theme[];
    /** Present handler, if the host wired one. */
    onPresent?: () => void;
}

export const DeckEditorContext = createContext<DeckEditorContextValue | null>(null);

/**
 * Read the shared editor controller. Must be called inside a
 * `<DeckEditor.Provider>` (which `<DeckEditor>` mounts for you) — throws a clear
 * error otherwise, mirroring `EditorToolbar`'s slot guard.
 */
export function useDeckEditor(): DeckEditorContextValue {
    const ctx = useContext(DeckEditorContext);
    if (!ctx) {
        throw new Error("useDeckEditor() (and DeckEditor.* slots) must be used inside <DeckEditor.Provider> (mounted for you by <DeckEditor>).");
    }
    return ctx;
}

