import React, { forwardRef, useEffect, useMemo, useState } from "react";
import type { EChartsOption } from "echarts";
import { useECharts } from "../hooks/use-echarts";
import type {
  EChartComponentProps,
  SeriesComponentProps,
  ChartDivProps,
} from "../types";

const DEFAULT_STYLE: React.CSSProperties = { width: "100%", height: 500 };

let glLoaded = false;
let glPromise: Promise<void> | null = null;

function loadEChartsGL(): Promise<void> {
  if (glLoaded) return Promise.resolve();
  if (!glPromise) {
    glPromise = import("echarts-gl")
      .then(() => {
        glLoaded = true;
      })
      .catch((err: unknown) => {
        console.warn("Failed to load echarts-gl for 3D charts:", err);
      });
  }
  return glPromise;
}

/** Wrapper that delays mount until echarts-gl is loaded */
function WithGL({ children, style, className }: { children: React.ReactNode; style?: React.CSSProperties; className?: string }) {
  const [ready, setReady] = useState(glLoaded);

  useEffect(() => {
    if (glLoaded) {
      setReady(true);
      return;
    }
    loadEChartsGL().then(() => setReady(true));
  }, []);

  if (!ready) {
    return (
      <div style={{ ...DEFAULT_STYLE, ...style, display: "flex", alignItems: "center", justifyContent: "center" }} className={className}>
        <span style={{ color: "#9ca3af", fontSize: 14 }}>Loading 3D engine...</span>
      </div>
    );
  }

  return <>{children}</>;
}

/**
 * EChart3D — 3D chart component that lazy-loads the bundled echarts-gl
 * engine on first mount (split into its own chunk to keep the main bundle small).
 */
const EChart3DInner = forwardRef<HTMLDivElement, EChartComponentProps>(
  (
    {
      option,
      theme,
      renderer,
      notMerge,
      lazyUpdate,
      showLoading,
      loadingOption,
      onEvents,
      autoResize = true,
      style,
      className,
      ...rest
    },
    _ref
  ) => {
    const { chartRef } = useECharts({
      option,
      theme,
      renderer,
      notMerge,
      lazyUpdate,
      showLoading,
      loadingOption,
      onEvents,
      autoResize,
    });

    return (
      <div
        ref={chartRef}
        style={{ ...DEFAULT_STYLE, ...style }}
        className={className}
        {...rest}
      />
    );
  }
);

EChart3DInner.displayName = "EChart3DInner";

const EChart3DBase = forwardRef<HTMLDivElement, EChartComponentProps>(
  (props, ref) => {
    const { style, className, ...rest } = props;
    return (
      <WithGL style={style} className={className}>
        <EChart3DInner ref={ref} style={style} className={className} {...rest} />
      </WithGL>
    );
  }
);

EChart3DBase.displayName = "EChart3D";

function create3DSeriesComponent(
  seriesType: string,
  displayName: string
): React.FC<SeriesComponentProps & ChartDivProps> {
  const Component: React.FC<SeriesComponentProps & ChartDivProps> = ({
    data,
    title,
    tooltip = true,
    seriesOptions = {},
    option: extraOption = {},
    style,
    className,
    ...rest
  }) => {
    const option = useMemo((): EChartsOption => {
      const base: any = {};

      if (title) {
        base.title = { text: title };
      }

      if (tooltip === true) {
        base.tooltip = {};
      } else if (tooltip && typeof tooltip === "object") {
        base.tooltip = tooltip;
      }

      if (["bar3D", "scatter3D", "line3D", "surface"].includes(seriesType)) {
        base.xAxis3D = { type: "value" };
        base.yAxis3D = { type: "value" };
        base.zAxis3D = { type: "value" };
        base.grid3D = {};
      }

      base.series = [{ type: seriesType, data, ...seriesOptions }];

      return { ...base, ...extraOption } as EChartsOption;
    }, [data, title, tooltip, seriesOptions, extraOption]);

    return (
      <EChart3DBase
        option={option}
        style={style}
        className={className}
        {...rest}
      />
    );
  };

  Component.displayName = displayName;
  return Component;
}

function createGlobeComponent(): React.FC<
  Omit<SeriesComponentProps, "data"> &
    ChartDivProps & { globe?: any; series?: any[] }
> {
  const Component: React.FC<
    Omit<SeriesComponentProps, "data"> &
      ChartDivProps & { globe?: any; series?: any[] }
  > = ({
    title,
    globe,
    series = [],
    option: extraOption = {},
    style,
    className,
    ...rest
  }) => {
    const option = useMemo((): EChartsOption => {
      const base: any = {};

      if (title) {
        base.title = { text: title };
      }

      base.globe = globe ?? {
        baseTexture: "",
        shading: "lambert",
        atmosphere: { show: true },
      };

      if (series.length > 0) {
        base.series = series;
      }

      return { ...base, ...extraOption } as EChartsOption;
    }, [title, globe, series, extraOption]);

    return (
      <EChart3DBase
        option={option}
        style={style}
        className={className}
        {...rest}
      />
    );
  };

  Component.displayName = "EChart3D.Globe";
  return Component;
}

export const EChart3D = Object.assign(EChart3DBase, {
  Bar: create3DSeriesComponent("bar3D", "EChart3D.Bar"),
  Scatter: create3DSeriesComponent("scatter3D", "EChart3D.Scatter"),
  Line: create3DSeriesComponent("line3D", "EChart3D.Line"),
  Surface: create3DSeriesComponent("surface", "EChart3D.Surface"),
  Globe: createGlobeComponent(),
});

import React, { forwardRef, useMemo } from "react";
import type { EChartsOption } from "echarts";
import { useECharts } from "../hooks/use-echarts";
import type { EChartBaseProps, ChartDivProps } from "../types";

export interface GraphicElement {
  type:
    | "rect"
    | "circle"
    | "ring"
    | "arc"
    | "polygon"
    | "polyline"
    | "path"
    | "image"
    | "text"
    | "group";
  left?: number | string;
  top?: number | string;
  right?: number | string;
  bottom?: number | string;
  shape?: Record<string, any>;
  style?: Record<string, any>;
  children?: GraphicElement[];
  onclick?: (e: any) => void;
  onmouseover?: (e: any) => void;
  onmouseout?: (e: any) => void;
  [key: string]: any;
}

export interface EChartGraphicProps
  extends Omit<EChartBaseProps, "option">,
    ChartDivProps,
    React.HTMLAttributes<HTMLDivElement> {
  elements: GraphicElement[];
  option?: Partial<EChartsOption>;
}

const DEFAULT_STYLE: React.CSSProperties = { width: "100%", height: 400 };

/**
 * EChartGraphic — for custom drawing via ECharts graphic layer.
 * Supports rect, circle, ring, arc, polygon, polyline, path, image, text, group elements.
 */
export const EChartGraphic = forwardRef<HTMLDivElement, EChartGraphicProps>(
  (
    {
      elements,
      option: extraOption = {},
      theme,
      renderer,
      notMerge,
      lazyUpdate,
      showLoading,
      loadingOption,
      onEvents,
      autoResize = true,
      style,
      className,
      ...rest
    },
    _ref
  ) => {
    const option = useMemo((): EChartsOption => {
      return {
        graphic: {
          elements,
        },
        ...extraOption,
      } as EChartsOption;
    }, [elements, extraOption]);

    const { chartRef } = useECharts({
      option,
      theme,
      renderer,
      notMerge,
      lazyUpdate,
      showLoading,
      loadingOption,
      onEvents,
      autoResize,
    });

    return (
      <div
        ref={chartRef}
        style={{ ...DEFAULT_STYLE, ...style }}
        className={className}
        {...rest}
      />
    );
  }
);

EChartGraphic.displayName = "EChartGraphic";

import { createContext, useContext } from "react";
import type { RefObject } from "react";
import type { RenderExtension } from "../ContentRenderer/extensions";

export interface EditorContextValue {
  contentRef: RefObject<HTMLDivElement | null>;
  exec: (command: string, arg?: string) => void;
  insertText: (text: string) => void;
  wrapSelection: (before: string, after: string) => void;
  outputFormat: "html" | "markdown";
  lineSpacing: number;
  placeholder?: string;
  /** Merged render extensions (global + instance). */
  extensions: RenderExtension[];
  /** Whether the raw-source view (textarea) is showing instead of the rich-text surface. */
  showSource: boolean;
  /** Toggle/set the raw-source view. */
  setShowSource: (showSource: boolean) => void;
  /** Initial HTML content to load into the editor on mount */
  _initialHtml: string;
  /** @internal Called by EditorContent on input events */
  _onInput: () => void;
  /** @internal Raw source value (`value` in `outputFormat`), for the source textarea. */
  _sourceValue: string;
  /** @internal Commit an edit made directly in the source textarea. */
  _onSourceInput: (value: string) => void;
}

export const EditorContext = createContext<EditorContextValue | null>(null);

export function useEditor(): EditorContextValue {
  const ctx = useContext(EditorContext);
  if (!ctx) {
    throw new Error("useEditor must be used within an <Editor> component");
  }
  return ctx;
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { marked } from "marked";
import { cn } from "../../utils/cn";
import { sanitizeHtml } from "../../utils/sanitize";
import { useControllableState } from "../../hooks";
import { EditorContext } from "./Editor.context";
import { EditorToolbar } from "./EditorToolbar";
import { EditorToolbarSeparator } from "./EditorToolbarSeparator";
import { EditorSourceToggle } from "./EditorSourceToggle";
import { EditorContent } from "./EditorContent";
import { htmlToMarkdown, detectFormat } from "./editor.utils";
import { mergeExtensions } from "../ContentRenderer/extensions";
import { ContentRenderer } from "../ContentRenderer/ContentRenderer";
import { useFieldMode } from "../inputs/mode/FieldMode.context";
import type { EditorProps } from "./Editor.types";

function toHtml(
  value: string,
  outputFormat: "html" | "markdown",
  unsafe: boolean,
  valueFormat: "markdown" | "html" | "auto" = "auto",
): string {
  if (!value) return "";
  const raw = (() => {
    // An explicit valueFormat is authoritative — the sniff misclassifies
    // markdown that merely MENTIONS HTML-ish snippets (`<code>`, `<table`),
    // collapsing it into an innerHTML wall of text (#10).
    const format =
      valueFormat !== "auto"
        ? valueFormat
        : outputFormat === "html"
          ? "html"
          : detectFormat(value);
    if (format === "html") return value;
    return (marked.parse(value, { async: false }) as string).trim();
  })();
  return unsafe ? raw : sanitizeHtml(raw);
}

function EditorRoot({
  children,
  className,
  value: controlledValue,
  defaultValue = "",
  onChange,
  outputFormat = "html",
  valueFormat = "auto",
  lineSpacing = 1.6,
  placeholder,
  mode: modeProp,
  extensions: instanceExtensions,
  unsafe = false,
  showSource: showSourceProp,
  defaultShowSource = false,
  onShowSourceChange,
}: EditorProps) {
  const contentRef = useRef<HTMLDivElement | null>(null);
  const [value, setValue] = useControllableState(controlledValue, defaultValue, onChange);
  const [showSource, setShowSource] = useControllableState(
    showSourceProp,
    defaultShowSource,
    onShowSourceChange,
  );
  // View/edit mode — same resolution as the inputs: prop → <Form> context → "edit".
  const mode = useFieldMode(modeProp);
  const isView = mode === "view";

  // The value this editor last emitted through `onChange`. An incoming `value`
  // equal to it is our own keystroke echoing back; anything else came from
  // OUTSIDE — an async load, a host reset, a form repopulating.
  const lastEmitted = useRef<string | null>(null);

  // Bumped only on an external `value` change, so the seed memo below recomputes
  // for those and stays put while the user types. Without this, `value` was
  // excluded from the deps to avoid re-seeding on keystrokes, which also meant a
  // value arriving after mount was silently dropped and the editor stayed blank
  // forever (#15).
  const [externalSeed, setExternalSeed] = useState(0);
  useEffect(() => {
    if (value !== lastEmitted.current) setExternalSeed((n) => n + 1);
  }, [value]);

  const initialHtml = useMemo(
    () => toHtml(value, outputFormat, unsafe, valueFormat),
    // Seed the contentEditable from the LIVE value when (re)entering edit mode —
    // and when returning from the raw-source view, which may have rewritten the
    // value out from under the rich-text surface. `value` itself stays out of
    // the deps so typing never re-seeds (which would fight the caret);
    // `externalSeed` covers the externally-driven case instead.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [isView, outputFormat, unsafe, valueFormat, showSource, externalSeed],
  );

  const extensions = useMemo(
    () => mergeExtensions(instanceExtensions),
    [instanceExtensions],
  );

  const getOutputValue = useCallback(
    (html: string): string => {
      return outputFormat === "markdown" ? htmlToMarkdown(html) : html;
    },
    [outputFormat],
  );

  const handleInput = useCallback(() => {
    const el = contentRef.current;
    if (!el) return;
    const next = getOutputValue(el.innerHTML);
    // Record what we emitted BEFORE publishing it, so the value coming back in
    // is recognised as our own and does not trigger a re-seed mid-keystroke.
    lastEmitted.current = next;
    setValue(next);
  }, [setValue, getOutputValue]);

  const exec = useCallback(
    (command: string, arg?: string) => {
      const el = contentRef.current;
      if (!el) return;
      el.focus();
      document.execCommand(command, false, arg);
      handleInput();
    },
    [handleInput],
  );

  const insertText = useCallback(
    (text: string) => {
      const el = contentRef.current;
      if (!el) return;
      el.focus();
      document.execCommand("insertText", false, text);
      handleInput();
    },
    [handleInput],
  );

  // The source textarea edits `value` directly — it is already the canonical
  // source in `outputFormat` (html or markdown), so no conversion round-trip.
  const handleSourceInput = useCallback(
    (next: string) => {
      // Also an internal emission — record it so typing in the source view is
      // not mistaken for an external change on every keystroke.
      lastEmitted.current = next;
      setValue(next);
    },
    [setValue],
  );

  const wrapSelection = useCallback(
    (before: string, after: string) => {
      const sel = window.getSelection();
      if (!sel || sel.rangeCount === 0) return;
      const range = sel.getRangeAt(0);
      const selectedText = range.toString();
      const el = contentRef.current;
      if (!el) return;
      el.focus();
      document.execCommand("insertText", false, `${before}${selectedText}${after}`);
      handleInput();
    },
    [handleInput],
  );

  const contextValue = {
    contentRef,
    exec,
    insertText,
    wrapSelection,
    outputFormat,
    lineSpacing,
    placeholder,
    extensions,
    showSource,
    setShowSource,
    _initialHtml: initialHtml,
    _onInput: handleInput,
    _sourceValue: value,
    _onSourceInput: handleSourceInput,
  };

  // View mode — render the value read-only through ContentRenderer, matching the
  // editor's own format (markdown/html), instead of the editable toolbar+content
  // tree. Driven by `mode` / a `<Form mode="view">`, exactly like the inputs.
  if (isView) {
    return (
      <div
        data-react-fancy-editor=""
        data-mode="view"
        className={cn(
          "overflow-hidden rounded-xl border border-zinc-200 bg-white dark:border-zinc-700 dark:bg-zinc-900",
          className,
        )}
      >
        <ContentRenderer
          value={value}
          format={valueFormat !== "auto" ? valueFormat : outputFormat}
          lineSpacing={lineSpacing}
          extensions={instanceExtensions}
          unsafe={unsafe}
          className="px-4 py-3"
        />
      </div>
    );
  }

  return (
    <EditorContext.Provider value={contextValue}>
      <div
        data-react-fancy-editor=""
        data-mode="edit"
        className={cn(
          "flex flex-col overflow-hidden rounded-xl border border-zinc-200 bg-white dark:border-zinc-700 dark:bg-zinc-900",
          className,
        )}
      >
        {children}
      </div>
    </EditorContext.Provider>
  );
}

const ToolbarWithSeparator = Object.assign(EditorToolbar, {
  Separator: EditorToolbarSeparator,
});

export const Editor = Object.assign(EditorRoot, {
  Toolbar: ToolbarWithSeparator,
  Content: EditorContent,
  SourceToggle: EditorSourceToggle,
});

import type { ReactNode } from "react";
import type { RenderExtension } from "../ContentRenderer/extensions";
import type { FieldMode } from "../inputs/inputs.types";

export interface EditorAction {
  icon: ReactNode;
  label: string;
  command: string;
  commandArg?: string;
  active?: boolean;
}

export interface EditorToolbarProps {
  actions?: EditorAction[];
  onAction?: (command: string) => void;
  children?: ReactNode;
  className?: string;
  /**
   * Append a "Source" toggle (reveals the raw HTML/Markdown behind the editor)
   * to the right of the default toolbar. Ignored when `children` are supplied —
   * custom toolbars compose their own `<Editor.SourceToggle />`.
   * @default true
   */
  showSourceToggle?: boolean;
}

export interface EditorContentProps {
  className?: string;
  /** Max height in px before scrolling. When set, content area becomes scrollable. */
  maxHeight?: number;
  /** Class names applied to the raw-source `<textarea>` shown while source mode is on. */
  sourceClassName?: string;
}

export interface EditorSourceToggleProps {
  className?: string;
  /** Toggle glyph/label. @default `</>` */
  icon?: ReactNode;
  /** Accessible title when in rich-text mode (click → source). @default "Source" */
  title?: string;
  /** Accessible title when in source mode (click → rich text). @default "Rich text" */
  activeTitle?: string;
}

export interface EditorProps {
  children: ReactNode;
  className?: string;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  outputFormat?: "html" | "markdown";
  /**
   * The format of the INCOMING `value` / `defaultValue`. Default `"auto"`
   * keeps the historical sniff (`detectFormat`) — but real-world markdown that
   * merely mentions HTML-ish snippets (`<code>`, `<table`, …) flips the sniff
   * to html and renders as a wall of text. Callers with a KNOWN format
   * (file-typed content, values previously emitted with
   * `outputFormat="markdown"`) should declare it; explicit values bypass the
   * sniff entirely — in edit mode AND view mode.
   * @default "auto"
   */
  valueFormat?: "markdown" | "html" | "auto";
  lineSpacing?: number;
  placeholder?: string;
  /**
   * View/edit mode — like the react-fancy inputs. Resolution: this prop →
   * nearest `<Form>` / `<FormProvider>` context → `"edit"`. In `"view"` mode the
   * editor renders its value read-only through `<ContentRenderer>` (matching
   * `outputFormat` — markdown/html) instead of the editable toolbar + content.
   * @default "edit"
   */
  mode?: FieldMode;
  /** Per-instance render extensions. Merged with any globally-registered extensions. */
  extensions?: RenderExtension[];
  /**
   * Controlled source-view flag. When `true` the content area shows the raw
   * HTML/Markdown (`value`, in `outputFormat`) in an editable `<textarea>`
   * instead of the rich-text surface. Pair with `onShowSourceChange`, or leave
   * uncontrolled and drive it with the toolbar's Source toggle.
   */
  showSource?: boolean;
  /** Initial source-view flag when uncontrolled. @default false */
  defaultShowSource?: boolean;
  /** Fired when the Source toggle (or an agent) flips source view on/off. */
  onShowSourceChange?: (showSource: boolean) => void;
  /**
   * Skip HTML sanitization of the initial value. By default the initial markdown/HTML
   * is sanitized to remove `<script>`, `<iframe>`, event handlers, and `javascript:`
   * URIs before being placed into contentEditable. Pass `unsafe` only when the
   * initial value is fully trusted.
   * @default false
   */
  unsafe?: boolean;
}

import { useEffect, useMemo, useRef } from "react";
import { cn } from "../../utils/cn";
import { CodeView } from "../CodeView";
import { useEditor } from "./Editor.context";
import { proseClasses, extensionEditorClasses } from "./editor.utils";
import type { EditorContentProps } from "./Editor.types";

export function EditorContent({ className, maxHeight, sourceClassName }: EditorContentProps) {
  const {
    contentRef,
    lineSpacing,
    placeholder,
    extensions,
    outputFormat,
    showSource,
    _initialHtml,
    _onInput,
    _sourceValue,
    _onSourceInput,
  } = useEditor();
  // Tracks which seed HTML is currently in the contentEditable. Seeding on the
  // seed VALUE (not a one-shot boolean) re-seeds when the source view rewrites
  // `value`, while still never re-seeding on plain keystrokes — typing leaves
  // `_initialHtml` untouched, so `seededHtml.current === _initialHtml` holds.
  const seededHtml = useRef<string | null>(null);

  useEffect(() => {
    // Source view replaces the contentEditable in the tree, so it unmounts.
    // Forget what we seeded — the div that returns is a fresh, empty one and
    // must always be re-seeded, even if `value` was left untouched.
    if (showSource) {
      seededHtml.current = null;
      return;
    }
    const el = contentRef.current;
    if (el && seededHtml.current !== _initialHtml) {
      el.innerHTML = _initialHtml;
      seededHtml.current = _initialHtml;
    }
  }, [contentRef, _initialHtml, showSource]);

  const extClasses = useMemo(
    () => extensionEditorClasses(extensions),
    [extensions],
  );

  if (showSource) {
    // Raw-source view — a syntax-highlighted code surface (HTML highlighted;
    // markdown/plain un-highlighted), built on the shared fancy-file-commons
    // primitives. It's a DIRECT child of the flex-column editor root (no
    // wrapper — a nested flex box collapses the fill), so `flex-auto` makes it
    // fill the editor body when height-constrained and grow with content
    // (≥ minHeight) when not. `maxHeight` caps + scrolls.
    return (
      <CodeView
        value={_sourceValue}
        onChange={_onSourceInput}
        language={outputFormat === "html" ? "html" : "plaintext"}
        placeholder={placeholder}
        maxHeight={maxHeight}
        className={cn("min-h-0 flex-auto", sourceClassName)}
      />
    );
  }

  return (
    <div
      ref={contentRef}
      contentEditable
      suppressContentEditableWarning
      data-react-fancy-editor-content=""
      data-placeholder={placeholder}
      onInput={_onInput}
      style={{
        lineHeight: lineSpacing,
        maxHeight: maxHeight ? `${maxHeight}px` : undefined,
      }}
      className={cn(
        "min-h-[120px] flex-auto overflow-y-auto px-4 py-3 text-sm outline-none",
        "focus:outline-none",
        proseClasses,
        extClasses,
        "empty:before:content-[attr(data-placeholder)] empty:before:text-zinc-400 empty:before:pointer-events-none",
        className,
      )}
    />
  );
}

EditorContent.displayName = "EditorContent";

import { cn } from "../../utils/cn";
import { useEditor } from "./Editor.context";
import type { EditorSourceToggleProps } from "./Editor.types";

/**
 * Toolbar button that reveals the raw HTML/Markdown behind the editor. Reads
 * `showSource` / `setShowSource` from context, so it works in the default
 * toolbar and in any custom toolbar composed with `useEditor()`.
 */
export function EditorSourceToggle({
  className,
  icon = "</>",
  title = "Source",
  activeTitle = "Rich text",
}: EditorSourceToggleProps) {
  const { showSource, setShowSource } = useEditor();

  return (
    <button
      type="button"
      onClick={() => setShowSource(!showSource)}
      title={showSource ? activeTitle : title}
      aria-pressed={showSource}
      data-react-fancy-editor-source-toggle=""
      className={cn(
