/**
 * Babylon engine adapter for `@particle-academy/fancy-3d`'s <Canvas>.
 *
 * Mounts a Babylon `Engine` + `Scene` + camera into a `<canvas>` element
 * overlaid on the Canvas DOM container, then exposes the live `Scene` via
 * `EngineHandle.root` so child components can register meshes alongside the
 * 2D node graph.
 *
 *   import { Canvas } from "@particle-academy/fancy-3d";
 *   import { babylonEngine } from "@particle-academy/fancy-3d-babylon/engine";
 *
 *   <Canvas engine={babylonEngine} style={{ height: 480 }} />
 */
import type { CanvasEngine, EngineHandle, ViewportState } from "@particle-academy/fancy-3d";

// Declare a CJS-style `require` so the dts compiler doesn't reject the lazy
// load below. Browsers don't have `require`, but this whole engine adapter
// only runs when a host bundler (vite/webpack) replaces the call with its own
// lazy-module shim, or under node-side SSR where the global exists.
declare const require: (specifier: string) => unknown;

export const babylonEngine: CanvasEngine = {
  name: "babylon",
  mount(host: HTMLElement, viewport: ViewportState): EngineHandle {
    // Lazy require so non-babylon Canvas users don't pay the parse cost.
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const BABYLON: any = require("@babylonjs/core");

    const overlay = document.createElement("canvas");
    overlay.style.position = "absolute";
    overlay.style.inset = "0";
    overlay.style.width = "100%";
    overlay.style.height = "100%";
    overlay.style.pointerEvents = "none";
    overlay.dataset.fancy3dCanvasEngine = "babylon";
    host.appendChild(overlay);

    const engine = new BABYLON.Engine(overlay, true, { preserveDrawingBuffer: true, stencil: true });
    const scene = new BABYLON.Scene(engine);
    scene.clearColor = new BABYLON.Color4(0, 0, 0, 0);

    const camera = new BABYLON.ArcRotateCamera(
      "fancy3d-canvas-camera",
      Math.PI / 2,
      Math.PI / 2.5,
      8,
      BABYLON.Vector3.Zero(),
      scene,
    );
    camera.attachControl(overlay, false);
    new BABYLON.HemisphericLight("fancy3d-canvas-light", new BABYLON.Vector3(0, 1, 0), scene);

    const observer = engine.runRenderLoop(() => scene.render());

    function updateViewport(_v: ViewportState) {
      // Default: 6DoF camera owns view; 2D viewport changes are observed
      // but don't move the Babylon camera. Consumers can override by
      // attaching their own observers to the scene.
    }

    function dispose() {
      try { engine.stopRenderLoop(observer as any); } catch {}
      scene.dispose();
      engine.dispose();
      if (overlay.parentElement === host) host.removeChild(overlay);
    }

    return {
      name: "babylon",
      root: scene,
      updateViewport,
      dispose,
    };
  },
};

/**
 * three.js engine adapter for `@particle-academy/fancy-3d`'s <Canvas>.
 *
 * Mounts a three `WebGLRenderer` + `Scene` + camera into a `<canvas>` overlaid
 * on the Canvas DOM container, then exposes the live `Scene` via
 * `EngineHandle.root` so child components can register meshes alongside the 2D
 * node graph.
 *
 *   import { Canvas } from "@particle-academy/fancy-3d";
 *   import { threeEngine } from "@particle-academy/fancy-3d-three/engine";
 *
 *   <Canvas engine={threeEngine} style={{ height: 480 }} />
 */
import * as THREE from "three";
import type { CanvasEngine, EngineHandle, ViewportState } from "@particle-academy/fancy-3d";

export const threeEngine: CanvasEngine = {
  name: "three",
  mount(host: HTMLElement, _viewport: ViewportState): EngineHandle {
    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true, preserveDrawingBuffer: true });
    renderer.setPixelRatio(window.devicePixelRatio || 1);
    const overlay = renderer.domElement;
    overlay.style.position = "absolute";
    overlay.style.inset = "0";
    overlay.style.width = "100%";
    overlay.style.height = "100%";
    overlay.style.pointerEvents = "none"; // the 2D node graph owns interaction
    overlay.dataset.fancy3dCanvasEngine = "three";
    host.appendChild(overlay);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(50, 1, 0.1, 1000);
    camera.position.set(0, 0, 8);
    camera.lookAt(0, 0, 0);

    const hemi = new THREE.HemisphereLight(0xb3c6ff, 0x1a1a2e, 1.0);
    scene.add(hemi);

    const resize = () => {
      const w = host.clientWidth || 1;
      const h = host.clientHeight || 1;
      renderer.setSize(w, h, false);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    };
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(host);

    let raf = 0;
    const loop = () => {
      raf = requestAnimationFrame(loop);
      renderer.render(scene, camera);
    };
    loop();

    function updateViewport(_v: ViewportState) {
      // The 3D camera owns its own view; 2D viewport changes are observed but
      // don't move the camera. Consumers can drive the camera off the scene.
    }

    function dispose() {
      cancelAnimationFrame(raf);
      ro.disconnect();
      renderer.dispose();
      if (overlay.parentElement === host) host.removeChild(overlay);
    }

    return {
      name: "three",
      root: scene,
      updateViewport,
      dispose,
    };
  },
};

import { useEffect, lazy, Suspense, type ComponentType, type ReactNode } from "react";
import { Toast } from "@particle-academy/react-fancy";

/**
 * fancy-screens is an OPTIONAL peer. Importing `ScreenSystem` statically
 * would put `@particle-academy/fancy-screens` in the base import graph, so
 * any bundler resolving `fancy-inertia` would hard-fail when it isn't
 * installed — even for consumers who only use `<FancyAppRoot withScreens={false}>`.
 * Load it lazily instead, and degrade to a passthrough if it's absent.
 */
const Passthrough = ({ children }: { children?: ReactNode }) => <>{children}</>;

const SCREENS_MISSING =
  "[fancy-inertia] `withScreens` is on but @particle-academy/fancy-screens is not available — rendering children without the ScreenSystem provider. Pass `withScreens={false}` to silence this.";

const ScreenSystemLazy = lazy<ComponentType<{ children?: ReactNode }>>(() =>
  import("@particle-academy/fancy-screens")
    .then((m) => {
      const Comp = (m as { ScreenSystem?: ComponentType<{ children?: ReactNode }> })?.ScreenSystem;
      // A bundler resolving an ABSENT optional peer can hand back an
      // export-less stub ({ default: undefined }) instead of rejecting — so a
      // reject-only `.catch` misses it and React.lazy gets `{ default: undefined }`
      // (React #306). Guard the resolved export, not just rejection.
      if (!Comp) {
        console.warn(SCREENS_MISSING);
        return { default: Passthrough };
      }
      return { default: Comp };
    })
    .catch((err) => {
      console.warn(SCREENS_MISSING, err);
      return { default: Passthrough };
    }),
);

export interface FancyAppRootProps {
  children: ReactNode;

  /** Toast position. Default `"bottom-right"`. */
  toastPosition?: "top-left" | "top-right" | "bottom-left" | "bottom-right";

  /**
   * Mount fancy-screens' `<Screen.System>` provider. Default `true`. Set
   * `false` if your app doesn't use fancy-screens — the optional peer is
   * never imported in that case.
   */
  withScreens?: boolean;

  /**
   * Auto-register echarts modules + built-in themes on mount. Default
   * `true`. Disable if you call `registerCharts(...)` yourself for
   * tree-shaking control, or if fancy-echarts isn't installed.
   */
  withECharts?: boolean;
}

/**
 * Composite top-level provider for the fancy UI set under Inertia.
 *
 * Mount once in your Inertia app entry, ABOVE the `<Inertia App>` outlet.
 * Subsequent page swaps preserve the providers — toasts survive
 * navigation, the screen registry persists, and echarts modules don't
 * have to re-register.
 *
 *   import { createInertiaApp } from "@inertiajs/react";
 *   import { FancyAppRoot } from "@particle-academy/fancy-inertia";
 *
 *   createInertiaApp({
 *     setup({ App, props, el }) {
 *       createRoot(el).render(
 *         <FancyAppRoot>
 *           <App {...props} />
 *         </FancyAppRoot>
 *       );
 *     },
 *   });
 *
 * `fancy-screens` and `fancy-echarts` are optional peers, loaded lazily
 * only when `withScreens` / `withECharts` are enabled — the base bundle
 * depends on nothing but `react-fancy`.
 */
export function FancyAppRoot({
  children,
  toastPosition = "bottom-right",
  withScreens = true,
  withECharts = true,
}: FancyAppRootProps) {
  useEffect(() => {
    if (!withECharts) return;
    let cancelled = false;
    void (async () => {
      try {
        const echarts = await import("@particle-academy/fancy-echarts");
        if (cancelled) return;
        echarts.registerAll?.();
        echarts.registerBuiltinThemes?.();
      } catch (err) {
        console.warn(
          "[fancy-inertia] `withECharts` is on but @particle-academy/fancy-echarts is not installed — skipping chart registration. Pass `withECharts={false}` to silence this.",
          err,
        );
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [withECharts]);

  const Inner = withScreens ? (
    <Suspense fallback={null}>
      <ScreenSystemLazy>{children}</ScreenSystemLazy>
    </Suspense>
  ) : (
    <>{children}</>
  );

  return <Toast.Provider position={toastPosition}>{Inner}</Toast.Provider>;
}

FancyAppRoot.displayName = "FancyAppRoot";

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { Button, Badge, Card, Separator } from "@particle-academy/react-fancy";
import { resolveSource } from "@particle-academy/fancy-file-commons";
import { mergeResult } from "@particle-academy/fancy-file-commons";
import type {
  AcceptanceState,
  AcceptanceStatus,
  Diff,
  DiffSegment,
  Hunk,
} from "@particle-academy/fancy-file-commons";
import { fileLabel } from "@particle-academy/fancy-file-commons";
import { emitHunkActivity } from "../activity";
import type {
  FancyDiffProps,
  DiffViewMode,
  MergedResult,
  HunkRenderArgs,
  ToolbarRenderArgs,
  GutterRenderArgs,
} from "./FancyDiff.types";

/** Imperative handle exposed via ref. */
export interface FancyDiffHandle {
  /** Compute the merged result from the current acceptance state. */
  getMergedResult: () => MergedResult;
  /** The resolved diffs (one per file). */
  getDiffs: () => Diff[];
  /** Current acceptance state. */
  getAcceptance: () => AcceptanceState;
}

const statusBadge: Record<AcceptanceStatus, { color: string; label: string }> = {
  accepted: { color: "emerald", label: "accepted" },
  rejected: { color: "rose", label: "rejected" },
  pending: { color: "amber", label: "pending" },
};

function cx(...parts: (string | false | undefined | null)[]): string {
  return parts.filter(Boolean).join(" ");
}

/** True when the document root currently signals a dark theme. */
function hostIsDark(): boolean {
  if (typeof document === "undefined") return false;
  const root = document.documentElement;
  if (root.classList.contains("dark")) return true;
  if (root.getAttribute("data-theme") === "dark") return true;
  try {
    if (getComputedStyle(root).colorScheme === "dark") return true;
  } catch {
    /* getComputedStyle can throw in detached/SSR contexts */
  }
  return false;
}

/**
 * Resolve the effective dark state for a `theme` prop. `"dark"`/`"light"` are
 * honored verbatim; `"auto"` probes the host (`.dark` / `data-theme` /
 * `color-scheme` on <html>) and falls back to `prefers-color-scheme`,
 * re-resolving when either changes so a host theme toggle flips the diff too.
 */
function useResolvedDark(theme: FancyDiffProps["theme"]): boolean {
  const explicit = theme === "dark" ? true : theme === "light" ? false : null;
  const [isDark, setIsDark] = useState<boolean>(explicit ?? false);

  useEffect(() => {
    if (explicit !== null) {
      setIsDark(explicit);
      return;
    }
    if (typeof window === "undefined") return;

    const mq = window.matchMedia?.("(prefers-color-scheme: dark)");
    const resolve = () => setIsDark(hostIsDark() || !!mq?.matches);
    resolve();

    mq?.addEventListener?.("change", resolve);
    const observer = new MutationObserver(resolve);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme", "style"],
    });
    return () => {
      mq?.removeEventListener?.("change", resolve);
      observer.disconnect();
    };
  }, [explicit]);

  return isDark;
}

export const FancyDiff = forwardRef<FancyDiffHandle, FancyDiffProps>(
  function FancyDiff(props, ref) {
    const {
      source,
      variant = "review",
      value,
      onChange,
      defaultValue,
      defaultStatus = "pending",
      mode: modeProp,
      onModeChange,
      pendingMode = false,
      onProposal,
      onResult,
      renderHunk,
      renderToolbar,
      renderGutter,
      tokenizer,
      actor,
      activity,
      showToolbar = true,
      showGutter = true,
      wrap = false,
      className,
      theme = "auto",
      header,
    } = props;

    // `compare` strips the whole acceptance UX — read-only comparison only.
    const interactive = variant !== "compare";

    // One value, spliced into every line row, because there are five of them
    // (split before/after, inline, and the equal-context rows) and a diff whose
    // sides disagree about wrapping is worse than either choice.
    //
    // `pre` — not `pre-wrap` — is what makes the stylesheet's
    // `[data-fancy-diff-body] { overflow-x: auto }` mean anything: while rows
    // wrapped, nothing could overflow and that rule was dead.


    // Resolve `theme="auto"` at runtime: prefer an explicit host signal (a
    // `.dark` class / `data-theme="dark"` / `color-scheme` on <html>), then fall
    // back to `prefers-color-scheme`. Re-resolves on system + host changes so a
    // theme toggle flips the diff with it. (theme="dark"/"light" are honored
    // verbatim; SSR starts from the explicit value, then resolves on mount.)
    const isDark = useResolvedDark(theme);

    // Resolve source -> diffs. Memoized on identity of source + tokenizer.
    const diffs = useMemo(
      () => resolveSource(source, { tokenizer }),
      [source, tokenizer],
    );

    // Controlled / uncontrolled acceptance state.
    const [internal, setInternal] = useState<AcceptanceState>(
      () => defaultValue ?? {},
    );
    const acceptance = value ?? internal;

    // Controlled / uncontrolled view mode.
    const [internalMode, setInternalMode] = useState<DiffViewMode>(
      modeProp ?? "split",
    );
    const mode = modeProp ?? internalMode;
    const setMode = useCallback(
      (m: DiffViewMode) => {
        if (modeProp === undefined) setInternalMode(m);
        onModeChange?.(m);
      },
      [modeProp, onModeChange],
    );

    const allHunks = useMemo(() => {
      const list: { hunk: Hunk; fileIndex: number }[] = [];
      diffs.forEach((d, fi) =>
        d.hunks.forEach((h) => {
          if (h.type !== "equal") list.push({ hunk: h, fileIndex: fi });
        }),
      );
      return list;
    }, [diffs]);

    const statusOf = useCallback(
      (id: string): AcceptanceStatus => acceptance[id] ?? defaultStatus,
      [acceptance, defaultStatus],
    );

    const computeMerged = useCallback(
      (state: AcceptanceState): MergedResult => {
        const files = diffs.map((d) => ({
          meta: d.file,
          merged: mergeResult(d, state, { defaultStatus }),
        }));
        return { files, text: files[0]?.merged ?? "" };
      },
      [diffs, defaultStatus],
    );

    const apply = useCallback(
      (hunkId: string, status: AcceptanceStatus, action: string, fileIndex?: number) => {
        if (pendingMode) {
          onProposal?.({ hunkId, proposedStatus: status, actor });
        }
        const next: AcceptanceState = { ...acceptance, [hunkId]: status };

        emitHunkActivity({
          action: status === "accepted" ? "diff_accept_hunk" : "diff_reject_hunk",
          hunkId,
          fileId: fileIndex !== undefined ? diffs[fileIndex]?.file?.newPath : undefined,
          actor,
          emitter: activity,
        });

        if (value === undefined) setInternal(next);
        onChange?.(next, { hunkId, status, action });
        onResult?.(computeMerged(next));
      },
      [acceptance, pendingMode, onProposal, actor, activity, value, onChange, onResult, computeMerged, diffs],
    );

    const setAll = useCallback(
      (status: AcceptanceStatus, action: string) => {
        const next: AcceptanceState = { ...acceptance };
        for (const { hunk } of allHunks) next[hunk.id] = status;
        emitHunkActivity({
          action: status === "accepted" ? "diff_accept_all" : "diff_reject_all",
          actor,
          emitter: activity,
        });
        if (value === undefined) setInternal(next);
        onChange?.(next, { hunkId: "*", status, action });
        onResult?.(computeMerged(next));
      },
      [acceptance, allHunks, actor, activity, value, onChange, onResult, computeMerged],
    );

    useImperativeHandle(
      ref,
      () => ({
        getMergedResult: () => computeMerged(acceptance),
        getDiffs: () => diffs,
        getAcceptance: () => acceptance,
      }),
      [computeMerged, acceptance, diffs],
    );

    const counts = useMemo(() => {
      let accepted = 0;
      let rejected = 0;
      let pending = 0;
      for (const { hunk } of allHunks) {
        const s = statusOf(hunk.id);
        if (s === "accepted") accepted++;
        else if (s === "rejected") rejected++;
        else pending++;
      }
      return { total: allHunks.length, accepted, rejected, pending };
    }, [allHunks, statusOf]);

    // ---- Toolbar ----
    const defaultToolbar: ReactNode = showToolbar ? (
      <div
        data-fancy-diff-toolbar=""
        role="toolbar"
        aria-label="Diff actions"
        className="flex items-center gap-2 flex-wrap px-3 py-2"
      >
        <Badge color="zinc" variant="soft" size="sm">
          {counts.total} change{counts.total === 1 ? "" : "s"}
        </Badge>
        {interactive && (
          <>
            <Badge color="emerald" variant="soft" size="sm">
              {counts.accepted} accepted
            </Badge>
            <Badge color="amber" variant="soft" size="sm">
              {counts.pending} pending
            </Badge>
          </>
        )}
        <span className="flex-1" />
        <Button
          size="sm"
          variant="ghost"
          icon={mode === "split" ? "columns" : "list"}
          onClick={() => setMode(mode === "split" ? "inline" : "split")}
          data-fancy-diff-mode-toggle=""
        >
          {mode === "split" ? "Split" : "Inline"}
        </Button>
        {interactive && (
          <>
            <Separator orientation="vertical" className="h-5" />
            <Button
              size="sm"
              variant="ghost"
              icon="check"
              onClick={() => setAll("accepted", "accept-all")}
              data-fancy-diff-accept-all=""
            >
              Accept all
            </Button>
            <Button
              size="sm"
              variant="ghost"
              icon="x"
              onClick={() => setAll("rejected", "reject-all")}
              data-fancy-diff-reject-all=""
            >
              Reject all
            </Button>
          </>
        )}
      </div>
    ) : null;

    const toolbar: ReactNode = renderToolbar
      ? renderToolbar({
          acceptAll: () => setAll("accepted", "accept-all"),
          rejectAll: () => setAll("rejected", "reject-all"),
          counts,
          mode,
          setMode,
          defaultNode: defaultToolbar,
        })
      : defaultToolbar;

    const renderGutterCell = (args: GutterRenderArgs): ReactNode => {
      if (renderGutter) return renderGutter(args);
      return (
        <span className="select-none tabular-nums text-zinc-400 dark:text-zinc-500 text-[11px] pr-2 text-right inline-block min-w-[2.5rem]">
          {args.side === "after"
            ? args.afterLineNo ?? ""
            : args.beforeLineNo ?? args.afterLineNo ?? ""}
        </span>
      );
    };

    return (
      <Card
        variant="outlined"
        padding="none"
        className={cx(
          "fancy-diff overflow-hidden font-mono text-[13px] text-zinc-800 dark:text-zinc-100",
          isDark && "dark",
          className,
        )}
        data-fancy-diff=""
        data-fancy-diff-wrap={wrap ? "" : undefined}
        data-fancy-diff-mode={mode}
        data-fancy-diff-variant={variant}
      >
        {header}
        {toolbar}
        {(header || toolbar) && <Separator />}
        <div data-fancy-diff-body="" role="table" aria-label="Diff">
          {diffs.map((diff, fileIndex) => (
            <FileBlock
              key={fileIndex}
              diff={diff}
              fileIndex={fileIndex}
              mode={mode}
              statusOf={statusOf}
              pendingMode={pendingMode}
              interactive={interactive}
              showGutter={showGutter}
              renderGutterCell={renderGutterCell}
              renderHunk={renderHunk}
              accept={(id) => apply(id, "accepted", "accept", fileIndex)}
              reject={(id) => apply(id, "rejected", "reject", fileIndex)}
            />
          ))}
        </div>
      </Card>
    );
  },
);

interface FileBlockProps {
  diff: Diff;
  fileIndex: number;
  mode: DiffViewMode;
  statusOf: (id: string) => AcceptanceStatus;
  pendingMode: boolean;
  interactive: boolean;
  showGutter: boolean;
  renderGutterCell: (args: GutterRenderArgs) => ReactNode;
  renderHunk?: FancyDiffProps["renderHunk"];
  accept: (id: string) => void;
  reject: (id: string) => void;
}

function FileBlock({
  diff,
  fileIndex,
  mode,
  statusOf,
  pendingMode,
  interactive,
  showGutter,
  renderGutterCell,
  renderHunk,
  accept,
  reject,
}: FileBlockProps) {
  const label = fileLabel(diff.file);
  return (
    <div data-fancy-diff-file={fileIndex} role="rowgroup">
      {label && (
        <div className="flex items-center gap-2 px-3 py-1.5 bg-zinc-50 dark:bg-zinc-800/60 border-b border-zinc-200 dark:border-zinc-700 text-xs">
          <span className="font-semibold text-zinc-700 dark:text-zinc-300">{label}</span>
          {diff.file?.partial && (
            <Badge color="amber" variant="soft" size="sm" title="Unified diff: only changed hunks + context are present">
              partial
            </Badge>
          )}
        </div>
      )}
      {diff.hunks.map((hunk) => {
        const status = statusOf(hunk.id);
        const defaultNode = (
          <HunkRow
            hunk={hunk}
            mode={mode}
            status={status}
            pendingMode={pendingMode}
            interactive={interactive}
            showGutter={showGutter}
            renderGutterCell={renderGutterCell}
            accept={() => accept(hunk.id)}
            reject={() => reject(hunk.id)}
          />
        );
        if (renderHunk && hunk.type !== "equal") {
          const args: HunkRenderArgs = {
            hunk,
            fileIndex,
            status,
            mode,
            pending: pendingMode && status === "pending",
            accept: () => accept(hunk.id),
            reject: () => reject(hunk.id),
            defaultNode,
          };
          const custom = renderHunk(args);
          return <div key={hunk.id}>{custom ?? defaultNode}</div>;
        }
        return <div key={hunk.id}>{defaultNode}</div>;
      })}
    </div>
  );
}

interface HunkRowProps {
  hunk: Hunk;
  mode: DiffViewMode;
  status: AcceptanceStatus;
  pendingMode: boolean;
  interactive: boolean;
  showGutter: boolean;
  renderGutterCell: (args: GutterRenderArgs) => ReactNode;
  accept: () => void;
  reject: () => void;
}

const sideBg: Record<string, string> = {
  add: "bg-emerald-50 dark:bg-emerald-500/10",
  remove: "bg-rose-50 dark:bg-rose-500/10",
  replaceBefore: "bg-rose-50 dark:bg-rose-500/10",
  replaceAfter: "bg-emerald-50 dark:bg-emerald-500/10",
};

function HunkRow({
  hunk,
  mode,
  status,
  pendingMode,
  interactive,
  showGutter,
  renderGutterCell,
  accept,
  reject,
}: HunkRowProps) {
  const isChange = hunk.type !== "equal";
  const dimmed = interactive && isChange && status === "rejected";

  return (
    <div
      data-fancy-diff-hunk={hunk.id}
      data-fancy-diff-hunk-type={hunk.type}
      data-fancy-diff-hunk-status={isChange && interactive ? status : undefined}
      role="row"
      className={cx(
        "group relative",
        dimmed && "opacity-50",
        isChange && "border-l-2",
        // review: the left border tracks acceptance status.
        interactive && isChange && status === "accepted" && "border-emerald-400",
        interactive && isChange && status === "rejected" && "border-rose-300",
        interactive && isChange && status === "pending" && "border-amber-300",
        // compare: no acceptance — the border marks the change *type* instead.
        !interactive && hunk.type === "add" && "border-emerald-400",
        !interactive && hunk.type === "remove" && "border-rose-300",
        !interactive && hunk.type === "replace" && "border-amber-300",
        !isChange && "border-l-2 border-transparent",
      )}
    >
      {mode === "split" && hunk.type === "replace" ? (
        <SplitReplace hunk={hunk} showGutter={showGutter} renderGutterCell={renderGutterCell} />
      ) : mode === "split" ? (
        <SplitSimple hunk={hunk} showGutter={showGutter} renderGutterCell={renderGutterCell} />
      ) : (
        <Inline hunk={hunk} showGutter={showGutter} renderGutterCell={renderGutterCell} />
      )}

      {isChange && interactive && (
        <div
          data-fancy-diff-hunk-actions=""
          className="absolute right-1.5 top-1/2 -translate-y-1/2 flex gap-1 opacity-0 group-hover:opacity-100 focus-within:opacity-100 transition-opacity"
        >
          <Button
            size="xs"
            variant="circle"
            icon="check"
            color={status === "accepted" ? "emerald" : undefined}
            checked={status === "accepted"}
            aria-label={pendingMode ? "Propose accept" : "Accept change"}
            title={pendingMode ? "Propose accept" : "Accept change"}
            onClick={accept}
            data-fancy-diff-accept={hunk.id}
          />
          <Button
            size="xs"
            variant="circle"
            icon="x"
            warn={status === "rejected"}
            aria-label={pendingMode ? "Propose reject" : "Reject change"}
            title={pendingMode ? "Propose reject" : "Reject change"}
            onClick={reject}
            data-fancy-diff-reject={hunk.id}
          />
        </div>
      )}
    </div>
  );
}

function gutterArgs(
  side: "before" | "after" | "both",
  beforeLineNo?: number,
  afterLineNo?: number,
): GutterRenderArgs {
  return { side, beforeLineNo, afterLineNo };
}

/** Split view for add/remove/equal hunks (no intra-line segments). */
function SplitSimple({
  hunk,
  showGutter,
  renderGutterCell,
}: {
  hunk: Hunk;
  showGutter: boolean;
  renderGutterCell: (a: GutterRenderArgs) => ReactNode;
}) {
  return (
    <>
      {hunk.lines.map((line, i) => {
        const leftText = line.side === "before" || line.side === "both" ? line.text : "";
        const rightText = line.side === "after" || line.side === "both" ? line.text : "";
        const leftFilled = line.side === "before" || line.side === "both";
        const rightFilled = line.side === "after" || line.side === "both";
        return (
          <div key={i} className="grid grid-cols-2" role="row">
            <div
              className={cx(
                "flex items-start gap-1 px-2 py-0.5 min-h-[1.4em] border-r border-zinc-100 dark:border-zinc-800",
                line.side === "before" && sideBg.remove,
              )}
            >
              {showGutter && renderGutterCell(gutterArgs("before", line.beforeLineNo))}
              {line.side === "before" && <span className="text-rose-500 select-none">-</span>}
              <span>{leftFilled ? leftText : ""}</span>
            </div>
            <div
              className={cx(
                "flex items-start gap-1 px-2 py-0.5 min-h-[1.4em]",
                line.side === "after" && sideBg.add,
              )}
            >
              {showGutter && renderGutterCell(gutterArgs("after", undefined, line.afterLineNo))}
              {line.side === "after" && <span className="text-emerald-500 select-none">+</span>}
              <span>{rightFilled ? rightText : ""}</span>
            </div>
          </div>
        );
      })}
    </>
  );
}

/** Split view for replace hunks, pairing before/after rows with segment highlights. */
function SplitReplace({
  hunk,
  showGutter,
  renderGutterCell,
}: {
  hunk: Hunk;
  showGutter: boolean;
  renderGutterCell: (a: GutterRenderArgs) => ReactNode;
}) {
  const before = hunk.lines.filter((l) => l.side === "before");
  const after = hunk.lines.filter((l) => l.side === "after");
  const rows = Math.max(before.length, after.length);
  const segs = hunk.segments ?? [];

  return (
    <>
      {Array.from({ length: rows }).map((_, i) => {
        const b = before[i];
        const a = after[i];
        const seg = segs.find((s) => s.pairIndex === i);
        return (
          <div key={i} className="grid grid-cols-2" role="row">
            <div
              className={cx(
                "flex items-start gap-1 px-2 py-0.5 min-h-[1.4em] border-r border-zinc-100 dark:border-zinc-800",
                b && sideBg.replaceBefore,
              )}
            >
              {showGutter && renderGutterCell(gutterArgs("before", b?.beforeLineNo))}
              {b && <span className="text-rose-500 select-none">-</span>}
              <span>{b ? (seg ? renderSegments(seg.before, "remove") : b.text) : ""}</span>
            </div>
            <div
              className={cx(
                "flex items-start gap-1 px-2 py-0.5 min-h-[1.4em]",
                a && sideBg.replaceAfter,
              )}
            >
              {showGutter && renderGutterCell(gutterArgs("after", undefined, a?.afterLineNo))}
              {a && <span className="text-emerald-500 select-none">+</span>}
              <span>{a ? (seg ? renderSegments(seg.after, "add") : a.text) : ""}</span>
            </div>
          </div>
        );
      })}
    </>
  );
}

/** Inline (single-column) view. */
function Inline({
  hunk,
  showGutter,
  renderGutterCell,
}: {
  hunk: Hunk;
  showGutter: boolean;
  renderGutterCell: (a: GutterRenderArgs) => ReactNode;
}) {
  const segs = hunk.segments ?? [];
  let removeIdx = 0;
  let addIdx = 0;
  return (
    <>
      {hunk.lines.map((line, i) => {
        const sign = line.side === "before" ? "-" : line.side === "after" ? "+" : " ";
        const bg =
          line.side === "before"
            ? sideBg.remove
            : line.side === "after"
              ? sideBg.add
              : "";
        let content: ReactNode = line.text;
        if (hunk.type === "replace") {
          if (line.side === "before") {
            const seg = segs.find((s) => s.pairIndex === removeIdx++);
            if (seg) content = renderSegments(seg.before, "remove");
          } else if (line.side === "after") {
            const seg = segs.find((s) => s.pairIndex === addIdx++);
            if (seg) content = renderSegments(seg.after, "add");
          }
        }
        return (
          <div
            key={i}
            role="row"
            className={cx(
              "flex items-start gap-1 px-2 py-0.5 min-h-[1.4em]",
              bg,
            )}
          >
            {showGutter &&
              renderGutterCell(
                gutterArgs(line.side, line.beforeLineNo, line.afterLineNo),
              )}
            <span
              className={cx(
                "select-none w-3",
                sign === "-" && "text-rose-500",
                sign === "+" && "text-emerald-500",
              )}
            >
              {sign}
            </span>
            <span>{content}</span>
          </div>
        );
      })}
    </>
  );
}

/** Render intra-line segments with add/remove emphasis. */
function renderSegments(segments: DiffSegment[], emphasis: "add" | "remove"): ReactNode {
  return segments.map((s, i) => {
    if (s.op === "equal") return <span key={i}>{s.text}</span>;
    const cls =
      emphasis === "add"
        ? "bg-emerald-200/70 dark:bg-emerald-400/25 rounded-sm"
        : "bg-rose-200/70 dark:bg-rose-400/25 rounded-sm";
    return (
      <span key={i} className={cls} data-fancy-diff-seg={s.op}>
        {s.text}
      </span>
    );
  });
}

import type { ReactNode } from "react";
import type {
  AcceptanceState,
  AcceptanceStatus,
  Diff,
  Hunk,
  WordTokenizer,
} from "@particle-academy/fancy-file-commons";
import type { DiffSource } from "@particle-academy/fancy-file-commons";
import type { DiffActivityEmitter, DiffActor } from "../activity";

/** Split = side-by-side; inline = single column with +/- rows. */
export type DiffViewMode = "split" | "inline";

/** Args passed to a custom hunk renderer. */
export interface HunkRenderArgs {
  hunk: Hunk;
  /** Index of the file this hunk belongs to. */
  fileIndex: number;
  status: AcceptanceStatus;
  mode: DiffViewMode;
  /** Whether this hunk has a pending proposal (pendingMode). */
  pending: boolean;
  accept: () => void;
  reject: () => void;
  /** The default rendered row (so custom renderers can wrap, not replace). */
  defaultNode: ReactNode;
}

/** Args passed to a custom toolbar renderer. */
export interface ToolbarRenderArgs {
  acceptAll: () => void;
  rejectAll: () => void;
  /** Counts across all files. */
  counts: { total: number; accepted: number; rejected: number; pending: number };
  mode: DiffViewMode;
  setMode: (mode: DiffViewMode) => void;
  defaultNode: ReactNode;
}

/** Args passed to a custom gutter (per-line number cell) renderer. */
export interface GutterRenderArgs {
  beforeLineNo?: number;
  afterLineNo?: number;
  side: "before" | "after" | "both";
}

/**
 * What the viewer is *for*:
 *   - `"review"`  — the trust-but-verify acceptance loop (per-hunk accept/reject,
 *     accept-all/reject-all, acceptance status + merged result). The default.
 *   - `"compare"` — a read-only comparison: no accept/reject affordances, no
 *     acceptance state — just the diff. Acceptance props (`value`/`onChange`/
 *     `pendingMode`/…) are ignored in this variant.
 */
export type DiffVariant = "review" | "compare";

export interface FancyDiffProps {
  /**
   * Source of the diff (JSON-friendly discriminated union):
   *   - `{ before, after }`  — compute the diff in-house
   *   - `{ unified }`        — parse a git unified diff (partial documents)
   *   - `{ diff }`           — use a pre-built structured Diff (or Diff[])
   */
  source: DiffSource;

  /**
   * `"review"` (default) — accept/reject acceptance UX. `"compare"` — read-only
   * comparison with the acceptance UX stripped out.
   */
  variant?: DiffVariant;

  /** Controlled acceptance state: hunkId -> "accepted" | "rejected" | "pending". */
  value?: AcceptanceState;
  /** Fired with the next acceptance state on every accept/reject. */
  onChange?: (next: AcceptanceState, info: AcceptanceChangeInfo) => void;
  /** Initial acceptance state when uncontrolled. */
  defaultValue?: AcceptanceState;

  /** Status applied to hunks with no entry in `value`. Default "pending". */
  defaultStatus?: AcceptanceStatus;

  /** "split" (side-by-side) or "inline". Default "split". */
  mode?: DiffViewMode;
  /** Controlled mode change handler (renders a view toggle in the toolbar). */
  onModeChange?: (mode: DiffViewMode) => void;

  /**
   * Trust-but-verify: when true, accept/reject are treated as *proposals*.
   * The status still flips, but consumers can render a confirm affordance and
   * gate `getMergedResult`. Pending proposals are reported via `onProposal`.
   */
  pendingMode?: boolean;
  /** Fired when a proposal is made in pendingMode (before any confirm step). */
  onProposal?: (proposal: DiffProposal) => void;

  /** Called with the merged document whenever acceptance changes. */
  onResult?: (result: MergedResult) => void;

  // --- Customization (mirror the specialized editors) -------------------
  /** Replace/wrap the per-hunk row. Return null to fall back to default. */
  renderHunk?: (args: HunkRenderArgs) => ReactNode;
  /** Replace/wrap the toolbar. */
  renderToolbar?: (args: ToolbarRenderArgs) => ReactNode;
  /** Replace the per-line gutter (line-number cell). */
  renderGutter?: (args: GutterRenderArgs) => ReactNode;
  /** Custom intra-line tokenizer for word/char segment highlighting. */
  tokenizer?: WordTokenizer;

  /** Actor metadata stamped onto emitted activity (agent vs human). */
  actor?: DiffActor;
  /** Per-instance activity emitter (defaults to the global one if set). */
  activity?: DiffActivityEmitter | null;

  /** Show the accept-all / reject-all toolbar. Default true. */
  showToolbar?: boolean;
  /** Show line-number gutters. Default true. */
  showGutter?: boolean;
  /**
   * Wrap long lines instead of scrolling them. Default **false**.
   *
   * A diff is read line-against-line, so a wrapped line silently breaks the
   * correspondence the view exists to show -- and it breaks INSIDE tokens,
   * turning `$plan->amount` into `$plan-` / `>amount;`. The default keeps each
   * source line on one row and lets the body scroll horizontally.
   */
  wrap?: boolean;

  /** Root className passthrough. */
  className?: string;
  /** Theme accent — "light" | "dark" | "auto". Default "auto" (inherits). */
  theme?: "light" | "dark" | "auto";
  /** Extra content rendered above the toolbar (e.g. a title). */
  header?: ReactNode;
}

export interface AcceptanceChangeInfo {
  hunkId: string;
  status: AcceptanceStatus;
  /** "accept" | "reject" | "accept-all" | "reject-all". */
  action: string;
}

export interface DiffProposal {
  hunkId: string;
  proposedStatus: AcceptanceStatus;
  actor?: DiffActor;
}

export interface MergedResult {
  /** Per-file merged documents (index-aligned with the resolved files). */
  files: { meta?: Diff["file"]; merged: string }[];
  /** Convenience: the first file's merged text (common single-file case). */
  text: string;
}

import { type CSSProperties, type ReactNode, useCallback, useEffect, useState } from "react";
import { StickyNote as FancyStickyNote } from "@particle-academy/react-fancy";
import type { StickyNoteItem } from "../../types";

export type StickyNoteProps = {
  item: StickyNoteItem;
  onChange?: (next: StickyNoteItem) => void;
  onSelect?: (id: string) => void;
  selected?: boolean;
  readOnly?: boolean;
  /** Smallest size resize will allow (default 80×60). */
  minWidth?: number;
  minHeight?: number;
  className?: string;
  style?: CSSProperties;
  /** When provided, replaces the default editable note body. */
  children?: ReactNode;
};

/**
 * StickyNote — draggable, resizable board note.
 *
 * The note's paper look and inline text editing come from react-fancy's shared
 * `<StickyNote>` primitive; this wrapper owns the board concerns: absolute
 * positioning, drag-to-move, corner resize, and selection.
 *
 * Interactions:
 *   • Drag anywhere on the note to move it.
 *   • Click (without dragging) — or double-click — to edit; click outside to commit.
 *   • Drag the bottom-right corner handle to resize.
 *
 * Controlled via `item` + `onChange`.
 */
export function StickyNote({
  item,
  onChange,
  onSelect,
  selected,
  readOnly,
  minWidth = 80,
  minHeight = 60,
  className,
  style,
  children,
}: StickyNoteProps) {
  const [editing, setEditing] = useState(false);
  const [dragging, setDragging] = useState(false);
  const [resizing, setResizing] = useState(false);

  // Deselected by parent → leave edit mode.
  useEffect(() => {
    if (!selected && editing) setEditing(false);
  }, [selected, editing]);

  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (readOnly || !onChange || editing) return;
      if (e.button !== 0 || e.altKey) return;
      onSelect?.(item.id);
      const start = { x: e.clientX, y: e.clientY };
      const origin = { x: item.x, y: item.y };
      const target = e.currentTarget;
      target.setPointerCapture(e.pointerId);
      let moved = false;
      const move = (ev: PointerEvent) => {
        if (!moved && Math.hypot(ev.clientX - start.x, ev.clientY - start.y) < 4) return;
        if (!moved) setDragging(true);
        moved = true;
        onChange({ ...item, x: origin.x + ev.clientX - start.x, y: origin.y + ev.clientY - start.y });
      };
      const up = () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        setDragging(false);
        // Click without drag → enter edit mode (more discoverable than double-click).
        if (!moved && !readOnly) setEditing(true);
      };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", up);
    },
    [item, onChange, onSelect, readOnly, editing],
  );

  const onResizePointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (readOnly || !onChange) return;
      e.stopPropagation();
      e.preventDefault();
      const start = { x: e.clientX, y: e.clientY };
      const origin = { w: item.width, h: item.height };
      const target = e.currentTarget;
      target.setPointerCapture(e.pointerId);
      setResizing(true);
      const move = (ev: PointerEvent) => {
        const w = Math.max(minWidth, origin.w + ev.clientX - start.x);
        const h = Math.max(minHeight, origin.h + ev.clientY - start.y);
        onChange({ ...item, width: w, height: h });
      };
      const up = () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        setResizing(false);
      };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", up);
    },
    [item, onChange, readOnly, minWidth, minHeight],
  );

  return (
    <div
      className={[
        "fw-item fw-sticky",
        dragging ? "fw-item--dragging" : "",
        resizing ? "fw-item--resizing" : "",
        selected ? "fw-sticky--selected" : "",
        editing ? "fw-sticky--editing" : "",
        className ?? "",
      ]
        .filter(Boolean)
        .join(" ")}
      style={{ left: item.x, top: item.y, width: item.width, height: item.height, zIndex: item.z, ...style }}
      onPointerDown={onPointerDown}
      onDoubleClick={() => {
        if (!readOnly) setEditing(true);
      }}
    >
      <FancyStickyNote
        className="h-full w-full"
        color={item.color ?? "yellow"}
        value={item.text}
        editable={!readOnly && editing}
        autoFocus
        onChange={(text) => onChange?.({ ...item, text })}
      >
        {children}
      </FancyStickyNote>
      {!readOnly && onChange && (
        <div className="fw-sticky__resize" onPointerDown={onResizePointerDown} aria-label="Resize note" />
      )}
    </div>
  );
}

import { forwardRef, useLayoutEffect, useRef, useState } from "react";
import { cn } from "../../utils/cn";
import type { FauxClientProps } from "./FauxClient.types";

const DOT_COLORS = ["bg-rose-300", "bg-amber-300", "bg-green-300"];

/**
 * A frame that mimics a browser window or device, rendering **real UI** inside.
 * With a logical `width` + `scale="fit"` it renders a full-size page/app and
 * scales it down to fit any container (live thumbnails, device mockups) — the
 * content is real and interactive, just zoomed.
 *
 * Omit `width` for chrome around natural-size content (e.g. a code/preview card).
 */
export const FauxClient = forwardRef<HTMLDivElement, FauxClientProps>(
  (
    {
      variant = "browser",
      url,
      meta,
      dots = true,
      width,
      scale = "fit",
      className,
      barClassName,
      bodyClassName,
      children,
      ...rest
    },
    ref,
  ) => {
    const scaled = typeof width === "number";
    const viewportRef = useRef<HTMLDivElement>(null);
    const stageRef = useRef<HTMLDivElement>(null);
    const [s, setS] = useState(typeof scale === "number" ? scale : 1);
    const [contentHeight, setContentHeight] = useState<number | undefined>(undefined);

    useLayoutEffect(() => {
      if (!scaled) return;
      const viewport = viewportRef.current;
      const stage = stageRef.current;
      if (!viewport || !stage) return;
      if (typeof ResizeObserver === "undefined") return;

      const measure = () => {
        const avail = viewport.clientWidth;
        const next = scale === "fit" ? (width && width > 0 ? avail / width : 1) : scale;
        // offsetHeight is the pre-transform layout height (CSS transforms don't affect it).
        const naturalHeight = stage.offsetHeight;
        setS(next);
        setContentHeight(naturalHeight * next);
      };

      measure();
      const ro = new ResizeObserver(measure);
      ro.observe(viewport);
      ro.observe(stage);
      return () => ro.disconnect();
    }, [scaled, scale, width]);

    const isBrowser = variant === "browser";
    const isDevice = variant === "device";

    return (
      <div
        ref={ref}
        data-react-fancy-faux-client=""
        className={cn(
          "overflow-hidden bg-white dark:bg-zinc-900",
          isBrowser && "rounded-2xl border border-zinc-200 shadow-xl dark:border-zinc-800",
          isDevice && "rounded-[2rem] border-[10px] border-zinc-800 shadow-2xl dark:border-zinc-700",
          variant === "bare" && "rounded-lg border border-zinc-200 dark:border-zinc-800",
          className,
        )}
        {...rest}
      >
        {isBrowser && (
          <div
            className={cn(
              "flex items-center gap-2 border-b border-zinc-200 bg-zinc-50 px-3.5 py-2.5 font-mono text-[11.5px] text-zinc-500 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-400",
              barClassName,
            )}
          >
            {dots && (
              <div className="mr-1.5 flex gap-[5px]">
                {DOT_COLORS.map((color, i) => (
                  <span key={i} className={cn("h-[9px] w-[9px] rounded-full", color)} />
                ))}
              </div>
            )}
            {url != null && <span className="min-w-0 flex-1 truncate">{url}</span>}
            {meta != null && <span className="shrink-0 text-zinc-400 dark:text-zinc-500">{meta}</span>}
          </div>
        )}

        <div
          ref={viewportRef}
          className={cn("relative overflow-hidden", bodyClassName)}
          style={scaled ? { height: contentHeight } : undefined}
        >
          {scaled ? (
            <div
              ref={stageRef}
              className="absolute left-0 top-0 origin-top-left"
              style={{ width, transform: `scale(${s})` }}
            >
              {children}
            </div>
          ) : (
            children
          )}
        </div>
      </div>
    );
  },
);

FauxClient.displayName = "FauxClient";

import type { HTMLAttributes, ReactNode } from "react";

export interface FauxClientProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  /** Chrome style: a browser window, a device bezel, or no chrome. */
  variant?: "browser" | "device" | "bare";
  /** Address-bar / title text (browser variant). */
  url?: ReactNode;
  /** Right-aligned meta text in the bar (browser variant). */
  meta?: ReactNode;
  /** Show the macOS traffic-light dots (browser variant). */
  dots?: boolean;
  /**
   * Logical content width in px. When set, children render at this width and are
   * scaled to fit (see {@link FauxClientProps.scale}) — for downscaled previews
   * of full pages/apps. Omit to render children at natural size (chrome only).
   */
  width?: number;
  /** `"fit"` scales the logical {@link FauxClientProps.width} to the frame; a number is a fixed scale. */
  scale?: number | "fit";
  className?: string;
  /** Class for the browser bar. */
  barClassName?: string;
  /** Class for the content viewport. */
  bodyClassName?: string;
  children?: ReactNode;
}

import { createContext, useContext } from "react";
import type { FileBrowserContextValue } from "./FileBrowser.types";

export const FileBrowserContext = createContext<FileBrowserContextValue | null>(null);

export function useFileBrowser(): FileBrowserContextValue {
  const ctx = useContext(FileBrowserContext);
  if (!ctx) {
    throw new Error("useFileBrowser must be used within a <FileBrowser> component");
  }
  return ctx;
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { cn } from "../../utils/cn";
import { useControllableState } from "../../hooks/use-controllable-state";
import { FileBrowserContext } from "./FileBrowser.context";
import { FileBrowserPathBar } from "./FileBrowserPathBar";
import { FileBrowserToolbar } from "./FileBrowserToolbar";
import { FileBrowserTree } from "./FileBrowserTree";
import { FileBrowserNode } from "./FileBrowserNode";
import {
  compareFileEntries,
  entryMatchesFilter,
  isEntryExpandable,
  parentPath,
} from "./FileBrowser.utils";
import type {
  FileBrowserContextValue,
  FileBrowserProps,
  FileBrowserRow,
  FileEntry,
  FileLoadStatus,
  FileSnapshotNode,
  FileSort,
} from "./FileBrowser.types";

const DEFAULT_SORT: FileSort = { by: "name", direction: "asc" };

function snapshotNodeToEntry(node: FileSnapshotNode): FileEntry {
  const { children: _children, ...entry } = node;
  return entry;
}

/**
 * Index a snapshot tree into a `parent path -> children` map. Roots group
 * under their own parent path (usually `"/"`); any node with a materialized
 * `children` array defines that folder's listing. Dirs with `children`
 * undefined stay unknown — a provider fills them lazily in hybrid mode.
 */
function buildSnapshotMap(snapshot: FileSnapshotNode[] | undefined): Map<string, FileEntry[]> {
  const map = new Map<string, FileEntry[]>();
  if (!snapshot || snapshot.length === 0) return map;

  for (const root of snapshot) {
    const parent = parentPath(root.path);
    const list = map.get(parent);
    if (list) list.push(snapshotNodeToEntry(root));
    else map.set(parent, [snapshotNodeToEntry(root)]);
  }

  const walk = (nodes: FileSnapshotNode[]) => {
    for (const node of nodes) {
      if (node.children) {
        map.set(node.path, node.children.map(snapshotNodeToEntry));
        walk(node.children);
      }
    }
  };
  walk(snapshot);

  return map;
}

/**
 * FileBrowser — remote-capable file/folder browser + directory picker.
 *
 * Browses any file tree the host can describe — local FS, HTTP, SSH, or a
 * remote machine streaming snapshots — via two feeding modes that may be
 * combined:
 *
 * - **Provider mode (lazy pull):** pass `provider.loadChildren(path)`. Folders
 *   load on first expand with per-node loading + error states; the tree is
 *   never walked eagerly.
 * - **Snapshot mode (streamed push):** pass a JSON-friendly `snapshot` tree
 *   and replace/patch it as chunks arrive (relay / WebSocket / MCP). The
 *   snapshot is the source of truth for every path it covers; with a provider
 *   also present, unknown-depth folders stay lazily loadable (hybrid).
 *
 * Fully controlled per the Human+ component contract (`value`/`onChange`,
 * `path`/`onPathChange`, `expandedPaths`/`onExpandedChange`, plus
 * `sort`/`filter`), with uncontrolled `defaultX` fallbacks. Every row carries
 * a `data-path` attribute — paths are the stable handles agents target, never
 * indexes or generated ids.
 *
 * Agent bridge sketch (ships later in `@particle-academy/agent-integrations`):
 * `registerFilesBridge(server, { adapter })` will expose MCP tools over this
 * surface — `files_list(path)`, `files_expand(path)` / `files_collapse(path)`,
 * `files_select(paths)`, `files_navigate(path)`, and
 * `files_request_snapshot(path, depth)` — with each mutation emitting an
 * `AgentActivity` event so presence, undo, and coaching layers compose. The
 * adapter maps those tools onto the same controlled props
 * (`value`/`path`/`expandedPaths`) and provider/snapshot contract; no DOM
 * scraping required.
 *
 * Read-only in v1: no content preview (pair with fancy-code's `FileViewer`)
 * and no write operations — rename/delete/upload arrive later behind a
 * `pendingMode`-gated iteration.
 */
function FileBrowserRoot({
  provider,
  snapshot,
  select = "file",
  multiple = false,
  value,
  defaultValue,
  onChange,
  path,
  defaultPath = "/",
  onPathChange,
  expandedPaths,
  defaultExpandedPaths,
  onExpandedChange,
  sort,
  defaultSort,
  onSortChange,
  filter,
  defaultFilter,
  onFilterChange,
  onError,
  onCreateFolder,
  indentSize = 16,
  showIcons = true,
  className,
  children,
}: FileBrowserProps) {
  // ---------------------------------------------------------------------------
  // Controlled / uncontrolled state
  // ---------------------------------------------------------------------------

  const [currentPath, setCurrentPath] = useControllableState(path, defaultPath, onPathChange);
  const [expanded, setExpanded] = useControllableState(
    expandedPaths,
    defaultExpandedPaths ?? [],
    onExpandedChange,
  );
  const [sortState, setSortState] = useControllableState(sort, defaultSort ?? DEFAULT_SORT, onSortChange);
  const [filterState, setFilterState] = useControllableState(filter, defaultFilter ?? "", onFilterChange);

  // Selection is managed directly (not via useControllableState) because
  // onChange also receives the matching FileEntry objects.
  const [internalValue, setInternalValue] = useState<string | string[] | null>(
    () => defaultValue ?? (multiple ? [] : null),
  );
  const selection = value !== undefined ? value : internalValue;
  const selectedPaths = useMemo(
    () => (selection == null ? [] : Array.isArray(selection) ? selection : [selection]),
    [selection],
  );

  // ---------------------------------------------------------------------------
  // Data layer — snapshot map + lazy provider cache
  // ---------------------------------------------------------------------------

  const snapshotMap = useMemo(() => buildSnapshotMap(snapshot), [snapshot]);

  const [loadedChildren, setLoadedChildren] = useState<Record<string, FileEntry[]>>({});
  const [loadStatus, setLoadStatus] = useState<Record<string, FileLoadStatus>>({});
  const [loadErrors, setLoadErrors] = useState<Record<string, string>>({});

  const seqCounter = useRef(0);
  const requestSeq = useRef<Record<string, number>>({});

  // Latest-state refs so `loadPath` stays referentially stable.
  const stateRef = useRef({ snapshotMap, loadedChildren, loadStatus });
  stateRef.current = { snapshotMap, loadedChildren, loadStatus };
  const providerRef = useRef(provider);
  providerRef.current = provider;
  const onErrorRef = useRef(onError);
  onErrorRef.current = onError;
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  const loadPath = useCallback((targetPath: string, options?: { reload?: boolean }) => {
    const prov = providerRef.current;
    if (!prov) return;
    const { snapshotMap: snap, loadedChildren: loaded, loadStatus: statuses } = stateRef.current;
    const status = statuses[targetPath] ?? "idle";
    if (status === "loading") return;
    const known = snap.get(targetPath) ?? loaded[targetPath];
    if (!options?.reload && (known !== undefined || status === "error")) return;

    const requestId = ++seqCounter.current;
    requestSeq.current[targetPath] = requestId;
    setLoadStatus((prev) => ({ ...prev, [targetPath]: "loading" }));

    prov.loadChildren(targetPath).then(
      (entries) => {
        if (requestSeq.current[targetPath] !== requestId) return;
        setLoadedChildren((prev) => ({ ...prev, [targetPath]: entries }));
        setLoadStatus((prev) => ({ ...prev, [targetPath]: "loaded" }));
        setLoadErrors((prev) => {
          if (!(targetPath in prev)) return prev;
          const next = { ...prev };
          delete next[targetPath];
          return next;
        });
      },
      (error: unknown) => {
        if (requestSeq.current[targetPath] !== requestId) return;
        setLoadStatus((prev) => ({ ...prev, [targetPath]: "error" }));
        setLoadErrors((prev) => ({
          ...prev,
          [targetPath]: error instanceof Error ? error.message : String(error),
        }));
        onErrorRef.current?.(targetPath, error);
      },
    );
  }, []);

  const entriesFor = useCallback(
    (p: string) => snapshotMap.get(p) ?? loadedChildren[p],
    [snapshotMap, loadedChildren],
  );

  const statusFor = useCallback(
    (p: string): FileLoadStatus => {
      if (snapshotMap.has(p)) return "loaded";
      const status = loadStatus[p];
      if (status) return status;
      return loadedChildren[p] !== undefined ? "loaded" : "idle";
    },
    [snapshotMap, loadStatus, loadedChildren],
  );

  const errorFor = useCallback((p: string) => loadErrors[p], [loadErrors]);

  // Lazy loading — only the current directory and explicitly expanded folders
  // (including expansions driven from outside via the controlled
  // `expandedPaths` prop). Never an eager walk; errored paths wait for an
  // explicit retry.
  useEffect(() => {
    if (!provider) return;
    loadPath(currentPath);
    for (const p of expanded) loadPath(p);
  }, [provider, currentPath, expanded, snapshotMap, loadPath]);

  // ---------------------------------------------------------------------------
  // Filter + sort + flattened visible rows
  // ---------------------------------------------------------------------------

  const filterLower = filterState.trim().toLowerCase();

  const visibleChildrenFor = useCallback(
    (p: string): FileEntry[] => {
      const entries = entriesFor(p);
      if (!entries) return [];
      const filtered = filterLower
        ? entries.filter((entry) => entryMatchesFilter(entry, filterLower, entriesFor))
        : entries.slice();
      return filtered.sort((a, b) => compareFileEntries(a, b, sortState));
    },
    [entriesFor, filterLower, sortState],
  );

  const visibleRows = useMemo(() => {
    const rows: FileBrowserRow[] = [];
    const visited = new Set<string>([currentPath]);
    const walk = (p: string, depth: number, parent: string | null) => {
      for (const entry of visibleChildrenFor(p)) {
        const expandable = isEntryExpandable(entry, entriesFor(entry.path), !!provider);
        const isOpen = expandable && expanded.includes(entry.path);
        rows.push({ entry, depth, expandable, expanded: isOpen, parentPath: parent });
        if (isOpen && !visited.has(entry.path)) {
          visited.add(entry.path);
          walk(entry.path, depth + 1, entry.path);
        }
      }
    };
    walk(currentPath, 0, null);
    return rows;
  }, [visibleChildrenFor, entriesFor, provider, expanded, currentPath]);

  // ---------------------------------------------------------------------------
  // Selection
  // ---------------------------------------------------------------------------

  const entryIndex = useMemo(() => {
    const map = new Map<string, FileEntry>();
    for (const list of snapshotMap.values()) {
      for (const entry of list) map.set(entry.path, entry);
    }
    for (const list of Object.values(loadedChildren)) {
      for (const entry of list) {
        if (!map.has(entry.path)) map.set(entry.path, entry);
      }
    }
    return map;
  }, [snapshotMap, loadedChildren]);

  const isSelectable = useCallback(
    (entry: FileEntry) =>
      !entry.disabled &&
      (select === "both" || (select === "file" ? entry.kind === "file" : entry.kind === "dir")),
    [select],
  );

  const isSelected = useCallback((p: string) => selectedPaths.includes(p), [selectedPaths]);

  const commitSelection = useCallback(
    (paths: string[]) => {
      const nextValue = multiple ? paths : (paths[0] ?? null);
      if (value === undefined) setInternalValue(nextValue);
      onChangeRef.current?.(
        nextValue,
        paths
          .map((p) => entryIndex.get(p))
          .filter((entry): entry is FileEntry => entry !== undefined),
      );
    },
    [multiple, value, entryIndex],
  );

  const selectEntry = useCallback(
    (entry: FileEntry) => {
      if (!isSelectable(entry)) return;
      if (multiple) {
        commitSelection(
          selectedPaths.includes(entry.path)
            ? selectedPaths.filter((p) => p !== entry.path)
            : [...selectedPaths, entry.path],
        );
      } else {
        commitSelection([entry.path]);
      }
    },
    [isSelectable, multiple, selectedPaths, commitSelection],
  );

  // ---------------------------------------------------------------------------
  // Expansion, navigation, roving focus
  // ---------------------------------------------------------------------------

  const toggleExpanded = useCallback(
    (p: string) => {
      setExpanded((prev) => (prev.includes(p) ? prev.filter((x) => x !== p) : [...prev, p]));
    },
    [setExpanded],
  );

  const [focusedPath, setFocusedPath] = useState<string | null>(null);

  const navigate = useCallback(
    (p: string) => {
      setCurrentPath(p);
      setFilterState("");
      setFocusedPath(null);
    },
    [setCurrentPath, setFilterState],
  );

  const rowRefs = useRef(new Map<string, HTMLElement>());

  const registerRow = useCallback((p: string, el: HTMLElement | null) => {
    if (el) rowRefs.current.set(p, el);
    else rowRefs.current.delete(p);
  }, []);

  const focusRow = useCallback((p: string) => {
    rowRefs.current.get(p)?.focus();
  }, []);

  const tabFocusPath = useMemo(() => {
    if (focusedPath && visibleRows.some((row) => row.entry.path === focusedPath)) {
      return focusedPath;
    }
    return visibleRows[0]?.entry.path ?? null;
  }, [focusedPath, visibleRows]);

  // ---------------------------------------------------------------------------
  // Context + render
  // ---------------------------------------------------------------------------

  const ctx = useMemo<FileBrowserContextValue>(
    () => ({
      entriesFor,
      visibleChildrenFor,
      statusFor,
      errorFor,
      loadPath,
      hasProvider: !!provider,
      path: currentPath,
      navigate,
      expandedPaths: expanded,
      toggleExpanded,
      select,
      multiple,
      selectedPaths,
      isSelected,
      isSelectable,
      selectEntry,
      sort: sortState,
      setSort: setSortState,
      filter: filterState,
      setFilter: setFilterState,
      visibleRows,
      focusedPath,
      setFocusedPath,
      tabFocusPath,
      focusRow,
      registerRow,
      indentSize,
      showIcons,
      onCreateFolder,
    }),
    [
      entriesFor, visibleChildrenFor, statusFor, errorFor, loadPath, provider,
      currentPath, navigate, expanded, toggleExpanded, select, multiple,
      selectedPaths, isSelected, isSelectable, selectEntry, sortState,
      setSortState, filterState, setFilterState, visibleRows, focusedPath,
      tabFocusPath, focusRow, registerRow, indentSize, showIcons, onCreateFolder,
    ],
  );

  return (
    <FileBrowserContext.Provider value={ctx}>
      <div
        data-react-fancy-file-browser=""
        className={cn(
          "flex flex-col overflow-hidden rounded-lg border border-zinc-200 bg-white text-sm dark:border-zinc-700 dark:bg-zinc-900",
          className,
        )}
      >
        {children ?? (
          <>
            <FileBrowserPathBar />
            <FileBrowserToolbar />
            <FileBrowserTree />
          </>
        )}
      </div>
    </FileBrowserContext.Provider>
  );
}

FileBrowserRoot.displayName = "FileBrowser";

export const FileBrowser = Object.assign(FileBrowserRoot, {
  PathBar: FileBrowserPathBar,
  Toolbar: FileBrowserToolbar,
  Tree: FileBrowserTree,
  Node: FileBrowserNode,
});

import type { ReactNode } from "react";

/** Entry kind — regular file or directory. */
export type FileKind = "file" | "dir";

/**
 * A single file-system entry. JSON-friendly by design so agents and remote
 * hosts can emit entries directly (over MCP, a relay, or a WebSocket).
 * `path` is the stable identity — POSIX-style, never an index.
 */
export interface FileEntry {
  /** Stable identity — POSIX-style path (e.g. `"/src/App.tsx"`). */
  path: string;
  /** Display name (usually the last path segment). */
  name: string;
  /** `"file"` or `"dir"`. */
  kind: FileKind;
  /** Size in bytes (optional; shown for files and used by size sorting). */
  size?: number;
  /** Last-modified timestamp, ISO 8601 (optional; used by mtime sorting). */
  mtime?: string;
  /**
   * Dirs only: `false` = known-empty (no expand affordance), `true` = has
   * children, `undefined` = unknown (expandable when a provider is present).
   */
  hasChildren?: boolean;
  /** Disabled entries render dimmed and cannot be selected, expanded, or navigated into. */
  disabled?: boolean;
}

/**
 * JSON-friendly snapshot node — a {@link FileEntry} plus optionally
 * materialized children. `children: undefined` on a dir = unknown depth (a
 * provider fills it lazily in hybrid mode); `children: []` = known-empty.
 */
export interface FileSnapshotNode extends FileEntry {
  children?: FileSnapshotNode[];
}

/** Async data source for provider mode. Works against local FS, HTTP, MCP bridges, SSH adapters — anything that resolves a listing. */
export interface FileBrowserProvider {
  /**
   * Load the direct children of `path`. Called lazily — only for the current
   * directory and explicitly expanded folders. The component never walks the
   * tree eagerly.
   */
  loadChildren: (path: string) => Promise<FileEntry[]>;
}

/** Which entry kinds are selectable. */
export type FileSelectMode = "file" | "directory" | "both";

export type FileSortField = "name" | "size" | "mtime";
export type FileSortDirection = "asc" | "desc";

/** Sort order for directory listings. Directories always sort before files. */
export interface FileSort {
  by: FileSortField;
  direction: FileSortDirection;
}

/** Per-path load lifecycle for provider mode. */
export type FileLoadStatus = "idle" | "loading" | "loaded" | "error";

export interface FileBrowserProps {
  /** Async data source (provider mode). Folders load on first expand — never an eager walk. */
  provider?: FileBrowserProvider;
  /**
   * JSON-friendly tree value (snapshot mode). Replace or patch it from outside
   * as stream chunks land — the component treats it as the source of truth for
   * every path it covers. May be combined with `provider` (hybrid): the
   * snapshot seeds, the provider fills unknown-depth folders.
   */
  snapshot?: FileSnapshotNode[];
  /** Which entry kinds are selectable (default `"file"`). Non-selectable entries stay browsable. */
  select?: FileSelectMode;
  /** Allow selecting multiple entries; `value` becomes `string[]` (default `false`). */
  multiple?: boolean;
  /** Controlled selection — a path, an array of paths (`multiple`), or `null`. */
  value?: string | string[] | null;
  /** Initial selection (uncontrolled). */
  defaultValue?: string | string[] | null;
  /** Called with the next selection and the matching known entries. */
  onChange?: (value: string | string[] | null, entries: FileEntry[]) => void;
  /** Controlled current directory. */
  path?: string;
  /** Initial current directory (uncontrolled, default `"/"`). */
  defaultPath?: string;
  /** Called when the current directory changes (breadcrumb click, path input, double-clicked folder). */
  onPathChange?: (path: string) => void;
  /** Controlled expanded folder paths. */
  expandedPaths?: string[];
  /** Initially expanded folder paths (uncontrolled). */
  defaultExpandedPaths?: string[];
  /** Called when the expanded set changes. */
  onExpandedChange?: (paths: string[]) => void;
  /** Controlled sort order. */
  sort?: FileSort;
  /** Initial sort order (uncontrolled, default `{ by: "name", direction: "asc" }`). */
  defaultSort?: FileSort;
  /** Called when the sort order changes. */
  onSortChange?: (sort: FileSort) => void;
  /** Controlled name filter — a client-side substring match over loaded nodes. */
  filter?: string;
  /** Initial name filter (uncontrolled). */
  defaultFilter?: string;
  /** Called when the name filter changes. */
  onFilterChange?: (filter: string) => void;
  /** Called when a provider load rejects; the failed folder shows an inline error with a retry. */
  onError?: (path: string, error: unknown) => void;
  /**
   * Create a folder. **Supplying this is the opt-in** — the toolbar renders a
   * "New folder" button only when it is present, so a visible button and a
   * working one cannot disagree.
   *
   * Receives the directory currently being viewed and the trimmed name, both
   * already validated against what is in that directory. Reject the promise to
   * surface a message on the form; in provider mode a resolved promise reloads
   * the directory so the folder appears.
   */
  onCreateFolder?: (input: { parentPath: string; name: string }) => void | Promise<void>;
  /** Indent per nesting level in px (default `16`). */
  indentSize?: number;
  /** Show file/folder icons (default `true`). */
  showIcons?: boolean;
  /** Custom className for the outer shell. */
  className?: string;
  /**
   * Custom layout. When omitted, renders the default
   * `<FileBrowser.PathBar />` + `<FileBrowser.Toolbar />` + `<FileBrowser.Tree />`.
   */
  children?: ReactNode;
}

/** A flattened, visible row — the keyboard-navigation order of the tree pane. */
export interface FileBrowserRow {
  entry: FileEntry;
  depth: number;
  /** Whether the row shows an expand affordance. */
  expandable: boolean;
  /** Whether the row is currently expanded. */
  expanded: boolean;
  /** Path of the parent row, or `null` for top-level rows of the current directory. */
  parentPath: string | null;
}

export interface FileBrowserContextValue {
  // Data
  /** Known children of a path (snapshot first, then provider cache), or `undefined` when not yet loaded. */
  entriesFor: (path: string) => FileEntry[] | undefined;
  /** Children of a path after the name filter + sort are applied (empty when unknown). */
  visibleChildrenFor: (path: string) => FileEntry[];
  statusFor: (path: string) => FileLoadStatus;
  errorFor: (path: string) => string | undefined;
  /** Request a lazy load of a path's children (no-op without a provider or when already known/loading). */
  loadPath: (path: string, options?: { reload?: boolean }) => void;
  hasProvider: boolean;
  // Navigation
  path: string;
  /** Change the current directory (also clears the name filter and resets roving focus). */
  navigate: (path: string) => void;
  // Expansion
  expandedPaths: string[];
  toggleExpanded: (path: string) => void;
  // Selection
  select: FileSelectMode;
  multiple: boolean;
  selectedPaths: string[];
  isSelected: (path: string) => boolean;
  isSelectable: (entry: FileEntry) => boolean;
  selectEntry: (entry: FileEntry) => void;
  // Sort + filter
  sort: FileSort;
  setSort: (sort: FileSort) => void;
  filter: string;
  setFilter: (filter: string) => void;
  // Keyboard / roving focus
  visibleRows: FileBrowserRow[];
  focusedPath: string | null;
  setFocusedPath: (path: string | null) => void;
  /** The row that currently owns `tabIndex={0}`. */
  tabFocusPath: string | null;
  focusRow: (path: string) => void;
  registerRow: (path: string, el: HTMLElement | null) => void;
  // Presentation
  indentSize: number;
  showIcons: boolean;
  /** Present only when the host opted in. See {@link FileBrowserProps.onCreateFolder}. */
  onCreateFolder?: (input: { parentPath: string; name: string }) => void | Promise<void>;
}

export interface FileBrowserPathBarProps {
  /** Allow switching to the editable path input (default `true`). */
  editable?: boolean;
  /** Placeholder for the path input. */
  placeholder?: string;
  className?: string;
}

export interface FileBrowserToolbarProps {
  /** Placeholder for the name filter input (default `"Filter"`). */
  filterPlaceholder?: string;
  className?: string;
}

export interface FileBrowserTreeProps {
  /** Accessible label for the tree (default `"Files"`). */
  ariaLabel?: string;
  className?: string;
}

export interface FileBrowserNodeProps {
  entry: FileEntry;
  depth: number;
}

import type { FileEntry, FileSort } from "./FileBrowser.types";

/**
 * Normalize free-typed path input: forward slashes, collapsed separators,
 * resolved `.` / `..` segments, no trailing slash. Absolute paths stay
 * absolute; relative paths stay relative (entry paths are identity and are
 * never rewritten — this is only for the editable path input).
 */
export function normalizePath(input: string): string {
  const raw = input.trim().replace(/\\/g, "/");
  if (raw === "") return "/";
  const absolute = raw.startsWith("/");
  const out: string[] = [];
  for (const segment of raw.split("/")) {
    if (segment === "" || segment === ".") continue;
    if (segment === "..") {
      out.pop();
      continue;
    }
    out.push(segment);
  }
  if (out.length === 0) return "/";
  return (absolute ? "/" : "") + out.join("/");
}

/** Parent of a path. Paths without a separator group under `"/"`. */
export function parentPath(path: string): string {
  const i = path.lastIndexOf("/");
  if (i === -1) return "/";
  if (i === 0) return "/";
  return path.slice(0, i);
}

export interface PathSegment {
  label: string;
  path: string;
}

/** Cumulative breadcrumb segments for a path (root anchor excluded). */
export function pathSegments(path: string): PathSegment[] {
  const absolute = path.startsWith("/");
  const parts = path.split("/").filter(Boolean);
  const segments: PathSegment[] = [];
  let acc = "";
  parts.forEach((part, i) => {
    acc = i === 0 && !absolute ? part : `${acc}/${part}`;
    segments.push({ label: part, path: acc });
  });
  return segments;
}

/**
 * Deterministic, numeric-aware name comparison. The locale is pinned to "en"
 * so server and client renders order identically (SSR safety).
 */
function compareNames(a: string, b: string): number {
  const cmp = a.localeCompare(b, "en", { numeric: true, sensitivity: "base" });
  if (cmp !== 0) return cmp;
  return a < b ? -1 : a > b ? 1 : 0;
}

/** Dirs-first, then the active sort field, with a stable ascending name tie-break. */
export function compareFileEntries(a: FileEntry, b: FileEntry, sort: FileSort): number {
  if (a.kind !== b.kind) return a.kind === "dir" ? -1 : 1;
  const direction = sort.direction === "desc" ? -1 : 1;
  let cmp: number;
  switch (sort.by) {
    case "size":
      cmp = (a.size ?? -1) - (b.size ?? -1);
      break;
    case "mtime": {
      const am = a.mtime ?? "";
      const bm = b.mtime ?? "";
      cmp = am < bm ? -1 : am > bm ? 1 : 0;
      break;
    }
    default:
      cmp = compareNames(a.name, b.name);
  }
  if (cmp !== 0) return direction * cmp;
  return compareNames(a.name, b.name);
}

/**
 * Whether a dir shows an expand affordance: known-empty dirs never do
 * (`hasChildren: false`, or a loaded/snapshot listing of zero entries);
 * unknown-depth dirs only do when a provider can load them.
 */
export function isEntryExpandable(
  entry: FileEntry,
  children: FileEntry[] | undefined,
  hasProvider: boolean,
): boolean {
  if (entry.kind !== "dir" || entry.hasChildren === false) return false;
  if (children !== undefined) return children.length > 0;
  return hasProvider;
}

/**
 * Client-side name filter over loaded nodes only: an entry matches when its
 * name contains the query, or (for dirs) when any already-loaded descendant
 * matches. Never triggers loads.
 */
export function entryMatchesFilter(
  entry: FileEntry,
  query: string,
  entriesFor: (path: string) => FileEntry[] | undefined,
  visited: Set<string> = new Set(),
): boolean {
  if (entry.name.toLowerCase().includes(query)) return true;
  if (entry.kind !== "dir" || visited.has(entry.path)) return false;
  visited.add(entry.path);
  const children = entriesFor(entry.path);
  return children?.some((child) => entryMatchesFilter(child, query, entriesFor, visited)) ?? false;
}

/** Compact, deterministic byte formatting ("1.4 KB", "12 MB"). */
export function formatFileSize(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes < 0) return "";
  if (bytes < 1024) return `${bytes} B`;
  const units = ["KB", "MB", "GB", "TB"];
  let value = bytes;
  let unit = -1;
  do {
    value /= 1024;
    unit++;
  } while (value >= 1024 && unit < units.length - 1);
  const rounded = value >= 100 ? Math.round(value) : Math.round(value * 10) / 10;
  return `${rounded} ${units[unit]}`;
}

/**
 * Why a proposed folder name cannot be used, or `null` if it can.
 *
 * Only checks what the BROWSER can know: that the name is a name rather than a
 * path, and that nothing in this directory already answers to it. Case
 * sensitivity, reserved device names and length limits depend on a filesystem
 * this component cannot see, so they stay the host's to enforce — and the host
 * rejecting a create is a supported outcome, surfaced on the form.
 *
 * A collision counts against FILES too. `mkdir` fails the same way either way,
 * and "there is already an index.ts here" is the useful message.
 */
export function validateFolderName(
  raw: string,
  siblings: ReadonlyArray<{ name: string }>,
): string | null {
  const name = raw.trim();

  if (name === "") return "Enter a name.";
  // `/` and `\` make it a path, not a name; `.`/`..` are traversal. Forwarding
  // either would make the host decide what an escape attempt means.
  if (name.includes("/") || name.includes("\\")) return "A name cannot contain / or \.";
  if (name === "." || name === "..") return "That name is reserved.";

  if (siblings.some((entry) => entry.name === name)) {
    return `“${name}” already exists here.`;
  }

  return null;
}

import { useEffect, useRef, useState } from "react";
import { FolderPlus } from "lucide-react";
import { cn } from "../../utils/cn";
import { useFileBrowser } from "./FileBrowser.context";
import { validateFolderName } from "./FileBrowser.utils";

/**
 * The "New folder" affordance — rendered only when the host opted in by
 * supplying `onCreateFolder`.
 *
 * ## Why an inline input and not `window.prompt`
 *
 * A prompt blocks the event loop, cannot be styled or themed, is unusable on
 * mobile, and — the one that matters for this suite — cannot be driven by an
 * agent. The Human+ contract asks that every interactive element carry a stable
 * handle an agent can target; a native dialog has none.
 *
 * ## Why validation lives here
 *
 * The browser already knows what is in the current directory. The host would
 * have to round-trip to find out, so a duplicate name becomes a failed write
 * and an error toast instead of a message before anything is attempted. Name
 * rules that are about PATHS rather than policy — separators, `.`, `..` — are
 * checked here too: those are not names, and forwarding them makes the host
 * decide what a traversal attempt means.
 *
 * Anything else is the host's call. This does not guess at case-sensitivity,
 * reserved Windows device names, or length limits, because the answer depends
 * on a filesystem the browser cannot see.
 */
export function FileBrowserNewFolder({ className }: { className?: string }) {
  const { path, entriesFor, onCreateFolder, loadPath, hasProvider } = useFileBrowser();

  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (open) inputRef.current?.focus();
  }, [open]);

  // Navigating away mid-name would otherwise create the folder in a directory
  // the person is no longer looking at.
  useEffect(() => {
    setOpen(false);
    setName("");
    setError(null);
  }, [path]);

  if (!onCreateFolder) return null;

  const siblings = entriesFor(path) ?? [];
  const problem = validateFolderName(name, siblings);
  const canSubmit = !busy && problem === null;

  const close = () => {
    setOpen(false);
    setName("");
    setError(null);
  };

  const submit = async () => {
    if (busy) return;
    const trimmed = name.trim();
    const invalid = validateFolderName(name, siblings);
    if (invalid) {
      setError(invalid);
      return;
    }

    setBusy(true);
    setError(null);
    try {
      await onCreateFolder({ parentPath: path, name: trimmed });
      // Only on success. Reloading after a failure would hide the failure
      // behind an unchanged listing, and closing would claim it worked.
      if (hasProvider) loadPath(path, { reload: true });
      setOpen(false);
      setName("");
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  };

  if (!open) {
    return (
      <button
        type="button"
        data-react-fancy-file-browser-new-folder=""
        onClick={() => setOpen(true)}
        title={`New folder in ${path}`}
        className={cn(
          "flex shrink-0 items-center gap-1 rounded-md px-1.5 py-0.5 text-xs text-zinc-500 transition-colors",
          "hover:bg-zinc-100 hover:text-zinc-700 dark:hover:bg-zinc-800 dark:hover:text-zinc-300",
          className,
        )}
      >
        <FolderPlus size={13} aria-hidden="true" />
        New folder
      </button>
    );
  }

  // Show the reason as soon as there is a name to judge — but not for an empty
  // field, which is "not typed yet" rather than wrong.
  //
  // This pairs with the disabled submit deliberately. A disabled button and no
  // explanation is the worst combination: the person has typed something
  // reasonable, the control is dead, and nothing says the folder already
  // exists. Either the button explains on click or the message is already
  // there; this takes the second, so the answer arrives before they reach for
  // the button.
  const shown = error ?? (name.trim() !== "" ? problem : null);

  return (
    <div
      data-react-fancy-file-browser-new-folder-form=""
      className={cn("flex shrink-0 flex-col gap-0.5", className)}
    >
      <div className="flex items-center gap-1">
        <FolderPlus size={13} aria-hidden="true" className="shrink-0 text-zinc-400" />
        <input
          ref={inputRef}
          type="text"
          data-react-fancy-file-browser-new-folder-input=""
          value={name}
          disabled={busy}
          aria-label="New folder name"
          aria-invalid={shown ? true : undefined}
          spellCheck={false}
          placeholder="Folder name"
          onChange={(e) => {
            setName(e.target.value);
            if (error) setError(null);
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              void submit();
            } else if (e.key === "Escape") {
              e.preventDefault();
              close();
            }
          }}
          className={cn(
            "w-32 min-w-0 rounded-md border px-1.5 py-0.5 text-xs outline-none",
            "bg-transparent text-zinc-700 placeholder:text-zinc-400 dark:text-zinc-300",
            shown ? "border-red-400 dark:border-red-500" : "border-zinc-200 dark:border-zinc-700",
          )}
        />
        <button
          type="button"
          data-react-fancy-file-browser-new-folder-submit=""
          disabled={!canSubmit}
          onClick={() => void submit()}
          className="rounded-md px-1.5 py-0.5 text-xs font-medium text-violet-600 transition-colors hover:bg-violet-50 disabled:cursor-not-allowed disabled:opacity-40 dark:text-violet-400 dark:hover:bg-violet-500/10"
        >
          {busy ? "Creating…" : "Create"}
        </button>
        <button
          type="button"
          data-react-fancy-file-browser-new-folder-cancel=""
          onClick={close}
          className="rounded-md px-1.5 py-0.5 text-xs text-zinc-500 transition-colors hover:text-zinc-700 dark:hover:text-zinc-300"
        >
          Cancel
        </button>
      </div>
      {shown && (
        <p
          data-react-fancy-file-browser-new-folder-error=""
          role="alert"
          className="pl-4 text-[11px] text-red-600 dark:text-red-400"
        >
          {shown}
        </p>
      )}
    </div>
  );
}

FileBrowserNewFolder.displayName = "FileBrowserNewFolder";

import { ChevronRight, CircleAlert, Loader2, RotateCw } from "lucide-react";
import { cn } from "../../utils/cn";
import { useFileBrowser } from "./FileBrowser.context";
import { formatFileSize, isEntryExpandable } from "./FileBrowser.utils";
import type { FileBrowserNodeProps } from "./FileBrowser.types";

// ---------------------------------------------------------------------------
// Icons — mirror TreeNav's file/folder icons so both tree surfaces look the
// same (TreeNav keeps them internal; duplicating ~40 lines beats widening its
// public API).
// ---------------------------------------------------------------------------

const EXT_COLORS: Record<string, string> = {
  ts: "#3178c6",
  tsx: "#3178c6",
  js: "#f7df1e",
  jsx: "#f7df1e",
  php: "#777bb4",
  html: "#e34c26",
  htm: "#e34c26",
  css: "#264de4",
  json: "#a1a1aa",
  md: "#71717a",
  yaml: "#cb171e",
  yml: "#cb171e",
};

function FileIcon({ ext }: { ext?: string }) {
  const color = (ext && EXT_COLORS[ext.toLowerCase()]) || "#71717a";
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" className="shrink-0">
      <path d="M4 1h5.5L13 4.5V14a1 1 0 01-1 1H4a1 1 0 01-1-1V2a1 1 0 011-1z" stroke={color} strokeWidth="1.2" />
      <path d="M9 1v4h4" stroke={color} strokeWidth="1.2" />
    </svg>
  );
}

function FolderIcon({ open }: { open: boolean }) {
  if (open) {
    return (
      <svg width="16" height="16" viewBox="0 0 16 16" fill="none" className="shrink-0">
        <path d="M1.5 3.5a1 1 0 011-1h3l1.5 1.5H13a1 1 0 011 1V5H2.5V3.5z" fill="#fbbf24" />
        <path d="M1 6h13l-1.5 7.5H2.5L1 6z" fill="#fbbf24" opacity="0.7" />
      </svg>
    );
  }
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" className="shrink-0">
      <path d="M1.5 3a1 1 0 011-1h3l1.5 1.5H13a1 1 0 011 1v8a1 1 0 01-1 1H2.5a1 1 0 01-1-1V3z" fill="#fbbf24" />
    </svg>
  );
}

// ---------------------------------------------------------------------------
// Status rows — loading / error / empty placeholders inside the tree. Not
// treeitems (they never receive roving focus); the owning folder carries
// `aria-busy` while its children load.
// ---------------------------------------------------------------------------

export interface FileBrowserStatusRowProps {
  depth: number;
  kind: "loading" | "error" | "empty" | "no-matches" | "unknown";
  message?: string;
  onRetry?: () => void;
}

export function FileBrowserStatusRow({ depth, kind, message, onRetry }: FileBrowserStatusRowProps) {
  const { indentSize } = useFileBrowser();
  const paddingLeft = depth * indentSize + 4 + 18;

  if (kind === "error") {
    return (
      <div
        role="none"
        data-react-fancy-file-browser-status="error"
        className="flex items-center gap-1.5 py-0.5 pr-2 text-xs text-red-600 dark:text-red-400"
        style={{ paddingLeft }}
      >
        <CircleAlert size={12} className="shrink-0" />
        <span className="min-w-0 flex-1 truncate">{message || "Failed to load"}</span>
        {onRetry && (
          <button
            type="button"
            onClick={onRetry}
            className="flex shrink-0 items-center gap-1 rounded-md px-1.5 py-0.5 text-[11px] text-zinc-500 transition-colors hover:bg-zinc-100 hover:text-zinc-700 dark:text-zinc-400 dark:hover:bg-zinc-800 dark:hover:text-zinc-200"
          >
            <RotateCw size={11} />
            Retry
          </button>
        )}
      </div>
    );
  }

  return (
    <div
      role="none"
      data-react-fancy-file-browser-status={kind}
      className="flex items-center gap-1.5 py-0.5 text-xs text-zinc-400 italic dark:text-zinc-500"
      style={{ paddingLeft }}
    >
      {kind === "loading" && <Loader2 size={12} className="shrink-0 animate-spin" aria-hidden="true" />}
      <span className="truncate">
        {kind === "loading" ? "Loading…" : kind === "empty" ? "Empty" : kind === "no-matches" ? "No matches" : "No entries"}
      </span>
    </div>
  );
}

FileBrowserStatusRow.displayName = "FileBrowserStatusRow";

// ---------------------------------------------------------------------------
// Node
// ---------------------------------------------------------------------------

export function FileBrowserNode({ entry, depth }: FileBrowserNodeProps) {
  const {
    entriesFor, visibleChildrenFor, statusFor, errorFor, loadPath, hasProvider,
    expandedPaths, toggleExpanded, navigate,
    isSelected, isSelectable, selectEntry,
    tabFocusPath, setFocusedPath, focusRow, registerRow,
    indentSize, showIcons,
  } = useFileBrowser();

  const rawChildren = entriesFor(entry.path);
  const childrenKnown = rawChildren !== undefined;
  const expandable = isEntryExpandable(entry, rawChildren, hasProvider);
  const expanded = expandable && expandedPaths.includes(entry.path);
  const status = statusFor(entry.path);
  const selectable = isSelectable(entry);
  const selected = isSelected(entry.path);
  const loading = expanded && !childrenKnown && status === "loading";
  const paddingLeft = depth * indentSize + 4;
  const ext = entry.name.includes(".") ? entry.name.split(".").pop() : undefined;

  const handleClick = () => {
    if (entry.disabled) return;
    setFocusedPath(entry.path);
    focusRow(entry.path);
    if (selectable) selectEntry(entry);
    if (expandable) toggleExpanded(entry.path);
  };

  const handleDoubleClick = () => {
    if (entry.disabled || entry.kind !== "dir") return;
    navigate(entry.path);
  };

  const handleChevronClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!entry.disabled && expandable) toggleExpanded(entry.path);
  };

  const visibleChildren = expanded && childrenKnown ? visibleChildrenFor(entry.path) : [];

  return (
    <div
      role="treeitem"
      data-react-fancy-file-browser-node=""
      data-path={entry.path}
      data-kind={entry.kind}
      aria-level={depth + 1}
      aria-expanded={expandable ? expanded : undefined}
      aria-selected={selectable ? selected : undefined}
      aria-disabled={entry.disabled || undefined}
      aria-busy={loading || undefined}
      tabIndex={tabFocusPath === entry.path ? 0 : -1}
      ref={(el) => registerRow(entry.path, el)}
      onFocus={(e) => {
        if (e.target === e.currentTarget) setFocusedPath(entry.path);
      }}
      className="group outline-none"
    >
      <div
        data-react-fancy-file-browser-row=""
        onClick={handleClick}
        onDoubleClick={handleDoubleClick}
        className={cn(
          "flex w-full cursor-pointer items-center gap-1 rounded-md py-0.5 pr-2 text-left text-[13px] transition-colors select-none",
          selected
            ? "bg-blue-500/15 text-blue-600 dark:text-blue-400"
            : "text-zinc-700 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800",
          entry.disabled && "pointer-events-none opacity-40",
          "group-focus-visible:ring-2 group-focus-visible:ring-blue-500/40 group-focus-visible:ring-inset",
        )}
        style={{ paddingLeft }}
      >
        {expandable ? (
          loading ? (
            <Loader2 size={14} className="shrink-0 animate-spin text-zinc-400" aria-hidden="true" />
          ) : (
            <button
              type="button"
              tabIndex={-1}
              aria-hidden="true"
              onClick={handleChevronClick}
              className="flex shrink-0 items-center justify-center text-zinc-400 hover:text-zinc-600 dark:hover:text-zinc-300"
            >
              <ChevronRight
                size={14}
                className={cn("transition-transform duration-150", expanded && "rotate-90")}
              />
            </button>
          )
        ) : (
          <span className="w-3.5 shrink-0" />
        )}
        {showIcons &&
          (entry.kind === "dir" ? <FolderIcon open={expanded} /> : <FileIcon ext={ext} />)}
        <span className="min-w-0 flex-1 truncate">{entry.name}</span>
        {entry.kind === "file" && entry.size !== undefined && (
          <span className="shrink-0 text-[11px] text-zinc-400 tabular-nums dark:text-zinc-500">
            {formatFileSize(entry.size)}
          </span>
        )}
      </div>

      {expanded && (
        <div role="group" data-react-fancy-file-browser-node-children="">
          {/* An expanded-but-unknown folder is only reachable with a provider;
              "idle" means its lazy load is about to start, so render it as
              loading (keeps SSR output and the first client frame identical). */}
          {!childrenKnown && (status === "loading" || status === "idle") && (
            <FileBrowserStatusRow depth={depth + 1} kind="loading" />
          )}
          {!childrenKnown && status === "error" && (
            <FileBrowserStatusRow
              depth={depth + 1}
              kind="error"
              message={errorFor(entry.path)}
              onRetry={() => loadPath(entry.path, { reload: true })}
            />
          )}
          {childrenKnown &&
            (visibleChildren.length > 0 ? (
              visibleChildren.map((child) => (
                <FileBrowserNode key={child.path} entry={child} depth={depth + 1} />
              ))
            ) : (
              <FileBrowserStatusRow
                depth={depth + 1}
                kind={rawChildren!.length === 0 ? "empty" : "no-matches"}
              />
            ))}
        </div>
      )}
    </div>
  );
}

