/** Surface a list of validation issues as a soft warning callout. */
export function IssueList({
  issues,
  testid,
}: {
  issues: string[];
  testid?: string;
}) {
  if (!issues.length) return null;
  return (
    <Callout color="amber" data-x-issues={testid ?? ""}>
      <ul style={{ margin: 0, paddingLeft: "1.1rem" }}>
        {issues.map((issue, i) => (
          <li key={i} data-x-issue>
            {issue}
          </li>
        ))}
      </ul>
    </Callout>
  );
}

/**
 * Controlled add/remove list of plain strings rendered as chips with an
 * inline "add a row" input. `disallowedValues` are rejected on add and, if
 * already present, flagged — used by RobotsEditor to keep protected paths out
 * of an Allow list.
 */
export function StringList({
  label,
  values,
  onChange,
  placeholder,
  handle,
  disallowedValues,
  disallowedReason,
}: {
  label?: string;
  values: string[];
  onChange: (next: string[]) => void;
  placeholder?: string;
  /** data-* handle base, e.g. "robots-allow". */
  handle: string;
  disallowedValues?: string[];
  disallowedReason?: (value: string) => string;
}) {
  const [draft, setDraft] = useState("");
  const blocked = new Set(disallowedValues ?? []);

  const add = () => {
    const v = draft.trim();
    if (!v || values.includes(v)) {
      setDraft("");
      return;
    }
    onChange([...values, v]);
    setDraft("");
  };

  const remove = (value: string) =>
    onChange(values.filter((v) => v !== value));

  return (
    <div data-x-list={handle}>
      {label ? (
        <div
          style={{ fontSize: "0.8rem", fontWeight: 600, marginBottom: "0.25rem" }}
        >
          {label}
        </div>
      ) : null}
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          gap: "0.35rem",
          marginBottom: values.length ? "0.4rem" : 0,
        }}
      >
        {values.map((value) => {
          const isBlocked = blocked.has(value);
          return (
            <Badge
              key={value}
              color={isBlocked ? "red" : "slate"}
              variant={isBlocked ? "soft" : "outline"}
              data-x-chip={`${handle}:${value}`}
              title={
                isBlocked && disallowedReason
                  ? disallowedReason(value)
                  : undefined
              }
            >
              {value}
              <button
                type="button"
                onClick={() => remove(value)}
                aria-label={`Remove ${value}`}
                data-x-remove={`${handle}:${value}`}
                style={{
                  marginLeft: "0.35rem",
                  border: "none",
                  background: "transparent",
                  cursor: "pointer",
                  fontWeight: 700,
                }}
              >
                ×
              </button>
            </Badge>
          );
        })}
      </div>
      <div style={{ display: "flex", gap: "0.4rem" }}>
        <Input
          value={draft}
          onValueChange={setDraft}
          placeholder={placeholder}
          data-x-input={`${handle}-draft`}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              add();
            }
          }}
        />
        <Button
          type="button"
          variant="ghost"
          onClick={add}
          data-x-add={handle}
        >
          Add
        </Button>
      </div>
    </div>
  );
}

/** A labelled section wrapper used to group fields inside an editor. */
export function Section({
  title,
  action,
  children,
  handle,
}: {
  title: string;
  action?: React.ReactNode;
  children: React.ReactNode;
  handle?: string;
}) {
  return (
    <section
      data-x-section={handle}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "0.5rem",
        marginBottom: "1rem",
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <h4 style={{ margin: 0, fontSize: "0.9rem", fontWeight: 700 }}>
          {title}
        </h4>
        {action}
      </div>
      {children}
    </section>
  );
}

import { forwardRef, useSyncExternalStore } from "react";
import { cn } from "../../utils/cn";
import { resolveIcon, subscribeIconResolution, getIconResolutionVersion } from "./icon-config";
import type { IconProps } from "./Icon.types";

const sizeClasses: Record<NonNullable<IconProps["size"]>, string> = {
  xs: "h-3 w-3",
  sm: "h-4 w-4",
  md: "h-5 w-5",
  lg: "h-6 w-6",
  xl: "h-8 w-8",
};

const sizePixels: Record<NonNullable<IconProps["size"]>, number> = {
  xs: 12,
  sm: 16,
  md: 20,
  lg: 24,
  xl: 32,
};

export const Icon = forwardRef<HTMLSpanElement, IconProps>(
  ({ size = "md", className, children, name, iconSet, ...props }, ref) => {
    // Re-render when the lazy lucide barrel lands, so `<Icon name>` auto-resolved
    // from lucide appears once loaded. Registered icons resolve synchronously and
    // never trigger the lazy load. SSR snapshot is the same getter (version 0).
    useSyncExternalStore(
      subscribeIconResolution,
      getIconResolutionVersion,
      getIconResolutionVersion,
    );

    let content = children;

    if (name && !children) {
      const ResolvedIcon = resolveIcon(name, iconSet);
      if (ResolvedIcon) {
        content = <ResolvedIcon size={sizePixels[size]} />;
      }
    }

    return (
      <span
        ref={ref}
        aria-hidden="true"
        data-react-fancy-icon=""
        className={cn(
          "inline-flex items-center justify-center flex-shrink-0",
          sizeClasses[size],
          className,
        )}
        {...props}
      >
        {content}
      </span>
    );
  },
);

Icon.displayName = "Icon";

import type { HTMLAttributes } from "react";

export interface IconProps extends HTMLAttributes<HTMLSpanElement> {
  /** Icon container size */
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  /** Icon name to resolve from the registered icon set (e.g., "rocket", "arrow-right") */
  name?: string;
  /** Which registered icon set to use (defaults to the configured default) */
  iconSet?: string;
}

import type { ComponentType } from "react";
import type { IconSet } from "./icon-config.types";

type IconComponent = ComponentType<{ className?: string; size?: number }>;

const registry = new Map<string, IconSet>();
let defaultSetName = "lucide";

/**
 * Addendum layer — icon sets consulted across EVERY lookup, after the active
 * base set but before the lucide auto-fallback, regardless of `defaultSet`.
 * This is how a brand-icon pack (e.g. `@particle-academy/fancy-brand-icons`)
 * layers in: `<Icon name="github" />` resolves the brand mark on top of Lucide
 * (or any swapped base) without a `set=` query. Base set still wins; addenda
 * supplement. Empty by default ⇒ behavior unchanged.
 */
const addenda: IconSet[] = [];

/** Register an icon set as an addendum (supplements every base set). */
export function registerIconAddendum(set: IconSet): void {
  if (!addenda.includes(set)) addenda.push(set);
}

function resolveFromAddenda(name: string): IconComponent | null {
  for (const set of addenda) {
    const hit = set.resolve(name);
    if (hit) return hit as IconComponent;
  }
  return null;
}

function kebabToPascal(str: string): string {
  return str
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("");
}

/**
 * Lazy lucide barrel. The auto-fallback (`<Icon name="…" />` resolving ANY
 * lucide icon by kebab name) needs the whole namespace because names are
 * dynamic — un-tree-shakeable. Importing it eagerly forced all ~5400 icons
 * into react-fancy's main bundle for every consumer (~548KB). Instead we
 * dynamic-import it on first auto-resolve, so the barrel becomes a lazy chunk
 * loaded ONLY by apps that actually use `<Icon name>` with an unregistered
 * icon — never on the critical path. Consumers wanting sync resolution +
 * tree-shaking should `registerIcons({ ...named imports })` (those win and
 * never trigger the lazy load).
 */
let lucideModule: Record<string, IconComponent | undefined> | null = null;
let lucidePromise: Promise<unknown> | null = null;
let lucideVersion = 0;
const lucideListeners = new Set<() => void>();

function ensureLucideLoaded(): void {
  if (lucideModule || lucidePromise) return;
  lucidePromise = import("lucide-react")
    .then((mod) => {
      lucideModule = mod as unknown as Record<string, IconComponent | undefined>;
      lucideVersion++;
      for (const listener of lucideListeners) listener();
    })
    .catch(() => {
      // Leave lucidePromise set so we don't hammer a failed import.
    });
}

/** Subscribe to the lazy lucide load so `<Icon>` can re-render once it lands. */
export function subscribeIconResolution(listener: () => void): () => void {
  lucideListeners.add(listener);
  return () => lucideListeners.delete(listener);
}

/** Snapshot for useSyncExternalStore — bumps when the lucide barrel loads. */
export function getIconResolutionVersion(): number {
  return lucideVersion;
}

/**
 * Fallback resolver: look up any lucide-react icon by its kebab-case name
 * without requiring the consumer to call `registerIcons()` first. Returns null
 * until the lazy barrel has loaded (the first call kicks off the import; `<Icon>`
 * re-renders via `subscribeIconResolution` when it's ready). Overrides
 * registered via `registerIcons()` still win and resolve synchronously.
 */
function resolveFromLucide(name: string): IconComponent | null {
  // SSR-deterministic: never resolve the lazily-imported lucide barrel on the
  // server. A long-running SSR process (e.g. Inertia's node SSR daemon) loads
  // the barrel after its first request, then renders auto-fallback lucide icons
  // that a fresh client (barrel not yet loaded) does NOT have at hydration →
  // React #418 ("server HTML didn't match"). Returning null on the server makes
  // the server render match the client's FIRST render; the icon then appears
  // once the client loads the barrel (via subscribeIconResolution). Registered
  // icons + addenda (brand packs) still resolve synchronously on both sides.
  if (typeof window === "undefined") return null;
  if (!lucideModule) {
    ensureLucideLoaded();
    return null;
  }
  const pascal = kebabToPascal(name);
  const icon = lucideModule[pascal];
  return typeof icon === "function" || (icon && typeof icon === "object") ? (icon as IconComponent) : null;
}

/**
 * Register individual icon components by their kebab-case name.
 *
 * ```tsx
 * import { registerIcons } from "@particle-academy/react-fancy";
 * import { Home, Settings, Mail } from "lucide-react";
 *
 * registerIcons({ Home, Settings, Mail });
 * ```
 *
 * Icons are registered into the default "lucide" icon set and resolved
 * by the `<Icon name="home" />` component using kebab-case names.
 */
export function registerIcons(
  icons: Record<string, ComponentType<{ className?: string; size?: number }>>,
): void {
  let set = registry.get("lucide");
  if (!set) {
    const map = new Map<string, ComponentType<{ className?: string; size?: number }>>();
    set = {
      resolve: (name: string) => {
        const pascal = kebabToPascal(name);
        return map.get(pascal) ?? null;
      },
      _map: map,
    } as IconSet & { _map: Map<string, ComponentType<{ className?: string; size?: number }>> };
    registry.set("lucide", set);
  }
  const map = (set as IconSet & { _map: Map<string, ComponentType<{ className?: string; size?: number }>> })._map;
  for (const [key, component] of Object.entries(icons)) {
    map.set(key, component);
  }
}

export function registerIconSet(name: string, set: IconSet): void {
  registry.set(name, set);
}

export function configureIcons(options: { defaultSet?: string }): void {
  if (options.defaultSet) {
    defaultSetName = options.defaultSet;
  }
}

export function resolveIcon(
  name: string,
  setName?: string,
): IconComponent | null {
  const resolvedSet = setName ?? defaultSetName;
  const set = registry.get(resolvedSet);
  const registered = set ? set.resolve(name) : null;
  if (registered) return registered;
  // Addenda fill gaps after the base set, before the lucide auto-fallback — so a
  // brand pack's `github` wins over lucide's auto-resolved one.
  const fromAddenda = resolveFromAddenda(name);
  if (fromAddenda) return fromAddenda;
  if (resolvedSet === "lucide") return resolveFromLucide(name);
  return null;
}

import type { ComponentType } from "react";

export interface IconSet {
  resolve: (name: string) => ComponentType<{ className?: string; size?: number }> | null;
}

export { Icon } from "./Icon";
export type { IconProps } from "./Icon.types";
export { registerIcons, registerIconSet, registerIconAddendum, configureIcons, resolveIcon } from "./icon-config";
export type { IconSet } from "./icon-config.types";

import type { CSSProperties } from "react";
import type { ImageElement } from "../../../types";

export interface ImageElementRendererProps {
    element: ImageElement;
}

/**
 * Renders an image element. When `element.crop` is set (a window in
 * image-relative 0..1 coords `{x,y,w,h}`), the image is shown cropped to that
 * window: an `overflow:hidden` box clips an inner `<img>` that's been scaled up
 * by `1/w` × `1/h` and offset so the crop window exactly fills the box. Without
 * a crop it's the plain `object-fit` image. The same renderer feeds both the
 * editor canvas and the viewer, so a crop is visible everywhere.
 */
export function ImageElementRenderer({ element }: ImageElementRendererProps) {
    const crop = element.crop;
    const fit = element.fit ?? "contain";

    if (crop && crop.w > 0 && crop.h > 0) {
        // The inner image is scaled so the crop window (fraction w×h of the
        // image) fills 100% of the box; then translated so the window's
        // top-left aligns with the box's top-left.
        const inner: CSSProperties = {
            position: "absolute",
            left: 0,
            top: 0,
            width: `${(1 / crop.w) * 100}%`,
            height: `${(1 / crop.h) * 100}%`,
            transform: `translate(${(-crop.x / crop.w) * 100}%, ${(-crop.y / crop.h) * 100}%)`,
            transformOrigin: "top left",
            objectFit: fit,
            display: "block",
        };
        return (
            <div style={{ position: "relative", width: "100%", height: "100%", overflow: "hidden" }}>
                <img src={element.src} alt={element.alt ?? ""} style={inner} draggable={false} />
            </div>
        );
    }

    return (
        <img
            src={element.src}
            alt={element.alt ?? ""}
            style={{
                width: "100%",
                height: "100%",
                objectFit: fit,
                display: "block",
            }}
            draggable={false}
        />
    );
}

import {
  forwardRef,
  useCallback,
  useRef,
  useState,
  type CSSProperties,
} from "react";
import { cn } from "../../utils/cn";
import { usePanZoom } from "../../hooks/use-pan-zoom";
import type { ImageViewerProps, ImageViewerViewport } from "./ImageViewer.types";

const DEFAULT_VIEWPORT: ImageViewerViewport = { panX: 0, panY: 0, zoom: 1 };

const fitClasses: Record<NonNullable<ImageViewerProps["fit"]>, string> = {
  contain: "h-full w-full object-contain",
  cover: "h-full w-full object-cover",
  none: "max-w-none object-none",
};

function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n));
}

/**
 * A standalone image viewer: fits the image to its container, with optional
 * Ctrl/⌘+wheel zoom, click-drag panning, and a transparency checkerboard. Works
 * anywhere on its own and is also what `<MediaViewer>` renders for images.
 *
 * The pan/zoom viewport is controllable (`viewport` + `onViewportChange`) so an
 * agent bridge can drive it; it's uncontrolled by default.
 *
 * ```tsx
 * <ImageViewer src="/logo.png" alt="logo.png" style={{ height: 320 }} />
 * ```
 */
export const ImageViewer = forwardRef<HTMLDivElement, ImageViewerProps>(
  (
    {
      src,
      alt = "",
      fit = "contain",
      zoomable = true,
      pannable = true,
      controls,
      minZoom = 0.25,
      maxZoom = 8,
      checkerboard = true,
      viewport,
      defaultViewport,
      onViewportChange,
      onLoad,
      onError,
      className,
      style,
    },
    ref,
  ) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [status, setStatus] = useState<"loading" | "loaded" | "error">("loading");

    // Controllable viewport supporting functional updates (usePanZoom needs them).
    const isControlled = viewport !== undefined;
    const [internal, setInternal] = useState<ImageViewerViewport>(
      defaultViewport ?? DEFAULT_VIEWPORT,
    );
    const current = isControlled ? viewport! : internal;
    const currentRef = useRef(current);
    currentRef.current = current;

    const setViewport = useCallback(
      (
        next:
          | ImageViewerViewport
          | ((prev: ImageViewerViewport) => ImageViewerViewport),
      ) => {
        const resolved =
          typeof next === "function" ? next(currentRef.current) : next;
        if (!isControlled) setInternal(resolved);
        onViewportChange?.(resolved);
      },
      [isControlled, onViewportChange],
    );

    const interactive = status === "loaded";
    const { containerProps, isPanning } = usePanZoom({
      viewport: current,
      setViewport,
      minZoom,
      maxZoom,
      pannable: pannable && interactive,
      zoomable: zoomable && interactive,
      containerRef,
    });

    // Zoom about the container centre — used by the +/− buttons.
    const zoomBy = useCallback(
      (factor: number) => {
        const el = containerRef.current;
        if (!el) return;
        const rect = el.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        setViewport((prev) => {
          const newZoom = clamp(prev.zoom * factor, minZoom, maxZoom);
          const ratio = newZoom / prev.zoom;
          return {
            zoom: newZoom,
            panX: cx - (cx - prev.panX) * ratio,
            panY: cy - (cy - prev.panY) * ratio,
          };
        });
      },
      [setViewport, minZoom, maxZoom],
    );

    const reset = useCallback(() => setViewport(DEFAULT_VIEWPORT), [setViewport]);

    const showControls = (controls ?? zoomable) && interactive;
    const transform = `translate(${current.panX}px, ${current.panY}px) scale(${current.zoom})`;

    return (
      <div
        ref={ref}
        data-react-fancy-image-viewer=""
        className={cn(
          "relative isolate overflow-hidden rounded-md select-none",
          checkerboard
            ? "fancy-checkerboard"
            : "bg-zinc-100 dark:bg-zinc-900",
          className,
        )}
        style={style}
      >
        <div
          ref={containerRef}
          data-canvas-bg=""
          className={cn(
            "absolute inset-0 flex items-center justify-center",
            isPanning
              ? "cursor-grabbing"
              : pannable && interactive
                ? "cursor-grab"
                : "",
          )}
          style={
            {
              transform,
              transformOrigin: "0 0",
              willChange: "transform",
              touchAction: zoomable || pannable ? "none" : undefined,
            } as CSSProperties
          }
          onDoubleClick={zoomable ? reset : undefined}
          {...containerProps}
        >
          <img
            src={src}
            alt={alt}
            draggable={false}
            onLoad={() => {
              setStatus("loaded");
              onLoad?.();
            }}
            onError={() => {
              setStatus("error");
              onError?.();
            }}
            className={cn(
              "pointer-events-none block",
              status === "error" && "hidden",
              fitClasses[fit],
            )}
          />
        </div>

        {status === "error" && (
          <div
            data-react-fancy-image-viewer-error=""
            className="absolute inset-0 flex flex-col items-center justify-center gap-1 p-4 text-center text-sm text-zinc-500 dark:text-zinc-400"
          >
            <span className="font-medium">Couldn&apos;t load image</span>
            <span className="max-w-full truncate text-xs opacity-70">{alt || src}</span>
          </div>
        )}

        {showControls && (
          <div
            data-react-fancy-image-viewer-controls=""
            className="absolute bottom-2 right-2 flex items-center gap-0.5 rounded-md border border-zinc-200 bg-white/90 p-0.5 text-zinc-700 shadow-sm backdrop-blur dark:border-zinc-700 dark:bg-zinc-900/90 dark:text-zinc-200"
          >
            <button
              type="button"
              aria-label="Zoom out"
              onClick={() => zoomBy(1 / 1.25)}
              className="flex h-6 w-6 items-center justify-center rounded text-base leading-none hover:bg-zinc-100 dark:hover:bg-zinc-800"
            >
              −
            </button>
            <button
              type="button"
              aria-label="Reset zoom"
              onClick={reset}
              className="min-w-[3rem] rounded px-1 text-center text-xs tabular-nums hover:bg-zinc-100 dark:hover:bg-zinc-800"
            >
              {Math.round(current.zoom * 100)}%
            </button>
            <button
              type="button"
              aria-label="Zoom in"
              onClick={() => zoomBy(1.25)}
              className="flex h-6 w-6 items-center justify-center rounded text-base leading-none hover:bg-zinc-100 dark:hover:bg-zinc-800"
            >
              +
            </button>
          </div>
        )}
      </div>
    );
  },
);

