import { forwardRef, useCallback, useEffect, useId, useMemo, useRef, useState } from "react";
import { cn } from "../../../utils/cn";
import { Field } from "../Field";
import { InputWrapper } from "../InputWrapper";
import { Portal } from "../../Portal";
import { useFloatingPosition } from "../../../hooks/use-floating-position";
import { useOutsideClick } from "../../../hooks/use-outside-click";
import { useEscapeKey } from "../../../hooks/use-escape-key";
import {
  dirtyClasses,
  errorClasses,
  inputBaseClasses,
  inputSizeClasses,
  resolveOption,
} from "../inputs.utils";
import { useFieldMode } from "../mode/FieldMode.context";
import { DisplayValue } from "../mode/DisplayValue";
import { useInlineEdit } from "../mode/useInlineEdit";
import type { InputOption, InputOptionGroup } from "../inputs.types";
import type { SelectProps } from "./Select.types";

function isOptionGroup(
  item: InputOption | InputOptionGroup,
): item is InputOptionGroup {
  return typeof item === "object" && "options" in item;
}

function flattenOptions(list: (InputOption | InputOptionGroup)[]): InputOption[] {
  const flat: InputOption[] = [];
  for (const item of list) {
    if (isOptionGroup(item)) {
      flat.push(...item.options);
    } else {
      flat.push(item);
    }
  }
  return flat;
}

function renderNativeOption(option: InputOption, index: number) {
  const resolved = resolveOption(option);
  return (
    <option
      key={`${resolved.value}-${index}`}
      value={resolved.value as string}
      disabled={resolved.disabled}
    >
      {resolved.label}
    </option>
  );
}

// ── Native variant ──────────────────────────────────────────────────────

const NativeSelect = forwardRef<HTMLSelectElement, SelectProps>(
  (
    {
      size = "md",
      dirty,
      error,
      label,
      labelHidden,
      description,
      required,
      disabled,
      className,
      id,
      list,
      placeholder,
      prefix,
      suffix,
      prefixPosition,
      suffixPosition,
      mode,
      onValueChange,
      onChange,
      value,
      defaultValue,
      ...props
    },
    ref,
  ) => {
    const autoId = useId();
    const selectId = id ?? autoId;
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);

    if (!showControl) {
      const current = (value ?? defaultValue) as string | undefined;
      const opt = flattenOptions(list)
        .map((o) => resolveOption(o))
        .find((o) => o.value === current);
      const display = (
        <DisplayValue
          size={size}
          leading={prefix}
          trailing={suffix}
          interactive={interactive}
          onActivate={enterEdit}
        >
          {opt?.label ?? current}
        </DisplayValue>
      );
      if (label || error || description) {
        return (
          <Field
            label={label}
            labelHidden={labelHidden}
            description={description}
            error={error}
            required={required}
            htmlFor={selectId}
            size={size}
          >
            {display}
          </Field>
        );
      }
      return display;
    }

    // When a placeholder is provided but no value/defaultValue, default to ""
    // so the disabled placeholder <option> is the initial selection instead of
    // the browser auto-picking the first real option.
    const isControlled = value !== undefined;
    const resolvedDefault =
      !isControlled && defaultValue === undefined && placeholder ? "" : defaultValue;

    const select = (
      <InputWrapper
        prefix={prefix}
        suffix={suffix}
        prefixPosition={prefixPosition}
        suffixPosition={suffixPosition}
        size={size}
      >
        <select
          data-react-fancy-select=""
          ref={ref}
          id={selectId}
          disabled={disabled}
          required={required}
          className={cn(
            inputBaseClasses,
            inputSizeClasses[size],
            dirtyClasses(dirty),
            errorClasses(error),
            "w-full appearance-none bg-no-repeat bg-[length:16px] bg-[right_8px_center]",
            "bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2020%2020%22%20fill%3D%22%236b7280%22%3E%3Cpath%20fill-rule%3D%22evenodd%22%20d%3D%22M5.23%207.21a.75.75%200%20011.06.02L10%2011.168l3.71-3.938a.75.75%200%20111.08%201.04l-4.25%204.5a.75.75%200%2001-1.08%200l-4.25-4.5a.75.75%200%2001.02-1.06z%22%20clip-rule%3D%22evenodd%22%2F%3E%3C%2Fsvg%3E')]",
            "pr-8",
            className,
          )}
          onChange={(e) => {
            onChange?.(e);
            onValueChange?.(e.target.value);
          }}
          {...props}
          {...(isControlled ? { value } : { defaultValue: resolvedDefault })}
          autoFocus={interactive || props.autoFocus}
          onBlur={(e) => {
            props.onBlur?.(e);
            if (interactive) exitEdit();
          }}
        >
          {placeholder && (
            <option value="" disabled>
              {placeholder}
            </option>
          )}
          {list.map((item, index) =>
            isOptionGroup(item) ? (
              <optgroup key={`group-${index}`} label={item.label}>
                {item.options.map((opt, optIndex) =>
                  renderNativeOption(opt, optIndex),
                )}
              </optgroup>
            ) : (
              renderNativeOption(item, index)
            ),
          )}
        </select>
      </InputWrapper>
    );

    if (label || error || description) {
      return (
        <Field
          label={label}
          labelHidden={labelHidden}
          description={description}
          error={error}
          required={required}
          htmlFor={selectId}
          size={size}
        >
          {select}
        </Field>
      );
    }

    return select;
  },
);

NativeSelect.displayName = "NativeSelect";

// ── Listbox variant ─────────────────────────────────────────────────────

const ListboxSelect = forwardRef<HTMLSelectElement, SelectProps>(
  (
    {
      size = "md",
      dirty,
      error,
      label,
      labelHidden,
      description,
      required,
      disabled,
      className,
      id,
      list,
      placeholder = "Select...",
      multiple = false,
      values: controlledValues,
      defaultValues,
      onValueChange,
      onValuesChange,
      searchable = false,
      creatable = false,
      onCreate,
      createLabel = "Create",
      selectedSuffix = "selected",
      indicator = "check",
      mode,
      value: controlledSingleValue,
      defaultValue: defaultSingleValue,
    },
    _ref,
  ) => {
    const autoId = useId();
    const selectId = id ?? autoId;
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);

    // Creatable implies a text input, which is also the search input.
    const textInputEnabled = searchable || creatable;

    // ── State ──────────────────────────────────────────────
    const [open, setOpen] = useState(false);
    const [search, setSearch] = useState("");
    const [activeIndex, setActiveIndex] = useState(-1);
    const [createdOptions, setCreatedOptions] = useState<InputOption[]>([]);

    // Single-select state
    const [singleValue, setSingleValue] = useState<string>(
      (controlledSingleValue as string) ?? (defaultSingleValue as string) ?? "",
    );
    const currentSingle = (controlledSingleValue as string) ?? singleValue;

    // Multi-select state
    const [multiValues, setMultiValues] = useState<string[]>(
      controlledValues ?? defaultValues ?? [],
    );
    const currentMulti = controlledValues ?? multiValues;

    // Sync controlled values
    useEffect(() => {
      if (controlledValues) setMultiValues(controlledValues);
    }, [controlledValues]);
    useEffect(() => {
      if (controlledSingleValue !== undefined) setSingleValue(controlledSingleValue as string);
    }, [controlledSingleValue]);

    // ── Refs ───────────────────────────────────────────────
    const anchorRef = useRef<HTMLButtonElement>(null);
    const listRef = useRef<HTMLDivElement>(null);
    const searchRef = useRef<HTMLInputElement>(null);

    const position = useFloatingPosition(anchorRef, listRef, {
      placement: "bottom-start",
      offset: 4,
      enabled: open,
    });

    const close = useCallback(() => {
      setOpen(false);
      setSearch("");
      setActiveIndex(-1);
    }, []);

    // Outside-click guards the dropdown (in a Portal) against its own clicks,
    // with the trigger button ignored since it toggles open/closed itself.
    useOutsideClick(listRef, close, open, anchorRef);
    useEscapeKey(close, open);

    // Focus text input on open
    useEffect(() => {
      if (open && textInputEnabled) {
        requestAnimationFrame(() => searchRef.current?.focus());
      }
    }, [open, textInputEnabled]);

    // ── Options ────────────────────────────────────────────
    const resolvedOptions = useMemo(() => {
      const base = flattenOptions(list).map(resolveOption);
      const created = createdOptions.map(resolveOption);
      return [...base, ...created];
    }, [list, createdOptions]);

    const filtered = search
      ? resolvedOptions.filter((o) =>
          o.label.toLowerCase().includes(search.toLowerCase()),
        )
      : resolvedOptions;

    // Exact-match check to decide whether to show the "Create X" row
    const canCreate =
      creatable &&
      search.trim().length > 0 &&
      !resolvedOptions.some(
        (o) =>
          o.label.toLowerCase() === search.trim().toLowerCase() ||
          o.value === search.trim(),
      );

    // ── Selection ──────────────────────────────────────────
    const isSelected = (value: string): boolean => {
      if (multiple) return currentMulti.includes(value);
      return currentSingle === value;
    };

    const toggleOption = useCallback(
      (value: string) => {
        if (multiple) {
          const next = currentMulti.includes(value)
            ? currentMulti.filter((v) => v !== value)
            : [...currentMulti, value];
          setMultiValues(next);
          onValuesChange?.(next);
        } else {
          setSingleValue(value);
          onValueChange?.(value);
          close();
        }
      },
      [multiple, currentMulti, onValuesChange, onValueChange, close],
    );

    const handleCreate = useCallback(() => {
      const label = search.trim();
      if (!label) return;
      const value = label;
      const newOption: InputOption = { value, label };
      setCreatedOptions((prev) => [...prev, newOption]);
      onCreate?.(label);
      setSearch("");
      if (multiple) {
        const next = [...currentMulti, value];
        setMultiValues(next);
        onValuesChange?.(next);
        // Keep dropdown open for multi-select; refocus input
        requestAnimationFrame(() => searchRef.current?.focus());
      } else {
        setSingleValue(value);
        onValueChange?.(value);
        close();
      }
    }, [search, multiple, currentMulti, onCreate, onValuesChange, onValueChange, close]);

    // ── Display text ───────────────────────────────────────
    const getDisplayText = (): string => {
      if (multiple) {
        if (currentMulti.length === 0) return placeholder;
        if (currentMulti.length === 1) {
          const opt = resolvedOptions.find((o) => o.value === currentMulti[0]);
          return opt?.label ?? currentMulti[0];
        }
        return `${currentMulti.length} ${selectedSuffix}`;
      }
      if (!currentSingle) return placeholder;
      const opt = resolvedOptions.find((o) => o.value === currentSingle);
      return opt?.label ?? currentSingle;
    };

    const hasValue = multiple ? currentMulti.length > 0 : !!currentSingle;

    // ── Keyboard ───────────────────────────────────────────
    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (!open) {
        if (e.key === "ArrowDown" || e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          setOpen(true);
        }
        return;
      }

      if (e.key === "ArrowDown") {
        e.preventDefault();
        setActiveIndex((i) => Math.min(i + 1, filtered.length - 1));
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        setActiveIndex((i) => Math.max(i - 1, 0));
      } else if (e.key === "Enter") {
        if (activeIndex >= 0) {
          e.preventDefault();
          const item = filtered[activeIndex];
          if (item && !item.disabled) toggleOption(item.value as string);
        } else if (canCreate) {
          e.preventDefault();
          handleCreate();
        }
      }
    };

    // ── View mode ──────────────────────────────────────────
    if (!showControl) {
      const labels = multiple
        ? currentMulti.map(
            (v) => resolvedOptions.find((o) => o.value === v)?.label ?? v,
          )
        : currentSingle
          ? [resolvedOptions.find((o) => o.value === currentSingle)?.label ?? currentSingle]
          : [];
      const display = (
        <DisplayValue size={size} interactive={interactive} onActivate={enterEdit}>
          {labels.join(", ")}
        </DisplayValue>
      );
      if (label || error || description) {
        return (
          <Field
            label={label}
            labelHidden={labelHidden}
            description={description}
            error={error}
            required={required}
            htmlFor={selectId}
            size={size}
          >
            {display}
          </Field>
        );
      }
      return display;
    }

    // ── Render ─────────────────────────────────────────────
    const trigger = (
      <button
        ref={anchorRef}
        type="button"
        id={selectId}
        disabled={disabled}
        autoFocus={interactive}
        onClick={() => setOpen((o) => !o)}
        onKeyDown={handleKeyDown}
        role="combobox"
        aria-expanded={open}
        aria-haspopup="listbox"
        data-react-fancy-select=""
        data-variant="listbox"
        className={cn(
          inputBaseClasses,
          inputSizeClasses[size],
          dirtyClasses(dirty),
          errorClasses(error),
          "flex w-full cursor-pointer items-center justify-between gap-2 text-left",
          !hasValue && "text-zinc-400 dark:text-zinc-500",
          className,
        )}
      >
        <span className="truncate">{getDisplayText()}</span>
        <svg
          className={cn("h-4 w-4 shrink-0 text-zinc-400 transition-transform", open && "rotate-180")}
          viewBox="0 0 20 20"
          fill="currentColor"
        >
          <path
            fillRule="evenodd"
            d="M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z"
            clipRule="evenodd"
          />
        </svg>
      </button>
    );

    const dropdown = open && (
      <Portal>
        <div
          ref={listRef}
          role="listbox"
          aria-multiselectable={multiple || undefined}
          className="fixed z-50 max-h-60 min-w-[8rem] overflow-y-auto rounded-xl border border-zinc-200 bg-white p-1 shadow-lg dark:border-zinc-700 dark:bg-zinc-900 dark:shadow-zinc-950/50 fancy-scale-in"
          style={{
            left: position.x,
            top: position.y,
            width: anchorRef.current?.offsetWidth,
          }}
        >
          {textInputEnabled && (
            <div className="px-2 pb-1 pt-1">
              <input
                ref={searchRef}
                type="text"
                value={search}
                onChange={(e) => {
                  setSearch(e.target.value);
                  setActiveIndex(-1);
                }}
                onKeyDown={handleKeyDown}
                placeholder={creatable && !searchable ? "Type to add…" : "Search…"}
                className="w-full rounded-md border-0 bg-zinc-100 px-2.5 py-1.5 text-sm text-zinc-900 placeholder:text-zinc-400 outline-none dark:bg-zinc-800 dark:text-zinc-100 dark:placeholder:text-zinc-500"
              />
            </div>
          )}

          {canCreate && (
            <button
              type="button"
              onClick={handleCreate}
              className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm text-blue-600 hover:bg-blue-50 dark:text-blue-400 dark:hover:bg-blue-500/10"
            >
              <svg className="h-4 w-4 shrink-0" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M10 3a.75.75 0 01.75.75v5.5h5.5a.75.75 0 010 1.5h-5.5v5.5a.75.75 0 01-1.5 0v-5.5h-5.5a.75.75 0 010-1.5h5.5v-5.5A.75.75 0 0110 3z" clipRule="evenodd" />
              </svg>
              <span className="truncate">{createLabel} &quot;{search.trim()}&quot;</span>
            </button>
          )}

          {filtered.length === 0 && !canCreate ? (
            <div className="px-3 py-2 text-sm text-zinc-400">No results found</div>
          ) : filtered.length === 0 ? null : (
            filtered.map((option, i) => {
              const selected = isSelected(option.value as string);
              return (
                <button
                  key={option.value as string}
                  type="button"
                  role="option"
                  aria-selected={selected}
                  disabled={option.disabled}
                  onClick={() => toggleOption(option.value as string)}
                  className={cn(
                    "flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm transition-colors",
                    i === activeIndex
                      ? "bg-zinc-100 dark:bg-zinc-800"
                      : "hover:bg-zinc-50 dark:hover:bg-zinc-800/50",
                    selected
                      ? "text-zinc-900 dark:text-zinc-100"
                      : "text-zinc-700 dark:text-zinc-300",
                    option.disabled && "cursor-not-allowed opacity-50",
                  )}
                >
                  {/* Indicator */}
                  {indicator === "checkbox" ? (
                    <span
                      className={cn(
                        "flex h-4 w-4 shrink-0 items-center justify-center rounded border transition-colors",
                        selected
                          ? "border-blue-500 bg-blue-500 text-white dark:border-blue-400 dark:bg-blue-400"
                          : "border-zinc-300 dark:border-zinc-600",
                      )}
                    >
                      {selected && (
                        <svg className="h-3 w-3" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                          <polyline points="2.5 6 5 8.5 9.5 3.5" />
                        </svg>
                      )}
                    </span>
                  ) : (
                    <span className="flex h-4 w-4 shrink-0 items-center justify-center">
                      {selected && (
                        <svg className="h-4 w-4 text-blue-500 dark:text-blue-400" viewBox="0 0 20 20" fill="currentColor">
                          <path fillRule="evenodd" d="M16.704 4.153a.75.75 0 01.143 1.052l-8 10.5a.75.75 0 01-1.127.075l-4.5-4.5a.75.75 0 011.06-1.06l3.894 3.893 7.48-9.817a.75.75 0 011.05-.143z" clipRule="evenodd" />
                        </svg>
                      )}
                    </span>
                  )}

                  {/* Label + description */}
                  <span className="min-w-0 flex-1">
                    <span className="block truncate">{option.label}</span>
                    {option.description && (
                      <span className="block truncate text-xs text-zinc-400 dark:text-zinc-500">{option.description}</span>
                    )}
                  </span>
                </button>
              );
            })
          )}
        </div>
      </Portal>
    );

    const content = (
      <div
        className="relative"
        onBlur={(e) => {
          // The popover is portaled (focus moves out of this wrapper), so only
          // exit edit when the dropdown is closed and focus has truly left.
          if (interactive && !open && !e.currentTarget.contains(e.relatedTarget as Node)) {
            exitEdit();
          }
        }}
      >
        {trigger}
        {dropdown}
      </div>
    );

    if (label || error || description) {
      return (
        <Field
          label={label}
          labelHidden={labelHidden}
          description={description}
          error={error}
          required={required}
          htmlFor={selectId}
          size={size}
        >
          {content}
        </Field>
      );
    }

    return content;
  },
);

ListboxSelect.displayName = "ListboxSelect";

// ── Public component ────────────────────────────────────────────────────

export const Select = forwardRef<HTMLSelectElement, SelectProps>(
  (props, ref) => {
    const variant = props.variant ?? (props.multiple ? "listbox" : "native");

    if (variant === "listbox") {
      return <ListboxSelect {...props} ref={ref} />;
    }
    return <NativeSelect {...props} ref={ref} />;
  },
);

Select.displayName = "Select";

import type { SelectHTMLAttributes } from "react";
import type { InputBaseProps, InputOption, InputOptionGroup, InputAffixProps } from "../inputs.types";

export interface SelectProps
  extends InputBaseProps,
    InputAffixProps,
    Omit<SelectHTMLAttributes<HTMLSelectElement>, "size" | "prefix" | "multiple"> {
  /** Options list — strings or objects with value/label */
  list: InputOption[] | InputOptionGroup[];
  placeholder?: string;
  /** Callback for single-select value changes */
  onValueChange?: (value: string) => void;

  /** Layout variant. "native" uses <select>, "listbox" uses a custom dropdown. Default: "native" */
  variant?: "native" | "listbox";
  /** Enable multi-select (listbox variant only) */
  multiple?: boolean;
  /** Controlled multi-select value */
  values?: string[];
  /** Default multi-select value (uncontrolled) */
  defaultValues?: string[];
  /** Callback for multi-select value changes */
  onValuesChange?: (values: string[]) => void;
  /** Enable search/filter within the dropdown (listbox variant only) */
  searchable?: boolean;
  /**
   * Allow creating new options by typing in the dropdown's text input
   * (listbox variant only). Automatically enables the text input.
   */
  creatable?: boolean;
  /** Callback invoked when a new option is created from user input */
  onCreate?: (label: string) => void;
  /** Label prefix for the "Create" affordance. Default: "Create" */
  createLabel?: string;
  /** Suffix for the selected count display. Default: "selected" */
  selectedSuffix?: string;
  /** Selection indicator style. Default: "check" */
  indicator?: "check" | "checkbox";
}

import { forwardRef, useEffect, useId, useRef } from "react";
import { cn } from "../../../utils/cn";
import { useControllableState } from "../../../hooks/use-controllable-state";
import { useFieldMode } from "../mode/FieldMode.context";
import { useInlineEdit } from "../mode/useInlineEdit";
import { dirtyRingClasses } from "../inputs.utils";
import type { CheckboxProps } from "./Checkbox.types";

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(
  (
    {
      size = "md",
      dirty,
      error,
      label,
      description,
      required,
      disabled,
      className,
      id,
      name,
      checked: controlledChecked,
      defaultChecked = false,
      onCheckedChange,
      indeterminate,
      mode,
      ...rest
    },
    ref,
  ) => {
    const autoId = useId();
    const checkboxId = id ?? autoId;
    const internalRef = useRef<HTMLInputElement | null>(null);
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
    const [checked, setChecked] = useControllableState(
      controlledChecked,
      defaultChecked,
      onCheckedChange,
    );

    useEffect(() => {
      const el = internalRef.current;
      if (el) {
        el.indeterminate = indeterminate ?? false;
      }
    }, [indeterminate]);

    const sizeClasses = {
      xs: "h-3.5 w-3.5",
      sm: "h-4 w-4",
      md: "h-[18px] w-[18px]",
      lg: "h-5 w-5",
      xl: "h-6 w-6",
    }[size];

    const glyph = indeterminate ? "—" : checked ? "✓" : "✕";

    return (
      <div {...rest} data-react-fancy-checkbox="" className={cn("flex items-start gap-2", className)}>
        {!showControl ? (
          <span
            data-react-fancy-display=""
            data-mode="view"
            role={interactive ? "button" : undefined}
            tabIndex={interactive ? 0 : undefined}
            title={interactive ? "Click to edit" : undefined}
            onClick={interactive ? enterEdit : undefined}
            onKeyDown={
              interactive
                ? (e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      enterEdit();
                    }
                  }
                : undefined
            }
            className={cn(
              "flex shrink-0 items-center justify-center text-zinc-700 dark:text-zinc-200",
              sizeClasses,
              interactive &&
                "cursor-pointer rounded outline-none transition-colors hover:text-zinc-900 focus-visible:ring-2 focus-visible:ring-blue-500/40 dark:hover:text-white",
            )}
            aria-hidden={interactive ? undefined : "true"}
          >
            {glyph}
          </span>
        ) : (
        <div className="relative flex items-center">
          <input
            ref={(node) => {
              internalRef.current = node;
              if (typeof ref === "function") {
                ref(node);
              } else if (ref) {
                ref.current = node;
              }
            }}
            id={checkboxId}
            type="checkbox"
            name={name}
            disabled={disabled}
            required={required}
            checked={checked}
            autoFocus={interactive}
            onBlur={() => {
              if (interactive) exitEdit();
            }}
            onChange={(e) => setChecked(e.target.checked)}
            className={cn(
              sizeClasses,
              "cursor-pointer rounded border border-zinc-300 bg-white text-blue-600 transition-[border-color,box-shadow] duration-150 focus:ring-2 focus:ring-blue-500/40 focus:ring-offset-0 disabled:cursor-not-allowed disabled:opacity-50 dark:border-zinc-700 dark:bg-[#1e1e24]",
              dirtyRingClasses(dirty),
              error && "border-red-500",
            )}
          />
        </div>
        )}
        {(label || description) && (
          <div className="flex flex-col">
            {label && (
              <label
                htmlFor={checkboxId}
                className={cn(
                  "cursor-pointer text-sm text-zinc-700 dark:text-zinc-100",
                  disabled && "cursor-not-allowed opacity-50",
                )}
              >
                {label}
                {required && <span className="ml-0.5 text-red-500">*</span>}
              </label>
            )}
            {description && (
              <span className="text-xs text-zinc-500 dark:text-zinc-400">
                {description}
              </span>
            )}
            {error && <span className="text-xs text-red-500">{error}</span>}
          </div>
        )}
      </div>
    );
  },
);

Checkbox.displayName = "Checkbox";

import type { HTMLAttributes } from "react";
import type { InputBaseProps } from "../inputs.types";

export interface CheckboxProps
  extends Omit<InputBaseProps, "label">,
    Omit<HTMLAttributes<HTMLDivElement>, "color" | "defaultChecked" | "onChange" | "id"> {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  indeterminate?: boolean;
  label?: string;
}

import { useId } from "react";
import { cn } from "../../../utils/cn";
import { useControllableState } from "../../../hooks/use-controllable-state";
import { Field } from "../Field";
import { useFieldMode } from "../mode/FieldMode.context";
import { DisplayValue } from "../mode/DisplayValue";
import { useInlineEdit } from "../mode/useInlineEdit";
import { dirtyRingClasses, resolveOption } from "../inputs.utils";
import type { CheckboxGroupProps } from "./CheckboxGroup.types";

export function CheckboxGroup<V = string>({
  size = "md",
  dirty,
  error,
  label,
  labelHidden,
  description,
  required,
  disabled,
  className,
  name,
  list,
  value: controlledValue,
  defaultValue = [],
  onValueChange,
  orientation = "vertical",
  mode,
  ...rest
}: CheckboxGroupProps<V>) {
  const groupId = useId();
  const resolvedMode = useFieldMode(mode);
  const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
  const [value, setValue] = useControllableState(
    controlledValue,
    defaultValue,
    onValueChange,
  );

  const handleToggle = (optionValue: V) => {
    const next = value.includes(optionValue)
      ? value.filter((v) => v !== optionValue)
      : [...value, optionValue];
    setValue(next);
  };

  const sizeClasses = {
    xs: "h-3.5 w-3.5",
    sm: "h-4 w-4",
    md: "h-[18px] w-[18px]",
    lg: "h-5 w-5",
    xl: "h-6 w-6",
  }[size];

  const content = !showControl ? (
    <DisplayValue size={size} interactive={interactive} onActivate={enterEdit}>
      {list
        .map(resolveOption)
        .filter((o) => value.includes(o.value))
        .map((o) => o.label)
        .join(", ")}
    </DisplayValue>
  ) : (
    <div
      {...rest}
      data-react-fancy-checkbox-group=""
      onBlur={(e) => {
        if (interactive && !e.currentTarget.contains(e.relatedTarget as Node)) exitEdit();
      }}
      className={cn(
        "flex gap-3",
        orientation === "vertical" ? "flex-col" : "flex-row flex-wrap",
        className,
      )}
    >
      {list.map((option, index) => {
        const resolved = resolveOption(option);
        const optionId = `${groupId}-${index}`;
        const isChecked = value.includes(resolved.value);

        return (
          <div key={optionId} className="flex items-start gap-2">
            <input
              id={optionId}
              type="checkbox"
              name={name}
              value={String(resolved.value)}
              checked={isChecked}
              disabled={disabled || resolved.disabled}
              autoFocus={interactive && index === 0}
              onChange={() => handleToggle(resolved.value)}
              className={cn(
                sizeClasses,
                "cursor-pointer rounded border border-zinc-300 bg-white text-blue-600 transition-[border-color,box-shadow] duration-150 focus:ring-2 focus:ring-blue-500/40 focus:ring-offset-0 disabled:cursor-not-allowed disabled:opacity-50 dark:border-zinc-700 dark:bg-[#1e1e24]",
                dirtyRingClasses(dirty),
                error && "border-red-500",
              )}
            />
            <div className="flex flex-col">
              <label
                htmlFor={optionId}
                className={cn(
                  "cursor-pointer text-sm text-zinc-700 dark:text-zinc-100",
                  (disabled || resolved.disabled) &&
                    "cursor-not-allowed opacity-50",
                )}
              >
                {resolved.label}
              </label>
              {resolved.description && (
                <span className="text-xs text-zinc-500 dark:text-zinc-400">
                  {resolved.description}
                </span>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );

  if (label || error || description) {
    return (
      <Field
        label={label}
        labelHidden={labelHidden}
        description={description}
        error={error}
        required={required}
        size={size}
      >
        {content}
      </Field>
    );
  }

  return content;
}

CheckboxGroup.displayName = "CheckboxGroup";

import type { InputBaseProps, InputOption } from "../inputs.types";

export interface CheckboxGroupProps<V = string>
  extends Omit<InputBaseProps, "id"> {
  list: InputOption<V>[];
  value?: V[];
  defaultValue?: V[];
  onValueChange?: (values: V[]) => void;
  orientation?: "horizontal" | "vertical";
}

import { useId } from "react";
import { cn } from "../../../utils/cn";
import { useControllableState } from "../../../hooks/use-controllable-state";
import { Field } from "../Field";
import { useFieldMode } from "../mode/FieldMode.context";
import { DisplayValue } from "../mode/DisplayValue";
import { useInlineEdit } from "../mode/useInlineEdit";
import { dirtyRingClasses, resolveOption } from "../inputs.utils";
import type { RadioGroupProps } from "./RadioGroup.types";

export function RadioGroup<V = string>({
  size = "md",
  dirty,
  error,
  label,
  labelHidden,
  description,
  required,
  disabled,
  className,
  name,
  list,
  value: controlledValue,
  defaultValue,
  onValueChange,
  orientation = "vertical",
  mode,
  ...rest
}: RadioGroupProps<V>) {
  const groupId = useId();
  const radioName = name ?? groupId;
  // Same reason as MultiSwitch: a `<label>` cannot name a div[role="radiogroup"].
  // This one did not even pass `htmlFor`, so its label named nothing at all.
  const labelId = label ? `${groupId}-label` : undefined;
  const resolvedMode = useFieldMode(mode);
  const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
  const [value, setValue] = useControllableState(
    controlledValue,
    defaultValue as V,
    onValueChange,
  );

  const sizeClasses = {
    xs: "h-3.5 w-3.5",
    sm: "h-4 w-4",
    md: "h-[18px] w-[18px]",
    lg: "h-5 w-5",
    xl: "h-6 w-6",
  }[size];

  const selectedIndex = list.map(resolveOption).findIndex((o) => o.value === value);

  const content = !showControl ? (
    <DisplayValue size={size} interactive={interactive} onActivate={enterEdit}>
      {list.map(resolveOption).find((o) => o.value === value)?.label}
    </DisplayValue>
  ) : (
    <div
      {...rest}
      data-react-fancy-radio-group=""
      role="radiogroup"
      aria-labelledby={labelId}
      onBlur={(e) => {
        if (interactive && !e.currentTarget.contains(e.relatedTarget as Node)) exitEdit();
      }}
      className={cn(
        "flex gap-3",
        orientation === "vertical" ? "flex-col" : "flex-row flex-wrap",
        className,
      )}
    >
      {list.map((option, index) => {
        const resolved = resolveOption(option);
        const optionId = `${groupId}-${index}`;
        const isSelected = value === resolved.value;
        // Focus the selected radio on entering edit (or the first if none).
        const shouldAutoFocus =
          interactive && (selectedIndex === -1 ? index === 0 : isSelected);

        return (
          <div key={optionId} className="flex items-start gap-2">
            <input
              id={optionId}
              type="radio"
              name={radioName}
              value={String(resolved.value)}
              checked={isSelected}
              disabled={disabled || resolved.disabled}
              autoFocus={shouldAutoFocus}
              onChange={() => setValue(resolved.value)}
              className={cn(
                sizeClasses,
                "cursor-pointer border border-zinc-300 bg-white text-blue-600 transition-[border-color,box-shadow] duration-150 focus:ring-2 focus:ring-blue-500/40 focus:ring-offset-0 disabled:cursor-not-allowed disabled:opacity-50 dark:border-zinc-700 dark:bg-[#1e1e24]",
                dirtyRingClasses(dirty),
                error && "border-red-500",
              )}
            />
            <div className="flex flex-col">
              <label
                htmlFor={optionId}
                className={cn(
                  "cursor-pointer text-sm text-zinc-700 dark:text-zinc-100",
                  (disabled || resolved.disabled) &&
                    "cursor-not-allowed opacity-50",
                )}
              >
                {resolved.label}
              </label>
              {resolved.description && (
                <span className="text-xs text-zinc-500 dark:text-zinc-400">
                  {resolved.description}
                </span>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );

  if (label || error || description) {
    return (
      <Field
        label={label}
        labelHidden={labelHidden}
        labelId={labelId}
        description={description}
        error={error}
        required={required}
        size={size}
      >
        {content}
      </Field>
    );
  }

  return content;
}

