SingleSlider.displayName = "SingleSlider";

const RangeSlider = forwardRef<HTMLInputElement, SliderProps & { range: true }>(
  (
    {
      size = "md",
      dirty,
      error,
      label,
      labelHidden,
      description,
      required,
      disabled,
      className,
      id,
      name,
      min = 0,
      max = 100,
      step = 1,
      showValue,
      marks,
      prefix,
      suffix,
      mode,
      ...rest
    },
    ref,
  ) => {
    const rangeProps = rest as { value?: [number, number]; defaultValue?: [number, number]; onValueChange?: (v: [number, number]) => void };
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
    const [value, setValue] = useControllableState(
      rangeProps.value,
      rangeProps.defaultValue ?? [min, max] as [number, number],
      rangeProps.onValueChange,
    );

    const handleMin = (n: number) => {
      setValue([Math.min(n, value[1]), value[1]]);
    };

    const handleMax = (n: number) => {
      setValue([value[0], Math.max(n, value[0])]);
    };

    const leftPercent = ((value[0] - min) / (max - min)) * 100;
    const rightPercent = ((value[1] - min) / (max - min)) * 100;

    const slider = !showControl ? (
      <DisplayValue
        size={size}
        className={className}
        interactive={interactive}
        onActivate={enterEdit}
      >
        {`${prefix ?? ""}${value[0]}${suffix ?? ""}–${prefix ?? ""}${value[1]}${suffix ?? ""}`}
      </DisplayValue>
    ) : (
      <div
        data-react-fancy-slider=""
        className={cn("flex flex-col gap-1", className)}
        onBlur={(e) => {
          if (interactive && !e.currentTarget.contains(e.relatedTarget as Node)) exitEdit();
        }}
      >
        <div className="flex items-center gap-3">
          <div className="relative w-full">
            <div className="pointer-events-none absolute top-1/2 h-1.5 w-full -translate-y-1/2 rounded-full bg-zinc-200 dark:bg-zinc-700" />
            <div
              className="pointer-events-none absolute top-1/2 h-1.5 -translate-y-1/2 rounded-full bg-blue-500"
              style={{ left: `${leftPercent}%`, width: `${rightPercent - leftPercent}%` }}
            />
            <input
              ref={ref}
              type="range"
              min={min}
              max={max}
              step={step}
              value={value[0]}
              disabled={disabled}
              autoFocus={interactive}
              onChange={(e) => handleMin(Number(e.target.value))}
              className={cn(
                "pointer-events-none absolute w-full cursor-pointer appearance-none bg-transparent [&::-webkit-slider-thumb]:pointer-events-auto [&::-webkit-slider-thumb]:h-4 [&::-webkit-slider-thumb]:w-4 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-blue-600 [&::-webkit-slider-thumb]:shadow",
                dirtyRingClasses(dirty),
              )}
            />
            <input
              type="range"
              min={min}
              max={max}
              step={step}
              value={value[1]}
              disabled={disabled}
              onChange={(e) => handleMax(Number(e.target.value))}
              className="pointer-events-none absolute w-full cursor-pointer appearance-none bg-transparent [&::-webkit-slider-thumb]:pointer-events-auto [&::-webkit-slider-thumb]:h-4 [&::-webkit-slider-thumb]:w-4 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-blue-600 [&::-webkit-slider-thumb]:shadow"
            />
            <div className="h-6" />
          </div>
          {showValue && (
            <span className="min-w-[6ch] shrink-0 whitespace-nowrap text-right text-sm font-medium text-zinc-700 dark:text-zinc-300">
              {prefix}{value[0]}{suffix}–{prefix}{value[1]}{suffix}
            </span>
          )}
        </div>
        {marks && marks.length > 0 && <SliderMarks marks={marks} min={min} max={max} />}
      </div>
    );

    if (label || error || description) {
      return (
        <Field label={label} labelHidden={labelHidden} description={description} error={error} required={required} htmlFor={id} size={size}>
          {slider}
        </Field>
      );
    }

    return slider;
  },
);

RangeSlider.displayName = "RangeSlider";

function SliderMarks({
  marks,
  min,
  max,
}: {
  marks: { value: number; label?: string }[];
  min: number;
  max: number;
}) {
  return (
    <div className="relative h-5 w-full">
      {marks.map((mark) => {
        const percent = ((mark.value - min) / (max - min)) * 100;
        return (
          <span
            key={mark.value}
            className="absolute -translate-x-1/2 text-xs text-zinc-500 dark:text-zinc-400"
            style={{ left: `${percent}%` }}
          >
            {mark.label ?? mark.value}
          </span>
        );
      })}
    </div>
  );
}

import type { ReactNode } from "react";
import type { InputBaseProps } from "../inputs.types";

interface SliderBaseProps extends InputBaseProps {
  min?: number;
  max?: number;
  step?: number;
  showValue?: boolean;
  marks?: { value: number; label?: string }[];
  prefix?: ReactNode;
  suffix?: ReactNode;
}

export interface SliderSingleProps extends SliderBaseProps {
  range?: false;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
}

export interface SliderRangeProps extends SliderBaseProps {
  range: true;
  value?: [number, number];
  defaultValue?: [number, number];
  onValueChange?: (value: [number, number]) => void;
}

export type SliderProps = SliderSingleProps | SliderRangeProps;

import { useRef, useState, useEffect, useCallback, useId } from "react";
import { cn } from "../../../utils/cn";
import { useControllableState } from "../../../hooks/use-controllable-state";
import { Field } from "../Field";
import { useFieldMode } from "../mode/FieldMode.context";
import { DisplayValue } from "../mode/DisplayValue";
import { useInlineEdit } from "../mode/useInlineEdit";
import { resolveOption } from "../inputs.utils";
import type { Size } from "../../../utils/types";
import type { MultiSwitchProps } from "./MultiSwitch.types";

const sizeClasses: Record<Size, string> = {
  xs: "px-2 py-1 text-xs",
  sm: "px-2.5 py-1.5 text-sm",
  md: "px-3 py-2 text-sm",
  lg: "px-4 py-2.5 text-base",
  xl: "px-5 py-3 text-lg",
};

export function MultiSwitch<V = string>({
  size = "md",
  dirty,
  error,
  label,
  labelHidden,
  description,
  required,
  disabled,
  className,
  id,
  name,
  list,
  value: controlledValue,
  defaultValue,
  onValueChange,
  linear,
  mode,
  ...rest
}: MultiSwitchProps<V>) {
  const reactId = useId();
  // A `<label for>` cannot name a div[role="radiogroup"], so the group points at
  // the label instead. Needs an id the label and the group both agree on.
  const labelId = label ? `${id ?? reactId}-label` : undefined;

  const resolvedOptions = list.map(resolveOption);
  const fallback = defaultValue ?? resolvedOptions[0]?.value;
  const resolvedMode = useFieldMode(mode);
  const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
  const [value, setValue] = useControllableState(controlledValue, fallback as V, onValueChange);

  const containerRef = useRef<HTMLDivElement>(null);
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const [indicator, setIndicator] = useState<{ left: number; width: number } | null>(null);

  const selectedIndex = resolvedOptions.findIndex(
    (o) => o.value === value,
  );

  const updateIndicator = useCallback(() => {
    const container = containerRef.current;
    const activeItem = itemRefs.current[selectedIndex];
    if (!container || !activeItem) {
      setIndicator(null);
      return;
    }
    const containerRect = container.getBoundingClientRect();
    const itemRect = activeItem.getBoundingClientRect();
    setIndicator({
      left: itemRect.left - containerRect.left,
      width: itemRect.width,
    });
  }, [selectedIndex]);

  useEffect(() => {
    updateIndicator();
  }, [updateIndicator]);

  const control = !showControl ? (
    <DisplayValue size={size} interactive={interactive} onActivate={enterEdit}>
      {resolvedOptions.find((o) => o.value === value)?.label}
    </DisplayValue>
  ) : (
    <div
      ref={containerRef}
      {...rest}
      data-react-fancy-multi-switch=""
      role="radiogroup"
      id={id}
      aria-labelledby={labelId}
      onBlur={(e) => {
        if (interactive && !e.currentTarget.contains(e.relatedTarget as Node)) exitEdit();
      }}
      className={cn(
        "relative inline-flex rounded-lg border border-zinc-300 bg-zinc-100 dark:border-zinc-700 dark:bg-zinc-800",
        dirty && "ring-2 ring-amber-400/50",
        error && "ring-2 ring-red-500/50",
        disabled && "opacity-50 cursor-not-allowed",
        className,
      )}
    >
      {indicator && (
        <span
          className="absolute top-0 bottom-0 rounded-lg bg-blue-600 transition-all duration-200 ease-out"
          style={{ left: indicator.left, width: indicator.width }}
        />
      )}
      {resolvedOptions.map((option, index) => {
        const isSelected = option.value === value;
        return (
          <button
            key={String(option.value)}
            ref={(el) => { itemRefs.current[index] = el; }}
            type="button"
            role="radio"
            aria-checked={isSelected}
            disabled={disabled || option.disabled}
            autoFocus={interactive && (selectedIndex === -1 ? index === 0 : isSelected)}
            onClick={() => {
              if (linear) {
                const nextIndex = (selectedIndex + 1) % resolvedOptions.length;
                setValue(resolvedOptions[nextIndex].value as V);
              } else {
                setValue(option.value as V);
              }
            }}
            className={cn(
              "relative z-10 font-medium transition-colors duration-200",
              sizeClasses[size],
              isSelected
                ? "text-white"
                : "text-zinc-600 hover:text-zinc-900 dark:text-zinc-400 dark:hover:text-zinc-100",
              (disabled || option.disabled) && "cursor-not-allowed",
            )}
          >
            {option.label}
          </button>
        );
      })}
      {name && <input type="hidden" name={name} value={String(value)} />}
    </div>
  );

  if (label || error || description) {
    return (
      <Field
        label={label}
        labelHidden={labelHidden}
        labelId={labelId}
        description={description}
        error={error}
        required={required}
        htmlFor={id}
        size={size}
      >
        {control}
      </Field>
    );
  }

  return control;
}

MultiSwitch.displayName = "MultiSwitch";

import type { HTMLAttributes } from "react";
import type { InputBaseProps, InputOption } from "../inputs.types";

/**
 * The container's DOM attributes are part of the API because the component
 * already spreads its rest props onto that container — `style`, `data-*` and
 * `aria-*` all worked at runtime while the type refused them, so a caller got a
 * compiler error for something the component does correctly.
 *
 * `onChange` is omitted because this control reports through `onValueChange`,
 * and admitting both would offer a handler that never fires.
 */
export interface MultiSwitchProps<V = string>
  extends InputBaseProps,
    Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  list: InputOption<V>[];
  value?: V;
  defaultValue?: V;
  onValueChange?: (value: V) => void;
  linear?: boolean;
}

import { forwardRef, useId } from "react";
import { cn } from "../../../utils/cn";
import { useControllableState } from "../../../hooks/use-controllable-state";
import { Field } from "../Field";
import { useFieldMode } from "../mode/FieldMode.context";
import { DisplayValue } from "../mode/DisplayValue";
import { useInlineEdit } from "../mode/useInlineEdit";
import {
  dirtyClasses,
  errorClasses,
  inputBaseClasses,
  inputSizeClasses,
} from "../inputs.utils";
import type { DatePickerProps } from "./DatePicker.types";

/** Locale-format an ISO date / datetime-local string; fall back to the raw value. */
function formatDateValue(iso: string, includeTime?: boolean): string {
  if (!iso) return "";
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return iso;
  return includeTime
    ? date.toLocaleString(undefined, {
        year: "numeric",
        month: "short",
        day: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      })
    : date.toLocaleDateString(undefined, {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
}

export const DatePicker = forwardRef<HTMLInputElement, DatePickerProps>(
  (props, ref) => {
    const {
      size = "md",
      dirty,
      error,
      label,
      labelHidden,
      description,
      required,
      disabled,
      className,
      id,
      name,
      min,
      max,
      includeTime,
    } = props;

    const autoId = useId();
    const pickerId = id ?? autoId;
    const inputType = includeTime ? "datetime-local" : "date";

    const inputClasses = cn(
      inputBaseClasses,
      inputSizeClasses[size],
      dirtyClasses(dirty),
      errorClasses(error),
      "w-full",
    );

    if (props.range) {
      return (
        <RangeDatePicker
          {...props}
          id={pickerId}
          inputType={inputType}
          inputClasses={inputClasses}
          ref={ref}
        />
      );
    }

    return (
      <SingleDatePicker
        {...props}
        range={false}
        id={pickerId}
        inputType={inputType}
        inputClasses={inputClasses}
        ref={ref}
      />
    );
  },
);

DatePicker.displayName = "DatePicker";

interface InternalProps {
  inputType: string;
  inputClasses: string;
}

const SingleDatePicker = forwardRef<
  HTMLInputElement,
  DatePickerProps & { range?: false } & InternalProps
>(
  (
    {
      size = "md",
      error,
      label,
      labelHidden,
      description,
      required,
      disabled,
      className,
      id,
      name,
      min,
      max,
      includeTime,
      mode,
      inputType,
      inputClasses,
      ...rest
    },
    ref,
  ) => {
    const singleProps = rest as {
      value?: string;
      defaultValue?: string;
      onValueChange?: (v: string) => void;
    };
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
    const [value, setValue] = useControllableState(
      singleProps.value,
      singleProps.defaultValue ?? "",
      singleProps.onValueChange,
    );

    const input = !showControl ? (
      <DisplayValue
        size={size}
        className={className}
        interactive={interactive}
        onActivate={enterEdit}
      >
        {formatDateValue(value, includeTime)}
      </DisplayValue>
    ) : (
      <input
        data-react-fancy-date-picker=""
        ref={ref}
        id={id}
        type={inputType}
        name={name}
        min={min}
        max={max}
        value={value}
        disabled={disabled}
        required={required}
        onChange={(e) => setValue(e.target.value)}
        className={cn(inputClasses, className)}
        autoFocus={interactive}
        onBlur={() => {
          if (interactive) exitEdit();
        }}
      />
    );

    if (label || error || description) {
      return (
        <Field
          label={label}
          labelHidden={labelHidden}
          description={description}
          error={error}
          required={required}
          htmlFor={id}
          size={size}
        >
          {input}
        </Field>
      );
    }

    return input;
  },
);

SingleDatePicker.displayName = "SingleDatePicker";

const RangeDatePicker = forwardRef<
  HTMLInputElement,
  DatePickerProps & { range: true } & InternalProps
>(
  (
    {
      size = "md",
      error,
      label,
      labelHidden,
      description,
      required,
      disabled,
      className,
      id,
      name,
      min,
      max,
      includeTime,
      mode,
      inputType,
      inputClasses,
      ...rest
    },
    ref,
  ) => {
    const rangeProps = rest as {
      value?: [string, string];
      defaultValue?: [string, string];
      onValueChange?: (v: [string, string]) => void;
    };
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);
    const [value, setValue] = useControllableState(
      rangeProps.value,
      rangeProps.defaultValue ?? ["", ""] as [string, string],
      rangeProps.onValueChange,
    );

    const input = !showControl ? (
      <DisplayValue
        size={size}
        className={className}
        interactive={interactive}
        onActivate={enterEdit}
      >
        {value[0] || value[1]
          ? `${formatDateValue(value[0], includeTime)} – ${formatDateValue(value[1], includeTime)}`
          : ""}
      </DisplayValue>
    ) : (
      <div
        data-react-fancy-date-picker=""
        className={cn("flex items-center gap-2", className)}
        onBlur={(e) => {
          if (interactive && !e.currentTarget.contains(e.relatedTarget as Node)) exitEdit();
        }}
      >
        <input
          ref={ref}
          id={id}
          type={inputType}
          name={name ? `${name}_start` : undefined}
          min={min}
          max={value[1] || max}
          value={value[0]}
          disabled={disabled}
          required={required}
          onChange={(e) => setValue([e.target.value, value[1]])}
          className={inputClasses}
          autoFocus={interactive}
        />
        <span className="text-sm text-zinc-500 dark:text-zinc-400">to</span>
        <input
          type={inputType}
          name={name ? `${name}_end` : undefined}
          min={value[0] || min}
          max={max}
          value={value[1]}
          disabled={disabled}
          onChange={(e) => setValue([value[0], e.target.value])}
          className={inputClasses}
        />
      </div>
    );

    if (label || error || description) {
      return (
        <Field
          label={label}
          labelHidden={labelHidden}
          description={description}
          error={error}
          required={required}
          htmlFor={id}
          size={size}
        >
          {input}
        </Field>
      );
    }

    return input;
  },
);

