};

/** Create or edit a posting. Status is never set here — publishing is its own action. */
export function JobPostingForm({
    posting,
    onSubmit,
    onCancel,
    submitting = false,
    errors = {},
    canPublish = true,
    publishBlockedReason,
    className,
}: JobPostingFormProps) {
    const [values, setValues] = useState<JobPostingInput>(() =>
        posting
            ? {
                  title: posting.title,
                  description: posting.description ?? '',
                  requirements: posting.requirements ?? '',
                  employment_type: posting.employment_type ?? null,
                  location: posting.location ?? '',
                  is_remote: posting.is_remote,
                  pay_min: posting.pay_min ?? null,
                  pay_max: posting.pay_max ?? null,
                  pay_unit: posting.pay_unit ?? 'hour',
                  contact_email: posting.contact_email ?? '',
                  contact_phone: posting.contact_phone ?? '',
                  apply_url: posting.apply_url ?? '',
                  openings: posting.openings,
              }
            : { ...emptyPosting },
    );

    const patch = (next: Partial<JobPostingInput>) =>
        setValues((current) => ({ ...current, ...next }));

    // Empty string is not a number; keep it null so the API sees "unset".
    const num = (v: string): number | null => (v.trim() === '' ? null : Number(v));

    return (
        <Card
            variant="outlined"
            padding="lg"
            className={`!rounded-xl !border-secondary-200 !shadow-sm ${className ?? ''}`}
        >
            <Heading as="h2" size="lg" weight="bold" className="!text-secondary-900">
                {posting ? 'Edit posting' : 'New posting'}
            </Heading>

            {!canPublish && (
                <Callout color="amber" className="!mt-4">
                    <Text size="sm">
                        {publishBlockedReason ??
                            'You can save drafts now. Publishing unlocks once your account is approved.'}
                    </Text>
                </Callout>
            )}

            <form
                className="mt-5 grid gap-4"
                onSubmit={(e) => {
                    e.preventDefault();
                    void onSubmit(values);
                }}
            >
                <Input
                    label="Job title"
                    required
                    placeholder="Overnight patrol guard"
                    value={values.title}
                    onValueChange={(title) => patch({ title })}
                    error={errors.title}
                />

                <Textarea
                    label="Description"
                    description="What the role involves day to day."
                    minRows={5}
                    autoResize
                    value={values.description ?? ''}
                    onValueChange={(description) => patch({ description })}
                    error={errors.description}
                />

                <Textarea
                    label="Requirements"
                    description="Licences, experience, availability."
                    minRows={3}
                    autoResize
                    value={values.requirements ?? ''}
                    onValueChange={(requirements) => patch({ requirements })}
                    error={errors.requirements}
                />

                <div className="grid gap-4 sm:grid-cols-2">
                    <Select
                        label="Employment type"
                        placeholder="Choose a type"
                        list={[...EMPLOYMENT_TYPE_OPTIONS]}
                        value={values.employment_type ?? ''}
                        onValueChange={(v) =>
                            patch({ employment_type: (v || null) as JobPostingInput['employment_type'] })
                        }
                        error={errors.employment_type}
                    />
                    <Input
                        type="number"
                        label="Openings"
                        value={String(values.openings ?? 1)}
                        onValueChange={(v) => patch({ openings: num(v) ?? 1 })}
                        error={errors.openings}
                    />
                </div>

                <div className="grid gap-4 sm:grid-cols-2 sm:items-end">
                    <Input
                        label="Location"
                        placeholder="Torrance, CA"
                        value={values.location ?? ''}
                        onValueChange={(location) => patch({ location })}
                        error={errors.location}
                    />
                    <div className="sm:pb-2">
                        <Switch
                            label="This role is remote"
                            checked={Boolean(values.is_remote)}
                            onCheckedChange={(is_remote) => patch({ is_remote })}
                        />
                    </div>
                </div>

                <div className="grid gap-4 sm:grid-cols-3">
                    <Input
                        type="number"
                        label="Pay from"
                        value={values.pay_min == null ? '' : String(values.pay_min)}
                        onValueChange={(v) => patch({ pay_min: num(v) })}
                        error={errors.pay_min}
                    />
                    <Input
                        type="number"
                        label="Pay to"
                        value={values.pay_max == null ? '' : String(values.pay_max)}
                        onValueChange={(v) => patch({ pay_max: num(v) })}
                        error={errors.pay_max}
                    />
                    <Select
                        label="Per"
                        list={[...PAY_UNIT_OPTIONS]}
                        value={values.pay_unit ?? 'hour'}
                        onValueChange={(v) => patch({ pay_unit: v as JobPostingInput['pay_unit'] })}
                        error={errors.pay_unit}
                    />
                </div>

                <div className="grid gap-4 sm:grid-cols-2">
                    <Input
                        type="email"
                        label="Contact email"
                        value={values.contact_email ?? ''}
                        onValueChange={(contact_email) => patch({ contact_email })}
                        error={errors.contact_email}
                    />
                    <Input
                        type="tel"
                        label="Contact phone"
                        value={values.contact_phone ?? ''}
                        onValueChange={(contact_phone) => patch({ contact_phone })}
                        error={errors.contact_phone}
                    />
                </div>

                <Input
                    type="url"
                    label="External application link"
                    description="Optional. Candidates can apply here instead."
                    value={values.apply_url ?? ''}
                    onValueChange={(apply_url) => patch({ apply_url })}
                    error={errors.apply_url}
                />

                <div className="flex items-center justify-end gap-3 pt-1">
                    {onCancel && (
                        <Button
                            type="button"
                            variant="ghost"
                            onClick={onCancel}
                            className="!text-secondary-700 hover:!text-brand !px-4 !py-2"
                        >
                            Cancel
                        </Button>
                    )}
                    <Button
                        type="submit"
                        loading={submitting}
                        disabled={submitting}
                        className="!bg-brand hover:!bg-primary-600 disabled:!bg-secondary-300 !text-white !font-semibold !px-6 !py-2.5 !rounded-md !shadow-sm"
                    >
                        {posting ? 'Save changes' : 'Create draft'}
                    </Button>
                </div>
            </form>
        </Card>
    );
}

import { createContext, useContext } from "react";
import type { FieldMode } from "../inputs/inputs.types";
import type { Size } from "../../utils/types";
import type {
  JsonEditorNode,
  JsonEditorPendingEdit,
  JsonFieldType,
  JsonValue,
} from "./JsonEditor.types";

/**
 * Everything a row needs that is not the row itself.
 *
 * Same shape as `Table`'s context and for the same reason: a row is rendered
 * once per key in a document that can be hundreds deep, and threading a dozen
 * props through the recursion makes every signature change a rewrite.
 */
export interface JsonEditorContextValue {
  mode: FieldMode;
  size: Size;
  readOnly: boolean;
  allowAdd: boolean;
  allowRemove: boolean;
  allowRename: boolean;
  allowReorder: boolean;
  pendingMode: boolean;
  idPrefix: string;

  isExpanded: (dotted: string) => boolean;
  toggleExpanded: (dotted: string) => void;

  setValueAt: (node: JsonEditorNode, value: JsonValue) => void;
  removeAt: (node: JsonEditorNode) => void;
  renameAt: (node: JsonEditorNode, key: string) => void;
  moveAt: (node: JsonEditorNode, to: number) => void;
  insertInto: (dotted: string, key: string | undefined, type: JsonFieldType) => void;

  /** Which container's add form is open, if any. Transient UI state, never model state. */
  addingAt: string | null;
  setAddingAt: (dotted: string | null) => void;

  pendingFor: (dotted: string) => JsonEditorPendingEdit[];
  acceptPending: (id: string) => void;
  rejectPending: (id: string) => void;
}

export const JsonEditorContext = createContext<JsonEditorContextValue | null>(null);

export function useJsonEditorContext(): JsonEditorContextValue {
  const context = useContext(JsonEditorContext);
  if (!context) {
    throw new Error("JsonEditor rows must be rendered inside a <JsonEditor>.");
  }
  return context;
}

import { resolveOption } from "../inputs/inputs.utils";
import {
  getAtPath,
  isJsonArray,
  isJsonObject,
  parsePath,
  pathToString,
} from "./JsonEditor.paths";
import { JSON_FIELD_TYPES } from "./JsonEditor.types";
import type {
  JsonEditorIssue,
  JsonFieldType,
  JsonKeyMapEntry,
  JsonKeyRule,
  JsonPath,
  JsonValue,
  ParsedKeyMap,
} from "./JsonEditor.types";

// ---------------------------------------------------------------------------
// The keyMap
//
// Shape: a FLAT object whose keys are dotted path patterns and whose values are
// either a bare type name or a rule object.
//
//   { "user.age": "number", "orders.*.total": "number", "tags.*": "string" }
//
// Why flat paths rather than a nested mirror of the data:
//
//  - A nested mirror is ambiguous the moment a key needs a type AND typed
//    children — `{"user": {"age": "number"}}` could mean either, and resolving
//    it needs a magic key (`$type`) that a flat map does not.
//  - Arrays force a wildcard into a nested mirror anyway, so the mirror buys
//    nothing there and costs a level of nesting per segment.
//  - One rule per line is greppable, diffable and reviewable, which matters
//    when the map arrives as a string from an agent or a config column.
//  - It is sparse by construction: you declare the keys you care about, and
//    everything else is inferred from the value.
//
// A `*` segment matches exactly one key or index. There is deliberately no
// `**`: "any depth" makes two patterns overlap in ways that are hard to reason
// about, and every case we had for it was really "this array's elements".
// ---------------------------------------------------------------------------

const TYPE_NAMES = new Set<string>(JSON_FIELD_TYPES);

function isTypeName(value: unknown): value is JsonFieldType {
  return typeof value === "string" && TYPE_NAMES.has(value);
}

function issue(kind: JsonEditorIssue["kind"], path: string, message: string): JsonEditorIssue {
  return { kind, path, message };
}

/**
 * Compile a `keyMap` JSON **string**.
 *
 * Never throws. Two failure modes, deliberately distinct:
 *
 *  - The string itself is unusable (not JSON, or JSON that is not an object) —
 *    `ok: false`, no rules, one `keymap` issue. The caller must show this: an
 *    editor that quietly runs untyped is worse than one that refuses, because
 *    the person editing believes the constraint is in force.
 *  - One entry is malformed — `ok: true`, that entry dropped, one `rule` issue.
 *    A typo in `orders.*.totl` must not disable the other forty rules.
 */
export function parseKeyMap(source?: string | null): ParsedKeyMap {
  if (source === undefined || source === null || source.trim() === "") {
    return { ok: true, rules: [], issues: [] };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(source);
  } catch (error) {
    return {
      ok: false,
      rules: [],
      issues: [
        issue(
          "keymap",
          "",
          `keyMap is not valid JSON: ${error instanceof Error ? error.message : String(error)}`,
        ),
      ],
    };
  }

  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    return {
      ok: false,
      rules: [],
      issues: [
        issue(
          "keymap",
          "",
          `keyMap must be a JSON object of path → type, got ${describeValue(parsed as JsonValue)}.`,
        ),
      ],
    };
  }

  const rules: JsonKeyMapEntry[] = [];
  const issues: JsonEditorIssue[] = [];
  let order = 0;

  for (const [key, raw] of Object.entries(parsed as Record<string, unknown>)) {
    const rule = normalizeRule(key, raw, issues);
    if (!rule) continue;

    const pattern = parsePath(key);
    rules.push({
      pattern,
      rule,
      source: key,
      literals: pattern.reduce((n, segment) => n + (segment === "*" ? 0 : 1), 0),
      order: order++,
    });
  }

  return { ok: true, rules, issues };
}

function normalizeRule(
  key: string,
  raw: unknown,
  issues: JsonEditorIssue[],
): JsonKeyRule | undefined {
  let candidate: Record<string, unknown>;

  if (typeof raw === "string") {
    candidate = { type: raw };
  } else if (typeof raw === "object" && raw !== null && !Array.isArray(raw)) {
    candidate = raw as Record<string, unknown>;
  } else {
    issues.push(
      issue(
        "rule",
        key,
        `Expected a type name or a rule object, got ${describeValue(raw as JsonValue)}.`,
      ),
    );
    return undefined;
  }

  if (!isTypeName(candidate.type)) {
    issues.push(
      issue(
        "rule",
        key,
        `Unknown type ${JSON.stringify(candidate.type)}. Known types: ${JSON_FIELD_TYPES.join(", ")}.`,
      ),
    );
    return undefined;
  }

  if (candidate.options !== undefined && !Array.isArray(candidate.options)) {
    issues.push(issue("rule", key, "`options` must be an array."));
    return undefined;
  }

  // An enum with nothing to choose from cannot type anything, and would render
  // an empty select that looks like a loading state.
  if (candidate.type === "enum" && (!candidate.options || candidate.options.length === 0)) {
    issues.push(issue("rule", key, "`enum` requires a non-empty `options` array."));
    return undefined;
  }

  return candidate as unknown as JsonKeyRule;
}

/**
 * The rule governing `segments`, or `undefined` when the map is silent.
 *
 * Specificity: the pattern with the most literal (non-`*`) segments wins, and
 * at equal specificity the one declared LAST wins — so a general
 * `orders.*.total` can be overridden by a specific `orders.0.total` placed
 * anywhere in the map.
 */
export function resolveKeyRule(
  rules: JsonKeyMapEntry[],
  segments: JsonPath,
): JsonKeyRule | undefined {
  let best: JsonKeyMapEntry | undefined;

  for (const entry of rules) {
    if (!matches(entry.pattern, segments)) continue;
    if (
      !best ||
      entry.literals > best.literals ||
      (entry.literals === best.literals && entry.order > best.order)
    ) {
      best = entry;
    }
  }

  return best?.rule;
}

function matches(pattern: JsonPath, segments: JsonPath): boolean {
  if (pattern.length !== segments.length) return false;
  return pattern.every((p, i) => p === "*" || p === segments[i]);
}

/** What a value IS, in the vocabulary the issue messages use. */
export function describeValue(value: JsonValue | undefined): string {
  if (value === undefined) return "undefined";
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

/** The type a value carries on its own, when nothing declares one for it. */
export function inferType(value: JsonValue | undefined): JsonFieldType {
  if (Array.isArray(value)) return "array";
  if (value === null || value === undefined) {
    // `null` carries no type information at all, so the raw editor is the only
    // choice that neither invents a type nor drops the value.
    return "json";
  }
  if (typeof value === "object") return "object";
  if (typeof value === "boolean") return "boolean";
  if (typeof value === "number") return "number";
  return "string";
}

function enumValues(rule: JsonKeyRule): (string | number | boolean)[] {
  return (rule.options ?? []).map((option) => resolveOption(option).value as string);
}

/**
 * Does the value satisfy the declared type?
 *
 * Deliberately strict and deliberately non-coercing. `"36"` is NOT a number
 * here — the whole reason a `keyMap` exists is to make that visible rather than
 * to paper over it.
 */
export function typeMatches(rule: JsonKeyRule, value: JsonValue | undefined): boolean {
  switch (rule.type) {
    case "string":
    case "text":
    case "url":
    case "email":
    case "secret":
    case "color":
      return typeof value === "string";
    case "number":
      return typeof value === "number" && Number.isFinite(value);
    case "integer":
      return typeof value === "number" && Number.isInteger(value);
    case "boolean":
      return typeof value === "boolean";
    case "date":
    case "datetime":
      return typeof value === "string" && value !== "" && !Number.isNaN(Date.parse(value));
    case "enum":
      return (
        (typeof value === "string" || typeof value === "number" || typeof value === "boolean") &&
        enumValues(rule).some((option) => String(option) === String(value))
      );
    case "object":
      return isJsonObject(value);
    case "array":
      return isJsonArray(value);
    case "json":
      // The escape hatch matches anything EXCEPT text that does not parse —
      // which is exactly the state the raw editor leaves behind when someone
      // saves a half-written document.
      if (typeof value !== "string") return true;
      try {
        JSON.parse(value);
        return true;
      } catch {
        return false;
      }
  }
}

function conflictMessage(rule: JsonKeyRule, value: JsonValue | undefined): string {
  if (rule.type === "enum") {
    return `${JSON.stringify(value)} is not one of the declared options (${enumValues(rule)
      .map((option) => JSON.stringify(option))
      .join(", ")}).`;
  }
  if (rule.type === "json") {
    return "Raw text is not valid JSON.";
  }
  if (rule.type === "date" || rule.type === "datetime") {
    return `Declared ${rule.type}, got ${describeValue(value)} that is not a parseable date.`;
  }
  return `Declared ${rule.type}, got ${describeValue(value)}.`;
}

/**
 * Every place the document contradicts its `keyMap`.
 *
 * Walks the value (so a conflict is found at any depth, arrays included), then
 * checks `required` on the wildcard-free patterns — a wildcard cannot say "this
 * must exist" about a key nobody has named.
 */
export function findJsonConflicts(value: JsonValue, rules: JsonKeyMapEntry[]): JsonEditorIssue[] {
  const issues: JsonEditorIssue[] = [];
  if (rules.length === 0) return issues;

  const walk = (node: JsonValue, segments: JsonPath) => {
    if (segments.length > 0) {
      const rule = resolveKeyRule(rules, segments);
      if (rule && !typeMatches(rule, node)) {
        issues.push({
          kind: "type",
          path: pathToString(segments),
          message: conflictMessage(rule, node),
          expected: rule.type,
          actual: describeValue(node),
        });
      }
    }

    if (isJsonArray(node)) {
      node.forEach((child, index) => walk(child, [...segments, String(index)]));
    } else if (isJsonObject(node)) {
      for (const [key, child] of Object.entries(node)) walk(child, [...segments, key]);
    }
  };

  walk(value, []);

  for (const entry of rules) {
    if (!entry.rule.required) continue;
    if (entry.pattern.includes("*")) continue;
    if (getAtPath(value, entry.pattern) !== undefined) continue;
    issues.push({
      kind: "type",
      path: entry.source,
      message: `Required key is missing (declared ${entry.rule.type}).`,
      expected: entry.rule.type,
      actual: "undefined",
    });
  }

  return issues;
}

/** The value a newly-added key starts as, so a new row is never `undefined`. */
export function seedValue(type: JsonFieldType, rule?: JsonKeyRule): JsonValue {
  switch (type) {
    case "number":
    case "integer":
      return 0;
    case "boolean":
      return false;
    case "object":
      return {};
    case "array":
      return [];
    case "json":
      return null;
    case "enum":
      return rule?.options?.length ? (resolveOption(rule.options[0]!).value as string) : "";
    default:
      return "";
  }
}

import type {
  JsonArray,
  JsonEditorEdit,
  JsonObject,
  JsonPath,
  JsonValue,
} from "./JsonEditor.types";

// ---------------------------------------------------------------------------
// Paths
//
// The wire form of a path is a dotted string — `user.address.city`,
// `orders.0.total` — because that is what fits in a `data-*` attribute, a
// keyMap key, an MCP tool argument, and a log line. `.` separates segments and
// `\` escapes, so a key that genuinely contains a dot is still addressable
// (`meta.a\.b` is `["meta", "a.b"]`, not three segments).
// ---------------------------------------------------------------------------

export function isJsonObject(value: JsonValue | undefined): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function isJsonArray(value: JsonValue | undefined): value is JsonArray {
  return Array.isArray(value);
}

export function isContainerValue(value: JsonValue | undefined): boolean {
  return isJsonObject(value) || isJsonArray(value);
}

/** Split a dotted path into segments, honouring `\.` and `\\`. */
export function parsePath(path: string): JsonPath {
  if (!path) return [];

  const segments: string[] = [];
  let current = "";
  let escaped = false;

  for (const char of path) {
    if (escaped) {
      current += char;
      escaped = false;
      continue;
    }
    if (char === "\\") {
      escaped = true;
      continue;
    }
    if (char === ".") {
      segments.push(current);
      current = "";
      continue;
    }
    current += char;
  }
  // A trailing lone backslash is a typo, not a separator — keep it literal
  // rather than throwing on a half-typed path.
  if (escaped) current += "\\";
  segments.push(current);

  return segments;
}

/** The inverse of {@link parsePath}. */
export function pathToString(segments: JsonPath): string {
  return segments
    .map((segment) => segment.replace(/\\/g, "\\\\").replace(/\./g, "\\."))
    .join(".");
}

export function getAtPath(value: JsonValue, segments: JsonPath): JsonValue | undefined {
  let current: JsonValue | undefined = value;

  for (const segment of segments) {
    if (isJsonArray(current)) {
      const index = Number(segment);
      if (!Number.isInteger(index)) return undefined;
      current = current[index];
    } else if (isJsonObject(current)) {
      if (!Object.prototype.hasOwnProperty.call(current, segment)) return undefined;
      current = current[segment];
    } else {
      return undefined;
    }
    if (current === undefined) return undefined;
  }

  return current;
}

/**
 * Rebuild `value` with `updater` applied to the container at `segments`,
 * cloning only the containers along that path. Returns the original reference
 * when the path does not resolve, so a no-op edit is detectable by identity.
 */
function updateContainer(
  value: JsonValue,
  segments: JsonPath,
  updater: (container: JsonObject | JsonArray) => JsonObject | JsonArray | undefined,
): JsonValue {
  if (segments.length === 0) {
    if (!isContainerValue(value)) return value;
    const next = updater(value as JsonObject | JsonArray);
    return next === undefined ? value : next;
  }

  const [head, ...rest] = segments as [string, ...string[]];

  if (isJsonArray(value)) {
    const index = Number(head);
    if (!Number.isInteger(index) || index < 0 || index >= value.length) return value;
    const child = updateContainer(value[index]!, rest, updater);
    if (child === value[index]) return value;
    const clone = value.slice();
    clone[index] = child;
    return clone;
  }

  if (isJsonObject(value)) {
    if (!Object.prototype.hasOwnProperty.call(value, head)) return value;
    const child = updateContainer(value[head]!, rest, updater);
    if (child === value[head]) return value;
    return { ...value, [head]: child };
  }

  return value;
}

/**
 * Apply one {@link JsonEditorEdit} and return a NEW document.
 *
 * Pure and total: an edit that cannot be applied — a path that does not exist,
 * a rename onto an occupied key, an insert without a key into an object —
 * returns the input unchanged rather than throwing or half-applying. The
 * component checks those cases first and raises an issue; this function is the
 * backstop for the same op arriving from a bridge, where there is no UI to warn.
 */
export function applyJsonEdit(value: JsonValue, edit: JsonEditorEdit): JsonValue {
  const segments = parsePath(edit.path);

  switch (edit.op) {
    case "set": {
      // An empty path is the document itself.
      if (segments.length === 0) return edit.value;

      const parent = segments.slice(0, -1);
      const key = segments[segments.length - 1]!;

      return updateContainer(value, parent, (container) => {
        if (isJsonArray(container)) {
          const index = Number(key);
          if (!Number.isInteger(index) || index < 0 || index >= container.length) return undefined;
          const clone = container.slice();
          clone[index] = edit.value;
          return clone;
        }
        return { ...container, [key]: edit.value };
      });
    }

    case "remove": {
      if (segments.length === 0) return value;

      const parent = segments.slice(0, -1);
      const key = segments[segments.length - 1]!;

      return updateContainer(value, parent, (container) => {
        if (isJsonArray(container)) {
          const index = Number(key);
          if (!Number.isInteger(index) || index < 0 || index >= container.length) return undefined;
          return container.filter((_, i) => i !== index);
        }
        if (!Object.prototype.hasOwnProperty.call(container, key)) return undefined;
        const clone: JsonObject = {};
        for (const [k, v] of Object.entries(container)) {
          if (k !== key) clone[k] = v;
        }
        return clone;
      });
    }

    case "rename": {
      if (segments.length === 0) return value;

      const parent = segments.slice(0, -1);
      const key = segments[segments.length - 1]!;

      return updateContainer(value, parent, (container) => {
        // Array indices are positional, not names — reorder is `move`.
        if (!isJsonObject(container)) return undefined;
        if (!Object.prototype.hasOwnProperty.call(container, key)) return undefined;
        if (edit.key === key) return undefined;
        // Renaming onto a live sibling would silently destroy it.
        if (Object.prototype.hasOwnProperty.call(container, edit.key)) return undefined;

        // Rebuilt in order: `delete` + re-add would move the key to the end,
        // which reads as the row jumping down the list for no reason.
        const clone: JsonObject = {};
        for (const [k, v] of Object.entries(container)) {
          clone[k === key ? edit.key : k] = v;
        }
        return clone;
      });
    }

    case "insert": {
      return updateContainer(value, segments, (container) => {
        if (isJsonArray(container)) return [...container, edit.value];
        if (edit.key === undefined || edit.key === "") return undefined;
        if (Object.prototype.hasOwnProperty.call(container, edit.key)) return undefined;
        return { ...container, [edit.key]: edit.value };
      });
    }

    case "move": {
      if (segments.length === 0) return value;

      const parent = segments.slice(0, -1);
      const from = Number(segments[segments.length - 1]);

      return updateContainer(value, parent, (container) => {
        if (!isJsonArray(container)) return undefined;
        if (!Number.isInteger(from) || from < 0 || from >= container.length) return undefined;
        const to = Math.min(Math.max(edit.to, 0), container.length - 1);
        if (to === from) return undefined;
        const clone = container.slice();
        const [moved] = clone.splice(from, 1);
        clone.splice(to, 0, moved!);
        return clone;
      });
    }
  }
}

/** A one-line summary of an edit, for the pending strip and activity events. */
export function describeEdit(edit: JsonEditorEdit): string {
  const at = edit.path === "" ? "the document" : edit.path;
  switch (edit.op) {
    case "set":
      return `set ${at}`;
    case "remove":
      return `remove ${at}`;
    case "rename":
      return `rename ${at} to ${edit.key}`;
    case "insert":
      return edit.key === undefined ? `append to ${at}` : `add ${edit.key} to ${at}`;
    case "move":
      return `move ${at} to index ${edit.to}`;
  }
}

import { forwardRef, useCallback, useEffect, useId, useMemo, useRef, useState } from "react";
import { cn } from "../../utils/cn";
import { Button } from "../Button/Button";
import { Callout } from "../Callout/Callout";
import { Text } from "../Text/Text";
import { JsonEditorContext } from "./JsonEditor.context";
import { JsonEditorAddForm, JsonEditorRow } from "./JsonEditorRow";
import { findJsonConflicts, inferType, parseKeyMap, resolveKeyRule, seedValue } from "./JsonEditor.keymap";
import {
  applyJsonEdit,
  describeEdit,
  getAtPath,
  isContainerValue,
  isJsonArray,
  isJsonObject,
  parsePath,
  pathToString,
} from "./JsonEditor.paths";
import type { JsonEditorContextValue } from "./JsonEditor.context";
import type {
  JsonEditorEdit,
  JsonEditorIssue,
  JsonEditorNode,
  JsonEditorPendingEdit,
  JsonEditorProps,
  JsonFieldType,
  JsonKeyMapEntry,
  JsonPath,
  JsonValue,
} from "./JsonEditor.types";

type RenderItem =
  | { kind: "node"; node: JsonEditorNode }
  | {
      kind: "add";
      path: string;
      containerKind: "object" | "array";
      depth: number;
      suggestedType?: JsonFieldType;
    };

/** Dotted paths of every container in the document — the "expand everything" set. */
function collectContainerPaths(value: JsonValue): string[] {
  const out: string[] = [];

  const walk = (node: JsonValue, segments: JsonPath) => {
    if (!isContainerValue(node)) return;
    if (segments.length > 0) out.push(pathToString(segments));
    if (isJsonArray(node)) {
      node.forEach((child, index) => walk(child, [...segments, String(index)]));
    } else if (isJsonObject(node)) {
      for (const [key, child] of Object.entries(node)) walk(child, [...segments, key]);
    }
  };

  walk(value, []);
  return out;
}

/**
 * JsonEditor — a key/value editor over arbitrary, arbitrarily-nested JSON, with
 * a caller-supplied `keyMap` imposing a data type on any path.
 *
 * The type does two jobs at once, which is the point of the feature: it decides
 * how a value is RENDERED when you are reading, and which control appears when
 * you are editing. `{"user.age": "number"}` is not documentation — it is the
 * reason that row is a numeric field and the reason `"thirty-six"` shows up in
 * red instead of quietly becoming `0`.
 *
 * The three design decisions worth knowing before you use it:
 *
 *  - **`keyMap` is a JSON string, and only a string.** It has to survive an MCP
 *    tool argument, a config column and a `data-*` attribute; a live object
 *    survives none of those. See {@link JsonEditorProps.keyMap}.
 *  - **Nothing is coerced and nothing is dropped.** A value that contradicts
 *    its declared type keeps its real value, renders through the raw editor,
 *    and is reported through the issues panel, the `data-issues` count and
 *    `onIssuesChange` — the same channel a broken `keyMap` uses.
 *  - **It is controlled, all the way down.** The document lives in `value`.
 *    The only state here is which rows are expanded, which add-form is open,
 *    and the half-typed text inside a control that has not committed yet.
 *
 * Every control is a `react-fancy` primitive, so restyling the kit restyles
 * this, and `mode="view"` gets the kit's click-to-edit behaviour for free.
 */
export const JsonEditor = forwardRef<HTMLDivElement, JsonEditorProps>(function JsonEditor(
  {
    value,
    onChange,
    keyMap,
    mode = "view",
    size = "sm",
    readOnly = false,
    expanded,
    defaultExpanded,
    onExpandedChange,
    showIssues = true,
    onIssuesChange,
    pendingMode = false,
    pending,
    onPendingChange,
    onActivity,
    allowAdd = true,
    allowRemove = true,
    allowRename = true,
    allowReorder = true,
    rootLabel = "value",
    emptyLabel = "No keys yet.",
    idPrefix,
    className,
    ...rest
  },
  ref,
) {
  const autoId = useId();
  const prefix = idPrefix ?? autoId;
  const editSeq = useRef(0);

  // Parsed ONCE per distinct keyMap string — not per row, not per render. The
  // map is compiled into path patterns with a specificity score, and rows only
  // ever do a match against that.
  const parsedKeyMap = useMemo(() => parseKeyMap(keyMap), [keyMap]);
  const rules = parsedKeyMap.rules;

  const conflicts = useMemo(() => findJsonConflicts(value, rules), [value, rules]);

  // Transient complaints about an edit that was refused (duplicate key, empty
  // key). They belong beside the type conflicts because from the user's side
  // they are the same thing: something they can see is wrong and can fix.
  const [editIssues, setEditIssues] = useState<JsonEditorIssue[]>([]);

  const issues = useMemo(
    () => [...parsedKeyMap.issues, ...conflicts, ...editIssues],
    [parsedKeyMap.issues, conflicts, editIssues],
  );

  const onIssuesChangeRef = useRef(onIssuesChange);
  onIssuesChangeRef.current = onIssuesChange;
  const lastIssueSignature = useRef<string | null>(null);

  useEffect(() => {
    const signature = JSON.stringify(issues);
    if (signature === lastIssueSignature.current) return;
    lastIssueSignature.current = signature;
    onIssuesChangeRef.current?.(issues);
  }, [issues]);

  // ── expansion ─────────────────────────────────────────────────────────
  // `null` means "expanded, everything" — the state a caller that named no
  // paths is in. Storing it as a sentinel rather than materialising every
  // container path keeps a container added later expanded too.
  const expandedControlled = expanded !== undefined;
  const [expandedUncontrolled, setExpandedUncontrolled] = useState<string[] | null>(
    defaultExpanded ?? null,
  );
  const expandedList = expandedControlled ? expanded : expandedUncontrolled;

  const isExpanded = useCallback(
    (dotted: string) => expandedList === null || expandedList.includes(dotted),
    [expandedList],
  );

  const toggleExpanded = useCallback(
    (dotted: string) => {
      const current = expandedList ?? collectContainerPaths(value);
      const next = current.includes(dotted)
        ? current.filter((path) => path !== dotted)
        : [...current, dotted];
      if (!expandedControlled) setExpandedUncontrolled(next);
      onExpandedChange?.(next);
    },
    [expandedList, expandedControlled, onExpandedChange, value],
  );

  // ── add form ──────────────────────────────────────────────────────────
  const [addingAt, setAddingAt] = useState<string | null>(null);

  // ── committing ────────────────────────────────────────────────────────
  const stagedPending = useMemo(() => pending ?? [], [pending]);

  const commit = useCallback(
    (edit: JsonEditorEdit) => {
      setEditIssues([]);

      if (pendingMode) {
        // Trust-but-verify: the edit becomes a PROPOSAL. `value` does not move
        // and `onChange` does not fire until a human accepts it.
        const staged: JsonEditorPendingEdit = {
          ...edit,
          id: edit.id ?? `${prefix}-edit-${editSeq.current++}`,
          label: edit.label ?? describeEdit(edit),
        };
        onPendingChange?.([...stagedPending, staged]);
        onActivity?.({ type: "stage", edit: staged });
        return;
      }

      const next = applyJsonEdit(value, edit);
      // `applyJsonEdit` returns the same reference when it refuses an edit, so
      // a refusal never reaches the host as a spurious "changed" callback.
      if (next === value) return;
      onChange?.(next, edit);
      onActivity?.({ type: "commit", edit });
    },
    [pendingMode, prefix, stagedPending, onPendingChange, onActivity, value, onChange],
  );

  const refuse = useCallback((path: string, message: string) => {
    setEditIssues([{ kind: "edit", path, message }]);
  }, []);

  const setValueAt = useCallback(
    (node: JsonEditorNode, next: JsonValue) => {
      commit({ op: "set", path: node.dotted, value: next });
    },
    [commit],
  );

  const removeAt = useCallback(
    (node: JsonEditorNode) => {
      commit({ op: "remove", path: node.dotted });
    },
    [commit],
  );

  const moveAt = useCallback(
    (node: JsonEditorNode, to: number) => {
      commit({ op: "move", path: node.dotted, to });
    },
    [commit],
  );

  const renameAt = useCallback(
    (node: JsonEditorNode, key: string) => {
      if (key === node.key) return;
      if (key.trim() === "") {
        refuse(node.dotted, "A key cannot be empty.");
        return;
      }
      const parent = getAtPath(value, node.path.slice(0, -1));
      if (isJsonObject(parent) && Object.prototype.hasOwnProperty.call(parent, key)) {
        refuse(node.dotted, `A key named "${key}" already exists here — rename refused.`);
        return;
      }
      commit({ op: "rename", path: node.dotted, key });
    },
    [commit, refuse, value],
  );

  const insertInto = useCallback(
    (dotted: string, key: string | undefined, type: JsonFieldType) => {
      const segments = parsePath(dotted);
      const container = dotted === "" ? value : getAtPath(value, segments);
      const isArray = isJsonArray(container);

      if (!isArray) {
        if (key === undefined || key.trim() === "") {
          refuse(dotted, "A new key needs a name.");
          return;
        }
        if (isJsonObject(container) && Object.prototype.hasOwnProperty.call(container, key)) {
          refuse(dotted, `A key named "${key}" already exists here.`);
          return;
        }
      }

      const rule = resolveKeyRule(rules, [...segments, isArray ? "*" : key!]);
      setAddingAt(null);
      commit({
        op: "insert",
        path: dotted,
        key: isArray ? undefined : key,
        value: seedValue(type, rule),
      });
    },
    [commit, refuse, rules, value],
  );

  const pendingFor = useCallback(
    (dotted: string) => stagedPending.filter((edit) => edit.path === dotted),
    [stagedPending],
  );

  const acceptPending = useCallback(
    (id: string) => {
      const edit = stagedPending.find((candidate) => candidate.id === id);
      if (!edit) return;
      const next = applyJsonEdit(value, edit);
      onPendingChange?.(stagedPending.filter((candidate) => candidate.id !== id));
      if (next !== value) {
        onChange?.(next, edit);
        onActivity?.({ type: "accept", edit });
      }
    },
    [stagedPending, value, onPendingChange, onChange, onActivity],
  );

  const rejectPending = useCallback(
    (id: string) => {
      const edit = stagedPending.find((candidate) => candidate.id === id);
      onPendingChange?.(stagedPending.filter((candidate) => candidate.id !== id));
      if (edit) onActivity?.({ type: "reject", edit });
    },
    [stagedPending, onPendingChange, onActivity],
  );

  // ── rows ──────────────────────────────────────────────────────────────
  const items = useMemo(
    () =>
      buildItems({
        value,
        rules,
        conflicts,
        isExpanded,
        addingAt,
        rootLabel,
      }),
    [value, rules, conflicts, isExpanded, addingAt, rootLabel],
  );

  const rootIsContainer = isContainerValue(value);
  const rootKind = isJsonArray(value) ? "array" : "object";
  const attachedIds = new Set(
    items.flatMap((item) => (item.kind === "node" ? [item.node.dotted] : [])),
  );
  const orphanPending = stagedPending.filter((edit) => !attachedIds.has(edit.path));

  const context = useMemo<JsonEditorContextValue>(
    () => ({
      mode: readOnly ? "view" : mode,
      size,
      readOnly,
      allowAdd: allowAdd && !readOnly,
      allowRemove: allowRemove && !readOnly,
      allowRename: allowRename && !readOnly,
      allowReorder: allowReorder && !readOnly,
      pendingMode,
      idPrefix: prefix,
      isExpanded,
      toggleExpanded,
      setValueAt,
      removeAt,
      renameAt,
      moveAt,
      insertInto,
      addingAt,
      setAddingAt,
      pendingFor,
      acceptPending,
      rejectPending,
    }),
    [
      mode,
      size,
      readOnly,
      allowAdd,
      allowRemove,
      allowRename,
      allowReorder,
      pendingMode,
      prefix,
      isExpanded,
      toggleExpanded,
      setValueAt,
      removeAt,
      renameAt,
      moveAt,
      insertInto,
      addingAt,
      pendingFor,
      acceptPending,
      rejectPending,
    ],
  );

  return (
    <JsonEditorContext.Provider value={context}>
      <div
        ref={ref}
        // Rest FIRST: a caller's `data-*` / `aria-*` reach the DOM, but nothing
        // they pass can overwrite the marker below or drop the internal classes.
        {...rest}
        data-react-fancy-json-editor=""
        data-issues={String(issues.length)}
        data-keymap-error={parsedKeyMap.ok ? undefined : "true"}
        data-mode={readOnly ? "readonly" : mode}
        className={cn(
          "overflow-hidden rounded-lg border border-zinc-200 bg-white text-zinc-900 dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-100",
          className,
        )}
      >
        {showIssues && issues.length > 0 && (
          <div data-react-fancy-json-editor-issues="" className="p-2">
            <Callout color={parsedKeyMap.ok ? "amber" : "red"}>
              <Text size="sm" weight="semibold" className="mb-1">
                {parsedKeyMap.ok
                  ? `${issues.length} ${issues.length === 1 ? "issue" : "issues"}`
                  : "The keyMap could not be used — values are shown untyped."}
              </Text>
              <ul className="space-y-0.5">
                {issues.map((issue, index) => (
                  <li key={`${issue.kind}-${issue.path}-${index}`}>
                    <Text as="span" size="xs" data-react-fancy-json-editor-issue="" data-kind={issue.kind} data-path={issue.path}>
                      {issue.path ? `${issue.path} — ` : ""}
                      {issue.message}
                    </Text>
                  </li>
                ))}
              </ul>
            </Callout>
          </div>
        )}

        <div data-react-fancy-json-editor-tree="" role="tree" aria-label={rest["aria-label"] ?? "JSON document"}>
          {items.length === 0 ? (
            <Text as="p" size="sm" color="muted" className="px-3 py-4">
              {emptyLabel}
            </Text>
          ) : (
            items.map((item) =>
              item.kind === "node" ? (
                <JsonEditorRow key={`row:${item.node.dotted}`} node={item.node} />
              ) : (
                <JsonEditorAddForm
                  key={`add:${item.path}`}
                  path={item.path}
                  kind={item.containerKind}
                  depth={item.depth}
                  suggestedType={item.suggestedType}
                />
              ),
            )
          )}
        </div>

        {orphanPending.length > 0 && (
          <div data-react-fancy-json-editor-orphan-pending="" className="border-t border-zinc-100 p-2 dark:border-zinc-800">
            {orphanPending.map((edit) => (
              <div key={edit.id} className="flex items-center gap-2 py-0.5">
                <Text as="span" size="xs" color="muted" className="min-w-0 flex-1 truncate font-mono">
                  {edit.label ?? describeEdit(edit)}
                </Text>
                <Button
                  size="xs"
                  color="emerald"
                  data-react-fancy-json-editor-accept=""
                  data-id={edit.id}
                  onClick={() => acceptPending(edit.id)}
                >
                  Accept
                </Button>
                <Button
                  size="xs"
                  variant="ghost"
                  data-react-fancy-json-editor-reject=""
                  data-id={edit.id}
                  onClick={() => rejectPending(edit.id)}
                >
                  Reject
                </Button>
              </div>
            ))}
          </div>
        )}

        {rootIsContainer && allowAdd && !readOnly && (
          <div className="border-t border-zinc-100 p-2 dark:border-zinc-800">
            <Button
              variant="ghost"
              size="xs"
              icon="plus"
              data-react-fancy-json-editor-add=""
              data-path=""
              onClick={() => setAddingAt(addingAt === "" ? null : "")}
            >
              {rootKind === "array" ? "Append item" : "Add key"}
            </Button>
          </div>
        )}
      </div>
    </JsonEditorContext.Provider>
  );
});

interface BuildItemsOptions {
  value: JsonValue;
  rules: JsonKeyMapEntry[];
  conflicts: JsonEditorIssue[];
  isExpanded: (dotted: string) => boolean;
  addingAt: string | null;
  rootLabel: string;
}

function buildItems({
  value,
  rules,
  conflicts,
  isExpanded,
  addingAt,
  rootLabel,
}: BuildItemsOptions): RenderItem[] {
  const out: RenderItem[] = [];
  const conflictByPath = new Map<string, JsonEditorIssue>();
  for (const issue of conflicts) {
    if (issue.kind === "type" && !conflictByPath.has(issue.path)) conflictByPath.set(issue.path, issue);
  }

  const makeNode = (
    segments: JsonPath,
    node: JsonValue,
    depth: number,
    parentKind: JsonEditorNode["parentKind"],
  ): JsonEditorNode => {
    const rule = segments.length > 0 ? resolveKeyRule(rules, segments) : undefined;
    const type = rule?.type ?? inferType(node);
    const dotted = pathToString(segments);
    const conflict = conflictByPath.get(dotted);
    // A `json` node is raw text by definition, and a node in conflict must show
    // what it really holds — neither is a branch to walk into.
    const container = !conflict && type !== "json" && isContainerValue(node);

    return {
      path: segments,
      dotted,
      key: segments[segments.length - 1] ?? rootLabel,
      depth,
      value: node,
      parentKind,
      rule,
      type,
      declared: rule !== undefined,
      container,
      childCount: isJsonArray(node)
        ? node.length
        : isJsonObject(node)
          ? Object.keys(node).length
          : 0,
      conflict,
    };
  };

  const emitChildren = (node: JsonValue, segments: JsonPath, depth: number) => {
    if (isJsonArray(node)) {
      node.forEach((child, index) => emit(child, [...segments, String(index)], depth, "array"));
    } else if (isJsonObject(node)) {
      for (const [key, child] of Object.entries(node)) {
        emit(child, [...segments, key], depth, "object");
      }
    }
  };

  const emit = (
    node: JsonValue,
    segments: JsonPath,
    depth: number,
    parentKind: JsonEditorNode["parentKind"],
  ) => {
    const built = makeNode(segments, node, depth, parentKind);
    out.push({ kind: "node", node: built });

    if (!built.container || !isExpanded(built.dotted)) return;

    emitChildren(node, segments, depth + 1);
    if (addingAt === built.dotted) {
      out.push({
        kind: "add",
        path: built.dotted,
        containerKind: isJsonArray(node) ? "array" : "object",
        depth: depth + 1,
        suggestedType: resolveKeyRule(rules, [...segments, "*"])?.type,
      });
    }
  };

  if (isContainerValue(value)) {
    emitChildren(value, [], 0);
    if (addingAt === "") {
      out.push({
        kind: "add",
        path: "",
        containerKind: isJsonArray(value) ? "array" : "object",
        depth: 0,
        suggestedType: resolveKeyRule(rules, ["*"])?.type,
      });
    }
  } else {
    out.push({ kind: "node", node: makeNode([], value, 0, "root") });
  }

  return out;
}

import type { HTMLAttributes } from "react";
import type { InputOption } from "../inputs/inputs.types";
import type { FieldMode } from "../inputs/inputs.types";
import type { Size } from "../../utils/types";

// ---------------------------------------------------------------------------
// JSON
// ---------------------------------------------------------------------------

export type JsonPrimitive = string | number | boolean | null;

export interface JsonObject {
  [key: string]: JsonValue;
}

export type JsonArray = JsonValue[];

export type JsonValue = JsonPrimitive | JsonObject | JsonArray;

/**
 * A location inside a JSON document, one array element per segment. Array
 * indices are decimal STRINGS (`["orders", "0", "total"]`) so a path is a plain
 * `string[]` an agent can emit without a tagged union, and so object keys and
 * array indices are addressed identically.
 *
 * The wire form is the dotted string produced by `pathToString` — see
 * `JsonEditor.paths.ts` for the escaping rule.
 */
export type JsonPath = string[];

// ---------------------------------------------------------------------------
// Declared types
// ---------------------------------------------------------------------------

/**
 * The data types a `keyMap` can impose on a JSON value.
 *
 * Each one owes BOTH a read-only representation and an edit control — that
 * pairing is the whole point of the feature, so a type with no distinct input
 * does not earn a place here.
 *
 * `json` is the escape hatch: it matches any value and edits as raw text, which
 * is how a sub-document opts out of the row-per-key treatment.
 */
export const JSON_FIELD_TYPES = [
  "string",
  "text",
  "number",
  "integer",
  "boolean",
  "date",
  "datetime",
  "enum",
  "secret",
  "url",
  "email",
  "color",
  "json",
  "object",
  "array",
] as const;

export type JsonFieldType = (typeof JSON_FIELD_TYPES)[number];

/**
 * The long form of a `keyMap` entry. The short form — a bare type name — is
 * sugar for `{ type }`.
 */
export interface JsonKeyRule {
  type: JsonFieldType;
  /** Overrides the raw key as the row's label. */
  label?: string;
  /** Choices for `type: "enum"`. Required there; ignored elsewhere. */
  options?: InputOption[];
  /** Render the value but never offer a control for it. */
  readOnly?: boolean;
  /** The key must be present. Only enforced on wildcard-free patterns. */
  required?: boolean;
  description?: string;
  placeholder?: string;
  /** Forwarded to the control for `number` / `integer` / `date` / `datetime`. */
  min?: number | string;
  max?: number | string;
}

/** One compiled `keyMap` entry: a path pattern plus the rule it imposes. */
export interface JsonKeyMapEntry {
  /** Path pattern; a `"*"` segment matches any single key or index. */
  pattern: JsonPath;
  rule: JsonKeyRule;
  /** The key exactly as written in the `keyMap`, for error messages. */
  source: string;
  /** Non-wildcard segment count — the specificity score. */
  literals: number;
  /** Declaration order, the tie-breaker at equal specificity. */
  order: number;
}

export interface ParsedKeyMap {
  /**
   * `false` only when the STRING itself was unusable (unparseable, or valid
   * JSON of the wrong shape). Individual bad rules leave this `true` — they are
   * reported and skipped so one typo cannot silently disable a whole map.
   */
  ok: boolean;
  rules: JsonKeyMapEntry[];
  issues: JsonEditorIssue[];
}

// ---------------------------------------------------------------------------
// Issues
// ---------------------------------------------------------------------------

/**
 * Everything the editor knows to be wrong, in one shape.
 *
 * A typing feature that silently stops typing things is worse than no typing at
 * all, because the caller believes the constraint is in force. So a broken
 * `keyMap`, a broken rule inside a working one, and a value that contradicts
 * its declared type all surface through the SAME channel — the panel, the
 * `data-issues` count, and `onIssuesChange`.
 */
export interface JsonEditorIssue {
  /**
   * - `keymap` — the `keyMap` string could not be used at all.
   * - `rule`   — one entry in an otherwise-usable map is malformed.
   * - `type`   — a value contradicts the type declared for its path.
   * - `edit`   — a structural edit was refused (duplicate key, and the like).
   */
  kind: "keymap" | "rule" | "type" | "edit";
  /** Dotted path; `""` for the `keyMap` as a whole. */
  path: string;
  message: string;
  /** The declared type, when the issue has one. */
  expected?: JsonFieldType;
  /** What the value actually is: `"string"`, `"array"`, `"null"`, … */
  actual?: string;
}

// ---------------------------------------------------------------------------
// Edits
// ---------------------------------------------------------------------------

/**
 * One mutation, as data.
 *
 * Every change the UI makes is expressed as one of these and applied through
 * `applyJsonEdit`, which means an MCP bridge can replay exactly what a human
 * did — and `pendingMode` can hold one in a queue instead of applying it —
 * without a second code path.
 */
export type JsonEditorEditBase = {
  id?: string;
  /** Human-readable summary, used by the pending strip. */
  label?: string;
};

export type JsonEditorEdit =
  | (JsonEditorEditBase & { op: "set"; path: string; value: JsonValue })
  | (JsonEditorEditBase & { op: "remove"; path: string })
  | (JsonEditorEditBase & { op: "rename"; path: string; key: string })
  /** `path` is the CONTAINER. `key` is required for an object, ignored for an array. */
  | (JsonEditorEditBase & { op: "insert"; path: string; key?: string; value: JsonValue })
  /** `path` is the element; `to` is its new index in the same array. */
  | (JsonEditorEditBase & { op: "move"; path: string; to: number });

export type JsonEditorPendingEdit = JsonEditorEdit & { id: string };

export interface JsonEditorActivity {
  /** `commit` — applied to the document. `stage` / `accept` / `reject` — pending flow. */
  type: "commit" | "stage" | "accept" | "reject";
  edit: JsonEditorEdit;
}

// ---------------------------------------------------------------------------
// Rows
// ---------------------------------------------------------------------------

/** One rendered key/value row — also the unit a bridge would address. */
export interface JsonEditorNode {
  path: JsonPath;
  /** `pathToString(path)`; `""` for a scalar root. */
  dotted: string;
  /** The last segment: an object key or an array index. */
  key: string;
  depth: number;
  value: JsonValue;
  parentKind: "object" | "array" | "root";
  /** The rule that matched, if any. */
  rule?: JsonKeyRule;
  /** Declared type if a rule matched, otherwise inferred from the value. */
  type: JsonFieldType;
  declared: boolean;
  /** Renders as a collapsible branch rather than a value. */
  container: boolean;
  childCount: number;
  /** Set when the value contradicts its declared type. */
  conflict?: JsonEditorIssue;
}

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

export interface JsonEditorProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  /** The document. Controlled — the editor keeps no copy of it. */
  value: JsonValue;
  /**
   * Called with the WHOLE next document plus the edit that produced it. The
   * edit is what a bridge would log, replay, or undo.
   */
  onChange?: (value: JsonValue, edit: JsonEditorEdit) => void;
  /**
   * Type declarations, as a **JSON string** — not an object, and an object is
   * NOT accepted as a convenience overload.
   *
   * A string survives every boundary this prop actually crosses: an MCP tool
   * argument, a config column, a `data-*` attribute, a form field. A live
   * object survives none of them, so accepting both would make the documented
   * form the second-class one in practice.
   *
   * ```jsonc
   * {
   *   "user.age":       "number",           // short form: a bare type name
   *   "tags.*":         "string",           // every element of an array
   *   "orders.*.total": "number",
   *   "role": { "type": "enum", "options": ["admin", "member"] }
   * }
   * ```
   *
   * Malformed input is never thrown and never silently ignored — see
   * {@link JsonEditorIssue}.
   */
  keyMap?: string | null;
  /**
   * `"view"` (the default here) renders values as text that turns into the
   * typed control when clicked; `"edit"` renders every control at once.
   *
   * The kit default is `"edit"`, and this component deliberately differs: a
   * forty-key document drawn as forty boxed inputs is not a document you can
   * read, and reading is most of what a JSON editor is for.
   */
  mode?: FieldMode;
  size?: Size;
  /** Show every value, offer no control. Overrides `mode` and every `allow*`. */
  readOnly?: boolean;
  /**
   * Dotted paths of the expanded containers. Omit BOTH this and
   * `defaultExpanded` to expand everything (pass `defaultExpanded={[]}` for a
   * large document).
   */
  expanded?: string[];
  defaultExpanded?: string[];
  onExpandedChange?: (expanded: string[]) => void;
  /** Render the issues panel. The `data-issues` count and `onIssuesChange` are unaffected. */
  showIssues?: boolean;
  onIssuesChange?: (issues: JsonEditorIssue[]) => void;
  /**
   * Trust-but-verify. With this on, an edit is STAGED into `pending` instead of
   * being applied: `onChange` does not fire until a human accepts it.
   */
  pendingMode?: boolean;
  /** Staged edits. Controlled, so an agent's proposals are inspectable. */
  pending?: JsonEditorPendingEdit[];
  onPendingChange?: (pending: JsonEditorPendingEdit[]) => void;
  /** Every mutation, staged or applied — the hook presence / undo layers listen on. */
  onActivity?: (event: JsonEditorActivity) => void;
  allowAdd?: boolean;
  allowRemove?: boolean;
  allowRename?: boolean;
  allowReorder?: boolean;
  /** Label for a scalar root document. Default `"value"`. */
  rootLabel?: string;
  /** Shown when the document has no keys. */
  emptyLabel?: string;
  /** Prefix for generated control ids — `<idPrefix>-<dotted path>`. */
  idPrefix?: string;
}

import { useState } from "react";
import { cn } from "../../utils/cn";
import { Badge } from "../Badge/Badge";
import { Button } from "../Button/Button";
import { Text } from "../Text/Text";
import { Input } from "../inputs/Input/Input";
import { Select } from "../inputs/Select/Select";
import { useJsonEditorContext } from "./JsonEditor.context";
import { describeEdit } from "./JsonEditor.paths";
import { JsonEditorValue, toText } from "./JsonEditorValue";
import { JSON_FIELD_TYPES } from "./JsonEditor.types";
import type { JsonEditorNode, JsonFieldType } from "./JsonEditor.types";

/** One indent step, in px. Applied as an inline style because depth is data. */
const INDENT = 18;

export interface JsonEditorRowProps {
  node: JsonEditorNode;
}

/**
 * One key/value row.
 *
 * Flat in the DOM rather than nested: `aria-level` carries the depth, so an
 * agent can address `[data-path="orders.2.total"]` in one selector instead of
 * walking a nesting it would have to guess the shape of. It is also the
 * standard flat-tree ARIA pattern.
 */
export function JsonEditorRow({ node }: JsonEditorRowProps) {
  const ctx = useJsonEditorContext();
  const { dotted, key, depth, container, conflict } = node;

  const expanded = container ? ctx.isExpanded(dotted) : undefined;
  const pending = ctx.pendingFor(dotted);
  const renameable =
    ctx.allowRename && !ctx.readOnly && node.parentKind === "object" && ctx.mode === "edit";
  const label = node.rule?.label ?? key;

  return (
    <div
      data-react-fancy-json-editor-row=""
      data-path={dotted}
      data-key={key}
      data-type={node.type}
      data-depth={depth}
      data-declared={node.declared ? "true" : "false"}
      data-conflict={conflict ? "true" : undefined}
      data-pending={pending.length > 0 ? "true" : undefined}
      role="treeitem"
      aria-level={depth + 1}
      aria-expanded={expanded}
      className={cn(
        "border-b border-zinc-100 py-1 last:border-b-0 dark:border-zinc-800",
        conflict && "bg-red-50/60 dark:bg-red-950/20",
        pending.length > 0 && "bg-violet-50/60 dark:bg-violet-950/20",
      )}
    >
      <div className="flex items-start gap-2 px-2" style={{ paddingInlineStart: depth * INDENT + 8 }}>
        {container ? (
          <Button
            variant="ghost"
            size="xs"
            data-react-fancy-json-editor-toggle=""
            data-path={dotted}
            aria-label={expanded ? `Collapse ${label}` : `Expand ${label}`}
            aria-expanded={expanded}
            icon={expanded ? "chevron-down" : "chevron-right"}
            onClick={() => ctx.toggleExpanded(dotted)}
          />
        ) : (
          <span aria-hidden="true" className="inline-block w-6 shrink-0" />
        )}

        <div
          data-react-fancy-json-editor-key=""
          data-path={dotted}
          className="w-1/3 min-w-0 shrink-0"
        >
          {renameable ? (
            <Input
              // Uncontrolled + keyed + commit on blur: renaming per keystroke
              // would fire one structural edit per character.
              key={key}
              size={ctx.size}
              mode="edit"
              defaultValue={key}
              spellCheck={false}
              aria-label={`Key of ${dotted}`}
              onKeyDown={(event) => {
                if (event.key === "Enter") event.currentTarget.blur();
              }}
              onBlur={(event) => {
                const next = event.currentTarget.value;
                if (next !== key) ctx.renameAt(node, next);
              }}
            />
          ) : (
            <Text
              as="span"
              size="sm"
              weight="medium"
              color={node.parentKind === "array" ? "muted" : "default"}
              className="block truncate py-1 font-mono"
              title={dotted}
            >
              {node.parentKind === "array" ? `[${key}]` : label}
            </Text>
          )}
          {node.rule?.description && (
            <Text as="span" size="xs" color="muted" className="block truncate">
              {node.rule.description}
            </Text>
          )}
        </div>

        <div
          data-react-fancy-json-editor-value=""
          data-path={dotted}
          data-type={node.type}
          className="min-w-0 flex-1"
        >
          {container ? (
            <Text as="span" size="sm" color="muted" className="block py-1 font-mono">
              {node.type === "array"
                ? `[ ${node.childCount} ${node.childCount === 1 ? "item" : "items"} ]`
                : `{ ${node.childCount} ${node.childCount === 1 ? "key" : "keys"} }`}
            </Text>
          ) : (
            <JsonEditorValue
              node={node}
              mode={ctx.mode}
              size={ctx.size}
              readOnly={ctx.readOnly}
              id={`${ctx.idPrefix}-${dotted}`}
              onCommit={(next) => ctx.setValueAt(node, next)}
            />
          )}
        </div>

        <div className="flex shrink-0 items-center gap-0.5 pt-0.5">
          {node.declared && (
            <Badge size="sm" variant="soft" color={conflict ? "red" : "zinc"}>
              {node.type}
            </Badge>
          )}
          {container && ctx.allowAdd && !ctx.readOnly && (
            <Button
              variant="ghost"
              size="xs"
              data-react-fancy-json-editor-add=""
              data-path={dotted}
              aria-label={`Add to ${label}`}
              icon="plus"
              onClick={() => ctx.setAddingAt(ctx.addingAt === dotted ? null : dotted)}
            />
          )}
          {ctx.allowReorder && !ctx.readOnly && node.parentKind === "array" && (
            <>
              <Button
                variant="ghost"
                size="xs"
                data-react-fancy-json-editor-move-up=""
                data-path={dotted}
                aria-label={`Move ${dotted} up`}
                icon="arrow-up"
                onClick={() => ctx.moveAt(node, Number(key) - 1)}
              />
              <Button
                variant="ghost"
                size="xs"
                data-react-fancy-json-editor-move-down=""
                data-path={dotted}
                aria-label={`Move ${dotted} down`}
                icon="arrow-down"
                onClick={() => ctx.moveAt(node, Number(key) + 1)}
              />
            </>
          )}
          {ctx.allowRemove && !ctx.readOnly && node.parentKind !== "root" && (
            <Button
              variant="ghost"
              size="xs"
              color="red"
              data-react-fancy-json-editor-remove=""
              data-path={dotted}
              aria-label={`Remove ${dotted}`}
              icon="trash-2"
              onClick={() => ctx.removeAt(node)}
            />
          )}
        </div>
      </div>

      {conflict && (
        <Text
          as="span"
          size="xs"
          color="danger"
          data-react-fancy-json-editor-conflict=""
          data-path={dotted}
          className="block px-2 pb-1"
          style={{ paddingInlineStart: depth * INDENT + 40 }}
        >
          {conflict.message}
        </Text>
      )}

      {pending.map((edit) => (
        <div
          key={edit.id}
          data-react-fancy-json-editor-pending=""
          data-id={edit.id}
          data-path={dotted}
          className="flex items-center gap-2 px-2 pb-1"
          style={{ paddingInlineStart: depth * INDENT + 40 }}
        >
          <Badge size="sm" variant="soft" color="violet">
            proposed
          </Badge>
          <Text as="span" size="xs" color="muted" className="min-w-0 truncate font-mono">
            {edit.label ?? describeEdit(edit)}
            {edit.op === "set" || edit.op === "insert" ? ` → ${toText(edit.value)}` : ""}
          </Text>
          <Button
            size="xs"
            color="emerald"
            data-react-fancy-json-editor-accept=""
            data-id={edit.id}
            onClick={() => ctx.acceptPending(edit.id)}
          >
            Accept
          </Button>
          <Button
            size="xs"
            variant="ghost"
            data-react-fancy-json-editor-reject=""
            data-id={edit.id}
            onClick={() => ctx.rejectPending(edit.id)}
          >
            Reject
          </Button>
        </div>
      ))}
    </div>
  );
}

export interface JsonEditorAddFormProps {
  /** Dotted path of the container being added to; `""` is the document root. */
  path: string;
  kind: "object" | "array";
  depth: number;
  /** Declared type for the container's children, when the keyMap names one. */
  suggestedType?: JsonFieldType;
}

/**
 * The inline "add a key" form.
 *
 * Its open/closed state and its two draft fields are the only state this
 * component owns that is not in `value` — and deliberately so: a half-typed key
 * name is not part of the document, and an agent adding a key does it through
 * an `insert` edit, never by driving this form.
 */
export function JsonEditorAddForm({ path, kind, depth, suggestedType }: JsonEditorAddFormProps) {
  const ctx = useJsonEditorContext();
  const [key, setKey] = useState("");
  const [type, setType] = useState<JsonFieldType>(suggestedType ?? "string");

  return (
    <div
      data-react-fancy-json-editor-add-form=""
      data-path={path}
      className="flex items-center gap-2 border-b border-zinc-100 px-2 py-1.5 dark:border-zinc-800"
      style={{ paddingInlineStart: depth * INDENT + 32 }}
    >
      {kind === "object" && (
        <Input
          size={ctx.size}
          mode="edit"
          value={key}
          placeholder="key"
          aria-label="New key"
          spellCheck={false}
          data-react-fancy-json-editor-add-key=""
          onValueChange={setKey}
        />
      )}
      <Select
        size={ctx.size}
        mode="edit"
        aria-label="New value type"
        data-react-fancy-json-editor-add-type=""
        list={[...JSON_FIELD_TYPES]}
        value={type}
        onValueChange={(next) => setType(next as JsonFieldType)}
      />
      <Button
        size="xs"
        color="blue"
        data-react-fancy-json-editor-add-confirm=""
        onClick={() => ctx.insertInto(path, kind === "object" ? key : undefined, type)}
      >
        Add
      </Button>
      <Button
        size="xs"
        variant="ghost"
        data-react-fancy-json-editor-add-cancel=""
        onClick={() => ctx.setAddingAt(null)}
      >
        Cancel
      </Button>
    </div>
  );
}

import { ColorPicker } from "../ColorPicker/ColorPicker";
import { Input } from "../inputs/Input/Input";
import { Textarea } from "../inputs/Textarea/Textarea";
import { Select } from "../inputs/Select/Select";
import { Switch } from "../inputs/Switch/Switch";
import { DatePicker } from "../inputs/DatePicker/DatePicker";
import { DisplayValue } from "../inputs/mode/DisplayValue";
import { useInlineEdit } from "../inputs/mode/useInlineEdit";
import { resolveOption } from "../inputs/inputs.utils";
import type { FieldMode } from "../inputs/inputs.types";
import type { Size } from "../../utils/types";
import type { JsonEditorNode, JsonFieldType, JsonValue } from "./JsonEditor.types";

export interface JsonEditorValueProps {
  node: JsonEditorNode;
  mode: FieldMode;
  size: Size;
  /** No control at all — the row still shows the value. */
  readOnly: boolean;
  /** Stable control id: `<idPrefix>-<dotted path>`. */
  id: string;
  onCommit: (value: JsonValue) => void;
}

const COLOR_PICKER_SIZE: Record<Size, "sm" | "md" | "lg"> = {
  xs: "sm",
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "lg",
};

/**
 * Types whose text form IS the value commit on every keystroke; types that must
 * be PARSED out of text commit on blur instead.
 *
 * That split is not fussiness. A controlled `number` field that parses per
 * keystroke turns `1.5` into `1` the moment you type the dot, and moves the
 * caret while you are still typing. Committing on blur means the intermediate
 * text is never anybody's value.
 */
function isRawTextType(type: JsonFieldType): boolean {
  return type === "number" || type === "integer" || type === "json";
}

/** The text shown for a value in a raw editor — strings verbatim, everything else as JSON. */
export function toText(value: JsonValue | undefined): string {
  if (value === undefined) return "";
  if (typeof value === "string") return value;
  return JSON.stringify(value) ?? "";
}

/**
 * Read a raw editor's text back into a value.
 *
 * Text that will not parse as the declared type is stored AS TEXT. That is the
 * deliberate choice at the heart of this component: typing `abc` into a field
 * declared `number` neither coerces to `0`/`NaN` nor throws the keystrokes
 * away — it writes `"abc"` and lets the conflict machinery say so, in the same
 * place it reports bad data that arrived from the server.
 */
export function fromText(text: string, type: JsonFieldType): JsonValue {
  switch (type) {
    case "number":
    case "integer": {
      const trimmed = text.trim();
      if (trimmed === "") return text;
      const parsed = Number(trimmed);
      return Number.isFinite(parsed) ? parsed : text;
    }
    case "boolean": {
      const trimmed = text.trim().toLowerCase();
      if (trimmed === "true") return true;
      if (trimmed === "false") return false;
      return text;
    }
    case "json":
    case "object":
    case "array":
      try {
        return JSON.parse(text) as JsonValue;
      } catch {
        return text;
      }
    default:
      return text;
  }
}

/**
 * The read-or-edit control for one leaf value.
 *
 * Everything here is a `react-fancy` primitive — `Input`, `Textarea`, `Select`,
 * `Switch`, `DatePicker`, `ColorPicker` — and the view/edit swap is the kit's
 * own `useInlineEdit` + `DisplayValue`, not a private re-implementation of it.
 */
export function JsonEditorValue({ node, mode, size, readOnly, id, onCommit }: JsonEditorValueProps) {
  const locked = readOnly || node.rule?.readOnly === true;
  const resolvedMode: FieldMode = locked ? "view" : mode;
  const { value, rule } = node;

  // A value that contradicts its declared type cannot be shown through that
  // type's control — a number input cannot hold "thirty-six" — so it falls back
  // to the raw editor, which is also the only place it can be repaired.
  if (node.conflict || isRawTextType(node.type)) {
    return (
      <RawValueEditor
        id={id}
        text={toText(value)}
        type={node.type}
        mode={resolvedMode}
        size={size}
        disabled={locked}
        multiline={node.type === "json" || typeof value === "object"}
        placeholder={rule?.placeholder}
        onCommitText={(text) => onCommit(fromText(text, node.type))}
      />
    );
  }

  const common = { id, size, mode: resolvedMode, disabled: locked } as const;

  switch (node.type) {
    case "boolean":
      return (
        <Switch
          {...common}
          checked={value === true}
          onCheckedChange={(next) => onCommit(next)}
        />
      );

    case "enum": {
      const options = rule?.options ?? [];
      return (
        <Select
          {...common}
          list={options}
          value={String(value)}
          onValueChange={(next) => {
            // Emit the option's ORIGINAL value, so a numeric or boolean enum
            // does not silently become a string on its way through the DOM.
            const match = options
              .map((option) => resolveOption(option))
              .find((option) => String(option.value) === next);
            onCommit((match?.value ?? next) as JsonValue);
          }}
        />
      );
    }

    case "date":
    case "datetime":
      return (
        <DatePicker
          {...common}
          includeTime={node.type === "datetime"}
          min={rule?.min === undefined ? undefined : String(rule.min)}
          max={rule?.max === undefined ? undefined : String(rule.max)}
          value={typeof value === "string" ? value : ""}
          onValueChange={(next) => onCommit(next)}
        />
      );

    case "color":
      return (
        <ColorPicker
          size={COLOR_PICKER_SIZE[size]}
          mode={resolvedMode}
          disabled={locked}
          value={typeof value === "string" ? value : ""}
          onChange={(next) => onCommit(next)}
        />
      );

    case "text":
      return (
        <Textarea
          {...common}
          minRows={2}
          autoResize
          placeholder={rule?.placeholder}
          value={typeof value === "string" ? value : ""}
          onValueChange={(next) => onCommit(next)}
        />
      );

    case "secret":
      return (
        <Input
          {...common}
          type="password"
          reveal
          placeholder={rule?.placeholder}
          value={typeof value === "string" ? value : ""}
          onValueChange={(next) => onCommit(next)}
        />
      );

    case "url":
    case "email":
    case "string":
    default:
      return (
        <Input
          {...common}
          type={node.type === "url" ? "url" : node.type === "email" ? "email" : "text"}
          placeholder={rule?.placeholder}
          value={typeof value === "string" ? value : ""}
          onValueChange={(next) => onCommit(next)}
        />
      );
  }
}

interface RawValueEditorProps {
  id: string;
  text: string;
  type: JsonFieldType;
  mode: FieldMode;
  size: Size;
  disabled: boolean;
  multiline: boolean;
  placeholder?: string;
  onCommitText: (text: string) => void;
}

/**
 * An uncontrolled text control that commits on blur.
 *
 * Uncontrolled is what keeps the component free of a private copy of the
 * document: the half-typed text lives in the DOM node, never in React state,
 * and the `key` is the committed text — so a value changed from OUTSIDE (an
 * agent writing through a bridge, a server push) remounts the control with the
 * new text, while local typing does not.
 */
function RawValueEditor({
  id,
  text,
  type,
  mode,
  size,
  disabled,
  multiline,
  placeholder,
  onCommitText,
}: RawValueEditorProps) {
  const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(mode, disabled);

  if (!showControl) {
    return (
      <DisplayValue size={size} interactive={interactive} onActivate={enterEdit}>
        {text}
      </DisplayValue>
    );
  }

  const commit = (next: string) => {
    if (next !== text) onCommitText(next);
  };

  if (multiline) {
    return (
      <Textarea
        id={id}
        key={text}
        size={size}
        mode="edit"
        minRows={3}
        disabled={disabled}
        placeholder={placeholder}
        defaultValue={text}
        spellCheck={false}
        autoFocus={interactive}
        className="font-mono"
        onBlur={(event) => {
          commit(event.currentTarget.value);
          exitEdit();
        }}
      />
    );
  }

  return (
    <Input
      id={id}
      key={text}
      size={size}
      mode="edit"
      type="text"
      // Not `type="number"`: an `<input type=number>` reports "" for text it
      // considers invalid, so the literal keystrokes we promise to keep would
      // be unreadable on commit. The numeric keyboard is requested instead.
      inputMode={type === "number" || type === "integer" ? "decimal" : undefined}
      disabled={disabled}
      placeholder={placeholder}
      defaultValue={text}
      spellCheck={false}
      autoFocus={interactive}
      onKeyDown={(event) => {
        if (event.key === "Enter") event.currentTarget.blur();
      }}
      onBlur={(event) => {
        commit(event.currentTarget.value);
        exitEdit();
      }}
    />
  );
}

export { JsonEditor } from "./JsonEditor";
export type {
  JsonEditorProps,
  JsonEditorEdit,
  JsonEditorPendingEdit,
  JsonEditorActivity,
  JsonEditorIssue,
  JsonEditorNode,
  JsonFieldType,
  JsonKeyRule,
  JsonKeyMapEntry,
  ParsedKeyMap,
  JsonValue,
  JsonObject,
  JsonArray,
  JsonPrimitive,
  JsonPath,
} from "./JsonEditor.types";
export {
  parseKeyMap,
  resolveKeyRule,
