import { useCallback, useEffect, useRef, useState } from "react";
import { Button } from "../Button";
import { Badge } from "../Badge";
import { Textarea } from "../inputs/Textarea/Textarea";

/**
 * MagicWand — selection-anchored floating toolbar for text inputs.
 *
 * When the user highlights text inside the wrapped <Textarea>, a small
 * pill of AI quick-actions floats above the selection. Clicking an
 * action invokes the host callback with the selected substring + range;
 * the host returns a replacement string and MagicWand swaps it in-place.
 *
 *   <MagicWand
 *     value={body}
 *     onValueChange={setBody}
 *     actions={[
 *       { id: "rephrase", label: "Rephrase", hint: "same meaning, different words",
 *         run: async (s) => await ai.rephrase(s) },
 *       …
 *     ]}
 *   />
 *
 * Two appearances: `"floating"` (default — full labels) and `"pill"`
 * (icon-only, compact). Auto-hides on click-away or scroll by default.
 */
export type MagicWandSelection = { start: number; end: number; text: string };

export type MagicWandAction = {
  /** Stable id, also shown as the busy-state key. */
  id: string;
  /** Display label (first character used in `pill` mode). */
  label: string;
  /** Tooltip body. */
  hint?: string;
  /** Optional kind chip rendered next to the label. */
  tag?: string;
  /** Returns the replacement text for the selection. */
  run: (selection: string, range: MagicWandSelection) => Promise<string> | string;
};

export type MagicWandAppearance = "pill" | "floating";

export interface MagicWandProps {
  /** Controlled textarea value. */
  value: string;
  /** Called on every edit. */
  onValueChange: (v: string) => void;
  /** Action list. */
  actions: MagicWandAction[];
  /** Visual treatment. Defaults to "floating". */
  appearance?: MagicWandAppearance;
  /** Auto-hide the wand on click-away or scroll. Defaults to true. */
  autoHide?: boolean;
  /** Textarea rows. */
  rows?: number;
  /** Placeholder. */
  placeholder?: string;
  /** Called after an action runs successfully. */
  onAction?: (action: MagicWandAction, selection: MagicWandSelection, replacement: string) => void;
}

export function MagicWand({
  value,
  onValueChange,
  actions,
  appearance = "floating",
  autoHide = true,
  rows = 6,
  placeholder,
  onAction,
}: MagicWandProps) {
  const taRef = useRef<HTMLTextAreaElement>(null);
  const wandRef = useRef<HTMLDivElement>(null);
  const [sel, setSel] = useState<MagicWandSelection | null>(null);
  const [pos, setPos] = useState<{ x: number; y: number } | null>(null);
  const [busy, setBusy] = useState<string | null>(null);

  const measureSelection = useCallback(() => {
    const ta = taRef.current;
    if (!ta) return;
    const start = ta.selectionStart ?? 0;
    const end = ta.selectionEnd ?? 0;
    if (start === end) {
      setSel(null);
      setPos(null);
      return;
    }
    const text = ta.value.slice(start, end);
    setSel({ start, end, text });
    const rect = caretRect(ta, start, end);
    if (rect) setPos({ x: rect.x, y: rect.y });
  }, []);

  useEffect(() => {
    if (!autoHide) return;
    const onScroll = () => {
      setSel(null);
      setPos(null);
    };
    window.addEventListener("scroll", onScroll, true);
    return () => window.removeEventListener("scroll", onScroll, true);
  }, [autoHide]);

  useEffect(() => {
    if (!autoHide) return;
    const onDocMouseDown = (e: MouseEvent) => {
      if (wandRef.current?.contains(e.target as Node)) return;
      if (taRef.current?.contains(e.target as Node)) return;
      setSel(null);
      setPos(null);
    };
    document.addEventListener("mousedown", onDocMouseDown);
    return () => document.removeEventListener("mousedown", onDocMouseDown);
  }, [autoHide]);

  const handleAction = async (action: MagicWandAction) => {
    if (!sel) return;
    setBusy(action.id);
    try {
      const replacement = await action.run(sel.text, sel);
      const next = value.slice(0, sel.start) + replacement + value.slice(sel.end);
      onValueChange(next);
      onAction?.(action, sel, replacement);
    } finally {
      setBusy(null);
      setSel(null);
      setPos(null);
    }
  };

  return (
    <div className="relative">
      <Textarea
        ref={taRef as unknown as React.Ref<HTMLTextAreaElement>}
        value={value}
        onValueChange={onValueChange}
        onSelect={measureSelection}
        onKeyUp={measureSelection}
        onMouseUp={measureSelection}
        rows={rows}
        placeholder={placeholder}
      />
      {sel && pos && (
        <Wand
          ref={wandRef}
          pos={pos}
          actions={actions}
          appearance={appearance}
          busy={busy}
          onAction={handleAction}
          selectionLength={sel.text.length}
        />
      )}
    </div>
  );
}

function Wand({
  ref,
  pos,
  actions,
  appearance,
  busy,
  onAction,
  selectionLength,
}: {
  ref: React.RefObject<HTMLDivElement | null>;
  pos: { x: number; y: number };
  actions: MagicWandAction[];
  appearance: MagicWandAppearance;
  busy: string | null;
  onAction: (a: MagicWandAction) => void;
  selectionLength: number;
}) {
  return (
    <div
      ref={ref}
      className="absolute z-20 -translate-x-1/2 -translate-y-full"
      style={{ left: pos.x, top: pos.y - 6 }}
    >
      <div className="flex items-center gap-1 rounded-full border border-violet-300 bg-white px-1.5 py-1 shadow-lg ring-1 ring-violet-200 dark:border-violet-700 dark:bg-zinc-900 dark:ring-violet-900">
        <span className="ml-1 mr-0.5 inline-flex items-center gap-1 text-[10px] font-medium text-violet-700 dark:text-violet-300">
          <span aria-hidden>✦</span>
          {appearance === "floating" && (
            <Badge color="violet">{selectionLength} chars</Badge>
          )}
        </span>
        {actions.map((a) => (
          <Button
            key={a.id}
            size="sm"
            variant="ghost"
            onClick={() => onAction(a)}
            disabled={busy !== null}
            title={a.hint}
          >
            {busy === a.id ? "…" : appearance === "pill" ? a.label[0] : a.label}
            {appearance === "floating" && a.tag && (
              <span className="ml-1 rounded-full bg-zinc-100 px-1 text-[9px] font-medium text-zinc-500 dark:bg-zinc-800">
                {a.tag}
              </span>
            )}
          </Button>
        ))}
      </div>
      <div className="absolute left-1/2 top-full -translate-x-1/2 -translate-y-px">
        <div className="h-2 w-2 rotate-45 border-b border-r border-violet-300 bg-white dark:border-violet-700 dark:bg-zinc-900" />
      </div>
    </div>
  );
}

/**
 * Caret/selection geometry: mirror the textarea into a hidden div and
 * measure the selected substring's bounding rect. Not perfect for
 * resized textareas, but works for typical chat composers.
 */
function caretRect(
  ta: HTMLTextAreaElement,
  start: number,
  end: number,
): { x: number; y: number } | null {
  const div = document.createElement("div");
  const style = getComputedStyle(ta);
  const props = [
    "boxSizing",
    "width",
    "height",
    "overflowX",
    "overflowY",
    "borderTopWidth",
    "borderRightWidth",
    "borderBottomWidth",
    "borderLeftWidth",
    "paddingTop",
    "paddingRight",
    "paddingBottom",
    "paddingLeft",
    "fontStyle",
    "fontVariant",
    "fontWeight",
    "fontStretch",
    "fontSize",
    "fontSizeAdjust",
    "lineHeight",
    "fontFamily",
    "textAlign",
    "textTransform",
    "textIndent",
    "letterSpacing",
    "wordSpacing",
    "tabSize",
  ] as const;
  for (const p of props) (div.style as any)[p] = (style as any)[p];
  div.style.position = "absolute";
  div.style.top = "-9999px";
  div.style.left = "-9999px";
  div.style.whiteSpace = "pre-wrap";
  div.style.wordWrap = "break-word";

  const value = ta.value;
  div.textContent = value.substring(0, start);
  const startSpan = document.createElement("span");
  startSpan.textContent = value.substring(start, end) || ".";
  div.appendChild(startSpan);

  document.body.appendChild(div);
  const taRect = ta.getBoundingClientRect();
  const parentRect =
    (ta.offsetParent as HTMLElement | null)?.getBoundingClientRect() ?? taRect;
  const spanRect = startSpan.getBoundingClientRect();
  const divRect = div.getBoundingClientRect();
  const offsetX = spanRect.left - divRect.left;
  const offsetY = spanRect.top - divRect.top;
  document.body.removeChild(div);

  const x = taRect.left - parentRect.left + offsetX + spanRect.width / 2;
  const y = taRect.top - parentRect.top + offsetY - ta.scrollTop;
  return { x, y };
}

export { MagicWand } from "./MagicWand";
export type {
  MagicWandProps,
  MagicWandAction,
  MagicWandSelection,
  MagicWandAppearance,
} from "./MagicWand";

import { useEffect, useRef, useState, type CSSProperties } from "react";
import type { LatLng, MapHandle, MapMarker, MapProvider, MapView } from "./types";

export type MapProps = {
  /** The map engine to render with — `leafletProvider()` / `googleProvider({ apiKey })`. */
  provider: MapProvider;
  /** Controlled camera. */
  view: MapView;
  /** Fires when the user pans/zooms (or a provider animation settles). */
  onViewChange?: (view: MapView) => void;
  /** Controlled markers (JSON-friendly; an agent can emit these directly). */
  markers?: MapMarker[];
  /** Controlled selection. */
  selectedId?: string | null;
  onSelect?: (id: string | null, marker?: MapMarker) => void;
  /** Fires when a draggable marker is released. */
  onMarkerDragEnd?: (id: string, position: LatLng) => void;
  /** Fires when the map background (not a marker) is clicked. */
  onMapClick?: (position: LatLng) => void;
  /**
   * Live follow — keep this marker centered as its position updates. Set it to a
   * moving marker's id (a vehicle, a delivery, the agent) for live tracking.
   */
  follow?: string | null;
  /** One-shot: fit the camera to enclose these points (re-runs on array identity change). */
  fitTo?: LatLng[];
  /** Grab the imperative handle once the engine is live (e.g. for a bridge's fitBounds). */
  onReady?: (handle: MapHandle) => void;
  /** Called if the provider fails to mount (e.g. Google SDK load error). */
  onError?: (error: unknown) => void;
  className?: string;
  style?: CSSProperties;
  "aria-label"?: string;
};

const EMPTY_MARKERS: MapMarker[] = [];

/** Whether two cameras are close enough to treat as "the same" (echo guard). */
function viewsClose(a: MapView, b: MapView): boolean {
  return (
    Math.abs(a.center.lat - b.center.lat) < 1e-7 &&
    Math.abs(a.center.lng - b.center.lng) < 1e-7 &&
    Math.abs(a.zoom - b.zoom) < 1e-3
  );
}

/**
 * The engine-agnostic map surface. Fully controlled (view + markers + selection),
 * SSR-safe (renders a sized placeholder on the server; the provider mounts inside
 * an effect, so there's no `window`/engine access during render and no hydration
 * mismatch), and driveable by both a human and — via the Human+ map bridge in
 * `@particle-academy/agent-integrations` — an agent, over the same controlled state.
 */
export function Map({
  provider,
  view,
  onViewChange,
  markers = EMPTY_MARKERS,
  selectedId = null,
  onSelect,
  onMarkerDragEnd,
  onMapClick,
  follow = null,
  fitTo,
  onReady,
  onError,
  className,
  style,
  "aria-label": ariaLabel = "Map",
}: MapProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const handleRef = useRef<MapHandle | null>(null);
  // A bump counter that flips once the (async) provider handle is live, so the
  // prop-sync effects below re-run and apply current props to the fresh engine.
  const [ready, setReady] = useState(0);

  // Latest callbacks + the initial mount snapshot, kept in refs so the mount
  // effect stays mount-once (it only re-runs when the provider identity changes).
  const cbRef = useRef({ onViewChange, onSelect, onMarkerDragEnd, onMapClick, onReady, onError });
  cbRef.current = { onViewChange, onSelect, onMarkerDragEnd, onMapClick, onReady, onError };
  const initialRef = useRef({ view, markers, selectedId });
  // The last camera the map itself emitted — lets the view-sync effect ignore
  // the echo of a user pan (which would otherwise fight the animation).
  const lastEmitted = useRef<MapView | null>(null);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) {
      return;
    }
    let disposed = false;
    let handle: MapHandle | null = null;
    const offs: Array<() => void> = [];

    Promise.resolve(
      provider.mount(host, {
        view: initialRef.current.view,
        markers: initialRef.current.markers,
        selectedId: initialRef.current.selectedId,
        interactive: true,
      }),
    )
      .then((h) => {
        if (disposed) {
          h.destroy();
          return;
        }
        handle = h;
        handleRef.current = h;
        offs.push(
          h.on("viewchange", (v) => {
            lastEmitted.current = v;
            cbRef.current.onViewChange?.(v);
          }),
          h.on("markerclick", ({ id, marker }) => cbRef.current.onSelect?.(id, marker)),
          h.on("markerdragend", ({ id, position }) => cbRef.current.onMarkerDragEnd?.(id, position)),
          h.on("click", ({ position }) => cbRef.current.onMapClick?.(position)),
        );
        cbRef.current.onReady?.(h);
        setReady((n) => n + 1);
      })
      .catch((err) => {
        if (!disposed) {
          cbRef.current.onError?.(err);
        }
      });

    return () => {
      disposed = true;
      for (const off of offs) {
        off();
      }
      handle?.destroy();
      if (handleRef.current === handle) {
        handleRef.current = null;
      }
    };
  }, [provider]);

  // Sync camera — skip the echo of the map's own emitted view.
  useEffect(() => {
    const h = handleRef.current;
    if (!h) {
      return;
    }
    if (lastEmitted.current && viewsClose(lastEmitted.current, view)) {
      return;
    }
    h.setView(view, true);
  }, [view, ready]);

  // Sync markers (provider diffs internally — cheap on live-tracking updates).
  useEffect(() => {
    handleRef.current?.setMarkers(markers);
  }, [markers, ready]);

  // Sync selection.
  useEffect(() => {
    handleRef.current?.setSelected(selectedId);
  }, [selectedId, ready]);

  // Live follow — recenter on the followed marker whenever it moves.
  useEffect(() => {
    if (!follow) {
      return;
    }
    const h = handleRef.current;
    if (!h) {
      return;
    }
    const m = markers.find((x) => x.id === follow);
    if (m) {
      h.setView({ center: m.position }, true);
    }
  }, [follow, markers, ready]);

  // One-shot fit.
  useEffect(() => {
    if (fitTo && fitTo.length) {
      handleRef.current?.fitBounds(fitTo);
    }
  }, [fitTo, ready]);

  return (
    <div
      ref={hostRef}
      className={className}
      role="region"
      aria-label={ariaLabel}
      data-fancy-map={provider.name}
      style={{ position: "relative", width: "100%", height: "100%", minHeight: 240, ...style }}
    />
  );
}

/**
 * fancy-map core types — provider-agnostic. Leaflet, Google Maps, and any
 * future engine (MapLibre, Mapbox GL) speak this same vocabulary, so swapping
 * the `provider` prop is the only change needed to move between map engines.
 *
 * Coordinates are `{ lat, lng }` objects (not `[lng, lat]` tuples): it matches
 * both Leaflet (`L.latLng`) and Google (`{ lat, lng }`) native conventions and
 * reads unambiguously in agent-emitted JSON.
 */

/** A geographic point. */
export type LatLng = { lat: number; lng: number };

/** The camera. `bearing`/`pitch` are honored only by providers that support them. */
export type MapView = {
  center: LatLng;
  zoom: number;
  bearing?: number;
  pitch?: number;
};

/**
 * A map marker. JSON-friendly so an agent can emit an array of these directly.
 * `id` is the stable handle — it appears as `data-map-marker-id` on the rendered
 * element and is how selection, updates, and the bridge address a marker.
 */
export type MapMarker = {
  id: string;
  position: LatLng;
  /** Tooltip / popup label. */
  label?: string;
  /** CSS color for the default pin (e.g. "#2563eb"). */
  color?: string;
  /** Emoji or 1–2 chars rendered inside the pin (e.g. "🚚", "A"). */
  icon?: string;
  /** Whether the human can drag this marker (fires onMarkerDragEnd). */
  draggable?: boolean;
  /** Arbitrary JSON payload carried with the marker (agent/host use). */
  data?: Record<string, unknown>;
};

/** Payloads for the events a {@link MapHandle} emits. */
export type MapEventMap = {
  /** Camera moved (user pan/zoom or a provider animation settling). */
  viewchange: MapView;
  /** A marker was clicked. */
  markerclick: { id: string; marker: MapMarker };
  /** A draggable marker was released. */
  markerdragend: { id: string; position: LatLng };
  /** The map background (not a marker) was clicked. */
  click: { position: LatLng };
};

/** Options a provider receives when the component mounts it. */
export type MapMountOptions = {
  view: MapView;
  markers: MapMarker[];
  selectedId?: string | null;
  /** True when the component is server/hydration constrained; providers ignore. */
  interactive?: boolean;
};

/**
 * The imperative handle a provider returns from {@link MapProvider.mount}. The
 * `<Map>` component drives it from props, and the Human+ bridge drives it from
 * an agent — both through this one surface.
 */
export type MapHandle = {
  /** Move the camera. Partial: pass only what changes. */
  setView(view: Partial<MapView>, animate?: boolean): void;
  /** Read the current camera. */
  getView(): MapView;
  /** Reconcile the rendered markers to exactly this set (providers diff). */
  setMarkers(markers: MapMarker[]): void;
  /** Highlight one marker (or clear with null). */
  setSelected(id: string | null): void;
  /** Fit the camera to enclose all points (with optional px padding). */
  fitBounds(points: LatLng[], padding?: number): void;
  /** Subscribe to an event; returns an unsubscribe fn. */
  on<K extends keyof MapEventMap>(event: K, cb: (payload: MapEventMap[K]) => void): () => void;
  /** Tear down the engine and release the host element. */
  destroy(): void;
};

/**
 * A map engine, ready to mount. Created by `leafletProvider()` /
 * `googleProvider({ apiKey })`. `mount` may be async (Google loads its SDK over
 * the network) — the component awaits it.
 */
export type MapProvider = {
  name: string;
  mount(host: HTMLElement, options: MapMountOptions): MapHandle | Promise<MapHandle>;
};

import { cn, ContentRenderer, useControllableState } from "@particle-academy/react-fancy";
import { CodeEditor } from "../CodeEditor";

export type MarkdownEditorMode = "split" | "edit" | "preview";

export interface MarkdownEditorProps {
  /** Controlled markdown value. */
  value?: string;
  /** Initial value (uncontrolled). */
  defaultValue?: string;
  /** Called with the new markdown whenever the document changes. */
  onValueChange?: (markdown: string) => void;
  /**
   * Layout: `split` (editor + live preview side by side), `edit` (editor only),
   * or `preview` (rendered only). Default `split`.
   */
  mode?: MarkdownEditorMode;
  /** Editor theme — `"light" | "dark" | "auto"` or a registered name. Default `auto`. */
  theme?: string;
  /** Prevent editing. */
  readOnly?: boolean;
  /** Show line numbers in the editor (default false — prose reads better without). */
  lineNumbers?: boolean;
  /** Wrap long lines in the editor (default true for prose). */
  wordWrap?: boolean;
  /** Placeholder shown when empty. */
  placeholder?: string;
  /**
   * Height bounds (px). `maxHeight` constrains the PREVIEW pane as well as the
   * editor — it previously reached only the editor, so a long document rendered
   * at full height instead of scrolling.
   */
  minHeight?: number;
  maxHeight?: number;
  className?: string;
  /**
   * Swap the markdown → HTML renderer used by the preview pane.
   *
   * Rarely needed now: the preview renders through react-fancy's
   * `<ContentRenderer format="markdown">`, which is a full CommonMark + GFM
   * parse. Supply this only to impose your own pipeline — the returned HTML is
   * injected as-is, so it must already be sanitised.
   */
  renderPreview?: (markdown: string) => string;
}

/**
 * A markdown-aware editor: a syntax-highlighted `CodeEditor` (the registered
 * `markdown` language) with an optional live preview pane. Controlled via
 * `value` + `onValueChange`. The preview renders through react-fancy's
 * `<ContentRenderer format="markdown">` — a full CommonMark + GFM parse,
 * sanitised by default. Pass `renderPreview` to impose your own pipeline.
 *
 * ```tsx
 * <MarkdownEditor value={md} onValueChange={setMd} mode="split" minHeight={240} />
 * ```
 */
export function MarkdownEditor({
  value,
  defaultValue = "",
  onValueChange,
  mode = "split",
  theme = "auto",
  readOnly = false,
  lineNumbers = false,
  wordWrap = true,
  placeholder,
  minHeight,
  maxHeight,
  className,
  renderPreview,
}: MarkdownEditorProps) {
  const [content, setContent] = useControllableState(value, defaultValue, onValueChange);

  const showEditor = mode !== "preview";
  const showPreview = mode !== "edit";

  return (
    <div
      data-fancy-markdown-editor=""
      data-mode={mode}
      className={cn("fancy-md-editor", className)}
    >
      {showEditor && (
        <div className="fancy-md-editor-pane">
          <CodeEditor
            value={content}
            onChange={setContent}
            language="markdown"
            theme={theme}
            readOnly={readOnly}
            lineNumbers={lineNumbers}
            wordWrap={wordWrap}
            placeholder={placeholder}
            minHeight={minHeight}
            maxHeight={maxHeight}
          >
            <CodeEditor.Panel />
          </CodeEditor>
        </div>
      )}
      {showPreview && (
        <div
          data-fancy-markdown-preview=""
          className="fancy-md-preview"
          style={maxHeight ? { maxHeight, overflowY: "auto" } : undefined}
        >
          {renderPreview ? (
            // The host imposed its own pipeline; its HTML is injected as-is and
            // is its own responsibility to sanitise.
            <div dangerouslySetInnerHTML={{ __html: renderPreview(content) }} />
          ) : (
            // The kit's own renderer — a full CommonMark + GFM parse that
            // sanitises by default. `marked` already sits in this tree as a
            // react-fancy runtime dependency, so the built-in renderer this
            // replaced was a second, weaker markdown implementation next to a
            // complete one.
            <ContentRenderer value={content} format="markdown" />
          )}
        </div>
      )}
    </div>
  );
}

MarkdownEditor.displayName = "MarkdownEditor";

import {
  Children,
  Fragment,
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { cn } from "../../utils/cn";
import type { MarqueeProps } from "./Marquee.types";

function toLength(value: string | number): string {
  return typeof value === "number" ? `${value}px` : value;
}

export const Marquee = forwardRef<HTMLDivElement, MarqueeProps>(
  (
    {
      children,
      items,
      speed = 40,
      duration,
      direction = "left",
      pauseOnHover = false,
      paused = false,
      gap = 40,
      fade = true,
      separator,
      angle = 0,
      decorative = true,
      className,
      style,
      ...rest
    },
    ref,
  ) => {
    const rootRef = useRef<HTMLDivElement>(null);
    const unitRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

    // copies = how many times the item sequence repeats inside ONE loop copy,
    // so short content still fills the strip edge-to-edge (no blank wrap).
    const [copies, setCopies] = useState(1);
    const [measuredDuration, setMeasuredDuration] = useState<number | null>(null);

    // Measure one content unit (incl. its trailing gap) + the container:
    //  - auto-fill: repeat the unit until one loop copy covers the container
    //  - px/s mode: derive the loop duration from the loop distance so the
    //    perceived speed stays constant regardless of content width.
    // Browser-only (effect) — SSR renders one unit at the fallback pace.
    useEffect(() => {
      const root = rootRef.current;
      const unit = unitRef.current;
      if (!root || !unit || typeof ResizeObserver === "undefined") return;
      const update = () => {
        const unitWidth = unit.getBoundingClientRect().width;
        const containerWidth = root.clientWidth;
        if (unitWidth <= 0) return;
        const nextCopies = Math.max(1, Math.ceil(containerWidth / unitWidth));
        setCopies(nextCopies);
        if (duration === undefined) {
          setMeasuredDuration((unitWidth * nextCopies) / Math.max(speed, 1));
        }
      };
      update();
      const observer = new ResizeObserver(update);
      observer.observe(root);
      observer.observe(unit);
      return () => observer.disconnect();
    }, [duration, speed]);

    const loopSeconds = duration ?? measuredDuration ?? 40;
    const itemNodes: ReactNode[] = items ?? Children.toArray(children);
    const hasSeparator = separator !== undefined && separator !== null;

    // One unit = the item sequence once (separator after every item so the
    // wrap point looks identical to any other joint).
    const renderUnit = (duplicate: boolean, unitElRef?: React.Ref<HTMLDivElement>) => (
      <div
        ref={unitElRef}
        className="fancy-marquee__unit"
        aria-hidden={duplicate || undefined}
      >
        {itemNodes.map((node, i) => (
          <Fragment key={i}>
            <div className="fancy-marquee__item" data-react-fancy-marquee-item="" data-index={i}>
              {node}
            </div>
            {hasSeparator && (
              <div
                className="fancy-marquee__separator"
                data-react-fancy-marquee-separator=""
                aria-hidden="true"
              >
                {separator}
              </div>
            )}
          </Fragment>
        ))}
      </div>
    );

    // Two identical groups + translateX(-50%) keyframes = seamless wrap. Only
    // the very first unit is exposed to AT; every repeat is aria-hidden.
    const renderGroup = (duplicate: boolean) => (
      <div
        className="fancy-marquee__group"
        data-react-fancy-marquee-group=""
        aria-hidden={duplicate || undefined}
      >
        {Array.from({ length: copies }, (_, c) =>
          <Fragment key={c}>
            {renderUnit(duplicate || c > 0, !duplicate && c === 0 ? unitRef : undefined)}
          </Fragment>,
        )}
      </div>
    );

    const cssVars: CSSProperties = {
      "--fancy-marquee-duration": `${loopSeconds}s`,
      "--fancy-marquee-gap": toLength(gap),
      ...(fade !== false && {
        "--fancy-marquee-fade": fade === true ? "48px" : toLength(fade),
      }),
    } as CSSProperties;

    // Tilted strips widen slightly (the classic 102% / -1% trick) so the
    // rotation never exposes the page background at the edges.
    const angleStyle: CSSProperties = angle
      ? { transform: `rotate(${angle}deg)`, width: "102%", marginLeft: "-1%" }
      : {};

    return (
      <div
        ref={rootRef}
        data-react-fancy-marquee=""
        data-direction={direction}
        data-paused={paused ? "" : undefined}
        aria-hidden={decorative || undefined}
        className={cn(
          "fancy-marquee",
          fade !== false && "fancy-marquee--fade",
          pauseOnHover && "fancy-marquee--pause-hover",
          className,
        )}
        style={{ ...cssVars, ...angleStyle, ...style }}
        {...rest}
      >
        <div className="fancy-marquee__track" data-react-fancy-marquee-track="">
          {renderGroup(false)}
          {renderGroup(true)}
        </div>
      </div>
    );
  },
);

Marquee.displayName = "Marquee";

import type { HTMLAttributes, ReactNode } from "react";

export type MarqueeDirection = "left" | "right";

export interface MarqueeProps extends HTMLAttributes<HTMLDivElement> {
  /** Item nodes — each child is one strip item (alternative to `items`) */
  children?: ReactNode;
  /** Data-driven items (alternative to children) — strings or nodes */
  items?: ReactNode[];
  /**
   * Scroll speed in px/s — keeps perceived speed constant regardless of
   * content width. Ignored when `duration` is set. Default: 40
   */
  speed?: number;
  /** Explicit seconds per loop (overrides `speed`) */
  duration?: number;
  /** Scroll direction. Default: "left" */
  direction?: MarqueeDirection;
  /** Pause the animation while hovered. Default: false */
  pauseOnHover?: boolean;
  /** Controlled pause — `true` freezes the strip. Default: false */
  paused?: boolean;
  /** Gap between items (number = px). Default: 40 */
  gap?: number | string;
  /**
   * Masked fade at the strip edges: `true` (48px, default), `false` to
   * disable, or a number/CSS length for a custom fade width
   */
  fade?: boolean | number | string;
  /** Optional node rendered between items */
  separator?: ReactNode;
  /**
   * Tilt the whole strip in degrees (e.g. `-1` for the torn, off-axis band
   * look). The strip widens slightly to stay edge-to-edge. Default: 0
   */
  angle?: number;
  /**
   * Decorative strips are `aria-hidden` (default). Set `false` to expose the
   * content to assistive tech — the duplicated loop copy stays hidden either
   * way. Default: true
   */
  decorative?: boolean;
  className?: string;
}

import { cn } from "../../utils/cn";

interface MediaFallbackProps {
  src: string;
  mime?: string;
  label?: string;
  className?: string;
}

/** Filename guess from a URL, ignoring query/hash and `data:`/`blob:` URLs. */
function basename(src: string): string | null {
  if (/^(data|blob):/i.test(src)) return null;
  const seg = src.split(/[?#]/, 1)[0].split("/").pop();
  return seg ? decodeURIComponent(seg) : null;
}

/**
 * Shown by `<MediaViewer>` when a source isn't a previewable media type — a
 * small themed card naming the file and offering a download.
 */
export function MediaFallback({ src, mime, label, className }: MediaFallbackProps) {
  const name = label || basename(src);
  return (
    <div
      data-react-fancy-media-fallback=""
      className={cn(
        "flex flex-col items-center justify-center gap-2 rounded-lg border border-zinc-200 bg-white p-6 text-center dark:border-zinc-700 dark:bg-zinc-900",
        className,
      )}
    >
      <span className="text-sm font-medium text-zinc-700 dark:text-zinc-200">
        No preview available
      </span>
      {(name || mime) && (
        <span className="max-w-full truncate text-xs text-zinc-500 dark:text-zinc-400">
          {name}
          {name && mime ? " · " : ""}
          {mime}
        </span>
      )}
      <a
        href={src}
        download={name ?? undefined}
        className="text-xs font-medium text-blue-600 hover:underline dark:text-blue-400"
      >
        Download
      </a>
    </div>
  );
}

import { forwardRef } from "react";
import { resolveMediaType } from "../../utils/media-type";
import { ImageViewer } from "../ImageViewer";
import { VideoViewer } from "../VideoViewer";
import { AudioViewer } from "../AudioViewer";
import { PdfViewer } from "../PdfViewer";
import { MediaFallback } from "./MediaFallback";
import type { MediaViewerProps } from "./MediaViewer.types";

/**
 * Renders the right viewer for a media file, picked from its `mime` (preferred)
 * or `src` — image, video, audio, or PDF — and a download fallback for anything
 * else. SVG renders through `<ImageViewer>`. The single entry point for showing
 * a file from a tree/workspace when you don't know its type ahead of time.
 *
 * ```tsx
 * <MediaViewer src={url} mime="image/png" alt="logo.png" style={{ height: 320 }} />
 * ```
 */
export const MediaViewer = forwardRef<HTMLDivElement, MediaViewerProps>(
  (
    {
      src,
      mime,
      alt,
      kind,
      imageProps,
      videoProps,
      audioProps,
      pdfProps,
      fallback,
      onError,
      className,
      style,
    },
    ref,
  ) => {
    const resolved = kind ?? resolveMediaType({ mime, src });

    switch (resolved) {
      case "image":
        return (
          <ImageViewer
            ref={ref}
            src={src}
            alt={alt ?? ""}
            onError={onError}
            className={className}
            style={style}
            {...imageProps}
          />
        );
      case "video":
        return (
          <VideoViewer
            ref={ref}
            src={src}
            onError={onError}
            className={className}
            style={style}
            {...videoProps}
          />
        );
      case "audio":
        return (
          <AudioViewer
            ref={ref}
            src={src}
            title={alt}
            onError={onError}
            className={className}
            style={style}
            {...audioProps}
          />
        );
      case "pdf":
        return (
          <PdfViewer
            ref={ref}
            src={src}
            title={alt}
            className={className}
            style={style}
            {...pdfProps}
          />
        );
      default:
        return (
          <div
            ref={ref}
            data-react-fancy-media-viewer=""
            className={className}
            style={style}
          >
            {fallback ?? <MediaFallback src={src} mime={mime} label={alt} />}
          </div>
        );
    }
  },
);

MediaViewer.displayName = "MediaViewer";

import type { CSSProperties, ReactNode } from "react";
import type { MediaKind } from "../../utils/media-type";
import type { ImageViewerProps } from "../ImageViewer/ImageViewer.types";
import type { VideoViewerProps } from "../VideoViewer/VideoViewer.types";
import type { AudioViewerProps } from "../AudioViewer/AudioViewer.types";
import type { PdfViewerProps } from "../PdfViewer/PdfViewer.types";

export interface MediaViewerProps {
  /** Media source — an `http(s):`, `data:`, or `blob:` URL. */
  src: string;
  /**
   * MIME type — preferred for picking the viewer. When omitted, the kind is
   * sniffed from `src` (extension or `data:` URI). Always pass `mime` with a
   * bare `blob:` URL, which carries no type of its own.
   */
  mime?: string;
  /** Alt text / label, forwarded as image alt and audio/PDF title. */
  alt?: string;
  /** Force a specific viewer, bypassing detection. */
  kind?: MediaKind;
  /** Extra props for the underlying `<ImageViewer>`. */
  imageProps?: Partial<Omit<ImageViewerProps, "src" | "alt">>;
  /** Extra props for the underlying `<VideoViewer>`. */
  videoProps?: Partial<Omit<VideoViewerProps, "src">>;
  /** Extra props for the underlying `<AudioViewer>`. */
  audioProps?: Partial<Omit<AudioViewerProps, "src">>;
  /** Extra props for the underlying `<PdfViewer>`. */
  pdfProps?: Partial<Omit<PdfViewerProps, "src">>;
  /** Rendered for unknown / unpreviewable types (default: a download card). */
  fallback?: ReactNode;
  /** Fired when the chosen viewer reports a load error. */
  onError?: () => void;
  /** Additional CSS classes, forwarded to the chosen viewer. */
  className?: string;
  /** Inline styles, forwarded to the chosen viewer. */
  style?: CSSProperties;
}

import { createContext, useContext } from "react";
import type { MenuContextValue } from "./Menu.types";

export const MenuContext = createContext<MenuContextValue | null>(null);

export function useMenu(): MenuContextValue {
  const ctx = useContext(MenuContext);
  if (!ctx) {
    throw new Error("useMenu must be used within a <Menu> component");
  }
  return ctx;
}

import { cn } from "../../utils/cn";
import { MenuContext } from "./Menu.context";
import { MenuItem } from "./MenuItem";
import { MenuSubmenu } from "./MenuSubmenu";
