}

import { Badge, Button, Heading, Text, type Color } from '@particle-academy/react-fancy';
import { useState } from 'react';
import type { ChangeAction, ChangePlan } from '../types';

const ACTION_COLOR: Record<ChangeAction, Color> = {
    create: 'green',
    update: 'blue',
    delete: 'red',
};

export interface PlanReviewProps {
    plan?: ChangePlan | null;
    onApply: () => void;
    onDiscard: () => void;
    busy?: boolean;
    /** Shown in the footer. Set to null to drop the note entirely. */
    draftNote?: React.ReactNode;
    /** react-fancy Button colour for the apply action. */
    color?: Color;
}

/**
 * The approval surface — the only place a proposal becomes rows.
 *
 * Every operation is inspectable before anything is written, raw attributes
 * included. A reviewer who cannot see what they are approving is not really
 * approving it, and "Apply" on an opaque list is just a slower yes.
 */
export function PlanReview({ plan, onApply, onDiscard, busy, draftNote, color = 'red' }: PlanReviewProps) {
    const [expanded, setExpanded] = useState<number | null>(null);

    if (!plan || !plan.operations?.length) return null;

    const summary = Object.entries(plan.summary ?? {})
        .map(([key, count]) => `${count} × ${key.replace('_', ' ')}`)
        .join(' · ');

    return (
        <section className="rounded-lg border border-amber-300 bg-amber-50/60 overflow-hidden">
            <header className="flex flex-wrap items-center justify-between gap-3 border-b border-amber-200 bg-amber-100/60 px-4 py-3">
                <div>
                    <Heading as="h2" size="sm" weight="semibold" className="!text-sm">
                        Proposed changes — nothing has been saved yet
                    </Heading>
                    {summary && <Text className="!text-xs !text-secondary-600 !mt-0.5">{summary}</Text>}
                </div>
                <div className="flex gap-2">
                    <Button
                        onClick={onDiscard}
                        disabled={busy}
                        className="!border !border-secondary-300 !bg-white dark:!bg-zinc-900 !text-secondary-700 !text-sm !px-3 !py-1.5 !rounded-md"
                    >
                        Discard
                    </Button>
                    <Button
                        onClick={onApply}
                        // See MessageComposer: colour is a prop, never a forced
                        // `!bg-brand` class the host may not define.
                        color={color}
                        loading={busy}
                        disabled={busy}
                        className="!font-semibold !text-sm"
                    >
                        Apply {plan.count} change{plan.count === 1 ? '' : 's'}
                    </Button>
                </div>
            </header>

            <ol className="divide-y divide-amber-200">
                {plan.operations.map((op, i) => {
                    const open = expanded === i;
                    const attributes = Object.entries(op.attributes ?? {});

                    return (
                        <li key={i} className="px-4 py-3">
                            <button
                                type="button"
                                onClick={() => setExpanded(open ? null : i)}
                                className="flex w-full items-start gap-3 text-left"
                                aria-expanded={open}
                            >
                                <Badge color={ACTION_COLOR[op.action] ?? 'gray'} variant="soft" size="sm">
                                    {op.action}
                                </Badge>
                                <span className="flex-1">
                                    <Text className="!text-sm !font-medium">{op.description}</Text>
                                    {op.ref && (
                                        <Text className="!text-xs !text-secondary-500 !mt-0.5">
                                            referenced later as ${op.ref}
                                        </Text>
                                    )}
                                </span>
                                <span className="text-xs text-secondary-500 shrink-0">
                                    {open ? 'Hide' : `${attributes.length} field${attributes.length === 1 ? '' : 's'}`}
                                </span>
                            </button>

                            {open && (
                                <dl className="mt-3 grid gap-2 rounded-md bg-white/70 dark:bg-zinc-900/70 p-3 text-sm">
                                    {attributes.map(([key, value]) => (
                                        <div key={key} className="grid sm:grid-cols-[10rem_1fr] gap-1 sm:gap-3">
                                            <dt className="text-xs font-medium uppercase tracking-wide text-secondary-500">
                                                {key}
                                            </dt>
                                            <dd className="whitespace-pre-wrap break-words text-secondary-800">
                                                {value !== null && typeof value === 'object'
                                                    ? JSON.stringify(value, null, 2)
                                                    : String(value)}
                                            </dd>
                                        </div>
                                    ))}
                                </dl>
                            )}
                        </li>
                    );
                })}
            </ol>

            {draftNote !== null && (
                <footer className="border-t border-amber-200 px-4 py-2">
                    <Text className="!text-xs !text-secondary-600">
                        {draftNote ?? (
                            <>
                                Applied changes are saved as <strong>drafts</strong>. Publishing stays a
                                separate, deliberate step.
                            </>
                        )}
                    </Text>
                </footer>
            )}
        </section>
    );
}

import { createContext, useContext } from "react";
import type { PopoverContextValue } from "./Popover.types";

export const PopoverContext = createContext<PopoverContextValue | null>(null);

export function usePopover(): PopoverContextValue {
  const ctx = useContext(PopoverContext);
  if (!ctx) {
    throw new Error("Popover compound components must be used within <Popover>");
  }
  return ctx;
}

import { useCallback, useMemo, useRef, useState } from "react";
import { PopoverContext } from "./Popover.context";
import { PopoverTrigger } from "./PopoverTrigger";
import { PopoverContent } from "./PopoverContent";
import type { PopoverProps } from "./Popover.types";

function PopoverRoot({
  children,
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  placement = "bottom",
  offset = 8,
  hover = false,
  hoverDelay = 200,
  hoverCloseDelay = 300,
}: PopoverProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const isControlled = controlledOpen !== undefined;
  const open = isControlled ? controlledOpen : internalOpen;

  const anchorRef = useRef<HTMLElement>(null);
  const floatingRef = useRef<HTMLDivElement>(null);
  const hoverTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);

  const setOpen = useCallback(
    (next: boolean) => {
      if (!isControlled) setInternalOpen(next);
      onOpenChange?.(next);
    },
    [isControlled, onOpenChange],
  );

  const onHoverEnter = useCallback(() => {
    if (!hover) return;
    clearTimeout(hoverTimeoutRef.current);
    hoverTimeoutRef.current = setTimeout(() => setOpen(true), hoverDelay);
  }, [hover, hoverDelay, setOpen]);

  const onHoverLeave = useCallback(() => {
    if (!hover) return;
    clearTimeout(hoverTimeoutRef.current);
    hoverTimeoutRef.current = setTimeout(() => setOpen(false), hoverCloseDelay);
  }, [hover, hoverCloseDelay, setOpen]);

  const ctx = useMemo(
    () => ({ open, setOpen, anchorRef, floatingRef, placement, offset, hover, onHoverEnter, onHoverLeave }),
    [open, setOpen, placement, offset, hover, onHoverEnter, onHoverLeave],
  );

  return (
    <PopoverContext.Provider value={ctx}>{children}</PopoverContext.Provider>
  );
}

export const Popover = Object.assign(PopoverRoot, {
  Trigger: PopoverTrigger,
  Content: PopoverContent,
});

import type { HTMLAttributes, ReactNode } from "react";
import type { Placement } from "../../utils/types";

export interface PopoverContextValue {
  open: boolean;
  setOpen: (open: boolean) => void;
  anchorRef: React.RefObject<HTMLElement | null>;
  floatingRef: React.RefObject<HTMLDivElement | null>;
  placement: Placement;
  offset: number;
  hover: boolean;
  onHoverEnter: () => void;
  onHoverLeave: () => void;
}

export interface PopoverProps {
  children: ReactNode;
  /** Controlled open state */
  open?: boolean;
  /** Default open state (uncontrolled) */
  defaultOpen?: boolean;
  /** Callback when open state changes */
  onOpenChange?: (open: boolean) => void;
  /** Placement of the popover relative to the trigger */
  placement?: Placement;
  /** Pixel offset from the trigger */
  offset?: number;
  /** Open on hover instead of click */
  hover?: boolean;
  /** Delay in ms before opening on hover. Default: 200 */
  hoverDelay?: number;
  /** Delay in ms before closing after hover leaves. Default: 300 */
  hoverCloseDelay?: number;
}

/**
 * The trigger renders a `<span>` — it extends its attributes so consumers can
 * forward `aria-*`, `data-*`, `id`, `title`, etc. onto the actual anchor node
 * (e.g. `aria-label` for an icon-only trigger). Popover-owned props (ref,
 * onClick, aria-expanded/haspopup) always win over forwarded ones.
 */
export interface PopoverTriggerProps extends HTMLAttributes<HTMLSpanElement> {
  children: ReactNode;
}

/**
 * The content renders a `<div>` — it extends its attributes so consumers can
 * forward `aria-*`/`data-*`/`role`/`id` onto the floating panel. Consumer
 * `style` is merged under the Popover's positioning (left/top always win).
 */
export interface PopoverContentProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
}

import { useCallback, useRef } from "react";
import { cn } from "../../utils/cn";
import { Portal } from "../Portal";
import { usePopover } from "./Popover.context";
import { useFloatingPosition } from "../../hooks/use-floating-position";
import { useOutsideClick } from "../../hooks/use-outside-click";
import { useEscapeKey } from "../../hooks/use-escape-key";
import type { PopoverContentProps } from "./Popover.types";

export function PopoverContent({ children, className, style, ...rest }: PopoverContentProps) {
  const { open, setOpen, anchorRef, floatingRef, placement, offset, hover, onHoverEnter, onHoverLeave } = usePopover();
  const outsideRef = useRef<HTMLDivElement>(null);

  const position = useFloatingPosition(anchorRef, floatingRef, {
    placement,
    offset,
    enabled: open,
  });

  const close = useCallback(() => setOpen(false), [setOpen]);
  useOutsideClick(outsideRef, close, open && !hover, anchorRef);
  useEscapeKey(close, open);

  // Hide until position is calculated to prevent flash at (-9999, -9999)
  const positioned = position.x !== -9999 && position.y !== -9999;

  if (!open) return null;

  return (
    <Portal>
      <div
        {...rest}
        ref={(node) => {
          outsideRef.current = node;
          (floatingRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }}
        data-react-fancy-popover=""
        className={cn(
          "fixed z-50 rounded-xl border border-zinc-200 bg-white p-4 text-zinc-700 shadow-lg dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-200 dark:shadow-zinc-950/50",
          positioned ? "fancy-scale-in" : "invisible",
          className,
        )}
        style={{ ...style, left: position.x, top: position.y }}
        onMouseEnter={hover ? onHoverEnter : undefined}
        onMouseLeave={hover ? onHoverLeave : undefined}
      >
        {children}
      </div>
    </Portal>
  );
}

PopoverContent.displayName = "PopoverContent";

import { cn } from "../../utils/cn";
import { usePopover } from "./Popover.context";
import type { PopoverTriggerProps } from "./Popover.types";

export function PopoverTrigger({ children, className, ...rest }: PopoverTriggerProps) {
  const { setOpen, open, anchorRef, hover, onHoverEnter, onHoverLeave } = usePopover();

  return (
    <span
      {...rest}
      ref={anchorRef as React.RefObject<HTMLSpanElement>}
      data-react-fancy-popover-trigger=""
      className={cn("inline-flex", className)}
      onClick={hover ? undefined : () => setOpen(!open)}
      onMouseEnter={hover ? onHoverEnter : undefined}
      onMouseLeave={hover ? onHoverLeave : undefined}
      aria-expanded={open}
      aria-haspopup
    >
      {children}
    </span>
  );
}

