import { createContext, useContext } from "react";
import type { SidebarContextValue } from "./Sidebar.types";

export const SidebarContext = createContext<SidebarContextValue | null>(null);

export function useSidebar(): SidebarContextValue {
  const ctx = useContext(SidebarContext);
  if (!ctx) {
    throw new Error("useSidebar must be used within a <Sidebar> component");
  }
  return ctx;
}

import { cn } from "../../utils/cn";
import { useControllableState } from "../../hooks";
import { SidebarContext } from "./Sidebar.context";
import { SidebarItem } from "./SidebarItem";
import { SidebarGroup } from "./SidebarGroup";
import { SidebarSubmenu } from "./SidebarSubmenu";
import { SidebarToggle } from "./SidebarToggle";
import type { SidebarProps } from "./Sidebar.types";

function SidebarRoot({
  children,
  collapsed: controlledCollapsed,
  defaultCollapsed = false,
  onCollapsedChange,
  collapseMode = "icons",
  embedded = false,
  className,
}: SidebarProps) {
  const [collapsed, setCollapsed] = useControllableState(
    controlledCollapsed,
    defaultCollapsed,
    onCollapsedChange,
  );

  return (
    <SidebarContext.Provider value={{ collapsed, collapseMode, setCollapsed }}>
      <aside
        data-react-fancy-sidebar=""
        data-collapsed={collapsed || undefined}
        data-embedded={embedded || undefined}
        className={cn(
          "flex flex-col gap-0.5 transition-[width] duration-200",
          // The app-shell chrome. Correct for the rail this is usually used as,
          // and actively wrong inside a container that already draws its own —
          // a 240px rail in a 300px card puts its right border 240px in, which
          // reads as a stray line slicing the panel rather than an edge.
          !embedded && "border-r border-zinc-200 bg-white dark:border-zinc-700 dark:bg-zinc-900",
          // Collapsed is a fixed icon rail either way; only the expanded width
          // defers to the container.
          collapsed ? "w-16" : embedded ? "w-full" : "w-60",
          className,
        )}
      >
        {children}
      </aside>
    </SidebarContext.Provider>
  );
}

export const Sidebar = Object.assign(SidebarRoot, {
  Item: SidebarItem,
  Group: SidebarGroup,
  Submenu: SidebarSubmenu,
  Toggle: SidebarToggle,
});

import type { ReactNode } from "react";
import type { NavigableProps } from "../../utils/types";

export type SidebarCollapseMode = "icons" | "letters";

export interface SidebarProps {
  /**
   * Render without the app-shell chrome — no right border, no background, and
   * full width instead of the fixed `w-60`.
   *
   * For a sidebar living inside a container that already owns its surface: a
   * card, a panel, a drawer. The defaults are right for the standalone rail and
   * wrong here, and neutralising them from outside takes four `!important`
   * utilities that every host has to rediscover and that rot when the base
   * classes change.
   *
   * Chrome only — collapsing still works, and a collapsed rail keeps its fixed
   * narrow width.
   */
  embedded?: boolean;
  children: ReactNode;
  collapsed?: boolean;
  defaultCollapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
  /**
   * How items display when collapsed:
   * - `"icons"` — show only the icon (falls back to first 3 letters if no icon)
   * - `"letters"` — show the first 3 letters of the label
   * @default "icons"
   */
  collapseMode?: SidebarCollapseMode;
  className?: string;
}

export interface SidebarItemProps extends NavigableProps {
  children: ReactNode;
  icon?: ReactNode;
  active?: boolean;
  disabled?: boolean;
  badge?: ReactNode;
  onClick?: () => void;
  className?: string;
}

export interface SidebarGroupProps {
  children: ReactNode;
  label?: string;
  className?: string;
}

export interface SidebarToggleProps {
  className?: string;
}

export interface SidebarSubmenuProps {
  children: ReactNode;
  label: string;
  icon?: ReactNode;
  defaultOpen?: boolean;
  className?: string;
}

export interface SidebarContextValue {
  collapsed: boolean;
  collapseMode: SidebarCollapseMode;
  setCollapsed: (collapsed: boolean) => void;
}

