            >
              {value}
            </div>
            {label != null && (
              <div
                data-react-fancy-stat-label=""
                className="mt-1.5 font-mono text-xs uppercase tracking-wide text-zinc-500 dark:text-zinc-400"
              >
                {label}
              </div>
            )}
          </>
        )}
      </div>
    );
  },
);

