import { MessageComposer } from './MessageComposer';
import { PlanReview } from './PlanReview';
import type { ChangePlan, ChatEntry } from '../types';

export interface TeachersAidChatProps {
    agentName: string;
    history: ChatEntry[];
    plan?: ChangePlan | null;
    onSend: (message: string, files: File[], reset: () => void) => void;
    onApply: () => void;
    onDiscard: () => void;
    onReset?: () => void;
    /** A turn or a plan action is in flight. */
    busy?: boolean;
    /**
     * Optimistic turn to append while the model works, so the transcript does
     * not sit empty during a slow call.
     */
    pending?: ChatEntry | null;
    /** False disables input. Pair it with a banner saying why. */
    configured?: boolean;
    /** Rendered above the plan — flash messages, key warnings, anything. */
    banner?: React.ReactNode;
    description?: React.ReactNode;
    className?: string;
    /** react-fancy colour for the primary actions (send, apply). */
    color?: Color;
}

/**
 * The whole Teachers Aid surface: plan review, transcript, composer.
 *
 * Fully controlled and transport-agnostic — it takes data and callbacks and
 * imports no router or HTTP client. The host owns how a message is sent, which
 * is what lets the same component sit on Inertia, a fetch call or a websocket.
 */
export function TeachersAidChat({
    agentName,
    history,
    plan,
    onSend,
    onApply,
    onDiscard,
    onReset,
    busy,
    pending,
    configured = true,
    banner,
    description,
    className,
    color = 'red',
}: TeachersAidChatProps) {
    const transcript = pending ? [...history, pending] : history;

    return (
        <div className={`grid gap-4 ${className ?? ''}`}>
            {description && <Text className="!text-sm !text-secondary-600">{description}</Text>}

            {banner}

            <PlanReview plan={plan} busy={busy} onApply={onApply} onDiscard={onDiscard} color={color} />

            <div className="flex min-h-[28rem] flex-col overflow-hidden rounded-lg border border-secondary-200 bg-white dark:bg-zinc-900">
                <div className="flex items-center justify-between border-b border-secondary-200 px-4 py-2">
                    <Text className="!text-xs !font-semibold !uppercase !tracking-wide !text-secondary-500">
                        Conversation
                    </Text>
                    {onReset && history.length > 0 && (
                        <button
                            type="button"
                            onClick={onReset}
                            disabled={busy}
                            className="text-xs text-secondary-500 hover:text-primary-600 disabled:opacity-50"
                        >
                            Clear conversation
                        </button>
                    )}
                </div>

                <ChatTranscript
                    history={transcript}
                    agentName={agentName}
                    thinking={!!busy && !!pending}
                />

                <MessageComposer
                    onSend={onSend}
                    agentName={agentName}
                    disabled={busy || !configured}
                    busy={busy}
                    color={color}
                />
            </div>
        </div>
    );
}

import { Badge, ContentRenderer, Text } from '@particle-academy/react-fancy';
import { useEffect, useRef } from 'react';
import type { ChatEntry } from '../types';

/**
 * Prose styling for rendered agent output.
 *
 * Written as arbitrary variants rather than a stylesheet so the package ships
 * no CSS of its own — a host that already scans this package with Tailwind gets
 * the styling for free, with nothing to import and nothing to override.
 */
const PROSE = [
    '[&_p]:my-1 [&_p:first-child]:mt-0 [&_p:last-child]:mb-0',
    '[&_strong]:font-semibold',
    '[&_em]:italic',
    '[&_ul]:my-1 [&_ul]:list-disc [&_ul]:pl-5',
    '[&_ol]:my-1 [&_ol]:list-decimal [&_ol]:pl-5',
    '[&_li]:my-0.5',
    '[&_h1]:text-base [&_h2]:text-base [&_h3]:text-sm',
    '[&_h1]:font-semibold [&_h2]:font-semibold [&_h3]:font-semibold',
    '[&_h1]:mt-2 [&_h2]:mt-2 [&_h3]:mt-2 [&_h1:first-child]:mt-0 [&_h2:first-child]:mt-0 [&_h3:first-child]:mt-0',
    '[&_code]:rounded [&_code]:bg-black/5 [&_code]:dark:bg-white/10 [&_code]:px-1 [&_code]:py-0.5 [&_code]:text-[0.85em]',
    '[&_pre]:my-2 [&_pre]:overflow-x-auto [&_pre]:rounded [&_pre]:bg-black/5 [&_pre]:dark:bg-white/10 [&_pre]:p-2',
    '[&_pre_code]:bg-transparent [&_pre_code]:p-0',
    '[&_a]:underline [&_a]:underline-offset-2',
    '[&_blockquote]:border-l-2 [&_blockquote]:border-secondary-300 [&_blockquote]:pl-3 [&_blockquote]:italic',
    '[&_table]:my-2 [&_table]:w-full [&_table]:text-left',
    '[&_th]:border-b [&_th]:border-secondary-300 [&_th]:pr-3 [&_th]:font-medium',
    '[&_td]:border-b [&_td]:border-secondary-200 [&_td]:pr-3 [&_td]:align-top',
    '[&_hr]:my-2 [&_hr]:border-secondary-300',
].join(' ');

export interface ChatTranscriptProps {
    history: ChatEntry[];
    agentName: string;
    /** Renders the working indicator while a turn is in flight. */
    thinking?: boolean;
    /** Replaces the default empty state. */
    emptyState?: React.ReactNode;
}

/**
 * The conversation.
 *
 * Renders `display` in preference to `content`: the latter is what the model
 * was sent, with extracted file text folded in, and showing it would paste a
 * whole handbook back at the teacher.
 */
export function ChatTranscript({ history, agentName, thinking, emptyState }: ChatTranscriptProps) {
    const endRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        endRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
    }, [history.length, thinking]);

    if (history.length === 0 && !thinking) {
        return (
            <div className="flex flex-1 items-center justify-center px-6 py-12 text-center">
                {emptyState ?? (
                    <div className="max-w-md">
                        <Text className="!text-sm !text-secondary-600">
                            Describe the course you want, or attach the material to build it from —
                            a handbook, a slide deck, a question bank.
                        </Text>
                        <Text className="!text-xs !text-secondary-500 !mt-3">
                            {agentName} drafts changes for you to review. It cannot save anything itself.
                        </Text>
                    </div>
                )}
            </div>
        );
    }

    return (
        <div className="flex-1 overflow-y-auto px-4 py-4 grid gap-4 content-start">
            {history.map((entry, i) => (
                <Bubble key={i} entry={entry} agentName={agentName} />
            ))}

            {thinking && (
                <div className="flex gap-3">
                    <Who label={agentName} />
                    <div className="rounded-lg bg-secondary-100 px-3 py-2">
                        <span className="inline-flex gap-1" aria-label={`${agentName} is working`}>
                            <Dot delay="0ms" />
                            <Dot delay="150ms" />
                            <Dot delay="300ms" />
                        </span>
                    </div>
                </div>
            )}

            <div ref={endRef} />
        </div>
    );
}

function Bubble({ entry, agentName }: { entry: ChatEntry; agentName: string }) {
    const mine = entry.role === 'user';
    const body = entry.display || entry.content || '';

    return (
        <div className={`flex gap-3 ${mine ? 'flex-row-reverse' : ''}`}>
            <Who label={mine ? 'You' : agentName} />
            <div className={`max-w-[46rem] ${mine ? 'text-right' : ''}`}>
                <div
                    className={`inline-block rounded-lg px-3 py-2 text-left break-words text-sm ${
                        mine
                            ? 'bg-brand text-white whitespace-pre-wrap'
                            : 'bg-secondary-100 text-secondary-900'
                    }`}
                >
                    {mine ? (
                        // The teacher's own words, verbatim. Rendering these as
                        // markdown would silently reformat what they typed.
                        body
                    ) : (
                        // Model output is markdown, and it is not trusted input —
                        // it can carry whatever an uploaded file talked it into
                        // writing. ContentRenderer sanitizes by default; never
                        // pass `unsafe` here.
                        <ContentRenderer value={body} format="markdown" className={PROSE} />
                    )}
                </div>
                {entry.files && entry.files.length > 0 && (
                    <div className={`mt-1.5 flex flex-wrap gap-1.5 ${mine ? 'justify-end' : ''}`}>
                        {entry.files.map((name) => (
                            <Badge key={name} color="gray" variant="soft" size="sm">
                                {name}
                            </Badge>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

function Who({ label }: { label: string }) {
    return (
        <div className="shrink-0 pt-1">
            <span className="text-[10px] font-semibold uppercase tracking-wide text-secondary-500">
                {label}
            </span>
        </div>
    );
}

function Dot({ delay }: { delay: string }) {
    return (
        <span
            className="h-1.5 w-1.5 rounded-full bg-secondary-400 animate-bounce"
            style={{ animationDelay: delay }}
        />
    );
}

import { Badge, Button, Text, type Color } from '@particle-academy/react-fancy';
import { useRef, useState } from 'react';

const ACCEPT = '.pdf,.png,.jpg,.jpeg,.gif,.webp,.docx,.xlsx,.csv,.txt,.pptx';

export interface MessageComposerProps {
    onSend: (message: string, files: File[], reset: () => void) => void;
    agentName: string;
    /** Blocks input — in flight, or no model configured. */
    disabled?: boolean;
    /** Spins the send button. Distinct from `disabled` on purpose. */
    busy?: boolean;
    accept?: string;
    maxFiles?: number;
    hint?: React.ReactNode;
    /** react-fancy Button colour for the send action. */
    color?: Color;
}

/**
 * Message box with file drop.
 *
 * Named to avoid colliding with react-fancy's own `Composer`, and hand-rolled
 * rather than using its `PromptInput` because that component maps dropped
 * files to `{id, name, bytes}` and discards the File — so the chip renders but
 * the upload can never happen. Reported upstream; switch to it once the
 * attachment carries the file.
 *
 * Attachments are held here until send, so a mistaken drop can be removed
 * before it costs a model call.
 */
export function MessageComposer({
    onSend,
    agentName,
    disabled,
    busy,
    accept = ACCEPT,
    maxFiles = 10,
    hint,
    color = 'red',
}: MessageComposerProps) {
    const [message, setMessage] = useState('');
    const [files, setFiles] = useState<File[]>([]);
    const [dragging, setDragging] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);

    function addFiles(list: FileList | null) {
        const incoming = Array.from(list ?? []);
        if (incoming.length === 0) return;

        setFiles((current) => {
            // De-dupe by name+size so dropping the same file twice does not
            // send it twice and pay for it twice.
            const seen = new Set(current.map((f) => `${f.name}:${f.size}`));
            return [...current, ...incoming.filter((f) => !seen.has(`${f.name}:${f.size}`))].slice(
                0,
                maxFiles,
            );
        });
    }

    function submit(e: React.FormEvent | React.KeyboardEvent) {
        e.preventDefault();
        if (disabled || message.trim() === '') return;

        onSend(message.trim(), files, () => {
            setMessage('');
            setFiles([]);
            if (inputRef.current) inputRef.current.value = '';
        });
    }

    function onKeyDown(e: React.KeyboardEvent) {
        // Enter sends, Shift+Enter breaks the line — the convention everywhere
        // else, and course descriptions are multi-line often enough to matter.
        if (e.key === 'Enter' && !e.shiftKey) submit(e);
    }

    return (
        <form
            onSubmit={submit}
            onDragOver={(e) => {
                e.preventDefault();
                setDragging(true);
            }}
            onDragLeave={() => setDragging(false)}
            onDrop={(e) => {
                e.preventDefault();
                setDragging(false);
                addFiles(e.dataTransfer.files);
            }}
            className={`border-t px-4 py-3 transition ${
                dragging ? 'border-brand bg-primary-50 dark:bg-primary-950' : 'border-secondary-200 bg-white dark:bg-zinc-900'
            }`}
        >
            {files.length > 0 && (
                <div className="mb-2 flex flex-wrap gap-1.5">
                    {files.map((file, i) => (
                        <span key={`${file.name}:${i}`} className="inline-flex items-center gap-1">
                            <Badge color="blue" variant="soft" size="sm">
                                {file.name} · {Math.max(1, Math.round(file.size / 1024))} KB
                            </Badge>
                            <button
                                type="button"
                                onClick={() => setFiles((c) => c.filter((_, j) => j !== i))}
                                className="text-xs text-secondary-500 hover:text-primary-600"
                                aria-label={`Remove ${file.name}`}
                            >
                                ×
                            </button>
                        </span>
                    ))}
                </div>
            )}

            <div className="flex items-end gap-2">
                <button
                    type="button"
                    onClick={() => inputRef.current?.click()}
                    className="shrink-0 rounded-md border border-secondary-300 px-3 py-2 text-sm text-secondary-700 hover:bg-secondary-50"
                    title="Attach course material"
                >
                    Attach
                </button>
                <input
                    ref={inputRef}
                    type="file"
                    multiple
                    accept={accept}
                    className="hidden"
                    onChange={(e) => addFiles(e.target.files)}
                />

                <textarea
                    rows={2}
                    value={message}
                    disabled={disabled}
                    onChange={(e) => setMessage(e.target.value)}
                    onKeyDown={onKeyDown}
                    placeholder={`Ask ${agentName} to draft or update course material…`}
                    className="flex-1 resize-none rounded-md border border-secondary-300 px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/15 disabled:bg-secondary-50"
                />

                <Button
                    type="submit"
                    // Colour comes from the PROP, not a forced `!bg-brand`
                    // class. That token is defined by some hosts and not
                    // others, so forcing it renders an unstyled grey slab
                    // wherever it is absent — with no error to trace.
                    color={color}
                    // Only `busy`, never `disabled` — the box is also disabled
                    // when no model is configured, and a permanent spinner reads
                    // as "working" when nothing is happening at all.
                    loading={busy}
                    disabled={disabled || message.trim() === ''}
                    className="!font-semibold"
                >
                    Send
                </Button>
            </div>

            <Text className="!text-[11px] !text-secondary-500 !mt-1.5">
                {hint ?? (
                    <>
                        PDF and images are read directly; Word, Excel, PowerPoint and CSV are converted
                        to text first. Drop files anywhere on this box.
                    </>
                )}
            </Text>
        </form>
    );
}

import { Badge, Button, Heading, Text, type Color } from '@particle-academy/react-fancy';
import { useState } from 'react';
import type { ChangeAction, ChangePlan } from '../types';

const ACTION_COLOR: Record<ChangeAction, Color> = {
    create: 'green',
    update: 'blue',
    delete: 'red',
};

export interface PlanReviewProps {
    plan?: ChangePlan | null;
    onApply: () => void;
    onDiscard: () => void;
    busy?: boolean;
    /** Shown in the footer. Set to null to drop the note entirely. */
    draftNote?: React.ReactNode;
    /** react-fancy Button colour for the apply action. */
    color?: Color;
}

/**
 * The approval surface — the only place a proposal becomes rows.
 *
 * Every operation is inspectable before anything is written, raw attributes
 * included. A reviewer who cannot see what they are approving is not really
 * approving it, and "Apply" on an opaque list is just a slower yes.
 */
export function PlanReview({ plan, onApply, onDiscard, busy, draftNote, color = 'red' }: PlanReviewProps) {
    const [expanded, setExpanded] = useState<number | null>(null);

    if (!plan || !plan.operations?.length) return null;

    const summary = Object.entries(plan.summary ?? {})
        .map(([key, count]) => `${count} × ${key.replace('_', ' ')}`)
        .join(' · ');

    return (
        <section className="rounded-lg border border-amber-300 bg-amber-50/60 overflow-hidden">
            <header className="flex flex-wrap items-center justify-between gap-3 border-b border-amber-200 bg-amber-100/60 px-4 py-3">
                <div>
                    <Heading as="h2" size="sm" weight="semibold" className="!text-sm">
                        Proposed changes — nothing has been saved yet
                    </Heading>
                    {summary && <Text className="!text-xs !text-secondary-600 !mt-0.5">{summary}</Text>}
                </div>
                <div className="flex gap-2">
                    <Button
                        onClick={onDiscard}
                        disabled={busy}
                        className="!border !border-secondary-300 !bg-white dark:!bg-zinc-900 !text-secondary-700 !text-sm !px-3 !py-1.5 !rounded-md"
                    >
                        Discard
                    </Button>
                    <Button
                        onClick={onApply}
                        // See MessageComposer: colour is a prop, never a forced
                        // `!bg-brand` class the host may not define.
                        color={color}
                        loading={busy}
                        disabled={busy}
                        className="!font-semibold !text-sm"
                    >
                        Apply {plan.count} change{plan.count === 1 ? '' : 's'}
                    </Button>
                </div>
            </header>

            <ol className="divide-y divide-amber-200">
                {plan.operations.map((op, i) => {
                    const open = expanded === i;
                    const attributes = Object.entries(op.attributes ?? {});

                    return (
                        <li key={i} className="px-4 py-3">
                            <button
                                type="button"
                                onClick={() => setExpanded(open ? null : i)}
                                className="flex w-full items-start gap-3 text-left"
                                aria-expanded={open}
                            >
                                <Badge color={ACTION_COLOR[op.action] ?? 'gray'} variant="soft" size="sm">
                                    {op.action}
                                </Badge>
                                <span className="flex-1">
                                    <Text className="!text-sm !font-medium">{op.description}</Text>
                                    {op.ref && (
                                        <Text className="!text-xs !text-secondary-500 !mt-0.5">
                                            referenced later as ${op.ref}
                                        </Text>
                                    )}
                                </span>
                                <span className="text-xs text-secondary-500 shrink-0">
                                    {open ? 'Hide' : `${attributes.length} field${attributes.length === 1 ? '' : 's'}`}
                                </span>
                            </button>

                            {open && (
                                <dl className="mt-3 grid gap-2 rounded-md bg-white/70 dark:bg-zinc-900/70 p-3 text-sm">
                                    {attributes.map(([key, value]) => (
                                        <div key={key} className="grid sm:grid-cols-[10rem_1fr] gap-1 sm:gap-3">
                                            <dt className="text-xs font-medium uppercase tracking-wide text-secondary-500">
                                                {key}
                                            </dt>
                                            <dd className="whitespace-pre-wrap break-words text-secondary-800">
                                                {value !== null && typeof value === 'object'
                                                    ? JSON.stringify(value, null, 2)
                                                    : String(value)}
                                            </dd>
                                        </div>
                                    ))}
                                </dl>
                            )}
                        </li>
                    );
                })}
            </ol>

            {draftNote !== null && (
                <footer className="border-t border-amber-200 px-4 py-2">
                    <Text className="!text-xs !text-secondary-600">
                        {draftNote ?? (
                            <>
                                Applied changes are saved as <strong>drafts</strong>. Publishing stays a
                                separate, deliberate step.
                            </>
                        )}
                    </Text>
                </footer>
            )}
        </section>
    );
}

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from "react";
import { useTerminal } from "../hooks/use-terminal";
import { ShellSwitcher } from "./ShellSwitcher";
import { TerminalContextMenu } from "./TerminalContextMenu";
import { diffOutput } from "../output-diff";
import { decideShellSelect } from "../shell-select";
import { providerWrite, resolveClipboard } from "../clipboard";
import { resolveMenuItems, type TerminalContextMenuContext, type TerminalContextMenuItem } from "../context-menu";
import { nextSelectionSnapshot } from "../selection-snapshot";
import type { TerminalHandle, TerminalProps } from "../types";

/**
 * Human+ `<Terminal>` — a controlled, themeable xterm.js terminal.
 *
 * - **Authoring surface:** terse, controlled (`output` + `onData`), JSON-friendly
 *   props (rows/cols, theme tokens, initial buffer), a stable `data-fancy-terminal`
 *   handle, and a ref exposing {@link TerminalHandle} (write/clear/fit/getBuffer/…).
 * - **Inhabited surface:** the same handle is what an MCP bridge drives, so an
 *   embedded agent reads the buffer + writes input without DOM-scraping.
 *
 * The parent must have a height — the terminal fits its container (like any xterm
 * surface); a 0-height parent collapses it.
 *
 * ```tsx
 * const [out, setOut] = useState("");
 * <div style={{ height: 360 }}>
 *   <Terminal output={out} onData={(d) => backend.send(d)} />
 * </div>
 * ```
 */
export const Terminal = forwardRef<TerminalHandle, TerminalProps>(function Terminal(
  {
    output,
    theme,
    rows,
    cols,
    fit = true,
    readOnly,
    cursorBlink,
    cursorStyle,
    fontFamily,
    fontSize,
    scrollback,
    initialOutput,
    onData,
    onResize,
    shells,
    activeShell,
    onShellChange,
    showShellBar = false,
    clipboard,
    osc52,
    copyPaste,
    onReady,
    onPaste,
    contextMenu,
    className,
    style,
    ...rest
  },
  ref,
) {
  const containerRef = useRef<HTMLDivElement>(null);

  // Selected shell: controlled by `activeShell` when provided, else internal.
  const isShellControlled = activeShell !== undefined;
  const [internalShell, setInternalShell] = useState<string | undefined>(undefined);
  const shellId = isShellControlled ? activeShell : internalShell;

  // Read shell state live so the stable handle's setShell/getShell never go stale.
  const shellStateRef = useRef({ shells, shellId, isShellControlled, onShellChange });
  shellStateRef.current = { shells, shellId, isShellControlled, onShellChange };

  const selectShell = useCallback((id: string) => {
    const s = shellStateRef.current;
    const decision = decideShellSelect(s.shells, s.shellId, id);
    if (!decision) return; // unknown id — no-op
    if (!s.isShellControlled) setInternalShell(id);
    s.onShellChange?.(id, decision.profile);
  }, []);

  const handle = useTerminal(containerRef, {
    theme,
    rows,
    cols,
    fit,
    readOnly,
    cursorBlink,
    cursorStyle,
    fontFamily,
    fontSize,
    scrollback,
    // `initialOutput` is for uncontrolled use; with a controlled `output` the
    // diffing effect below owns the buffer, so don't double-write.
    initialOutput: output === undefined ? initialOutput : undefined,
    onData,
    onResize,
    clipboard,
    osc52,
    copyPaste,
    onReady,
    onPaste,
  });

  // Delegate `xterm` / `ready` as live getters rather than spreading `handle`
  // (object spread would snapshot the getters — capturing xterm === null before
  // the container is measured, the exact race consumers hit). Methods are stable.
  useImperativeHandle(
    ref,
    (): TerminalHandle => ({
      get xterm() {
        return handle.xterm;
      },
      get ready() {
        return handle.ready;
      },
      write: handle.write,
      writeln: handle.writeln,
      clear: handle.clear,
      reset: handle.reset,
      fit: handle.fit,
      focus: handle.focus,
      getBuffer: handle.getBuffer,
      getSelection: handle.getSelection,
      copySelection: handle.copySelection,
      paste: handle.paste,
      selectAll: handle.selectAll,
      clearSelection: handle.clearSelection,
      setShell: selectShell,
      getShell: () => shellStateRef.current.shellId,
    }),
    [handle, selectShell],
  );

  // Controlled output: write only the appended delta; reset + rewrite if the
  // value diverges from what we've already written (a wholesale replace).
  const written = useRef("");
  useEffect(() => {
    if (output === undefined) return;
    const change = diffOutput(written.current, output);
    if (!change) return;
    if (change.reset) handle.reset();
    handle.write(change.write);
    written.current = output;
  }, [output, handle]);

  // Right-click selection context menu (Copy / Paste / Select all / Clear by
  // default; customizable via the `contextMenu` prop).
  const [menu, setMenu] = useState<{
    at: { x: number; y: number };
    items: TerminalContextMenuItem[];
    ctx: TerminalContextMenuContext;
  } | null>(null);

  // #2 — over a mouse-reporting TUI (Claude Code, tmux, vim) the app's redraw
  // asynchronously clears xterm's selection right after a right-click, so both
  // late reads lose: at `contextmenu` time the selection may already be gone,
  // and by the time the user clicks Copy it almost always is. Track a snapshot
  // at pointer time (capture phase — before xterm / the app can react) and use
  // it as the menu's source of truth whenever the live selection is empty.
  const selectionSnapshot = useRef("");
  const trackSelection = useCallback(
    (e: React.MouseEvent) => {
      selectionSnapshot.current = nextSelectionSnapshot(
        selectionSnapshot.current,
        { type: e.type as "mousedown" | "mouseup", button: e.button },
        handle.getSelection(),
      );
    },
    [handle],
  );

  const openMenu = useCallback(
    (e: React.MouseEvent) => {
      if (contextMenu === false) return;
      e.preventDefault();
      const selection = handle.getSelection() || selectionSnapshot.current;
      const ctx: TerminalContextMenuContext = {
        hasSelection: selection.length > 0,
        selection,
        readOnly: !!readOnly,
      };
      const items = resolveMenuItems(contextMenu, ctx, {
        // Copy writes the SNAPSHOTTED selection through the active clipboard
        // provider — never a click-time re-read, which copies "" over a TUI
        // (falling back to the live selection only when the snapshot is empty).
        copy: (c) => {
          const text = c.selection || handle.getSelection();
          if (text) void providerWrite(resolveClipboard(clipboard).provider, text);
        },
        paste: () => void handle.paste(),
        selectAll: () => handle.selectAll(),
        clear: () => handle.clear(),
      });
      if (items) setMenu({ at: { x: e.clientX, y: e.clientY }, items, ctx });
    },
    [contextMenu, handle, readOnly, clipboard],
  );

  const menuNode = menu ? (
    <TerminalContextMenu at={menu.at} items={menu.items} ctx={menu.ctx} onClose={() => setMenu(null)} />
  ) : null;

  const surface = (
    <div
      ref={containerRef}
      data-fancy-terminal=""
      onMouseDownCapture={trackSelection}
      onMouseUpCapture={trackSelection}
      onContextMenu={openMenu}
      data-readonly={readOnly ? "" : undefined}
      data-fancy-terminal-shell={shellId ?? undefined}
      // When the shell bar is shown the wrapper owns the box; the surface flexes.
      style={
        showShellBar && shells
          ? { width: "100%", flex: 1, minHeight: 0 }
          : { width: "100%", height: "100%", ...style }
      }
      {...(showShellBar && shells ? {} : rest)}
    />
  );

  if (!showShellBar || !shells) {
    return (
      <>
        {surface}
        {menuNode}
      </>
    );
  }

  return (
    <div
      data-fancy-terminal-shell={shellId ?? undefined}
      className={className}
      style={{ display: "flex", flexDirection: "column", width: "100%", height: "100%", ...style }}
      {...rest}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          padding: "4px 6px",
          background: "#09090b",
          borderBottom: "1px solid #27272a",
        }}
      >
        <ShellSwitcher
          shells={shells}
          value={shellId}
          onChange={(id) => selectShell(id)}
          disabled={readOnly}
        />
      </div>
      {surface}
      {menuNode}
    </div>
  );
});

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
} from "react";
import { resolveShell, type ShellProfile } from "../types";

export interface ShellSwitcherProps {
  /** The available shells / profiles. */
  shells: ShellProfile[];
  /** Controlled selected shell id. */
  value?: string;
  /** Fired when a shell is picked. */
  onChange: (id: string, profile: ShellProfile) => void;
  className?: string;
  style?: CSSProperties;
  /** Disable the control. */
  disabled?: boolean;
}

const PANEL_BG = "#18181b"; // zinc-900
const BORDER = "#3f3f46"; // zinc-700
const FG = "#e4e4e7"; // zinc-200
const MUTED = "#a1a1aa"; // zinc-400
const ACCENT = "#8b5cf6"; // violet-500
const HOVER_BG = "#27272a"; // zinc-800

/**
 * Compact, accessible shell picker styled to the Fancy dark theme. Self-contained
 * (zero third-party deps) — a button that toggles a listbox of `shells`.
 *
 * Stable handles for agents: the root carries `data-fancy-shell-switcher` and each
 * option carries `data-shell-id`, so a bridge can pick a shell without DOM-guessing.
 *
 * Controlled: pass `value` + `onChange`. Keyboard accessible (Arrow / Enter / Esc).
 */
export function ShellSwitcher({
  shells,
  value,
  onChange,
  className,
  style,
  disabled,
}: ShellSwitcherProps) {
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);
  const rootRef = useRef<HTMLDivElement>(null);
  const listId = useId();

  const selected = resolveShell(shells, value);
  const selectedIndex = selected ? shells.indexOf(selected) : -1;

  // Close on outside click.
  useEffect(() => {
    if (!open) return;
    const onDocClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [open]);

  const openMenu = useCallback(() => {
    if (disabled) return;
    setActiveIndex(selectedIndex >= 0 ? selectedIndex : 0);
    setOpen(true);
  }, [disabled, selectedIndex]);

  const pick = useCallback(
    (i: number) => {
      const profile = shells[i];
      if (!profile) return;
      onChange(profile.id, profile);
      setOpen(false);
    },
    [shells, onChange],
  );

  const onButtonKeyDown = (e: KeyboardEvent) => {
    if (disabled) return;
    if (e.key === "ArrowDown" || e.key === "ArrowUp" || e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      openMenu();
    }
  };

  const onListKeyDown = (e: KeyboardEvent) => {
    if (e.key === "Escape") {
      e.preventDefault();
      setOpen(false);
      return;
    }
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((i) => Math.min(shells.length - 1, i + 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((i) => Math.max(0, i - 1));
    } else if (e.key === "Home") {
      e.preventDefault();
      setActiveIndex(0);
    } else if (e.key === "End") {
      e.preventDefault();
      setActiveIndex(shells.length - 1);
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      pick(activeIndex);
    }
  };

  const buttonStyle: CSSProperties = {
    display: "inline-flex",
    alignItems: "center",
    gap: 6,
    height: 26,
    padding: "0 8px",
    fontSize: 12,
    lineHeight: 1,
    fontFamily: "inherit",
    color: FG,
    background: PANEL_BG,
    border: `1px solid ${BORDER}`,
    borderRadius: 6,
    cursor: disabled ? "default" : "pointer",
    opacity: disabled ? 0.6 : 1,
    userSelect: "none",
  };

  return (
    <div
      ref={rootRef}
      data-fancy-shell-switcher=""
      data-active-shell={value ?? undefined}
      className={className}
      style={{ position: "relative", display: "inline-block", ...style }}
    >
      <button
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label="Select shell"
        disabled={disabled}
        style={buttonStyle}
        onClick={() => (open ? setOpen(false) : openMenu())}
        onKeyDown={onButtonKeyDown}
      >
        {selected?.icon ? (
          <span aria-hidden="true" style={{ color: ACCENT }}>
            {selected.icon}
          </span>
        ) : null}
        <span>{selected?.label ?? "Select shell"}</span>
        <span aria-hidden="true" style={{ color: MUTED, fontSize: 9 }}>
          ▼
        </span>
      </button>

      {open ? (
        <ul
          role="listbox"
          id={listId}
          aria-label="Shells"
          tabIndex={-1}
          // Autofocus is deliberate: this list only renders once the switcher
          // is opened by an explicit user action, so focus is going where the
          // person just asked to be. (This used to carry an
          // `eslint-disable jsx-a11y/no-autofocus`, but jsx-a11y has never been
          // a dependency here — it silenced a rule that did not exist, and
          // broke linting once ESLint was actually turned on.)
          autoFocus
          onKeyDown={onListKeyDown}
          ref={(el) => el?.focus()}
          style={{
            position: "absolute",
            zIndex: 50,
            top: "calc(100% + 4px)",
            left: 0,
            minWidth: "100%",
            margin: 0,
            padding: 4,
            listStyle: "none",
            background: PANEL_BG,
            border: `1px solid ${BORDER}`,
            borderRadius: 8,
            boxShadow: "0 8px 24px rgba(0,0,0,0.45)",
            outline: "none",
          }}
        >
          {shells.map((s, i) => {
            const isSelected = s.id === value;
            const isActive = i === activeIndex;
            return (
              <li
                key={s.id}
                role="option"
                aria-selected={isSelected}
                data-shell-id={s.id}
                onMouseEnter={() => setActiveIndex(i)}
                onClick={() => pick(i)}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  padding: "6px 8px",
                  fontSize: 12,
                  borderRadius: 5,
                  color: FG,
                  cursor: "pointer",
                  background: isActive ? HOVER_BG : "transparent",
                }}
              >
                <span
                  aria-hidden="true"
                  style={{
                    width: 18,
                    textAlign: "center",
                    color: isSelected ? ACCENT : MUTED,
                  }}
                >
                  {s.icon ?? ""}
                </span>
                <span style={{ flex: 1 }}>{s.label}</span>
                {isSelected ? (
                  <span aria-hidden="true" style={{ color: ACCENT, fontSize: 11 }}>
                    ✓
                  </span>
                ) : null}
              </li>
            );
          })}
        </ul>
      ) : null}
    </div>
  );
}

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { clampMenuPosition } from "../menu-position";
import type {
  TerminalContextMenuContext,
  TerminalContextMenuItem,
} from "../context-menu";

/**
 * The terminal selection context menu. Deliberately plain React + inline styles
 * (fancy-term has no react-fancy dependency) styled to match the shell bar. It
 * closes on click-outside + Escape, and clamps itself inside the viewport on
 * mount so a right-click near an edge never spills off-screen.
 */
export function TerminalContextMenu({
  at,
  items,
  ctx,
  onClose,
}: {
  at: { x: number; y: number };
  items: TerminalContextMenuItem[];
  ctx: TerminalContextMenuContext;
  onClose: () => void;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [pos, setPos] = useState(at);

  // Clamp once we can measure the rendered menu.
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el || typeof window === "undefined") return;
    const r = el.getBoundingClientRect();
    setPos(
      clampMenuPosition(
        at,
        { width: r.width, height: r.height },
        { width: window.innerWidth, height: window.innerHeight },
      ),
    );
  }, [at]);

  // Dismiss on click-outside + Escape (capture so it wins over the surface).
  useEffect(() => {
    const onDown = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) onClose();
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("mousedown", onDown, true);
    document.addEventListener("keydown", onKey, true);
    return () => {
      document.removeEventListener("mousedown", onDown, true);
      document.removeEventListener("keydown", onKey, true);
    };
  }, [onClose]);

  return (
    <div
      ref={ref}
      data-fancy-terminal-menu=""
      role="menu"
      style={{
        position: "fixed",
        left: pos.x,
        top: pos.y,
        zIndex: 2147483000,
        minWidth: 176,
        padding: 4,
        background: "#18181b",
        border: "1px solid #3f3f46",
        borderRadius: 8,
        boxShadow: "0 10px 32px -8px rgba(0,0,0,.6)",
        color: "#e4e4e7",
        font: '13px/1.4 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif',
        userSelect: "none",
      }}
    >
      {items.map((it) =>
        it.separator ? (
          <div
            key={it.id}
            role="separator"
            style={{ height: 1, margin: "4px 6px", background: "#3f3f46" }}
          />
        ) : (
          <button
            key={it.id}
            type="button"
            role="menuitem"
            data-menu-item={it.id}
            disabled={it.disabled}
            onClick={() => {
              if (it.disabled) return;
              it.onSelect?.(ctx);
              onClose();
            }}
            onMouseEnter={(e) => {
              if (!it.disabled) e.currentTarget.style.background = "#27272a";
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.background = "transparent";
            }}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 9,
              width: "100%",
              textAlign: "left",
              padding: "6px 9px",
              border: "none",
              borderRadius: 5,
              background: "transparent",
              color: it.disabled ? "#52525b" : "inherit",
              cursor: it.disabled ? "default" : "pointer",
              font: "inherit",
            }}
          >
            <span style={{ width: 16, textAlign: "center", opacity: 0.8 }}>
              {it.icon ?? ""}
            </span>
            <span style={{ flex: 1 }}>{it.label}</span>
          </button>
        ),
      )}
    </div>
  );
}

import { useMemo, useState } from 'react';
import {
    Badge,
    Button,
    Callout,
    Card,
    cn,
    Heading,
    Modal,
    Progress,
    Text,
} from '@particle-academy/react-fancy';
import {
    QuestionRenderer,
    type AnswerValue,
    answerValueToPayload,
} from './QuestionRenderer';
import type { AnswerInput, Test, TestAttempt } from '../types';

export interface TestRunnerProps {
    test: Test;
    onSubmit: (answers: AnswerInput[]) => Promise<TestAttempt>;
    onFinished?: (attempt: TestAttempt) => void;
}

export function TestRunner({ test, onSubmit, onFinished }: TestRunnerProps) {
    const questions = useMemo(() => test.questions ?? [], [test.questions]);
    const [answers, setAnswers] = useState<Record<number, AnswerValue>>({});
    const [submitting, setSubmitting] = useState(false);
    const [result, setResult] = useState<TestAttempt | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [confirmOpen, setConfirmOpen] = useState(false);

    const answeredCount = Object.values(answers).filter(
        (a) => a !== null && a !== undefined,
    ).length;
    const percent = questions.length
        ? Math.round((answeredCount / questions.length) * 100)
        : 0;
    const allAnswered = answeredCount === questions.length && questions.length > 0;

    async function handleSubmit(): Promise<void> {
        setConfirmOpen(false);
        setSubmitting(true);
        setError(null);
        try {
            const payload: AnswerInput[] = questions.map(
                (q) => answerValueToPayload(q.id, answers[q.id] ?? null) as AnswerInput,
            );
            const attempt = await onSubmit(payload);
            setResult(attempt);
            onFinished?.(attempt);
        } catch (e) {
            const message = e instanceof Error ? e.message : String(e);
            setError(message);
        } finally {
            setSubmitting(false);
        }
    }

    if (result) {
        return <TestResult attempt={result} />;
    }

    return (
        <>
            <Card
                variant="outlined"
                padding="none"
                className="!rounded-xl !shadow-sm overflow-hidden"
            >
                <div className="px-6 py-5 border-b border-secondary-200">
                    <div className="flex items-start justify-between gap-4">
                        <div>
                            <Heading as="h1" size="xl" weight="bold">
                                {test.title}
                            </Heading>
                            {test.description && (
                                <Text className="!mt-1" color="muted">
                                    {test.description}
                                </Text>
                            )}
                        </div>
                        <div className="flex flex-col items-end gap-2">
                            {test.is_final && (
                                <Badge color="amber" variant="soft" size="md">
                                    Final exam
                                </Badge>
                            )}
                            <Text size="xs" color="muted">
                                Pass at {test.passing_score}%
                            </Text>
                        </div>
                    </div>

                    <div className="mt-4 grid gap-1.5">
                        <Progress
                            value={percent}
                            max={100}
                            color="red"
                            size="sm"
                        />
                        <div className="flex items-center justify-between">
                            <Text size="xs" color="muted">
                                {answeredCount} of {questions.length} answered
                            </Text>
                            <Text size="xs" weight="semibold" className="!text-brand">
                                {percent}%
                            </Text>
                        </div>
                    </div>
                </div>

                <div className="px-6 py-6 grid gap-5">
                    {questions.map((q, i) => (
                        <Card
                            key={q.id}
                            variant="outlined"
                            padding="md"
                            className="!rounded-lg"
                        >
                            <div className="flex items-center justify-between mb-3">
                                <Text size="xs" weight="semibold" className="uppercase tracking-wide" color="muted">
                                    Question {i + 1} of {questions.length}
                                </Text>
                                <Badge color="zinc" variant="soft" size="sm">
                                    {q.points} pt{q.points === 1 ? '' : 's'}
                                </Badge>
                            </div>
                            <QuestionRenderer
                                question={q}
                                value={answers[q.id] ?? null}
                                onChange={(next) =>
                                    setAnswers((prev) => ({ ...prev, [q.id]: next }))
                                }
                            />
                        </Card>
                    ))}
                </div>

                {error && (
                    <div className="px-6 pb-4">
                        <Callout color="red">{error}</Callout>
                    </div>
                )}

                <div className="px-6 py-4 border-t border-secondary-200 bg-secondary-50/50 flex items-center justify-between gap-3">
                    <Text size="sm" color="muted">
                        {allAnswered
                            ? "You've answered every question."
                            : `${questions.length - answeredCount} question${questions.length - answeredCount === 1 ? '' : 's'} remaining`}
                    </Text>
                    <Button
                        loading={submitting}
                        disabled={submitting || answeredCount === 0}
                        onClick={() => setConfirmOpen(true)}
                        className="!bg-brand hover:!bg-primary-600 disabled: !text-white !font-semibold !px-6 !py-2.5 !rounded-md !shadow-sm"
                    >
                        {submitting ? 'Submitting…' : 'Submit test'}
                    </Button>
                </div>
            </Card>

            <Modal open={confirmOpen} onClose={() => setConfirmOpen(false)} size="sm">
                <Card variant="flat" padding="lg">
                    <Heading as="h2" size="lg" weight="bold">
                        Submit your answers?
                    </Heading>
                    <Text color="muted" className="!mt-2">
                        {allAnswered
                            ? `You've answered all ${questions.length} questions. You can't change your answers after submitting.`
                            : `You have ${questions.length - answeredCount} unanswered question${questions.length - answeredCount === 1 ? '' : 's'}. Unanswered questions count as zero.`}
                    </Text>
                    <div className="mt-6 flex justify-end gap-3">
                        <Button
                            variant="ghost"
                            onClick={() => setConfirmOpen(false)}
                            className="hover:!text-brand !px-4 !py-2"
                        >
                            Keep working
                        </Button>
                        <Button
                            onClick={handleSubmit}
                            className="!bg-brand hover:!bg-primary-600 !text-white !font-semibold !px-5 !py-2 !rounded-md"
                        >
                            Submit
                        </Button>
                    </div>
                </Card>
            </Modal>
        </>
    );
}

function TestResult({ attempt }: { attempt: TestAttempt }) {
    const passed = attempt.passed === true;
    const pending = attempt.passed === null;
    const score = attempt.score !== null ? Number(attempt.score) : null;

    return (
        <Card
            variant="outlined"
            padding="none"
            className="!rounded-xl !shadow-sm overflow-hidden"
        >
            <div
                className={cn(
                    'px-6 py-5',
                    pending
                            ? 'bg-blue-50 dark:bg-blue-950/40'
                            : passed
                              ? 'bg-emerald-50 dark:bg-emerald-950/40'
                              : 'bg-red-50 dark:bg-red-950/40',
                )}
            >
                <div className="flex items-center gap-3">
                    <div
                        className={cn(
                            'flex h-12 w-12 items-center justify-center rounded-full text-xl font-bold',
                            pending
                                ? 'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200'
                                : passed
                                ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900 dark:text-emerald-200'
                                : 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200',
                        )}
                    >
                        {pending ? '…' : passed ? '✓' : '✕'}
                    </div>
                    <div>
                        <Heading as="h2" size="xl" weight="bold">
                            {pending ? 'Awaiting grading' : passed ? 'You passed!' : 'Did not pass'}
                        </Heading>
                        <Text className="!mt-0.5" color="muted">
                            {pending
                                ? 'Some answers require manual review.'
                                : passed
                                ? 'Nice work. Your certificate is being issued.'
                                : 'Review the material and try again.'}
                        </Text>
                    </div>
                </div>
            </div>

            <div className="px-6 py-5 grid sm:grid-cols-3 gap-4">
                <Stat label="Score" value={score !== null ? `${score}%` : '—'} highlight />
                <Stat
                    label="Points awarded"
                    value={
                        attempt.points_awarded !== null && attempt.max_score !== null
                            ? `${attempt.points_awarded} / ${attempt.max_score}`
                            : '—'
                    }
                />
                <Stat label="Attempt" value={`#${attempt.attempt_number}`} />
            </div>
        </Card>
    );
}

function Stat({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
    return (
        <div className="rounded-lg border border-secondary-200 bg-secondary-50/50 px-4 py-3">
            <Text size="xs" weight="semibold" className="uppercase tracking-wide" color="muted">
                {label}
            </Text>
            <div
                className={cn(
                    'mt-1 text-2xl font-bold',
                    highlight ? 'text-brand' : 'text-secondary-900',
                )}
            >
                {value}
            </div>
        </div>
    );
}

import {
    CheckboxGroup,
    RadioGroup,
    Text,
    Textarea,
} from '@particle-academy/react-fancy';
import type { Question } from '../types';

export type AnswerValue =
    | { kind: 'option_id'; value: number }
    | { kind: 'option_ids'; value: number[] }
    | { kind: 'text'; value: string }
    | null;

export interface QuestionRendererProps {
    question: Question;
    value: AnswerValue;
    onChange: (next: AnswerValue) => void;
    disabled?: boolean;
}

export function QuestionRenderer({
    question,
    value,
    onChange,
    disabled,
}: QuestionRendererProps) {
    const options = question.options ?? [];

    if (question.type === 'multiple_choice' || question.type === 'true_false') {
        const selected =
            value?.kind === 'option_id' ? String(value.value) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <RadioGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_id', value: Number(next) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    if (question.type === 'multiple_select') {
        const selected =
            value?.kind === 'option_ids' ? value.value.map(String) : undefined;

        return (
            <div className="grid gap-3">
                <Text weight="semibold" className="!text-base">
                    {question.prompt}
                </Text>
                <Text size="sm" color="muted">
                    Select all that apply.
                </Text>
                <CheckboxGroup<string>
                    name={`q-${question.id}`}
                    list={options.map((o) => ({ value: String(o.id), label: o.label }))}
                    value={selected}
                    onValueChange={(next) =>
                        onChange({ kind: 'option_ids', value: next.map(Number) })
                    }
                    disabled={disabled}
                />
            </div>
        );
    }

    // short_answer
    const text = value?.kind === 'text' ? value.value : '';
    return (
        <div className="grid gap-3">
            <Text weight="semibold" className="!text-base">
                {question.prompt}
            </Text>
            <Textarea
                value={text}
                onChange={(e) =>
                    onChange({
                        kind: 'text',
                        value: (e.target as HTMLTextAreaElement).value,
                    })
                }
                disabled={disabled}
                rows={4}
                placeholder="Type your answer here…"
            />
        </div>
    );
}

export function answerValueToPayload(
    questionId: number,
    value: AnswerValue,
): { question_id: number; answer: unknown } {
    if (!value) return { question_id: questionId, answer: null };
    switch (value.kind) {
        case 'option_id':
            return { question_id: questionId, answer: { option_id: value.value } };
        case 'option_ids':
            return { question_id: questionId, answer: { option_ids: value.value } };
        case 'text':
            return { question_id: questionId, answer: { text: value.value } };
    }
}

import { forwardRef } from "react";
import { cn } from "../../utils/cn";
