import { useId, type CSSProperties } from "react";
import { ContentRenderer, Editor } from "@particle-academy/react-fancy";
import type { TextElement, Theme } from "../../../types";
import { resolveTheme } from "../../../theme/theme-utils";
import { splitParagraphs, textBlocks, type ParaReveal } from "../../../utils/builds";
import { buildEnterStyle } from "../../Slide/builds-style";
import { PRESENTATION_EDITOR_ACTIONS, normalizeSlideMarkdown } from "./editor-preset";

export interface TextElementRendererProps {
    element: TextElement;
    theme?: Theme;
    /** Rendered slide width in px (for font-size scaling). */
    slideWidthPx: number;
    /**
     * Edit mode — when true, the element is potentially editable.
     * The textarea actually becomes pointer-interactive only when both
     * `editing` and `selected` are true, so the first click on an
     * unselected text element selects it (handled by the parent Slide)
     * rather than landing on the textarea.
     */
    editing?: boolean;
    /** Element is selected — gates whether the textarea grabs pointer events. */
    selected?: boolean;
    /** Called when the user edits the content (only fires when the textarea is focusable). */
    onContentChange?: (content: string) => void;
    /**
     * By-paragraph reveal state, set by `<Slide>` in viewer mode when this text
     * element has a `byParagraph` animation. When present, the renderer splits
     * `content` on `"\n"` and shows only the first `revealed` paragraphs,
     * animating the one at `firingParaIndex`. Ignored in editing mode (the full
     * text always renders so authors can position/edit it).
     */
    paraReveal?: ParaReveal;
}

/**
 * Renderer for `text` elements. Three formats:
 *
 *   - `"markdown"` (default) — parsed via react-fancy's ContentRenderer.
 *     Bullets, bold/italic, code spans, links, headings.
 *   - `"html"` — parsed sanitized HTML via ContentRenderer's html path.
 *   - `"plain"` — raw text rendered into a single block; preserves newlines
 *     via `white-space: pre-wrap`.
 *
 * In editing mode + when the element is selected, the renderer swaps to a
 * textarea showing the raw source. Edits flow back via `onContentChange`.
 */
export function TextElementRenderer({
    element,
    theme,
    slideWidthPx,
    editing = false,
    selected = false,
    onContentChange,
    paraReveal,
}: TextElementRendererProps) {
    const t = resolveTheme(theme);
    const style = element.style ?? {};
    const designWidth = t.slideWidth ?? 1920;
    const scale = slideWidthPx / designWidth;
    const format = element.format ?? "markdown";
    const scopeId = useId();

    const css: CSSProperties = {
        fontFamily: style.fontFamily ?? t.fonts?.body,
        fontSize: `${(style.fontSize ?? 28) * scale}px`,
        fontWeight: weight(style.weight) ?? 400,
        fontStyle: style.italic ? "italic" : "normal",
        textDecoration: style.underline ? "underline" : "none",
        color: style.color ?? t.colors?.text,
        textAlign: style.align ?? "left",
        lineHeight: style.lineHeight ?? 1.4,
        display: "flex",
        flexDirection: "column",
        justifyContent:
            style.verticalAlign === "middle" ? "center" : style.verticalAlign === "bottom" ? "flex-end" : "flex-start",
        width: "100%",
        height: "100%",
        padding: 0,
        margin: 0,
        outline: "none",
        background: "transparent",
        whiteSpace: format === "plain" ? "pre-wrap" : "normal",
        wordBreak: "break-word",
        overflow: "hidden",
    };

    // Edit mode is gated by selection: an unselected element in the editor
    // still shows the parsed markdown so the user sees the real layout.
    // Clicking selects → the react-fancy Editor appears, a WYSIWYG rich-text
    // surface tuned for presentations (bold / italic / heading / bullets).
    // Edits emit markdown, normalized to the line-based paragraph model the
    // slide content + dark-slide writer commit to. The Editor is keyed by the
    // element id because it loads its value once on mount (it's uncontrolled
    // after that), so selecting a different element remounts it with the right
    // content. Scoped CSS strips the Editor's card chrome and matches the
    // element's scaled typography so editing looks like the live slide.
    if (editing && selected) {
        const fontPx = Math.round((style.fontSize ?? 28) * scale);
        const lh = style.lineHeight ?? 1.4;
        const editScope = scopeId;
        return (
            <div
                data-fs-edit-scope={editScope}
                style={{
                    width: "100%",
                    height: "100%",
                    pointerEvents: "auto",
                    cursor: "text",
                    textAlign: style.align ?? "left",
                    color: style.color ?? t.colors?.text,
                    fontFamily: style.fontFamily ?? t.fonts?.body,
                }}
                // Keep editing interactions (toolbar clicks, text selection) from
                // bubbling to the Slide's element drag / deselect handlers.
                onPointerDown={(e) => e.stopPropagation()}
            >
                <style>{`
                    [data-fs-edit-scope="${editScope}"] [data-react-fancy-editor] {
                        border: none; background: transparent; border-radius: 0;
                        height: 100%; display: flex; flex-direction: column; overflow: hidden;
                    }
                    [data-fs-edit-scope="${editScope}"] [data-react-fancy-editor-toolbar] {
                        background: rgba(244,244,245,0.85); border-radius: 6px 6px 0 0;
                        padding: 2px 4px;
                    }
                    [data-fs-edit-scope="${editScope}"] [data-react-fancy-editor-content] {
                        flex: 1; min-height: 0; padding: 4px 2px; overflow: auto;
                        font-size: ${fontPx}px; line-height: ${lh};
                    }
                    [data-fs-edit-scope="${editScope}"] [data-react-fancy-editor-content] :is(p, ul, ol, li) { font-size: inherit; margin: 0; }
                    [data-fs-edit-scope="${editScope}"] [data-react-fancy-editor-content] :where(p, li) + :where(p, li, ul, ol) { margin-top: 0.4em; }
                    [data-fs-edit-scope="${editScope}"] [data-react-fancy-editor-content] h1 { font-size: 1.6em; font-weight: 700; margin: 0; }
                    [data-fs-edit-scope="${editScope}"] [data-react-fancy-editor-content] h2 { font-size: 1.35em; font-weight: 700; margin: 0; }
                    [data-fs-edit-scope="${editScope}"] [data-react-fancy-editor-content] h3 { font-size: 1.15em; font-weight: 600; margin: 0; }
                `}</style>
                <Editor
                    key={element.id}
                    value={element.content}
                    onChange={(md) => onContentChange?.(normalizeSlideMarkdown(md))}
                    outputFormat="markdown"
                    lineSpacing={lh}
                >
                    <Editor.Toolbar actions={PRESENTATION_EDITOR_ACTIONS} />
                    <Editor.Content />
                </Editor>
            </div>
        );
    }

    // Scope the ContentRenderer's prose styles so element-level typography
    // (fontSize, weight, align) wins over the global prose CSS. We render a
    // tiny inline style block that targets only this instance via the
    // generated useId scope.
    //
    // CRITICAL: ContentRenderer wraps its content in `text-sm` plus per-tag
    // Tailwind utilities (`[&_h1]:text-2xl`, etc). Those have higher
    // specificity than the inline `fontSize` we set on the wrapper, so
    // without forced overrides the slide text ignores `style.fontSize` AND
    // ignores the slide's resolution scaling — that's why thumbnails were
    // rendering text at ~14px instead of (fontSize × scale)px.
    //
    // We double the attribute-selector to outrank Tailwind's
    // `[&_h2]:text-xl`-style utilities, and re-express heading sizes in
    // `em` so they remain proportional as the slide scales.
    const proseScope = `[data-fs-text-scope="${scopeId}"]`;
    const doubleScope = `${proseScope}${proseScope}`;
    const proseStyle = (
        <style>{`
            ${proseScope} > div { width: 100%; height: 100%; font-size: inherit; }
            ${doubleScope} :is(p, ul, ol, li, blockquote, h1, h2, h3, h4, h5, h6, pre, code, strong, em, a) {
                font-size: inherit;
            }
            ${doubleScope} h1 { font-size: 1.6em; font-weight: 700; }
            ${doubleScope} h2 { font-size: 1.35em; font-weight: 700; }
            ${doubleScope} h3 { font-size: 1.15em; font-weight: 600; }
            ${proseScope} :where(p, ul, ol, h1, h2, h3, h4, h5, h6, pre, blockquote) {
                margin: 0;
                padding: 0;
            }
            ${proseScope} :where(p, li) + :where(p, li, ul, ol) { margin-top: 0.4em; }
            ${proseScope} > [data-fancy-slides-paragraph] + [data-fancy-slides-paragraph]:not(:empty) { margin-top: 0.4em; }
            ${proseScope} :where(ul, ol) { padding-left: 1.4em; }
            ${proseScope} :where(strong) { font-weight: ${Math.max(700, weight(style.weight) ?? 400 + 200)}; }
            ${proseScope} :where(a) { color: inherit; text-decoration: underline; }
            ${proseScope} :where(code) { font-family: ${t.fonts?.mono ?? "monospace"}; }
        `}</style>
    );

    // Render one chunk of content in the element's format. Reused for the whole
    // element and for each paragraph in a by-paragraph build.
    const renderChunk = (content: string) =>
        format === "plain" ? content : <ContentRenderer value={content} format={format === "html" ? "html" : "markdown"} />;

    // ─── By-paragraph build reveal ──────────────────────────────────────────
    // When `<Slide>` hands us a paraReveal, split the content and show only the
    // first `revealed` paragraphs, animating the one that just fired. We always
    // render the prose scope wrapper so markdown/html paragraphs keep their
    // typography. Each line of markdown renders through the same path, so a
    // bullet line ("- …") renders as its own list item.
    if (paraReveal) {
        const paras = splitParagraphs(element.content);
        return (
            <div data-fs-text-scope={scopeId} style={css}>
                {proseStyle}
                {paras.map((para, i) => {
                    if (i >= paraReveal.revealed) return null; // not yet built
                    const firing = i === paraReveal.firingParaIndex && !!element.animation;
                    const enter = firing
                        ? buildEnterStyle(element.animation!, element.animation!.delay ?? 0)
                        : null;
                    return (
                        <div
                            key={i}
                            className={firing ? "fs-build-enter" : undefined}
                            style={{ whiteSpace: format === "plain" ? "pre-wrap" : "normal", ...enter }}
                            data-fancy-slides-paragraph={i}
                        >
                            {renderChunk(para)}
                        </div>
                    );
                })}
            </div>
        );
    }

    if (format === "plain") {
        return <div style={css}>{element.content}</div>;
    }

    // ─── Static (non-build) render ──────────────────────────────────────────
    // Render line-by-line, mirroring the by-paragraph path above, so a single
    // `"\n"` is a hard line/paragraph break — the canonical line-based model the
    // rest of the system commits to (`splitParagraphs`, `normalizeSlideMarkdown`,
    // dark-slide's `explode("\n", …)` pptx export). Passing the whole multi-line
    // string to a markdown renderer would instead treat a lone `"\n"` as a
    // CommonMark soft break (a space), collapsing bullet lists and
    // "label + description" blocks onto one wrapped line.
    const lines = textBlocks(element.content, format);
    return (
        <div data-fs-text-scope={scopeId} style={css}>
            {proseStyle}
            {lines.map((line, i) => (
                <div key={i} data-fancy-slides-paragraph={i}>
                    {renderChunk(line)}
                </div>
            ))}
        </div>
    );
}

function weight(w: "normal" | "medium" | "semibold" | "bold" | number | undefined): number | undefined {
    if (typeof w === "number") return w;
    if (w === "normal") return 400;
    if (w === "medium") return 500;
    if (w === "semibold") return 600;
    if (w === "bold") return 700;
    return undefined;
}

export { TextElementRenderer } from "./TextElement";
export type { TextElementRendererProps } from "./TextElement";
export { PRESENTATION_EDITOR_ACTIONS, normalizeSlideMarkdown } from "./editor-preset";

import { forwardRef, useState } from "react";
import { cn } from "../../utils/cn";
import type { TimeGridProps, TimeGridTone } from "./TimeGrid.types";

const TONE_CLASSES: Record<TimeGridTone, string> = {
  violet: "bg-violet-500 hover:bg-violet-600",
  emerald: "bg-emerald-500 hover:bg-emerald-600",
  sky: "bg-sky-500 hover:bg-sky-600",
  rose: "bg-rose-500 hover:bg-rose-600",
  amber: "bg-amber-500 hover:bg-amber-600",
  indigo: "bg-indigo-500 hover:bg-indigo-600",
  blue: "bg-blue-500 hover:bg-blue-600",
  zinc: "bg-zinc-500 hover:bg-zinc-600",
};

const OFF_CLASSES =
  "bg-zinc-100 hover:bg-zinc-200 dark:bg-zinc-800 dark:hover:bg-zinc-700";

export const TimeGrid = forwardRef<HTMLDivElement, TimeGridProps>(
  (
    {
      rows,
      cols,
      value,
      onChange,
      toneOn = "violet",
      cellWidth = 20,
      cellHeight = 16,
      sparseColLabels = true,
      toggleStripsOnHeaderClick = true,
      ariaCell,
      cellId,
      className,
    },
    ref,
  ) => {
    const [drag, setDrag] = useState<boolean | null>(null);

    const setCell = (r: number, c: number, v: boolean) => {
      if (value[r]?.[c] === v) return;
      const next = value.map((row) => row.slice());
      next[r][c] = v;
      onChange(next);
    };

    const toggleRow = (r: number) => {
      if (!toggleStripsOnHeaderClick) return;
      const all = value[r].every(Boolean);
      const next = value.map((row) => row.slice());
      for (let c = 0; c < cols.length; c++) next[r][c] = !all;
      onChange(next);
    };

    const toggleCol = (c: number) => {
      if (!toggleStripsOnHeaderClick) return;
      const all = value.every((row) => row[c]);
      const next = value.map((row) => row.slice());
      for (let r = 0; r < rows.length; r++) next[r][c] = !all;
      onChange(next);
    };

    const colStep = Math.max(1, Math.floor(cols.length / 6));
    const onTone = TONE_CLASSES[toneOn];

    return (
      <div
        ref={ref}
        data-react-fancy-timegrid=""
        className={cn(
          "select-none overflow-x-auto",
          className,
        )}
        onMouseLeave={() => setDrag(null)}
        onMouseUp={() => setDrag(null)}
      >
        <table className="text-[10px]">
          <thead>
            <tr>
              <th />
              {cols.map((label, c) => (
                <th
                  key={c}
                  onClick={() => toggleCol(c)}
                  style={{ width: cellWidth }}
                  data-react-fancy-timegrid-col={c}
                  className={cn(
                    "text-zinc-400",
                    toggleStripsOnHeaderClick &&
                      "cursor-pointer hover:text-zinc-700 dark:hover:text-zinc-200",
                  )}
                >
                  {sparseColLabels ? (c % colStep === 0 ? label : "") : label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((label, r) => (
              <tr key={r}>
                <th
                  onClick={() => toggleRow(r)}
                  data-react-fancy-timegrid-row={r}
                  className={cn(
                    "pr-1 text-right font-medium text-zinc-500",
                    toggleStripsOnHeaderClick &&
                      "cursor-pointer hover:text-zinc-800 dark:hover:text-zinc-200",
                  )}
                >
                  {label}
                </th>
                {cols.map((_, c) => {
                  const on = value[r]?.[c] ?? false;
                  return (
                    <td key={c} className="p-px">
                      <button
                        type="button"
                        onMouseDown={() => {
                          const v = !on;
                          setDrag(v);
                          setCell(r, c, v);
                        }}
                        onMouseEnter={() => drag !== null && setCell(r, c, drag)}
                        style={{ width: cellWidth, height: cellHeight }}
                        data-react-fancy-timegrid-cell={
                          cellId ? cellId(r, c) : `${r}:${c}`
                        }
                        aria-pressed={on}
                        aria-label={
                          ariaCell
                            ? ariaCell(r, c, on)
                            : `${rows[r]} ${cols[c]} ${on ? "on" : "off"}`
                        }
                        className={cn(
                          "block rounded-sm transition",
                          on ? onTone : OFF_CLASSES,
                        )}
                      />
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  },
);

TimeGrid.displayName = "TimeGrid";

/**
 * Subset of palette colors the TimeGrid offers for the "cell-on" tone —
 * small enough to keep the compiled CSS tight, broad enough to cover most
 * use cases.
 */
export type TimeGridTone =
  | "violet"
  | "emerald"
  | "sky"
  | "rose"
  | "amber"
  | "indigo"
  | "blue"
  | "zinc";

export interface TimeGridProps {
  /** Row labels, one per row in `value` (e.g. ["Sun","Mon",…]). */
  rows: string[];
  /** Column labels, one per column in `value` (e.g. ["0","1",…,"23"]). */
  cols: string[];
  /**
   * Controlled cell state. Must be a rectangular `rows.length × cols.length`
   * matrix of booleans. The component never mutates it — every change
   * produces a new array passed to `onChange`.
   */
  value: boolean[][];
  /** Called with the next matrix whenever a cell, row, or column toggles. */
  onChange: (next: boolean[][]) => void;

  /** Cell-on tone. Default `"violet"`. */
  toneOn?: TimeGridTone;
  /** Cell width in px. Default `20`. */
  cellWidth?: number;
  /** Cell height in px. Default `16`. */
  cellHeight?: number;
  /**
   * If true (default), only every Nth column label is rendered to keep the
   * top axis legible at small `cellWidth`. Set false to show all labels.
   */
  sparseColLabels?: boolean;
  /** If true (default), clicking a row/column header toggles that strip. */
  toggleStripsOnHeaderClick?: boolean;

  /**
   * Optional accessible label per cell. Default produces
   * `${rows[r]} ${cols[c]} on|off`. Override for richer context
   * (e.g. include unit: `${rows[r]} ${cols[c]}:00 ${on ? "on" : "off"}`).
   */
  ariaCell?: (rowIdx: number, colIdx: number, on: boolean) => string;

  /**
   * Stable per-cell identifier. Emitted as `data-react-fancy-timegrid-cell`
   * on the button so MCP bridges can address a specific cell from a tool
   * call without DOM walking. Default `${row}:${col}`.
   */
  cellId?: (rowIdx: number, colIdx: number) => string;

  /** Additional CSS classes on the outer scroll container. */
  className?: string;
}

import { forwardRef, useCallback } from "react";
import { ChevronUp, ChevronDown } from "lucide-react";
import { cn } from "../../utils/cn";
import { useControllableState } from "../../hooks/use-controllable-state";
import { useFieldMode } from "../inputs/mode/FieldMode.context";
import { useInlineEdit } from "../inputs/mode/useInlineEdit";
import type { TimePickerProps } from "./TimePicker.types";

function pad(n: number): string {
  return n.toString().padStart(2, "0");
}

function parseTime(val: string): { hours: number; minutes: number } {
  const [h, m] = val.split(":").map(Number);
  return { hours: h || 0, minutes: m || 0 };
}

export const TimePicker = forwardRef<HTMLDivElement, TimePickerProps>(
  function TimePicker(
    {
      value: controlledValue,
      defaultValue = "12:00",
      onChange,
      format = "12h",
      minuteStep = 1,
      disabled = false,
      className,
      mode,
    },
    ref,
  ) {
    const [value, setValue] = useControllableState(
      controlledValue,
      defaultValue,
      onChange,
    );
    const resolvedMode = useFieldMode(mode);
    const { showControl, interactive, enterEdit, exitEdit } = useInlineEdit(resolvedMode, disabled);

    const { hours: h24, minutes } = parseTime(value);
    const isPM = h24 >= 12;
    const displayHour = format === "12h" ? (h24 % 12 || 12) : h24;

    // These four MUST stay above the view-mode early return below.
    //
    // They used to sit after it, which meant view mode ran three hooks and edit
    // mode ran seven. Clicking "Click to edit" flipped `showControl` and React
    // hit a different hook count on the very next render — the classic
    // desync, which surfaces as a crash from inside React naming none of this
    // code. Nothing caught it because no test ever crossed the boundary.
    const updateTime = useCallback(
      (hours: number, mins: number) => {
        setValue(`${pad(hours)}:${pad(mins)}`);
      },
      [setValue],
    );

    const changeHour = useCallback(
      (delta: number) => {
        const newHour = (h24 + delta + 24) % 24;
        updateTime(newHour, minutes);
      },
      [h24, minutes, updateTime],
    );

    const changeMinute = useCallback(
      (delta: number) => {
        const newMin = (minutes + delta + 60) % 60;
        updateTime(h24, newMin);
      },
      [h24, minutes, updateTime],
    );

    const toggleAmPm = useCallback(() => {
      updateTime((h24 + 12) % 24, minutes);
    }, [h24, minutes, updateTime]);

    if (!showControl) {
      const formatted =
        format === "12h"
          ? `${pad(displayHour)}:${pad(minutes)} ${isPM ? "PM" : "AM"}`
          : `${pad(displayHour)}:${pad(minutes)}`;
      return (
        <div
          data-react-fancy-time-picker=""
          data-mode="view"
          ref={ref}
          role={interactive ? "button" : undefined}
          tabIndex={interactive ? 0 : undefined}
          title={interactive ? "Click to edit" : undefined}
          onClick={interactive ? enterEdit : undefined}
          onKeyDown={
            interactive
              ? (e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    enterEdit();
                  }
                }
              : undefined
          }
          className={cn(
            "text-sm font-medium tabular-nums text-zinc-900 dark:text-zinc-100",
            interactive &&
              "cursor-pointer rounded-md outline-none transition-colors hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-blue-500/40 dark:hover:bg-zinc-800",
            className,
          )}
        >
          {formatted}
        </div>
      );
    }

    const spinBtnClass =
      "flex h-7 w-full items-center justify-center rounded text-zinc-400 transition-colors hover:bg-zinc-100 hover:text-zinc-600 dark:hover:bg-zinc-800 dark:hover:text-zinc-300 disabled:opacity-50";
    const displayClass =
      "flex h-10 w-12 items-center justify-center text-lg font-medium tabular-nums";

    return (
      <div
        data-react-fancy-time-picker=""
        ref={ref}
        onBlur={(e) => {
          if (interactive && !e.currentTarget.contains(e.relatedTarget as Node)) exitEdit();
        }}
        className={cn(
          "inline-flex items-center gap-1 rounded-lg border border-zinc-200 bg-white p-2 dark:border-zinc-700 dark:bg-zinc-900",
          disabled && "opacity-50",
          className,
        )}
      >
        {/* Hour column */}
        <div className="flex flex-col items-center">
          <button type="button" autoFocus={interactive} onClick={() => changeHour(1)} disabled={disabled} className={spinBtnClass} aria-label="Increase hour">
            <ChevronUp size={14} />
          </button>
          <div className={displayClass}>{pad(displayHour)}</div>
          <button type="button" onClick={() => changeHour(-1)} disabled={disabled} className={spinBtnClass} aria-label="Decrease hour">
            <ChevronDown size={14} />
          </button>
        </div>

        <span className="text-lg text-zinc-400">:</span>

        {/* Minute column */}
        <div className="flex flex-col items-center">
          <button type="button" onClick={() => changeMinute(minuteStep)} disabled={disabled} className={spinBtnClass} aria-label="Increase minute">
            <ChevronUp size={14} />
          </button>
          <div className={displayClass}>{pad(minutes)}</div>
          <button type="button" onClick={() => changeMinute(-minuteStep)} disabled={disabled} className={spinBtnClass} aria-label="Decrease minute">
            <ChevronDown size={14} />
          </button>
        </div>

        {/* AM/PM toggle */}
        {format === "12h" && (
          <button
            type="button"
            onClick={toggleAmPm}
            disabled={disabled}
            className="ml-1 rounded-lg bg-zinc-100 px-2 py-1 text-sm font-medium transition-colors hover:bg-zinc-200 dark:bg-zinc-800 dark:hover:bg-zinc-700"
          >
            {isPM ? "PM" : "AM"}
          </button>
        )}
      </div>
    );
  },
);

