import { useCallback, useMemo, useRef, useState } from "react";
import { cn } from "../../utils/cn";
import { Portal } from "../Portal";
import { ToastContext } from "./Toast.context";
import { ToastItem } from "./ToastItem";
import type { ToastData, ToastProviderProps } from "./Toast.types";

const POSITION_STYLES = {
  "top-right": "top-4 right-4",
  "top-left": "top-4 left-4",
  "bottom-right": "bottom-4 right-4",
  "bottom-left": "bottom-4 left-4",
} as const;

function ToastProvider({
  children,
  position = "bottom-right",
  maxToasts = 5,
}: ToastProviderProps) {
  const [toasts, setToasts] = useState<ToastData[]>([]);
  const idCounter = useRef(0);

  const toast = useCallback(
    (data: Omit<ToastData, "id">) => {
      const id = `toast-${++idCounter.current}`;
      setToasts((prev) => [...prev.slice(-(maxToasts - 1)), { ...data, id }]);
      return id;
    },
    [maxToasts],
  );

  const dismiss = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const ctx = useMemo(() => ({ toasts, toast, dismiss }), [toasts, toast, dismiss]);

  return (
    <ToastContext.Provider value={ctx}>
      {children}
      <Portal>
        <div
          data-react-fancy-toast=""
          className={cn(
            "fixed z-[100] flex flex-col gap-2 pointer-events-none",
            POSITION_STYLES[position],
          )}
        >
          {toasts.map((t) => (
            <ToastItem key={t.id} data={t} onDismiss={dismiss} />
          ))}
        </div>
      </Portal>
    </ToastContext.Provider>
  );
}

export const Toast = {
  Provider: ToastProvider,
};

import type { ReactNode } from "react";

export type ToastVariant = "default" | "success" | "error" | "warning" | "info";
export type ToastPosition =
  | "top-right"
  | "top-left"
  | "bottom-right"
  | "bottom-left";

/** A single control offered inside a toast — typically "Undo". */
export interface ToastAction {
  label: string;
  onClick: () => void;
}

export interface ToastData {
  id: string;
  title: string;
  description?: string;
  variant?: ToastVariant;
  /**
   * Auto-dismiss delay in ms. `0` (or less) never dismisses.
   *
   * Defaults to 5000 — but to 0 when `action` is set, because expiring the
   * offer is the same bug as making undo a timeout. Pass a number to opt back in.
   */
  duration?: number;
  /**
   * An action the toast offers, rendered as a real button.
   *
   * Undo has to be a control rather than a countdown: a timeout makes the safety
   * of an action depend on how fast someone reads, which is worst for exactly
   * the people who need undo most.
   */
  action?: ToastAction;
}

export interface ToastContextValue {
  toasts: ToastData[];
  toast: (data: Omit<ToastData, "id">) => string;
  dismiss: (id: string) => void;
}

export interface ToastProviderProps {
  children: ReactNode;
  position?: ToastPosition;
  maxToasts?: number;
}

export interface ToastItemProps {
  data: ToastData;
  onDismiss: (id: string) => void;
}

import { useEffect } from "react";
import { AlertTriangle, Check, Info, X, XCircle } from "lucide-react";
import { cn } from "../../utils/cn";
import type { ToastItemProps } from "./Toast.types";

const VARIANT_STYLES = {
  default:
    "border-zinc-200 bg-white dark:border-zinc-700 dark:bg-zinc-900",
  success:
    "border-emerald-200 bg-emerald-50 dark:border-emerald-800 dark:bg-emerald-950",
  error:
    "border-red-200 bg-red-50 dark:border-red-800 dark:bg-red-950",
  warning:
    "border-amber-200 bg-amber-50 dark:border-amber-800 dark:bg-amber-950",
  info: "border-blue-200 bg-blue-50 dark:border-blue-800 dark:bg-blue-950",
} as const;

const VARIANT_ICON_COLORS = {
  default: "text-zinc-400",
  success: "text-emerald-500",
  error: "text-red-500",
  warning: "text-amber-500",
  info: "text-blue-500",
} as const;

export function ToastItem({ data, onDismiss }: ToastItemProps) {
  const { id, title, description, variant = "default", action } = data;
  // An action toast does not expire by default.
  const duration = data.duration ?? (action ? 0 : 5000);

  useEffect(() => {
    if (duration <= 0) return;
    const timer = setTimeout(() => onDismiss(id), duration);
    return () => clearTimeout(timer);
  }, [id, duration, onDismiss]);

  return (
    <div
      data-react-fancy-toast-item=""
      role="alert"
      // Scoped to the toast rather than the document: a global Escape handler
      // would fight whatever modal or drawer is already listening.
      onKeyDown={(e) => {
        if (e.key === "Escape") onDismiss(id);
      }}
      className={cn(
        "fancy-toast-in pointer-events-auto w-80 rounded-xl border p-4 shadow-lg",
        VARIANT_STYLES[variant],
      )}
    >
      <div className="flex items-start gap-3">
        <div className={cn("mt-0.5 shrink-0", VARIANT_ICON_COLORS[variant])}>
          {variant === "success" && <Check size={16} />}
          {variant === "error" && <XCircle size={16} />}
          {variant === "warning" && <AlertTriangle size={16} />}
          {variant === "info" && <Info size={16} />}
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium text-zinc-900 dark:text-zinc-100">{title}</p>
          {description && (
            <p className="mt-1 text-xs text-zinc-500 dark:text-zinc-400">
              {description}
            </p>
          )}
        </div>
        {action && (
          <button
            type="button"
            onClick={() => {
              action.onClick();
              // The offer is consumed; leaving it up invites undoing an
              // already-undone action.
              onDismiss(id);
            }}
            className="shrink-0 self-center rounded-md px-2 py-1 text-xs font-medium text-zinc-700 underline-offset-2 transition-colors hover:bg-zinc-100 hover:underline dark:text-zinc-200 dark:hover:bg-zinc-800"
          >
            {action.label}
          </button>
        )}
        <button
          type="button"
          onClick={() => onDismiss(id)}
          className="shrink-0 rounded p-0.5 text-zinc-400 transition-colors hover:text-zinc-600 dark:hover:text-zinc-300"
          aria-label="Dismiss"
        >
          <X size={14} />
        </button>
      </div>
    </div>
  );
}

