import { Marked } from "marked";
import { markedTerminal } from "marked-terminal";

// marked-terminal's DefinitelyTyped signature still models the pre-token
// renderer API although v7 supports marked 15 at runtime.
const parser = new Marked();
parser.use(markedTerminal({ reflowText: true, tab: 2 }) as never);

// C0 control codes we keep: TAB (9), LF (10), CR (13). Everything else in
// 0x00-0x1F, plus DEL (0x7F), is stripped from untrusted markdown before it
// reaches the terminal. Critically this includes ESC (27) — ESC begins every
// ANSI / OSC / CSI escape sequence, so leaving it in would let agent replies or
// tool output carry OSC52 clipboard writes, OSC8 hyperlink spoofs, and CSI
// buffer overwrites straight to the user's terminal. Expressed as a codepoint
// filter (not a regex character class) so the pattern carries no invisible
// control characters itself — the split-range class that predated this let ESC
// slip through exactly because the gap was easy to miss.
const KEEP_CONTROL = new Set([9, 10, 13]);

function stripControlChars(source: string): string {
  let out = "";
  for (const ch of source) {
    const cp = ch.codePointAt(0) ?? 0;
    const isControl = cp <= 0x1f || cp === 0x7f;
    if (!isControl || KEEP_CONTROL.has(cp)) {
      out += ch;
    }
  }
  return out;
}

export function renderMarkdown(source: string): string {
  const result = parser.parse(stripControlChars(source));
  return String(result).trimEnd();
}

import { useCallback } from "react";
import { useForm as inertiaUseForm } from "@inertiajs/react";

/**
 * Per-field bridge returned by `useFancyForm().field(name)`. Shaped to
 * drop directly into react-fancy form components without further
 * wiring.
 */
export interface FancyFieldBridge<T = unknown> {
  /** Pass to `<Input value={...} />` — current field value (string). */
  value: T;
  /** Pass to `<Input onChange={...} />`. Accepts the React event *or* a raw value (Select, Switch). */
  onChange: (e: React.ChangeEvent<HTMLInputElement> | T) => void;
  /** Pass to `<Input error={...} />` — last server validation error for this field. */
  error?: string;
  /** True while a submit is in flight. */
  loading?: boolean;
  /** Stable name attribute. */
  name: string;
}

/**
 * Bridge type returned by useFancyForm. Wraps Inertia's `useForm()` and
 * adds a `field(name)` helper that returns props ready to spread into
 * react-fancy's `<Input>`, `<Select>`, `<Switch>`, `<Textarea>`, etc.
 */
export interface FancyFormBridge<TData extends Record<string, unknown>> {
  data: TData;
  setData: <K extends keyof TData>(key: K, value: TData[K]) => void;
  errors: Partial<Record<keyof TData, string>>;
  processing: boolean;

  /**
   * Returns `{ value, onChange, error, loading, name }` for a field.
   * `onChange` accepts both a React change event (native input/textarea)
   * and a raw value (Select/Switch/MultiSwitch which pass the new value
   * directly).
   */
  field<K extends keyof TData & string>(name: K): FancyFieldBridge<TData[K]>;

  /** Forwarded from Inertia's useForm. */
  submit: (method: string, url: string, options?: object) => void;
  post: (url: string, options?: object) => void;
  put: (url: string, options?: object) => void;
  patch: (url: string, options?: object) => void;
  delete: (url: string, options?: object) => void;
  reset: (...fields: Array<keyof TData>) => void;
  clearErrors: (...fields: Array<keyof TData>) => void;
}

/**
 * Inertia's `useForm()` shape (loose typing — we don't import @inertiajs
 * statically since it's an optional peer when fancy-inertia is used
 * outside of Inertia for code-sharing reasons).
 */
type InertiaForm<T> = {
  data: T;
  setData: (key: keyof T, value: unknown) => void;
  errors: Partial<Record<keyof T, string>>;
  processing: boolean;
  submit: (method: string, url: string, options?: object) => void;
  post: (url: string, options?: object) => void;
  put: (url: string, options?: object) => void;
  patch: (url: string, options?: object) => void;
  delete: (url: string, options?: object) => void;
  reset: (...fields: Array<keyof T>) => void;
  clearErrors: (...fields: Array<keyof T>) => void;
};

/**
 * Wraps Inertia's `useForm()` so each field can be wired into react-fancy
 * inputs in one line:
 *
 *   const form = useFancyForm({ name: "", email: "" });
 *   <Input {...form.field("name")} placeholder="Name" />
 *   <Input {...form.field("email")} placeholder="Email" />
 *   <Button onClick={() => form.post("/users")}>Save</Button>
 *
 * Call signature mirrors `useForm()` from @inertiajs/react. Pass either
 * the initial values, or the result of `useForm(...)` if you've already
 * called it (lets you compose with library-supplied form objects):
 *
 *   const inertiaForm = useForm({ name: "" });
 *   const form = useFancyForm(inertiaForm);
 */
export function useFancyForm<TData extends Record<string, unknown>>(
  initialOrForm: TData | InertiaForm<TData>,
): FancyFormBridge<TData> {
  // If the consumer already called useForm() and passed the result in, re-use
  // it; otherwise instantiate one here.
  //
  // The shim is called UNCONDITIONALLY and at the top level. It used to live
  // inside a useMemo keyed on `initialOrForm`, which meant Inertia's useForm ran
  // only when that memo recomputed. Pass a stable reference — a module-level
  // constant, or anything memoised — and the memo is cached from the second
  // render on, the inner hooks are skipped, React's hook order desyncs, and the
  // next render dies with "Cannot read properties of undefined (reading
  // 'length')" from deep inside React.
  //
  // It hid well: every call site that passes an inline object literal gets a new
  // reference each render, so the memo always recomputed and the hooks always
  // ran. Only callers doing the tidier thing were affected.
  const provided = isInertiaForm<TData>(initialOrForm) ? initialOrForm : null;

  // EMPTY_INITIAL is module-level and therefore stable, so this costs one idle
  // Inertia form when a caller supplied their own. Rules of Hooks over
  // micro-optimisation: the alternative is a conditional hook.
  const shim = useInertiaFormShim<TData>(
    (provided ? EMPTY_INITIAL : initialOrForm) as TData,
  );

  const form: InertiaForm<TData> = provided ?? shim;

  const field = useCallback(
    <K extends keyof TData & string>(name: K): FancyFieldBridge<TData[K]> => ({
      name,
      value: form.data[name],
      onChange: (e) => {
        const next =
          e !== null && typeof e === "object" && "target" in (e as object)
            ? ((e as React.ChangeEvent<HTMLInputElement>).target as HTMLInputElement & {
                checked?: boolean;
                type?: string;
              })
            : null;
        if (next) {
          const value = next.type === "checkbox" ? next.checked : next.value;
          form.setData(name, value as unknown as TData[K]);
        } else {
          form.setData(name, e as unknown as TData[K]);
        }
      },
      error: form.errors[name],
      loading: form.processing,
    }),
    [form],
  );

  return {
    data: form.data,
    setData: form.setData as FancyFormBridge<TData>["setData"],
    errors: form.errors,
    processing: form.processing,
    field,
    submit: form.submit,
    post: form.post,
    put: form.put,
    patch: form.patch,
    delete: form.delete,
    reset: form.reset,
    clearErrors: form.clearErrors,
  };
}

function isInertiaForm<T>(x: unknown): x is InertiaForm<T> {
  return (
    typeof x === "object" &&
    x !== null &&
    "data" in (x as object) &&
    "setData" in (x as object) &&
    "errors" in (x as object) &&
    "processing" in (x as object)
  );
}

/**
 * Stable placeholder for the case where the caller supplied their own form.
 * Module-level so the reference never changes between renders.
 */
const EMPTY_INITIAL = Object.freeze({}) as Record<string, unknown>;

function useInertiaFormShim<TData extends Record<string, unknown>>(initial: TData): InertiaForm<TData> {
  return inertiaUseForm(initial as any) as unknown as InertiaForm<TData>;
}

import { useCallback, useRef, useState } from "react";
import { runFlow, type RunOptions, type RunResult } from "./run-flow";
import { getNodeKind } from "../registry/registry";
import type {
  ExecutorRegistry,
  FlowGraph,
  NodeRunStatus,
  RunEvent,
} from "../types";

export type FlowRunFeedEntry = {
  id: string;
  at: number;
  /**
   * `message` is a node's own human-facing announcement (`startingMsg` /
   * `stoppingMsg`), kept distinct from `status` and `info` so a progress UI can
   * show ONLY the narration. Folded in with diagnostics it would be unfindable,
   * which is the same as not having it.
   */
  level: "info" | "warn" | "error" | "status" | "message";
  text: string;
  nodeId?: string;
  detail?: unknown;
};

export type UseFlowRunReturn = {
  /** Status keyed by nodeId — drive the UI overlay from this. */
  statuses: Record<string, NodeRunStatus>;
  /** Per-node status text (e.g. error message). */
  statusText: Record<string, string | undefined>;
  /** Latest computed output value per node (for reactive kinds). */
  outputs: Record<string, unknown>;
  /**
   * Latest status message per nodeId, from the node's own `startingMsg` /
   * `stoppingMsg`. Undefined for the nodes that declared none, which is most
   * of them by design.
   */
  nodeMessages: Record<string, string | undefined>;
  /** Live event log (capped to last N). */
  feed: FlowRunFeedEntry[];
  /** Whether a run is currently in progress. */
  running: boolean;
  /** Last run result, or null. */
  lastResult: RunResult | null;
  /** Kick off a run with the provided graph + executors. */
  run: (graph: FlowGraph, executors: ExecutorRegistry, options?: RunOptions) => Promise<RunResult>;
  /** Cancel the current run (if any). */
  cancel: () => void;
  /** Reset all runtime state (statuses, feed, lastResult). */
  reset: () => void;
};

export type UseFlowRunOptions = {
  /** Cap the in-memory feed to this many entries. Default 200. */
  maxFeed?: number;
};

/**
 * useFlowRun — drives `runFlow` + maintains observability state. Pair with
 * `applyStatusesToNodes` (below) before passing nodes to `<FlowCanvas>` so
 * the per-node status badge renders.
 */
export function useFlowRun({ maxFeed = 200 }: UseFlowRunOptions = {}): UseFlowRunReturn {
  const [statuses, setStatuses] = useState<Record<string, NodeRunStatus>>({});
  const [statusText, setStatusText] = useState<Record<string, string | undefined>>({});
  const [nodeMessages, setNodeMessages] = useState<Record<string, string | undefined>>({});
  const [outputs, setOutputs] = useState<Record<string, unknown>>({});
  const [feed, setFeed] = useState<FlowRunFeedEntry[]>([]);
  const [running, setRunning] = useState(false);
  const [lastResult, setLastResult] = useState<RunResult | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const handleEvent = useCallback(
    (e: RunEvent) => {
      switch (e.type) {
        case "node-status":
          setStatuses((s) => ({ ...s, [e.nodeId]: e.status }));
          setStatusText((t) => ({ ...t, [e.nodeId]: e.text }));
          appendFeed({ level: "status", text: `${e.nodeId} → ${e.status}${e.text ? ` (${e.text})` : ""}`, nodeId: e.nodeId });
          break;
        case "node-message":
          setNodeMessages((m) => ({ ...m, [e.nodeId]: e.message }));
          appendFeed({ level: "message", text: e.message, nodeId: e.nodeId });
          break;
        case "node-output":
          setOutputs((o) => ({ ...o, [e.nodeId]: e.value }));
          appendFeed({ level: "info", text: `${e.nodeId}.${e.portId} = ${preview(e.value)}`, nodeId: e.nodeId, detail: e.value });
          break;
        case "log":
          appendFeed({ level: e.level, text: e.message, nodeId: e.nodeId, detail: e.detail });
          break;
        case "run-start":
          appendFeed({ level: "info", text: "▶ run started" });
          break;
        case "run-end":
          appendFeed({ level: e.ok ? "info" : "error", text: e.ok ? "✓ run complete" : "✗ run failed" });
          break;
        case "run-error":
          appendFeed({ level: "error", text: e.error });
          break;
      }
      function appendFeed(partial: Omit<FlowRunFeedEntry, "id" | "at">) {
        setFeed((f) => {
          const entry: FlowRunFeedEntry = { id: `${Date.now()}_${f.length}`, at: Date.now(), ...partial };
          const next = [...f, entry];
          return next.length > maxFeed ? next.slice(next.length - maxFeed) : next;
        });
      }
    },
    [maxFeed],
  );

  const run = useCallback(
    async (graph: FlowGraph, executors: ExecutorRegistry, options: RunOptions = {}) => {
      if (running) {
        return { ok: false, outputs: {}, error: "another run is already in progress" } satisfies RunResult;
      }
      const controller = new AbortController();
      abortRef.current = controller;
      // Reset previous statuses for the nodes we're about to run.
      const idleStatuses: Record<string, NodeRunStatus> = {};
      for (const n of graph.nodes) idleStatuses[n.id] = "idle";
      setStatuses(idleStatuses);
      setStatusText({});
      setOutputs({});
      setRunning(true);
      try {
        const result = await runFlow(graph, executors, handleEvent, { ...options, signal: controller.signal });
        setLastResult(result);
        return result;
      } finally {
        setRunning(false);
        abortRef.current = null;
      }
    },
    [handleEvent, running],
  );

  const cancel = useCallback(() => abortRef.current?.abort(), []);

  const reset = useCallback(() => {
    setStatuses({});
    setStatusText({});
    setOutputs({});
    setFeed([]);
    setLastResult(null);
  }, []);

  return { statuses, statusText, nodeMessages, outputs, feed, running, lastResult, run, cancel, reset };
}

/**
 * Write each reactive kind's latest run output into its `data.output`, so its
 * card can render the computed value live. Non-reactive kinds are returned
 * untouched. Pair with `applyStatusesToNodes` before rendering.
 */
export function applyOutputsToNodes<TNode extends { id: string; type?: string; data: any }>(
  nodes: TNode[],
  outputs: Record<string, unknown>,
): TNode[] {
  return nodes.map((n) => {
    const kind = getNodeKind((n.data as any)?.kind ?? n.type ?? "");
    if (!kind?.reactive || !(n.id in outputs)) return n;
    return { ...n, data: { ...n.data, output: outputs[n.id] } };
  });
}

/** Merge runtime statuses into nodes for rendering. */
export function applyStatusesToNodes<TNode extends { id: string; data: any }>(
  nodes: TNode[],
  statuses: Record<string, NodeRunStatus>,
  statusText: Record<string, string | undefined>,
): TNode[] {
  return nodes.map((n) => ({
    ...n,
    data: {
      ...n.data,
      status: statuses[n.id] ?? n.data?.status ?? "idle",
      statusText: statusText[n.id] ?? n.data?.statusText,
    },
  }));
}

function preview(v: unknown): string {
  try {
    const s = JSON.stringify(v);
    return s && s.length > 60 ? s.slice(0, 57) + "…" : (s ?? String(v));
  } catch {
    return String(v);
  }
}

import type {
  ExecutorRegistry,
  FlowEdge,
  FlowGraph,
  FlowNode,
  NodeExecutor,
  RunEvent,
} from "../types";
// Both modules are React-free by design — the `/engine` entry must not pull in
// React. Import them directly rather than via the `registry` barrel, which
// re-exports the RegistryNode component.
import { getNodeKind, kindIds } from "../registry/registry";
import { resolveNodePorts } from "../registry/ports";
import { RunIdentity, type RunIdentityJson } from "./run-identity";
import { resolveWorkflowProps } from "./workflow-props";

export type RunOptions = {
  /** Stop the run after this many ms. Default: no timeout. */
  timeoutMs?: number;
  /** Abort signal — host can cancel the run. */
  signal?: AbortSignal;
  /** Initial inputs supplied to entry-point nodes (no incoming edges). */
  initialInputs?: Record<string, Record<string, unknown>>;
  /**
   * Values for the inputs the graph DECLARES, passed by name.
   *
   * The flat, node-id-free way to configure a run. `initialInputs` is keyed by
   * node id, so a caller had to know the trigger was called `t` and a rename
   * broke every caller while the graph stayed valid. Props are checked against
   * `graph.inputs`, so a misspelling fails the run instead of sitting unread.
   */
  props?: Record<string, unknown>;
  /**
   * Which ENTRY POINTS are live — the ids of nodes with NO incoming edges this
   * run should start from. Omit it and every entry point runs, exactly as
   * before the option existed.
   *
   * A graph may hold more than one trigger — a `manual_trigger` for
   * hand-testing beside the event trigger that runs it for real — and a trigger
   * has no inbound edges, which IS the readiness rule. So without this, every
   * trigger's branch runs on every run, whichever one fired. The triggers
   * themselves are harmless; everything DOWNSTREAM of the ones that did not
   * fire is not. A `user_input` stranded on the manual branch parks an
   * event-driven run to ask a person for data the event already supplied,
   * which from outside looks like the event trigger being ignored.
   *
   * Naming the live entry points makes the others INACTIVE, and the existing
   * "at least one active inbound edge" rule then skips everything reachable
   * only from them. No new routing logic.
   *
   * Three edges, each pinned by `flow/entry-points` in
   * `@particle-academy/fancy-conformance`:
   *  - `undefined` is NOT `[]`. Unset runs every entry point; an empty array
   *    says none is live and runs nothing.
   *  - A node reachable from SEVERAL entry points still runs when any one of
   *    them fires — one active inbound edge is enough, as always.
   *  - Naming a node that HAS inbound edges names no entry point, so every real
   *    entry is inactive and nothing runs. That falls out of the rule rather
   *    than being special-cased; validate your ids if you want a typo to be
   *    loud, because the runtime cannot tell one from a deliberate empty
   *    selection.
   */
  entryNodes?: string[];
  /** Nesting depth — set by `subflow` when it runs a child graph. */
  depth?: number;
  /**
   * Who is running, so a writing node can derive a stable idempotency key.
   *
   * A bare string is taken as the run key. **Deliberately not defaulted:** a
   * minted-per-call key would change on every whole-run retry, which is exactly
   * the failure an idempotency key exists to prevent — so a host that has not
   * supplied one gets `ctx.run === undefined` and a connector that declines to
   * write blind, rather than a plausible-looking key that double-charges.
   */
  run?: RunIdentity | RunIdentityJson | string;
  /**
   * Outputs already checkpointed for this run, keyed by node id.
   *
   * A node present here is **republished, not re-executed** — its stored value
   * goes back onto the same ports, so downstream routing reproduces exactly
   * what it did the first time. This is what makes a per-node durable driver
   * possible without a second copy of the routing rules, and it is how the PHP
   * and Python runtimes have always resumed.
   */
  resumeOutputs?: Record<string, unknown>;
};

export type RunResult = {
  ok: boolean;
  /** Outputs collected per node, keyed by node id. */
  outputs: Record<string, unknown>;
  /** Error captured if any node threw. */
  error?: string;
};

/**
 * runFlow — topological execution of a FlowGraph against an ExecutorRegistry.
 *
 * Each node runs once, when all upstream nodes have produced outputs on the
 * connected ports. Decision nodes (or any executor that returns `{ branch:
 * 'true' }`) can short-circuit specific output ports — only edges leaving
 * an "active" port propagate to downstream nodes.
 *
 * Cycles are detected and abort the run with an error.
 *
 * The `onEvent` callback receives a stream of `RunEvent`s — wire it to a
 * status feed, log panel, or store.
 */
export async function runFlow(
  graph: FlowGraph,
  executors: ExecutorRegistry,
  onEvent: (event: RunEvent) => void = () => {},
  options: RunOptions = {},
): Promise<RunResult> {
  const { signal, initialInputs = {}, timeoutMs, depth = 0, resumeOutputs = {}, entryNodes } = options;
  const run = options.run === undefined ? undefined : RunIdentity.from(options.run);
  const outputs: Record<string, unknown> = {};
  const portValues = new Map<string, unknown>(); // key: `${nodeId}:${portId}`
  const completed = new Set<string>();
  const errors: string[] = [];

  // Topological order via Kahn's algorithm. We allow nodes to run as soon
  // as their incoming edges' source ports have produced values, so the
  // order here is just a deterministic baseline used for cycle detection.
  const order = topoSort(graph);
  if (order === null) {
    const msg = "Cycle detected in flow graph — aborting.";
    onEvent({ type: "run-error", error: msg });
    return { ok: false, outputs, error: msg };
  }

  // Props are checked BEFORE anything runs, and a failure aborts the run.
  //
  // Before a node executes, not after: a workflow whose third node needed a
  // value the caller misspelled would otherwise do two nodes' worth of real
  // work — sending, writing, charging — and only then discover the call was
  // malformed. Validation that happens after a side effect is not validation.
  const propsCheck = resolveWorkflowProps(graph.inputs, options.props);
  if (!propsCheck.ok) {
    onEvent({ type: "run-error", error: propsCheck.error });
    return { ok: false, outputs, error: propsCheck.error };
  }
  const props = propsCheck.props;
  const declaresProps = (graph.inputs?.length ?? 0) > 0;

  const incomingByNode = indexIncoming(graph.edges);
  const timer = timeoutMs ? setTimeout(() => errors.push(`Run timed out after ${timeoutMs}ms`), timeoutMs) : null;

  onEvent({ type: "run-start" });

  try {
    for (const node of order) {
      if (signal?.aborted) throw new Error("aborted");
      if (errors.length) break;

      // A checkpointed node is republished, never re-executed. Publishing the
      // stored value back onto its own ports is what makes the resume exact:
      // the branch it took, the ports it lit and the inputs its successors
      // collect are all reproduced by the engine's own rules rather than by a
      // driver's recollection of them.
      if (Object.prototype.hasOwnProperty.call(resumeOutputs, node.id)) {
        const stored = resumeOutputs[node.id];
        outputs[node.id] = stored;
        const activated = activatedPorts(node, stored);
        for (const portId of activated.ports) {
          portValues.set(`${node.id}:${portId}`, activated.value);
          onEvent({ type: "node-output", nodeId: node.id, portId, value: activated.value });
        }
        completed.add(node.id);
        onEvent({ type: "node-status", nodeId: node.id, status: "done", text: "resumed" });
        continue;
      }

      const incoming = incomingByNode.get(node.id) ?? [];

      // An ENTRY POINT this run did not start from is inactive.
      //
      // A node with no inbound edges is unconditionally ready -- that IS the
      // readiness rule -- so a graph with two triggers ran both branches on
      // every run, whichever trigger actually fired. Marking the unnamed ones
      // inactive here lets the "at least one active inbound edge" test below
      // skip everything reachable only from them, with no new routing logic.
      //
      // Gates only nodes with NO incoming edges: a node further down the graph
      // is not an entry point, and its readiness is still decided by its edges.
      if (incoming.length === 0 && entryNodes !== undefined && !entryNodes.includes(node.id)) {
        onEvent({ type: "node-status", nodeId: node.id, status: "idle", text: "skipped" });
        continue;
      }

      // Run a node once any upstream branch reaches it. We iterate in
      // topological order, so by the time we reach this node every upstream
      // node has been processed — each incoming edge is therefore *settled*
      // (active or dead, never still-pending). Requiring ALL incoming edges to
      // be active wrongly skipped MERGE POINTS: when a Decision routes down one
      // branch, the other branch's edge stays dead forever, so an `every` check
      // skipped the shared continuation node and halted the run after the first
      // branch (#1). Run when AT LEAST ONE incoming edge is active —
      // collectInputs() only reads from the active ones. A genuine parallel
      // join still works: in topo order both of its inputs are already active.
      if (incoming.length > 0) {
        const anyActive = incoming.some((e) => portValues.has(`${e.source}:${e.sourceHandle ?? "out"}`));
        if (!anyActive) {
          onEvent({ type: "node-status", nodeId: node.id, status: "idle", text: "skipped" });
          continue;
        }
      }

      // Notes/annotations + layout (lane/pool) nodes are visual only — never
      // executed and never fed to runners. Their config (a note's text, a lane's
      // title) stays in the document for editors + MCP tools, but the engine
      // walks straight past them. Edges cross lanes freely, so grouping never
      // affects topology.
      const visualKind = getNodeKind(node.type ?? "");
      const isLayout = visualKind?.category === "layout";
      const isAnnotation = node.type === "note" || visualKind?.category === "annotation";
      if (isLayout || isAnnotation) {
        onEvent({
          type: "node-status",
          nodeId: node.id,
          status: "idle",
          text: isLayout ? "lane" : "annotation",
        });
        continue;
      }

      onEvent({ type: "node-status", nodeId: node.id, status: "running" });
      announce(onEvent, node, "start");

      const inputs = collectInputs(node, incoming, portValues, initialInputs, props, declaresProps);
      const exec = pickExecutor(executors, node);
      if (!exec) {
        // Name what was LOOKED FOR, not just what the node calls itself.
        //
        // This said `kind=${node.type}` — so a registry keyed under one of the
        // kind's other ids produced "kind=manual_trigger is missing" about a
        // kind that exists AND is registered, just under a different key. The
        // consumer who reported it reasonably read that as the kind being
        // absent and went looking for a missing package.
        // The wildcard is part of `executorLookupIds` now, so it is already in
        // the list — appending "and the wildcard" as well made the message name
        // it twice, and the test that reads the ids back out of the message
        // parsed the prose between the two quoted stars as an id.
        const tried = executorLookupIds(node);
        const msg = `No executor registered for kind=${node.type}`
          + ` — tried ${tried.map((id) => `"${id}"`).join(", ")}`
          + `. Key your registry by one of those.`;
        errors.push(msg);
        onEvent({ type: "node-status", nodeId: node.id, status: "error", text: msg });
        onEvent({ type: "log", nodeId: node.id, level: "error", message: msg });
        break;
      }

      try {
        const result = await Promise.resolve(
          exec({
            node,
            inputs,
            abort: (reason) => { throw new Error(reason ?? "aborted"); },
            emit: onEvent,
            executors,
            depth,
            run,
          }),
        );
        outputs[node.id] = result;

        // Decide which output ports were activated. Three conventions:
        //  1) If result is `{ __port: "out", value: x }`, only that port emits.
        //  2) If result has `branch: <portId>`, only that port emits (decision sugar).
        //  3) Otherwise, the value is published on every declared output port.
        const activated = activatedPorts(node, result);
        for (const portId of activated.ports) {
          portValues.set(`${node.id}:${portId}`, activated.value);
          onEvent({ type: "node-output", nodeId: node.id, portId, value: activated.value });
        }
        completed.add(node.id);
        onEvent({ type: "node-status", nodeId: node.id, status: "done" });
        // Only on the success path, and deliberately so: a `stoppingMsg` of
        // "Analysis complete" emitted after a throw tells a human the opposite
        // of what happened, in the part of the UI they trust most. A failure
        // reports through node-status/log, which is what those exist for.
        announce(onEvent, node, "end");
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        errors.push(msg);
        onEvent({ type: "node-status", nodeId: node.id, status: "error", text: msg });
        onEvent({ type: "log", nodeId: node.id, level: "error", message: msg });
        break;
      }
    }
  } finally {
    if (timer) clearTimeout(timer);
  }

  const ok = errors.length === 0;
  onEvent({ type: "run-end", ok });
  return ok ? { ok, outputs } : { ok, outputs, error: errors[0] };
}

function indexIncoming(edges: FlowEdge[]): Map<string, FlowEdge[]> {
  const map = new Map<string, FlowEdge[]>();
  for (const e of edges) {
    const list = map.get(e.target) ?? [];
    list.push(e);
    map.set(e.target, list);
  }
  return map;
}

function topoSort(graph: FlowGraph): FlowNode[] | null {
  const inDegree = new Map<string, number>();
  for (const n of graph.nodes) inDegree.set(n.id, 0);
  for (const e of graph.edges) inDegree.set(e.target, (inDegree.get(e.target) ?? 0) + 1);
  const queue: string[] = [];
  for (const [id, d] of inDegree) if (d === 0) queue.push(id);
  const ordered: string[] = [];
  while (queue.length) {
    const id = queue.shift()!;
    ordered.push(id);
    for (const e of graph.edges) {
      if (e.source !== id) continue;
      const next = (inDegree.get(e.target) ?? 0) - 1;
      inDegree.set(e.target, next);
      if (next === 0) queue.push(e.target);
    }
  }
  if (ordered.length !== graph.nodes.length) return null;
  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  return ordered.map((id) => byId.get(id)!).filter(Boolean);
}

function collectInputs(
  node: FlowNode,
  incoming: FlowEdge[],
  portValues: Map<string, unknown>,
  initial: Record<string, Record<string, unknown>>,
  props: Record<string, unknown>,
  declaresProps: boolean,
): Record<string, unknown> {
  const inputs: Record<string, unknown> = { ...(initial[node.id] ?? {}) };

  // ENTRY POINTS are seeded with the props by their bare names.
  //
  // This is what lets an existing graph keep working unchanged. A trigger that
  // reads `{{ topic }}` was fed by `initialInputs[triggerId].topic`; a caller
  // moving to props passes `{ topic }` and the node sees exactly what it saw
  // before. Only entry points, because a node in the middle of a graph reading
  // a bare `topic` would be shadowing whatever its upstream edge is called.
  //
  // Never clobbers: a value already seeded by the host is the host's.
  if (incoming.length === 0) {
    for (const [name, value] of Object.entries(props)) {
      if (!(name in inputs)) inputs[name] = value;
    }
  }
  for (const e of incoming) {
    const portId = e.targetHandle ?? "in";
    const key = `${e.source}:${e.sourceHandle ?? "out"}`;
    // A branch that never fired has no entry in portValues. Assigning its
    // `undefined` would CLOBBER the value the branch that DID fire already
    // contributed on this same handle — emptying every merge point downstream
    // of a decision, silently, with the run still reporting success.
    //
    // This is the other half of the merge-point bug above: that fix stopped the
    // shared continuation node being skipped, but it still arrived with nothing
    // whenever a later inactive edge happened to be last in `incoming`.
    if (!portValues.has(key)) continue;
    inputs[portId] = portValues.get(key);

    // ALSO address it by the SOURCE NODE'S ID, when the edge named no handle.
    //
    // Authors reach for node ids -- every graph tool addresses nodes that way,
    // so `{{ n2.text }}` is the first thing written, by people and far more
    // often by assistants generating graphs. That resolved to nothing, and
    // NOTHING FAILED: an unresolvable path yields "", so the node ran, the run
    // reported success, and the damage was output that was quietly wrong. A
    // consumer shipped a file named `document.md` containing the literal text
    // of its own template, on a green run (fancy-flow-php#8).
    //
    // `targetHandle` already covers this and stays the right mechanism for
    // reading something other than the immediate predecessor -- but it is set
    // on the EDGE, which is not where an author is looking while writing a
    // node's config. The model was not wrong; the obvious spelling meant
    // nothing.
    //
    // Only for edges that declared NO handle: an edge that named one said what
    // it meant, and a second key under the source id would quietly widen a
    // deliberate contract. `??=` so nothing already seeded -- by the host's
    // initialInputs or an earlier edge -- is ever clobbered.
    if (e.targetHandle == null && !(e.source in inputs)) {
      inputs[e.source] = portValues.get(key);
    }
  }

  // EVERY node gets `$props` — but ONLY when the workflow declares inputs.
  //
  // The first half is what makes props usable at depth. Seeding entry points
  // alone would mean a node six hops downstream had the value threaded through
  // every edge in between, and every hop is somewhere it can be dropped. It
  // costs nothing to resolve because `$props` is an ORDINARY KEY in the inputs
  // object: `resolvePath` already walks dot-paths against it, so
  // `{{ $props.topic }}` works with no change to any expression resolver in any
  // of the three runtimes.
  //
  // The second half is a CORRECTION, and the golden parity fixtures caught it.
  // An earlier draft wrote `$props` unconditionally, justified as "so
  // `{{ $props.x }}` resolves to null rather than throwing" — which is not
  // true. `resolvePath` returns null for any unresolvable path, so on a graph
  // declaring nothing the key changes no behaviour at all. What it DOES do is
  // add a key to every executor's inputs, on every graph, forever — which
  // showed up instantly as a diff in every stored golden.
  //
  // `ConnectorFacet::from` states the same rule for the same reason: a payload
  // gaining a key on every entry is a wire change for no gain, and the ABSENCE
  // of a key is already the honest way to say "this one takes no props".
  //
  // Keyed on the DECLARATION rather than on whether a value arrived: a workflow
  // whose inputs are all optional and all omitted still declared a contract, so
  // `$props` is present and empty.
  if (declaresProps) inputs.$props = props;

  return inputs;
}

/**
 * Every key a node's executor may legitimately be registered under, in
 * precedence order. **This is the resolution rule** — `pickExecutor` walks this
 * list and takes the first hit, and the failure message lists the same ids.
 *
 * That sharing is the point, and it used to be a claim rather than a fact: this
 * docblock already said "shared by the lookup and by its failure message" while
 * `pickExecutor` re-implemented the walk beside it. The two agreed until the
 * precedence changed, and then the message listed an id the lookup no longer
 * tried — sending a reader to check something that never happened, which the
 * comment correctly named as worse than listing nothing. **Prose next to a check
 * is not the check.** One list now, walked by both, so they cannot drift.
 *
 * The order, and why:
 *
 * 1. `node.id` — the per-node override. First so a graph can pin ONE node to a
 *    stub without unbinding that kind for every other node using it.
 * 2. `node.type`, then every id its kind answers to — **if `node.type` names a
 *    registered kind, it is authoritative and `data.kind` is not consulted at
 *    all.** A node that says it is an `llm_call` must never quietly run another
 *    kind's code; it fails closed instead.
 * 3. Otherwise `data.kind` and its kind's ids. A `node.type` naming no
 *    registered kind is not a claim about behaviour — usually it is an xyflow
 *    RENDERER type (`"fancyNode"`), which is ordinary practice, and then
 *    `data.kind` is the only real answer. This branch also covers `type` absent.
 * 4. `"*"` — the wildcard, last, and a sentinel rather than a kind: it is never
 *    expanded through the alias machinery, or every unmatched node would bind to
 *    whatever a kind literally named `*` aliased to.
 *
 * Pinned as `flow/executor-resolution` in `@particle-academy/fancy-conformance`.
 */
function executorLookupIds(node: FlowNode): string[] {
  const ids: string[] = [node.id];
  if (node.type) ids.push(node.type);

  const typeKind = node.type ? getNodeKind(node.type) : null;

  if (typeKind) {
    for (const id of kindIds(typeKind)) ids.push(id);
  } else {
    const declared = (node.data as { kind?: unknown } | undefined)?.kind;
    const kindName = typeof declared === "string" && declared !== "" ? declared : null;

    if (kindName) {
      ids.push(kindName);
      const dataKind = getNodeKind(kindName);
      if (dataKind) {
        for (const id of kindIds(dataKind)) ids.push(id);
      }
    }
  }

  ids.push("*");

  return [...new Set(ids)];
}

function pickExecutor(
  executors: ExecutorRegistry,
  node: FlowNode,
): NodeExecutor | undefined {
  // The whole rule lives in `executorLookupIds` -- see its docblock. Walking
  // that one list is what keeps the resolution and the failure message from
  // ever disagreeing about which keys were tried.
  for (const id of executorLookupIds(node)) {
    if (executors[id]) return executors[id];
  }

  return undefined;
}

function activatedPorts(node: FlowNode, result: unknown): { ports: string[]; value: unknown } {
  if (result && typeof result === "object") {
    const r = result as Record<string, unknown>;
    if (typeof r.__port === "string") {
      return { ports: [r.__port], value: r.value };
    }
    if (typeof r.branch === "string") {
      // `Object.hasOwn`, NOT `??`. The two are different questions:
      //   no `value` key at all -> the whole result IS the payload (the case
      //                            this fallback exists for)
      //   `value` present, null -> the payload is null; pass null on
      // `r.value ?? r` cannot tell them apart, so a branch whose payload was
      // null leaked the WRAPPER downstream -- every following node received
      // `{ branch, value }`, two fields no kind declares, while the fields it
      // does declare were absent. The reachable path is an upstream `transform`
      // whose dot-path did not resolve, which is exactly the silent-null case.
      // `Port.only`'s `?? null` never had it. All four runtimes shared this,
      // identically -- so no parity table could catch it; they agreed on being
      // wrong.
      return { ports: [r.branch], value: Object.prototype.hasOwnProperty.call(r, "value") ? r.value : r };
    }
  }
  // Resolve through the shared helper so the ports the runtime activates are
  // the same ones the canvas drew — including config-driven ports, which the
  // node's `data` does not carry. Falls back to a lone `out` when a node
  // declares nothing.
  const kind = getNodeKind((node.data as any)?.kind ?? node.type ?? "") ?? undefined;
  const declared = resolveNodePorts(node, kind).outputs?.map((p) => p.id);
  return { ports: declared?.length ? declared : ["out"], value: result };
}

/**
 * Emit a node's own status message for one phase of its execution, if it
 * declared one.
 *
 * Opt-in by absence: a node with no `startingMsg` / `stoppingMsg` says nothing,
 * because most nodes in a real graph are plumbing and narrating all of them
 * buries the two or three steps a person actually wants to follow.
 *
 * A message must be a non-empty string after trimming. An empty string is the
 * shape a cleared editor field takes, and a blank line in a progress feed is
 * indistinguishable from a real message that happens to render as nothing —
 * so it is treated as "not set" rather than as "announce nothing visible".
 */
function announce(
  onEvent: (event: RunEvent) => void,
  node: FlowNode,
  phase: "start" | "end",
): void {
  const data = node.data as { startingMsg?: unknown; stoppingMsg?: unknown } | undefined;
  const raw = phase === "start" ? data?.startingMsg : data?.stoppingMsg;
  if (typeof raw !== "string") return;

  const message = raw.trim();
  if (message === "") return;

  onEvent({ type: "node-message", nodeId: node.id, phase, message });
}

/**
 * Who is running, which step this is, and how many times it has been tried.
 *
 * ## Why an engine needs this at all
 *
 * A node that WRITES to somebody else's system — charge a card, send a message,
 * open a pull request — can only survive a retry if the retry carries the same
 * idempotency key the first attempt did. Otherwise the provider treats the
 * second call as a new request and the customer is charged twice.
 *
 * Until this existed the executor context was `{ node, inputs, emit, abort }`,
 * which is not enough to derive one. Both obvious fallbacks are worse than
 * sending no key at all:
 *
 * - **the node id alone** is stable across retries, and also across RUNS — two
 *   legitimate payments share a key and the provider silently collapses the
 *   second into the first. A payment that never happened, reported as success;
 * - **a fresh random value** is unique per run, and also per ATTEMPT — a retry
 *   creates a second charge, which is the thing being avoided.
 *
 * ## What actually identifies a step
 *
 * Not `(run, node)`. A node legitimately executes more than once inside one
 * run: once per subflow invocation, once per iteration of a loop an executor
 * drives itself. `(run, node)` would give every one of those the same key, and
 * a provider would honour exactly one of them.
 *
 * So a step is identified by the **path of invocations that led to it**, plus
 * an optional **occurrence** for repetition at the same level:
 *
 * ```text
 * runKey ":" segment ("/" segment)*        segment := escape(id) ["#" occurrence]
 * ```
 *
 * And the part that is easy to get backwards: **`attempt` is NOT in the key.**
 * It is carried here for logging and for {@link RunIdentity.isReplaySafe}, and
 * putting it in the key would restore the exact bug the key exists to prevent.
 *
 * Pinned cross-runtime by `shared/flow-run-identity` in
 * `@particle-academy/fancy-conformance`.
 */

/** The wire shape — what a queue job payload carries. */
export type RunIdentityJson = {
  runKey: string;
  path?: string[];
  attempt?: number;
  firstAttemptAt?: string;
};

/**
 * Escape one segment so the composition is injective.
 *
 * `%` FIRST, or the escaping is not reversible: escaping `/` before `%` turns a
 * literal `a%2Fb` into the same text as the escaped form of `a/b`, which is the
 * collision this exists to prevent, reintroduced by its own fix.
 */
export function escapeSegment(value: string): string {
  // Not `replaceAll` — the package targets ES2020, and this must produce the
  // identical string on every runtime that reads the conformance table.
  return value.replace(/%/g, "%25").replace(/\//g, "%2F").replace(/#/g, "%23");
}

function renderSegment(value: string, occurrence?: number | null): string {
  const escaped = escapeSegment(value);
  // `occurrence === 0` is a real occurrence. A truthiness check here silently
  // collapses iteration 0 into the un-iterated key.
  return occurrence === undefined || occurrence === null ? escaped : `${escaped}#${occurrence}`;
}

function instant(value: string): number {
  const ms = Date.parse(value);
  if (Number.isNaN(ms)) {
    throw new Error(
      `RunIdentity: firstAttemptAt is not a parseable timestamp: ${JSON.stringify(value)}`,
    );
  }
  return ms;
}

/**
 * A run, a position inside it, and how many times this position has been tried.
 *
 * Immutable. {@link descend} returns a new identity rather than mutating, so an
 * executor cannot change what its siblings see.
 */
export class RunIdentity {
  /** Stable for the whole run: same across retries, resumes, workers and hosts. */
  readonly runKey: string;

  /**
   * Enclosing invocation segments, outermost first, ALREADY RENDERED.
   *
   * Empty at the top level. A subflow pushes the invoking node's id; an
   * executor that loops pushes `id#i`.
   */
  readonly path: readonly string[];

  /**
   * 1-based attempt of THIS logical step. Never part of the key.
   *
   * The durable driver sets it from the node's claim row, which is exact. A
   * plain in-process `runFlow` gets whatever the host passed, which is
   * run-scoped and therefore conservative — see `isReplaySafe`.
   */
  readonly attempt: number;

  /** ISO-8601 UTC instant of attempt 1 of this step. */
  readonly firstAttemptAt: string;

  constructor(
    runKey: string,
    path: readonly string[] = [],
    attempt = 1,
    firstAttemptAt: string = new Date().toISOString(),
  ) {
    if (!runKey || runKey.trim() === "") {
      throw new Error("RunIdentity: runKey must be a non-empty string.");
    }
    this.runKey = runKey;
    this.path = Object.freeze([...path]);
    this.attempt = Math.max(1, Math.trunc(attempt));
    this.firstAttemptAt = firstAttemptAt;
    Object.freeze(this);
  }

  /**
   * The identity of one execution of one node — stable across retries of that
   * execution, distinct from every other execution of the same node.
   *
   * Pass `occurrence` when an executor runs the same node more than once at the
   * same level (a loop body, one item of a fan-out it drives itself).
   */
  stepKey(nodeId: string, occurrence?: number | null): string {
    return `${this.runKey}:${[...this.path, renderSegment(nodeId, occurrence)].join("/")}`;
  }

  /**
   * A child identity for work nested inside this step.
   *
   * `subflow` pushes the invoking node's id, so a node inside the child graph
   * cannot collide with a same-named node in the parent. Attempt and
   * `firstAttemptAt` are carried down unchanged: the nested work happens inside
   * this step's attempt, and shares its clock.
   */
  descend(segment: string, occurrence?: number | null): RunIdentity {
    return new RunIdentity(
      this.runKey,
      [...this.path, renderSegment(segment, occurrence)],
      this.attempt,
      this.firstAttemptAt,
    );
  }

  /** A copy on a different attempt, first-attempt clock preserved. */
  withAttempt(attempt: number, firstAttemptAt?: string): RunIdentity {
    return new RunIdentity(
      this.runKey,
      this.path,
      attempt,
      firstAttemptAt ?? this.firstAttemptAt,
    );
  }

  /**
   * May this attempt reuse the step key and still be deduplicated?
   *
   * Providers forget idempotency keys — Stripe after 24 hours. Past that
   * window, resending the key creates a second charge and sending a fresh one
   * creates a second charge, so **the caller must refuse rather than pick
   * between them**: a loud stuck run beats a silent double write.
   *
   * `true` on attempt 1 whatever the elapsed time — nothing was sent on an
   * earlier attempt, so there is nothing for the provider to have forgotten.
   * That is what lets a run park on a human gate for a week and then write.
   *
   * `windowSeconds: null` means the provider does not expire keys. `0` means
   * it does not dedupe at all, so no retry may reuse a key — it is a real
   * window, not an absent one, and the two must not be conflated: reading `0`
   * as `null` turns "this provider does not dedupe" into "this provider
   * dedupes forever", which is the more dangerous of the two by a distance.
   */
  isReplaySafe(windowSeconds: number | null | undefined, now: Date | string = new Date()): boolean {
    if (this.attempt <= 1) return true;
    if (windowSeconds === null || windowSeconds === undefined) return true;
    if (windowSeconds <= 0) return false;

    const nowMs = typeof now === "string" ? instant(now) : now.getTime();
    // Clock skew between two workers must not turn a legitimate retry into a
    // refusal, so a negative elapsed clamps to zero.
    const elapsedSeconds = Math.max(0, (nowMs - instant(this.firstAttemptAt)) / 1000);

    // Inclusive: a key written at T is remembered THROUGH T + window.
    return elapsedSeconds <= windowSeconds;
  }

  toJSON(): Required<RunIdentityJson> {
    return {
      runKey: this.runKey,
      path: [...this.path],
      attempt: this.attempt,
      firstAttemptAt: this.firstAttemptAt,
    };
  }

  /** Rebuild from a queue payload. */
  static from(value: RunIdentity | RunIdentityJson | string): RunIdentity {
    if (value instanceof RunIdentity) return value;
    if (typeof value === "string") return new RunIdentity(value);
    return new RunIdentity(
      value.runKey,
      value.path ?? [],
      value.attempt ?? 1,
      value.firstAttemptAt ?? new Date().toISOString(),
    );
  }
}

import type { WorkflowInput } from "../types";

/**
 * Resolving what a caller passed against what a workflow declared.
 *
 * Kept in its own module, and deliberately a pure function over two plain
 * objects, because the PHP and Python runtimes implement the same rules and
 * `suites/flow/workflow-props` in `@particle-academy/fancy-conformance` is the
 * table all three run. A rule that lives inside a runner is a rule each runtime
 * re-derives; a rule that is a function over maps is one they can share a
 * fixture for.
 *
 * ## Every branch here exists to make a mistake LOUD
 *
 * The failure this replaces was silence. `initialInputs` was keyed by node id,
 * so a caller passed `{ t: { topic: "otters" } }` and had to know the trigger
 * was named `t`; and nothing declared what a workflow accepted, so a
 * misspelled key was not an error — the value sat unread, the node saw
 * nothing, and the run reported success with output that was quietly wrong.
 *
 * So: an unknown key fails, a missing required value fails, and a wrong type
 * fails. None of those is a warning. A warning on a queue worker is a line in a
 * log nobody opens.
 */

/**
 * Why a resolution failed, in a vocabulary that is the same in every runtime.
 *
 * The MESSAGE is English prose and each runtime words it slightly differently,
 * which is fine for a human and useless for a shared fixture table. The CODE is
 * what `suites/flow/workflow-props` asserts, so parity is pinned on the
 * decision rather than on the phrasing — otherwise the three implementations
 * would be held to a translation instead of a behaviour.
 */
export type PropsErrorCode = "unknown_input" | "missing_required" | "type_mismatch";

/** The outcome of checking a caller's props against a declaration. */
export type PropsResolution =
  | { ok: true; props: Record<string, unknown> }
  | { ok: false; code: PropsErrorCode; error: string };

/**
 * The runtime type of a value, in the vocabulary a declaration uses.
 *
 * Arrays are checked before objects because `typeof []` is `"object"` and a
 * declaration that says `array` means a list — accepting `{}` there would be
 * the check passing while meaning nothing.
 */
function typeOf(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

/**
 * Check and fill a caller's props.
 *
 * Returns the resolved map — declared defaults filled in, nothing else added —
 * or the first error. One error rather than a list, because a run stops at the
 * first one anyway and a caller fixing a call wants the thing to fix, not a
 * report.
 */
export function resolveWorkflowProps(
  declared: WorkflowInput[] | undefined,
  passed: Record<string, unknown> | undefined,
): PropsResolution {
  const inputs = declared ?? [];
  const given = passed ?? {};
  const byName = new Map(inputs.map((input) => [input.name, input]));

  // UNKNOWN KEYS FIRST, and this is the check the whole feature is for.
  //
  // A caller who misspells `topic` as `topik` has configured nothing, and
  // before this the run went ahead and looked fine. Checking it before
  // anything else means the error names what they typed rather than
  // complaining that the thing they thought they passed is missing.
  for (const name of Object.keys(given)) {
    if (!byName.has(name)) {
      const known = inputs.map((input) => input.name);
      const suffix = known.length === 0
        ? "this workflow declares no inputs"
        : `known inputs: ${known.join(", ")}`;

      return {
        ok: false,
        code: "unknown_input",
        error: `Unknown workflow input "${name}" — ${suffix}.`,
      };
    }
  }

  const resolved: Record<string, unknown> = {};

  for (const input of inputs) {
    // `hasOwnProperty`, not a truthiness or `??` check. `0`, `false` and `""`
    // are real values a caller meant to pass, and a default applied over them
    // is a silent override — a limit of 0 quietly becoming 10 is not an error
    // anybody sees.
    const supplied = Object.prototype.hasOwnProperty.call(given, input.name);
    const hasDefault = Object.prototype.hasOwnProperty.call(input, "default");

    if (!supplied) {
      if (hasDefault) {
        resolved[input.name] = input.default;
        continue;
      }

      if (input.required) {
        return {
          ok: false,
          code: "missing_required",
          error: `Missing required workflow input "${input.name}"${
            input.type ? ` (${input.type})` : ""
          }.`,
        };
      }

      // Not supplied, no default, not required — absent rather than
      // `undefined`, so `{{ $props.x }}` resolves to null on both runtimes
      // instead of one of them inventing a key.
      continue;
    }

    const value = given[input.name];

    // An undeclared type accepts anything. "I am not asserting a shape" must
    // not degrade into "nothing is allowed".
    if (input.type !== undefined) {
      const actual = typeOf(value);
      if (actual !== input.type) {
        return {
          ok: false,
          code: "type_mismatch",
          error: `Workflow input "${input.name}" expects ${input.type}, got ${actual}.`,
        };
      }
    }

    resolved[input.name] = value;
  }

  return { ok: true, props: resolved };
}

import { useCallback, useState } from "react";
import {
  addEdge,
  applyEdgeChanges,
  applyNodeChanges,
  type Connection,
  type Edge,
  type EdgeChange,
  type NodeChange,
} from "@xyflow/react";
import type { FlowEdge, FlowGraph, FlowNode } from "../types";

export type UseFlowStateReturn = {
  nodes: FlowNode[];
  edges: FlowEdge[];
  setNodes: React.Dispatch<React.SetStateAction<FlowNode[]>>;
  setEdges: React.Dispatch<React.SetStateAction<FlowEdge[]>>;
  /**
   * Replace nodes AND edges atomically in a single commit. Use this for any op
   * that touches both (delete-with-edge-prune, undo/redo restore, setGraph):
   * calling `setNodes` then `setEdges` is NOT atomic in controlled mode (each
   * closes over a stale `value`), so the second write clobbers the first.
   */
  setGraph: (graph: FlowGraph) => void;
  onNodesChange: (changes: NodeChange[]) => void;
  onEdgesChange: (changes: EdgeChange[]) => void;
  onConnect: (connection: Connection) => void;
  /** Snapshot the current graph (suitable for serialization). */
  toGraph: () => FlowGraph;
};

/**
 * useFlowState — React Flow's standard controlled-state plumbing in one hook.
 * Spread into <FlowCanvas>.
 */
export function useFlowState(initial: FlowGraph): UseFlowStateReturn {
  const [nodes, setNodes] = useState<FlowNode[]>(initial.nodes);
  const [edges, setEdges] = useState<FlowEdge[]>(initial.edges);

  const onNodesChange = useCallback((changes: NodeChange[]) => {
    setNodes((ns) => applyNodeChanges(changes, ns) as FlowNode[]);
  }, []);
  const onEdgesChange = useCallback((changes: EdgeChange[]) => {
    setEdges((es) => applyEdgeChanges(changes, es));
  }, []);
  const onConnect = useCallback((connection: Connection) => {
    setEdges((es) => addEdge(connection, es) as Edge[]);
  }, []);

  const setGraph = useCallback((graph: FlowGraph) => {
    // Two useState writes in one event are batched, so this IS atomic here.
    setNodes(graph.nodes);
    setEdges(graph.edges);
  }, []);

  const toGraph = useCallback(() => ({ nodes, edges }), [nodes, edges]);

  return { nodes, edges, setNodes, setEdges, setGraph, onNodesChange, onEdgesChange, onConnect, toGraph };
}

import { forwardRef, useState } from "react";
import { cn } from "../../utils/cn";
import type { VideoViewerProps } from "./VideoViewer.types";

/**
 * A standalone video viewer — native controls, optional poster, fit-to-box, and
 * dark-aware framing. Renders for video sources inside `<MediaViewer>`.
 *
 * ```tsx
 * <VideoViewer src="/clip.mp4" poster="/clip.jpg" style={{ height: 360 }} />
 * ```
 */
export const VideoViewer = forwardRef<HTMLDivElement, VideoViewerProps>(
  (
    {
      src,
      poster,
      controls = true,
      autoPlay = false,
      loop = false,
      preload = "metadata",
      muted = false,
      fit = "contain",
      onError,
      className,
      style,
    },
    ref,
  ) => {
    const [errored, setErrored] = useState(false);

    return (
      <div
        ref={ref}
        data-react-fancy-video-viewer=""
        className={cn(
          "relative flex items-center justify-center overflow-hidden rounded-md bg-black",
          className,
        )}
        style={style}
      >
        {errored ? (
          <div className="flex flex-col items-center justify-center gap-1 p-4 text-center text-sm text-zinc-400">
            <span className="font-medium">Couldn&apos;t load video</span>
            <span className="max-w-full truncate text-xs opacity-70">{src}</span>
          </div>
        ) : (
          <video
            src={src}
            preload={preload}
            poster={poster}
            controls={controls}
            autoPlay={autoPlay}
            loop={loop}
            muted={muted}
            playsInline
            onError={() => {
              setErrored(true);
              onError?.();
            }}
            className={cn(
              "max-h-full max-w-full",
              fit === "cover" ? "h-full w-full object-cover" : "object-contain",
            )}
          />
        )}
      </div>
    );
  },
);

VideoViewer.displayName = "VideoViewer";

import type { CSSProperties } from "react";

export interface VideoViewerProps {
  /**
   * How much to fetch before playback is requested.
   *
   * Defaults to `"metadata"` — duration and the scrubber, nothing more. With no
   * attribute the browser decides, and Chrome decides `"auto"` for audio, which
   * means simply RENDERING the component downloads the whole file. Measured on
   * the Fancy showcase: one audio tile on the package grid transferred 995 KB
   * before anyone pressed play.
   *
   * Pass `"none"` for a thumbnail that should cost nothing, or `"auto"` to
   * restore the eager behaviour deliberately.
   */
  preload?: "none" | "metadata" | "auto";
  /** Video source — an `http(s):`, `data:`, or `blob:` URL. */
  src: string;
  /** Poster image shown before playback. */
  poster?: string;
  /** Show native playback controls (default `true`). */
  controls?: boolean;
  /** Autoplay on mount (most browsers require `muted` too). */
  autoPlay?: boolean;
  /** Loop playback (default `false`). */
  loop?: boolean;
  /** Start muted (default `false`). */
  muted?: boolean;
  /** How the video fits its box: `"contain"` (default) or `"cover"`. */
  fit?: "contain" | "cover";
  /** Fired when the video fails to load. */
  onError?: () => void;
  /** Additional CSS classes for the container. */
  className?: string;
  /** Inline styles for the container (e.g. a fixed height). */
  style?: CSSProperties;
}

import { Badge, Button, Checkbox } from "@particle-academy/react-fancy";
import type { WorkingTreeStatus } from "@particle-academy/fancy-git";
import { statusColor } from "./status-color.js";

export interface WorkingTreeProps {
  value: WorkingTreeStatus;
  selectedPaths?: string[];
  onSelectedPathsChange?: (paths: string[]) => void;
  onStage?: (paths: string[]) => void;
  onUnstage?: (paths: string[]) => void;
  pending?: boolean;
  className?: string;
}

/**
 * Changed paths, and the intent to stage or unstage them.
 *
 * Built from react-fancy primitives rather than raw HTML: the checkbox is
 * `<Checkbox>`, the actions are `<Button>`, the status is `<Badge>`. A bare
 * `<input type="checkbox">` meant this surface ignored the host's theme, focus
 * ring and sizing scale — a git panel that looked nothing like the app it was
 * dropped into, in a kit whose entire point is that they match.
 *
 * The `data-git-*` handles are unchanged. They are the contract agents and
 * stylesheets target, and swapping the implementation must not move them.
 */
export function WorkingTree({
  value,
  selectedPaths = [],
  onSelectedPathsChange,
  onStage,
  onUnstage,
  pending,
  className,
}: WorkingTreeProps) {
  const toggle = (path: string) =>
    onSelectedPathsChange?.(
      selectedPaths.includes(path) ? selectedPaths.filter((item) => item !== path) : [...selectedPaths, path],
    );

  const none = selectedPaths.length === 0;

  return (
    <section className={className} data-git-working-tree="" aria-label="Working tree">
      <header>
        <strong>{value.branch ?? "Detached HEAD"}</strong>
        <Badge color={value.clean ? "emerald" : "amber"} variant="soft" size="sm">
          {value.clean ? "Clean" : `${value.files.length} changes`}
        </Badge>
      </header>

      <ul>
        {value.files.map((file) => {
          const status = String(file.index ?? file.worktree ?? "");

          return (
            <li key={file.path} data-git-path={file.path}>
              {/* The path IS the label. It used to be a <label> wrapping a bare
                  input with the path beside it, which left the control and its
                  text as two unrelated boxes that ran together. */}
              <Checkbox
                checked={selectedPaths.includes(file.path)}
                onCheckedChange={() => toggle(file.path)}
                label={file.path}
                size="sm"
              />
              <Badge color={statusColor(status)} variant="soft" size="sm">
                {status}
              </Badge>
            </li>
          );
        })}
      </ul>

      <footer>
        <Button type="button" size="sm" disabled={pending || none} onClick={() => onStage?.(selectedPaths)}>
          Stage
        </Button>
        <Button
          type="button"
          size="sm"
          variant="ghost"
          disabled={pending || none}
          onClick={() => onUnstage?.(selectedPaths)}
        >
          Unstage
        </Button>
      </footer>
    </section>
  );
}

import type { Color } from "@particle-academy/react-fancy";

/**
 * A git status code, as the colour a reader already expects from a diff.
 *
 * Shared rather than repeated per component so the working tree and the
 * repository browser cannot drift into showing the same status two colours —
 * which is the kind of inconsistency nobody files a bug about and everybody
 * notices.
 *
 * `untracked` is deliberately neutral, not a warning: a file git has not been
 * told about is not a problem, and colouring it amber puts a caution next to
 * every new file you write.
 */
const STATUS_COLOR: Record<string, Color> = {
  added: "emerald",
  new: "emerald",
  modified: "amber",
  deleted: "rose",
  removed: "rose",
  renamed: "sky",
  copied: "sky",
  conflicted: "rose",
  untracked: "zinc",
};

export function statusColor(status: string | null | undefined): Color {
  return STATUS_COLOR[String(status ?? "").toLowerCase()] ?? "zinc";
}

/** Review state, in the colours every forge already trains people to read. */
const REVIEW_STATE_COLOR: Record<string, Color> = {
  open: "emerald",
  merged: "violet",
  closed: "rose",
  draft: "zinc",
};

export function reviewStateColor(state: string | null | undefined): Color {
  return REVIEW_STATE_COLOR[String(state ?? "").toLowerCase()] ?? "zinc";
}

