                >
                  ×
                </Button>
              </div>
            ))}
            <Button
              type="button"
              variant="ghost"
              onClick={() => addLink(si)}
              data-x-add={`llms-link:${si}`}
            >
              Add link
            </Button>
          </div>
        ))}
      </Section>

      {hideIssues ? null : <IssueList issues={issues} testid="llmsTxt" />}
    </div>
  );
}

import { Button, Callout, Input } from "@particle-academy/react-fancy";
import type { RobotsGroup, RobotsModel } from "../model.js";
import { validateRobots } from "../validate.js";
import { IssueList, Section, StringList } from "./internal.js";

export interface RobotsEditorProps {
  /** Controlled robots.txt model. */
  value: RobotsModel;
  /** Fires with the next model on every edit. */
  onChange: (next: RobotsModel) => void;
  /** Hide the inline validation issue list. Default `false`. */
  hideIssues?: boolean;
  className?: string;
}

/**
 * Controlled robots.txt rule builder.
 *
 * Protected-path safety (mirrors the PHP `protect()` rail): paths listed under
 * **Protected paths** are pinned Disallowed for every group and can NEVER be
 * Allowed. The editor:
 *  - renders protected chips in red, labelled "Disallowed everywhere";
 *  - strips a protected path out of any group's Allow list as you protect it;
 *  - flags (via {@link validateRobots}) any protected path still sitting in an
 *    Allow list, so the issue surfaces inline.
 */
export function RobotsEditor({
  value,
  onChange,
  hideIssues,
  className,
}: RobotsEditorProps) {
  const issues = validateRobots(value);

  const patch = (next: Partial<RobotsModel>) => onChange({ ...value, ...next });

  const updateGroup = (index: number, next: Partial<RobotsGroup>) => {
    const groups = value.groups.map((g, i) =>
      i === index ? { ...g, ...next } : g,
    );
    onChange({ ...value, groups });
  };

  const addGroup = () =>
    patch({
      groups: [
        ...value.groups,
        { userAgents: ["*"], allow: [], disallow: [] },
      ],
    });

  const removeGroup = (index: number) =>
    patch({ groups: value.groups.filter((_, i) => i !== index) });

  /** Setting Allow for a group: protected paths are filtered out entirely. */
  const setAllow = (index: number, next: string[]) => {
    const filtered = next.filter((p) => !value.protectedPaths.includes(p));
    updateGroup(index, { allow: filtered });
  };

  /** Protecting a path also removes it from every group's Allow list. */
  const setProtected = (next: string[]) => {
    const protectedSet = new Set(next);
    const groups = value.groups.map((g) => ({
      ...g,
      allow: g.allow.filter((p) => !protectedSet.has(p)),
    }));
    onChange({ ...value, protectedPaths: next, groups });
  };

  return (
    <div className={className} data-x-editor="robots">
      <Section
        title="Protected paths"
        handle="robots-protected"
        action={
          value.protectedPaths.length ? (
            <span style={{ fontSize: "0.75rem", opacity: 0.7 }}>
              Disallowed for every agent · cannot be Allowed
            </span>
          ) : null
        }
      >
        <Callout color="red">
          Paths added here are pinned <strong>Disallow</strong> on every
          user-agent group and can never be marked Allow. This mirrors the
          server-side <code>protect()</code> safety rail.
        </Callout>
        <StringList
          handle="robots-protected"
          values={value.protectedPaths}
          onChange={setProtected}
          placeholder="/admin"
        />
      </Section>

      <Section
        title="Sitemaps"
        handle="robots-sitemaps"
      >
        <StringList
          handle="robots-sitemaps"
          values={value.sitemaps}
          onChange={(sitemaps) => patch({ sitemaps })}
          placeholder="https://example.com/sitemap.xml"
        />
      </Section>

      <Section title="Host" handle="robots-host">
        <Input
          value={value.host ?? ""}
          onValueChange={(host) => patch({ host: host || undefined })}
          placeholder="example.com"
          data-x-input="robots-host"
        />
      </Section>

      <Section
        title="User-agent groups"
        handle="robots-groups"
        action={
          <Button
            type="button"
            variant="ghost"
            onClick={addGroup}
            data-x-add="robots-group"
          >
            Add group
          </Button>
        }
      >
        {value.groups.map((group, i) => (
          <div
            key={i}
            data-x-group={i}
            style={{
              border: "1px solid var(--rf-border, #e5e7eb)",
              borderRadius: "0.5rem",
              padding: "0.75rem",
              display: "flex",
              flexDirection: "column",
              gap: "0.6rem",
            }}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <strong style={{ fontSize: "0.8rem" }}>Group {i + 1}</strong>
              <Button
                type="button"
                variant="ghost"
                color="red"
                onClick={() => removeGroup(i)}
                data-x-remove={`robots-group:${i}`}
                disabled={value.groups.length <= 1}
              >
                Remove
              </Button>
            </div>
            <StringList
              label="User-agents"
              handle={`robots-ua:${i}`}
              values={group.userAgents}
              onChange={(userAgents) => updateGroup(i, { userAgents })}
              placeholder="*"
            />
            <StringList
              label="Disallow"
              handle={`robots-disallow:${i}`}
              values={group.disallow}
              onChange={(disallow) => updateGroup(i, { disallow })}
              placeholder="/private"
            />
            <StringList
              label="Allow"
              handle={`robots-allow:${i}`}
              values={group.allow}
              onChange={(allow) => setAllow(i, allow)}
              placeholder="/public"
              disallowedValues={value.protectedPaths}
              disallowedReason={(p) =>
                `"${p}" is protected and cannot be Allowed.`
              }
            />
            <div style={{ maxWidth: "12rem" }}>
              <Input
                type="number"
                label="Crawl-delay (s)"
                value={group.crawlDelay != null ? String(group.crawlDelay) : ""}
                onValueChange={(v) =>
                  updateGroup(i, {
                    crawlDelay: v === "" ? undefined : Number(v),
                  })
                }
                data-x-input={`robots-crawldelay:${i}`}
                placeholder="0"
              />
            </div>
          </div>
        ))}
      </Section>

      {hideIssues ? null : <IssueList issues={issues} testid="robots" />}
    </div>
  );
}

import { Field, Input } from "@particle-academy/react-fancy";
import type { SecurityTxtModel } from "../model.js";
import { validateSecurityTxt } from "../validate.js";
import { IssueList, Section, StringList } from "./internal.js";

export interface SecurityTxtEditorProps {
  value: SecurityTxtModel;
  onChange: (next: SecurityTxtModel) => void;
  hideIssues?: boolean;
  className?: string;
}

/**
 * Controlled security.txt editor (RFC 9116). Contact is required (one or more
 * mailto:/https: URIs) and Expires must be a future date — surfaced both as a
 * date input and inline issues from {@link validateSecurityTxt}.
 */
export function SecurityTxtEditor({
  value,
  onChange,
  hideIssues,
  className,
}: SecurityTxtEditorProps) {
  const issues = validateSecurityTxt(value);
  const patch = (next: Partial<SecurityTxtModel>) =>
    onChange({ ...value, ...next });

  // <input type="datetime-local"> wants `YYYY-MM-DDTHH:mm`; tolerate a stored
  // ISO string with seconds/zone by trimming to minutes for the control.
  const expiresLocal = value.expires ? value.expires.slice(0, 16) : "";

  return (
    <div className={className} data-x-editor="securityTxt">
      <Section title="Contact (required)" handle="security-contact">
        <StringList
          handle="security-contact"
          values={value.contact}
          onChange={(contact) => patch({ contact })}
          placeholder="mailto:security@example.com"
        />
      </Section>

      <Section title="Expires (required, future)" handle="security-expires">
        <Field description="Must be a date/time in the future.">
          <input
            type="datetime-local"
            value={expiresLocal}
            onChange={(e) =>
              patch({
                expires: e.target.value
                  ? `${e.target.value}:00Z`
                  : "",
              })
            }
            data-x-input="security-expires"
            style={{
              padding: "0.4rem 0.6rem",
              borderRadius: "0.4rem",
              border: "1px solid var(--rf-border, #e5e7eb)",
            }}
          />
        </Field>
      </Section>

      <Section title="Optional fields" handle="security-optional">
        <Input
          label="Encryption"
          value={value.encryption ?? ""}
          onValueChange={(v) => patch({ encryption: v || undefined })}
          placeholder="https://example.com/pgp-key.txt"
          data-x-input="security-encryption"
        />
        <Input
          label="Acknowledgments"
          value={value.acknowledgments ?? ""}
          onValueChange={(v) => patch({ acknowledgments: v || undefined })}
          placeholder="https://example.com/hall-of-fame"
          data-x-input="security-acknowledgments"
        />
        <Input
          label="Preferred-Languages"
          value={value.preferredLanguages ?? ""}
          onValueChange={(v) => patch({ preferredLanguages: v || undefined })}
          placeholder="en, fr"
          data-x-input="security-languages"
        />
        <Input
          label="Canonical"
          value={value.canonical ?? ""}
          onValueChange={(v) => patch({ canonical: v || undefined })}
          placeholder="https://example.com/.well-known/security.txt"
          data-x-input="security-canonical"
        />
        <Input
          label="Policy"
          value={value.policy ?? ""}
          onValueChange={(v) => patch({ policy: v || undefined })}
          placeholder="https://example.com/security-policy"
          data-x-input="security-policy"
        />
        <Input
          label="Hiring"
          value={value.hiring ?? ""}
          onValueChange={(v) => patch({ hiring: v || undefined })}
          placeholder="https://example.com/jobs"
          data-x-input="security-hiring"
        />
      </Section>

      {hideIssues ? null : <IssueList issues={issues} testid="securityTxt" />}
    </div>
  );
}

import { Button, Input, Select } from "@particle-academy/react-fancy";
import type {
  SitemapChangeFreq,
  SitemapModel,
  SitemapUrl,
} from "../model.js";
import { validateSitemap } from "../validate.js";
import { IssueList, Section } from "./internal.js";

export interface SitemapEditorProps {
  value: SitemapModel;
  onChange: (next: SitemapModel) => void;
  hideIssues?: boolean;
  className?: string;
}

const CHANGE_FREQS: SitemapChangeFreq[] = [
  "always",
  "hourly",
  "daily",
  "weekly",
  "monthly",
  "yearly",
  "never",
];

/** Controlled sitemap.xml editor: a flat list of URL entries. */
export function SitemapEditor({
  value,
  onChange,
  hideIssues,
  className,
}: SitemapEditorProps) {
  const issues = validateSitemap(value);
  const patch = (next: Partial<SitemapModel>) => onChange({ ...value, ...next });

  const updateUrl = (index: number, next: Partial<SitemapUrl>) =>
    patch({
      urls: value.urls.map((u, i) => (i === index ? { ...u, ...next } : u)),
    });

  const addUrl = () => patch({ urls: [...value.urls, { loc: "" }] });

  const removeUrl = (index: number) =>
    patch({ urls: value.urls.filter((_, i) => i !== index) });

  return (
    <div className={className} data-x-editor="sitemap">
      <Section
        title="URLs"
        handle="sitemap-urls"
        action={
          <Button
            type="button"
            variant="ghost"
            onClick={addUrl}
            data-x-add="sitemap-url"
          >
            Add URL
          </Button>
        }
      >
        {value.urls.map((url, i) => (
          <div
            key={i}
            data-x-url={i}
            style={{
              border: "1px solid var(--rf-border, #e5e7eb)",
              borderRadius: "0.5rem",
              padding: "0.6rem",
              display: "flex",
              flexDirection: "column",
              gap: "0.4rem",
            }}
          >
            <div style={{ display: "flex", gap: "0.4rem", alignItems: "end" }}>
              <div style={{ flex: 1 }}>
                <Input
                  label="loc"
                  value={url.loc}
                  onValueChange={(loc) => updateUrl(i, { loc })}
                  placeholder="https://example.com/page"
                  data-x-input={`sitemap-loc:${i}`}
                />
              </div>
              <Button
                type="button"
                variant="ghost"
                color="red"
                onClick={() => removeUrl(i)}
                data-x-remove={`sitemap-url:${i}`}
              >
                ×
              </Button>
            </div>
            <div
              style={{
                display: "flex",
                gap: "0.4rem",
                flexWrap: "wrap",
              }}
            >
              <div style={{ flex: "1 1 9rem" }}>
                <Input
                  label="lastmod"
                  type="text"
                  value={url.lastmod ?? ""}
                  onValueChange={(v) =>
                    updateUrl(i, { lastmod: v || undefined })
                  }
                  placeholder="2026-01-01"
                  data-x-input={`sitemap-lastmod:${i}`}
                />
              </div>
              <div style={{ flex: "1 1 9rem" }}>
                <Select
                  label="changefreq"
                  value={url.changefreq ?? ""}
                  list={["", ...CHANGE_FREQS]}
                  onValueChange={(v) =>
                    updateUrl(i, {
                      changefreq: (v || undefined) as
                        | SitemapChangeFreq
                        | undefined,
                    })
                  }
                  data-x-input={`sitemap-changefreq:${i}`}
                />
              </div>
              <div style={{ flex: "1 1 6rem" }}>
                <Input
                  label="priority"
                  type="number"
                  value={url.priority != null ? String(url.priority) : ""}
                  onValueChange={(v) =>
                    updateUrl(i, {
                      priority: v === "" ? undefined : Number(v),
                    })
                  }
                  placeholder="0.5"
                  data-x-input={`sitemap-priority:${i}`}
                />
              </div>
            </div>
          </div>
        ))}
      </Section>

      {hideIssues ? null : <IssueList issues={issues} testid="sitemap" />}
    </div>
  );
}

import { Badge, Card } from "@particle-academy/react-fancy";
import { X_FILE_META, type XFileKind } from "../model.js";
import { renderXFile } from "../render.js";

export interface XFilePreviewProps {
  /** Which well-known file to preview. */
  kind: XFileKind;
  /** The model for that file kind. */
  model: unknown;
  /** Override the filename label shown in the header. */
  filename?: string;
  className?: string;
}

/**
 * Renders the real text/XML a well-known file will become on disk, using the
 * local render logic that mirrors the `fancy-x-files` output format. Shown in
 * a Card with a monospace <pre> so what you see is what ships.
 */
export function XFilePreview({
  kind,
  model,
  filename,
  className,
}: XFilePreviewProps) {
  const meta = X_FILE_META[kind];
  const text = model != null ? renderXFile(kind, model) : "";

  return (
    <Card variant="outlined" padding="none" className={className}>
      <Card.Header
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "0.5rem 0.75rem",
          borderBottom: "1px solid var(--rf-border, #e5e7eb)",
        }}
      >
        <code style={{ fontSize: "0.8rem" }} data-x-preview-name={kind}>
          {filename ?? meta.filename}
        </code>
        <Badge color="slate" variant="soft" size="sm">
          preview
        </Badge>
      </Card.Header>
      <Card.Body style={{ padding: 0 }}>
        <pre
          data-x-preview={kind}
          style={{
            margin: 0,
            padding: "0.75rem",
            fontFamily:
              "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace",
            fontSize: "0.78rem",
            lineHeight: 1.5,
            whiteSpace: "pre-wrap",
            wordBreak: "break-word",
            overflowX: "auto",
          }}
        >
          {text || "— empty —"}
        </pre>
      </Card.Body>
    </Card>
  );
}

import { useState } from "react";
import { Badge, Button, Callout, Input } from "@particle-academy/react-fancy";

/**
 * Shared internal building blocks for the editors. Not exported from the
 * package root — these are implementation details of the editors.
 */

/** Surface a list of validation issues as a soft warning callout. */
export function IssueList({
  issues,
  testid,
}: {
  issues: string[];
  testid?: string;
}) {
  if (!issues.length) return null;
  return (
    <Callout color="amber" data-x-issues={testid ?? ""}>
      <ul style={{ margin: 0, paddingLeft: "1.1rem" }}>
        {issues.map((issue, i) => (
          <li key={i} data-x-issue>
            {issue}
          </li>
        ))}
      </ul>
    </Callout>
  );
}

/**
 * Controlled add/remove list of plain strings rendered as chips with an
 * inline "add a row" input. `disallowedValues` are rejected on add and, if
 * already present, flagged — used by RobotsEditor to keep protected paths out
 * of an Allow list.
 */
export function StringList({
  label,
  values,
  onChange,
  placeholder,
  handle,
  disallowedValues,
  disallowedReason,
}: {
  label?: string;
  values: string[];
  onChange: (next: string[]) => void;
  placeholder?: string;
  /** data-* handle base, e.g. "robots-allow". */
  handle: string;
  disallowedValues?: string[];
  disallowedReason?: (value: string) => string;
}) {
  const [draft, setDraft] = useState("");
  const blocked = new Set(disallowedValues ?? []);

  const add = () => {
    const v = draft.trim();
    if (!v || values.includes(v)) {
      setDraft("");
      return;
    }
    onChange([...values, v]);
    setDraft("");
  };

  const remove = (value: string) =>
    onChange(values.filter((v) => v !== value));

  return (
    <div data-x-list={handle}>
      {label ? (
        <div
          style={{ fontSize: "0.8rem", fontWeight: 600, marginBottom: "0.25rem" }}
        >
          {label}
        </div>
      ) : null}
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          gap: "0.35rem",
          marginBottom: values.length ? "0.4rem" : 0,
        }}
      >
        {values.map((value) => {
          const isBlocked = blocked.has(value);
          return (
            <Badge
              key={value}
              color={isBlocked ? "red" : "slate"}
              variant={isBlocked ? "soft" : "outline"}
              data-x-chip={`${handle}:${value}`}
              title={
                isBlocked && disallowedReason
                  ? disallowedReason(value)
                  : undefined
              }
            >
              {value}
              <button
                type="button"
                onClick={() => remove(value)}
                aria-label={`Remove ${value}`}
                data-x-remove={`${handle}:${value}`}
                style={{
                  marginLeft: "0.35rem",
                  border: "none",
                  background: "transparent",
                  cursor: "pointer",
                  fontWeight: 700,
                }}
              >
                ×
              </button>
            </Badge>
          );
        })}
      </div>
      <div style={{ display: "flex", gap: "0.4rem" }}>
        <Input
          value={draft}
          onValueChange={setDraft}
          placeholder={placeholder}
          data-x-input={`${handle}-draft`}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              add();
            }
          }}
        />
        <Button
          type="button"
          variant="ghost"
          onClick={add}
          data-x-add={handle}
        >
          Add
        </Button>
      </div>
    </div>
  );
}

/** A labelled section wrapper used to group fields inside an editor. */
export function Section({
  title,
  action,
  children,
  handle,
}: {
  title: string;
  action?: React.ReactNode;
  children: React.ReactNode;
  handle?: string;
}) {
  return (
    <section
      data-x-section={handle}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "0.5rem",
        marginBottom: "1rem",
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <h4 style={{ margin: 0, fontSize: "0.9rem", fontWeight: 700 }}>
          {title}
        </h4>
        {action}
      </div>
      {children}
    </section>
  );
}
